    // إيقاف عملية بالقوة مع كل العمليات الفرعية التابعة لها (مثل عمليات proot وgradle/java
    // التي يشغّلها البناء داخل Debian): الاعتماد على destroyForcibly() وحده على العملية
    // الأم فقط قد لا يكفي، لأن SIGKILL يمنع proot من تنفيذ تنظيفه الداخلي (--kill-on-exit)
    // فتبقى العمليات الفرعية تعمل بالخلفية رغم اختفاء العملية الظاهرة للتطبيق. لذلك نقتل
    // كل الأحفاد أولًا ثم العملية نفسها، لضمان إلغاء العملية الجارية فعليًا وبالكامل.
    private void killProcessTree(Process p) {
        if (p == null) return;
        try {
            long pid = getPid(p);
            if (pid > 0) killTree(pid);
        } catch (Throwable ignored) {}
        try { Compat.destroyForcibly(p); } catch (Throwable ignored) {}
    }

    private long getPid(Process p) {
        try {
            java.lang.reflect.Field f = p.getClass().getDeclaredField("pid");
            f.setAccessible(true);
            return f.getLong(p);
        } catch (Throwable e) {
            return -1;
        }
    }

    private void killTree(long pid) {
        java.util.List<Long> children = new java.util.ArrayList<>();
        java.io.File procDir = new java.io.File("/proc");
        java.io.File[] entries = procDir.listFiles();
        if (entries != null) {
            for (java.io.File entry : entries) {
                if (!entry.getName().matches("\\d+")) continue;
                try {
                    java.io.File statFile = new java.io.File(entry, "stat");
                    String stat = new String(Compat.readAllBytes(statFile));
                    int close = stat.lastIndexOf(')');
                    String[] parts = stat.substring(close + 2).trim().split("\\s+");
                    long ppid = Long.parseLong(parts[1]);
                    if (ppid == pid) children.add(Long.parseLong(entry.getName()));
                } catch (Throwable ignored) {}
            }
        }
        for (long childPid : children) killTree(childPid);
        try {
            Runtime.getRuntime().exec(new String[]{"kill", "-9", String.valueOf(pid)});
        } catch (Throwable ignored) {}
    }

    // ===== مهل الإيقاف التلقائي (قابلة للتعديل، منفصلة للبناء وللأوامر) =====
    private static final int DEFAULT_BUILD_TIMEOUT_MIN = 60;
    private static final int DEFAULT_CMD_TIMEOUT_MIN = 30;

    private int getBuildTimeoutMin() {
        int v = uiPrefs().getInt("timeout_build_min", DEFAULT_BUILD_TIMEOUT_MIN);
        return v > 0 ? v : DEFAULT_BUILD_TIMEOUT_MIN;
    }

    private int getCmdTimeoutMin() {
        int v = uiPrefs().getInt("timeout_cmd_min", DEFAULT_CMD_TIMEOUT_MIN);
        return v > 0 ? v : DEFAULT_CMD_TIMEOUT_MIN;
    }

    private void timeoutSettingsDialog() {
        LinearLayout box = new LinearLayout(this);
        box.setOrientation(LinearLayout.VERTICAL);
        int p = dp(16);
        box.setPadding(p, p, p, p);

        TextView t1 = new TextView(this);
        t1.setText("مهلة البناء (بالدقائق)");
        t1.setTextSize(14);
        box.addView(t1);
        final android.widget.EditText buildEd = new android.widget.EditText(this);
        buildEd.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);
        buildEd.setText(String.valueOf(getBuildTimeoutMin()));
        box.addView(buildEd);

        TextView t2 = new TextView(this);
        t2.setText("مهلة الأوامر (بالدقائق)");
        t2.setTextSize(14);
        t2.setPadding(0, dp(14), 0, 0);
        box.addView(t2);
        final android.widget.EditText cmdEd = new android.widget.EditText(this);
        cmdEd.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);
        cmdEd.setText(String.valueOf(getCmdTimeoutMin()));
        box.addView(cmdEd);

        TextView t3 = new TextView(this);
        t3.setText("إيقاف وضع الخلفية عند عدم وجود عمليات (بالدقائق، 0 = معطّل)");
        t3.setTextSize(14);
        t3.setPadding(0, dp(14), 0, 0);
        box.addView(t3);
        final android.widget.EditText idleEd = new android.widget.EditText(this);
        idleEd.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);
        idleEd.setText(String.valueOf(BuildService.idleMinutes(this)));
        box.addView(idleEd);

        new NavAlertBuilder()
                .setTitle("إعدادات مهل الإيقاف التلقائي")
                .setView(box)
                .setPositiveButton("حفظ", (d, w) -> {
                    int b = parseIntOr(buildEd.getText().toString(), getBuildTimeoutMin());
                    int c = parseIntOr(cmdEd.getText().toString(), getCmdTimeoutMin());
                    if (b < 1) b = 1;
                    if (c < 1) c = 1;
                    int idle = parseIntOr(idleEd.getText().toString(), BuildService.idleMinutes(this));
                    if (idle < 0) idle = 0;
                    uiPrefs().edit().putInt("timeout_build_min", b).putInt("timeout_cmd_min", c).putInt("idle_stop_min", idle).apply();
                    BuildService.rescheduleIdle(this);
                    Toast.makeText(this, "تم الحفظ: البناء " + b + "د — الأوامر " + c + "د — خمول الخلفية " + (idle == 0 ? "معطّل" : idle + "د"), Toast.LENGTH_SHORT).show();
                })
                .setNeutralButton("استعادة الافتراضي", (d, w) -> {
                    uiPrefs().edit().remove("timeout_build_min").remove("timeout_cmd_min").remove("idle_stop_min").apply();
                    BuildService.rescheduleIdle(this);
                    Toast.makeText(this, "تمت الاستعادة (بناء " + DEFAULT_BUILD_TIMEOUT_MIN + "د — أوامر " + DEFAULT_CMD_TIMEOUT_MIN + "د — خمول الخلفية " + BuildService.DEFAULT_IDLE_MIN + "د)", Toast.LENGTH_SHORT).show();
                })
                .setNegativeButton("إلغاء", null)
                .show();
    }

    private int parseIntOr(String s, int fallback) {
        try { return Integer.parseInt(s.trim()); } catch (Throwable e) { return fallback; }
    }

    // ===== سجل الإيقافات التلقائية (بسبب تجاوز المهلة) =====
    private void logAutoStop(String kind, String project, int durationMin) {
        try {
            String ts = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", java.util.Locale.US).format(new java.util.Date());
            String entry = ts + "|" + kind + "|" + (project == null || project.isEmpty() ? "-" : project) + "|" + durationMin;
            java.util.LinkedHashSet<String> set = new java.util.LinkedHashSet<>(uiPrefs().getStringSet("auto_stop_log", new java.util.LinkedHashSet<>()));
            java.util.List<String> list = new java.util.ArrayList<>(set);
            list.add(entry);
            while (list.size() > 100) list.remove(0);
            uiPrefs().edit().putStringSet("auto_stop_log", new java.util.LinkedHashSet<>(list)).apply();
        } catch (Throwable ignored) {}
    }

    private void autoStopLogDialog() {
        java.util.List<String> list = new java.util.ArrayList<>(uiPrefs().getStringSet("auto_stop_log", new java.util.LinkedHashSet<>()));
        // الأحدث أولًا حسب الطابع الزمني النصي (yyyy-MM-dd HH:mm قابل للترتيب مباشرة)
        java.util.Collections.sort(list);
        java.util.Collections.reverse(list);

        ScrollView sv = new ScrollView(this);
        LinearLayout box = new LinearLayout(this);
        box.setOrientation(LinearLayout.VERTICAL);
        int p = dp(14);
        box.setPadding(p, p, p, p);
        sv.addView(box);

        if (list.isEmpty()) {
            TextView empty = new TextView(this);
            empty.setText("لا توجد إيقافات تلقائية مسجّلة.");
            box.addView(empty);
        }
        for (String e : list) {
            String[] parts = e.split("\\|", 4);
            if (parts.length < 4) continue;
            String kindLabel = "cmd".equals(parts[1]) ? "أمر" : "بناء";
            TextView row = new TextView(this);
            if ("idle".equals(parts[1])) {
                row.setText("⏱ " + parts[0] + " — أُوقف وضع الخلفية لعدم وجود عمليات لمدة " + parts[3] + "د");
            } else {
                row.setText("⏱ " + parts[0] + " — " + kindLabel + (parts[2].equals("-") ? "" : " (" + parts[2] + ")") + " — تجاوز " + parts[3] + "د");
            }
            row.setTextSize(13);
            row.setPadding(0, dp(6), 0, dp(6));
            box.addView(row);
        }

        new NavAlertBuilder()
                .setTitle("سجل الإيقافات التلقائية")
                .setView(sv)
                .setPositiveButton("إغلاق", null)
                .setNegativeButton("مسح السجل", (d, w) -> {
                    uiPrefs().edit().remove("auto_stop_log").apply();
                    Toast.makeText(this, "تم مسح السجل", Toast.LENGTH_SHORT).show();
                })
                .show();
    }

    // ===== إشعار نظام عند إيقاف تلقائي بسبب تجاوز المهلة =====
    private static final String AUTOSTOP_CHANNEL_ID = "autostop_channel";

    private void ensureAutoStopChannel() {
        if (Build.VERSION.SDK_INT >= 26) {
            android.app.NotificationManager nm = (android.app.NotificationManager) getSystemService(Context.NOTIFICATION_SERVICE);
            if (nm != null && nm.getNotificationChannel(AUTOSTOP_CHANNEL_ID) == null) {
                android.app.NotificationChannel ch = new android.app.NotificationChannel(
                        AUTOSTOP_CHANNEL_ID, "إيقاف تلقائي للبناء/الأوامر", android.app.NotificationManager.IMPORTANCE_HIGH);
                nm.createNotificationChannel(ch);
            }
        }
    }

    private void notifyAutoStop(String title, String text) {
        try {
            if (Build.VERSION.SDK_INT >= 33) {
                if (checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) != PackageManager.PERMISSION_GRANTED) {
                    return; // بدون الإذن (POST_NOTIFICATIONS) لا يمكن إظهار إشعار على أندرويد 13+
                }
            }
            ensureAutoStopChannel();
            android.app.Notification.Builder b = (Build.VERSION.SDK_INT >= 26)
                    ? new android.app.Notification.Builder(this, AUTOSTOP_CHANNEL_ID)
                    : new android.app.Notification.Builder(this);
            b.setContentTitle(title)
                    .setContentText(text)
                    .setSmallIcon(android.R.drawable.stat_sys_warning)
                    .setAutoCancel(true);
            android.app.NotificationManager nm = (android.app.NotificationManager) getSystemService(Context.NOTIFICATION_SERVICE);
            if (nm != null) nm.notify((int) System.currentTimeMillis(), b.build());
        } catch (Throwable ignored) {}
    }

    // ===== الذهاب لأعلى/أسفل النص الطويل (من الوصول السريع ⚡) =====
    // الهدف: نافذة الناتج المفتوحة إن وُجدت، ثم شاشة الناتج إن كانت هي المحرر الأساسي،
    // وإلا محرر الأوامر (حقل الإدخال).
    private void scrollMainText(final boolean top) {
        try {
            if (taskDialog != null && taskDialog.isShowing() && taskDialogScroll != null) {
                taskDialogScroll.post(() -> taskDialogScroll.fullScroll(top ? View.FOCUS_UP : View.FOCUS_DOWN));
                return;
            }
            if (outputIsPrimary() && termScroll != null) {
                termScroll.post(() -> termScroll.fullScroll(top ? View.FOCUS_UP : View.FOCUS_DOWN));
                return;
            }
            if (termInput != null) {
                termInput.requestFocus();
                int len = termInput.getText().length();
                termInput.setSelection(top ? 0 : len);
                return;
            }
            if (termScroll != null) termScroll.post(() -> termScroll.fullScroll(top ? View.FOCUS_UP : View.FOCUS_DOWN));
        } catch (Throwable ignored) {}
    }

    // ===== إشعار نظام عند انتهاء أي عملية (بناء/أمر) =====
    private static final String DONE_CHANNEL_ID = "task_done_channel";

    private void notifyTaskDone(String title, String text) {
        try {
            Context ctx = getApplicationContext();
            if (!uiPrefs().getBoolean("notify_done", true)) return;
            if (Build.VERSION.SDK_INT >= 33
                    && checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) != PackageManager.PERMISSION_GRANTED) {
                return;
            }
            android.app.NotificationManager nm = (android.app.NotificationManager) ctx.getSystemService(Context.NOTIFICATION_SERVICE);
            if (nm == null) return;
            if (Build.VERSION.SDK_INT >= 26 && nm.getNotificationChannel(DONE_CHANNEL_ID) == null) {
                nm.createNotificationChannel(new android.app.NotificationChannel(
                        DONE_CHANNEL_ID, "انتهاء العمليات", android.app.NotificationManager.IMPORTANCE_HIGH));
            }
            Intent open = new Intent(ctx, MainActivity.class);
            open.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TOP | Intent.FLAG_ACTIVITY_SINGLE_TOP);
            android.app.PendingIntent pi = android.app.PendingIntent.getActivity(ctx, 0, open,
                    android.app.PendingIntent.FLAG_UPDATE_CURRENT | android.app.PendingIntent.FLAG_IMMUTABLE);
            android.app.Notification.Builder b = (Build.VERSION.SDK_INT >= 26)
                    ? new android.app.Notification.Builder(ctx, DONE_CHANNEL_ID)
                    : new android.app.Notification.Builder(ctx).setDefaults(android.app.Notification.DEFAULT_ALL);
            b.setContentTitle(title)
                    .setContentText(text)
                    .setStyle(new android.app.Notification.BigTextStyle().bigText(text))
                    .setSmallIcon(android.R.drawable.stat_sys_download_done)
                    .setContentIntent(pi)
                    .setAutoCancel(true);
            nm.notify(9002, b.build());
        } catch (Throwable ignored) {}
    }

    private static String shortLine(String s, int max) {
        if (s == null) return "";
        String t = s.trim();
        int nl = t.indexOf('\n');
        if (nl > 0) t = t.substring(0, nl);
        return t.length() > max ? t.substring(0, max) + "…" : t;
    }

    private void shareText(String s) {
        try {
            android.content.Intent it = new android.content.Intent(android.content.Intent.ACTION_SEND);
            it.setType("text/plain");
            it.putExtra(android.content.Intent.EXTRA_TEXT, s);
            startActivity(android.content.Intent.createChooser(it, "مشاركة النتيجة"));
        } catch (Exception e) {
            Toast.makeText(this, "تعذّرت المشاركة: " + e, Toast.LENGTH_SHORT).show();
        }
    }

    // نسخ آمن للناتج إلى الحافظة: يلتقط TransactionTooLargeException (يحدث عند تجاوز
    // حد نقل بيانات Binder الذي يفرضه أندرويد، وهو ما كان يُسقط التطبيق فورًا عند
    // الضغط على زر النسخ لناتج بناء طويل)، ويقتطع الناتج تلقائيًا إن كان ضخمًا جدًا،
    // مع إبقاء الجزء الأخير (الأهم عادة عند تتبّع سبب فشل البناء).
    private static final int SAFE_CLIP_MAX_CHARS = 300_000; // ~ هامش أمان تحت حد الـ Binder

    private void safeCopyToClipboard(String label, CharSequence textCs) {
        String text = textCs == null ? "" : textCs.toString();
        boolean truncated = false;
        if (text.length() > SAFE_CLIP_MAX_CHARS) {
            text = "... [تم اقتطاع الجزء الأول لضخامة الناتج]\n\n"
                    + text.substring(text.length() - SAFE_CLIP_MAX_CHARS);
            truncated = true;
        }
        try {
            ClipboardManager cm = (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
            if (cm == null) {
                Toast.makeText(this, "تعذّر الوصول إلى الحافظة", Toast.LENGTH_SHORT).show();
                return;
            }
            cm.setPrimaryClip(ClipData.newPlainText(label, text));
            Toast.makeText(this, truncated ? "تم النسخ (تم اقتطاع الناتج لضخامته)" : "تم النسخ",
                    Toast.LENGTH_SHORT).show();
        } catch (Throwable t) {
            // TransactionTooLargeException وأي خطأ آخر غير متوقع أثناء النسخ: لا نترك
            // التطبيق ينهار، بل نحاول مرة أخرى بنسخة مقتطعة أصغر بكثير، وإن فشلت أيضًا
            // نكتفي برسالة خطأ للمستخدم.
            try {
                ClipboardManager cm = (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
                String shrunk = text.length() > 50_000 ? text.substring(text.length() - 50_000) : text;
                cm.setPrimaryClip(ClipData.newPlainText(label,
                        "... [تم اقتطاع الناتج بشدة بسبب فشل النسخ الكامل]\n\n" + shrunk));
                Toast.makeText(this, "الناتج كبير جدًا — تم نسخ الجزء الأخير فقط", Toast.LENGTH_LONG).show();
            } catch (Throwable t2) {
                Toast.makeText(this, "تعذّر النسخ: الناتج كبير جدًا على الحافظة", Toast.LENGTH_LONG).show();
            }
        }
    }

    // ===== نسخ الأخطاء فقط مع فقرة قبلها وفقرة بعدها وأرقام الأسطر =====
    private static final java.util.regex.Pattern ERR_LINE_RE = java.util.regex.Pattern.compile(
            "(?i)(\\berror\\b|\\be: |exception|\\bfailed\\b|\\bfailure\\b|\\bfatal\\b|what went wrong|caused by:|"
            + "cannot find symbol|does not exist|incompatible types|unresolved reference|execution failed|"
            + "could not (resolve|find|get|create|read|determine)|permission denied|command not found|no such file|"
            + "not found|syntax error|unexpected|aapt|فشل|خطأ|تعذّر|تعذر|مرفوض)");
    private static final java.util.regex.Pattern ERR_IGNORE_RE = java.util.regex.Pattern.compile(
            "(?i)(\\b0 errors?\\b|\\bno errors?\\b|errors?: 0|0 failed|without errors?|build successful|نجح البناء)");

    private static boolean isErrLine(String l) {
        if (l.trim().isEmpty()) return false;
        if (l.startsWith("\tat ") || l.startsWith("    at ")) return false;
        return ERR_LINE_RE.matcher(l).find() && !ERR_IGNORE_RE.matcher(l).find();
    }

    private void copyErrorsOnly(CharSequence cs) {
        final String text = cs == null ? "" : cs.toString();
        String res;
        try {
            res = extractErrorsWithContext(text);
        } catch (Throwable t) {
            Toast.makeText(this, "تعذّر استخراج الأخطاء: " + t, Toast.LENGTH_LONG).show();
            return;
        }
        if (res == null) {
            Toast.makeText(this, "لم أجد أخطاء في الناتج", Toast.LENGTH_SHORT).show();
            return;
        }
        safeCopyToClipboard("errors", res);
    }

    private static final java.util.regex.Pattern JAVAC_ERR_RE = java.util.regex.Pattern.compile(
            "^\\s*(\\S+?\\.(?:java|kt|kts|xml|gradle)):(\\d+)(?::(\\d+))?:\\s*(?:error|warning: \\[?error)\\s*:?\\s*(.*)$");
    private static final java.util.regex.Pattern KOTLIN_ERR_RE = java.util.regex.Pattern.compile(
            "^\\s*e:\\s*(?:file://)?(\\S+?\\.kt):?\\s*\\(?(\\d+)(?:,\\s*(\\d+))?\\)?:?\\s*(.*)$");
    private static final java.util.regex.Pattern STACK_FRAME_RE = java.util.regex.Pattern.compile(
            "^\\s+at [\\w.$<>/]+\\(.*\\)\\s*$");
    private static final java.util.regex.Pattern NOISE_RE = java.util.regex.Pattern.compile(
            "(?i)(aapt2FromMavenOverride|AAPT2 wrap Daemon|Problems report|Run with --|^\\s*\\* Try:|^\\s*> Run |Get more help|--scan"
            + "|^Transforming |Received JVM|^Resolve mutations|Caching disabled|is not up-to-date|^Starting process|^Initialized |^Using \\d+ worker)");
    private static final java.util.regex.Pattern WRAPPER_RE = java.util.regex.Pattern.compile(
            "(?i)(^\\s*> Task \\S+ FAILED|^FAILURE:|what went wrong|^\\s*\\* Exception is|Execution failed for task|"
            + "Compilation failed|CompilationFailedException|TaskExecutionException|BUILD FAILED|^\\s*> Compilation failed|Check your code and dependencies|^\\d+ errors?$)");

    private static String shortPath(String p) {
        if (p == null) return "";
        p = p.replace("/proj/", "");
        int i = p.indexOf("app/src/");
        return i >= 0 ? p.substring(i) : p;
    }

    private static String firstMatch(String text, String regex) {
        java.util.regex.Matcher m = java.util.regex.Pattern.compile(regex).matcher(text);
        return m.find() ? (m.groupCount() >= 1 ? m.group(1) : m.group()) : null;
    }

    // ينتج تقرير أخطاء لتسهيل التصحيح:
    // 1) معلومات عامة (المشروع، رمز الخروج، المهمة الفاشلة، إصدارات Gradle/AGP/Java)
    // 2) أخطاء التجميع (ملف:سطر + الرسالة + سطر الكود) بدون تكرار
    // 3) بقية الأخطاء مع فقرة قبلها وفقرة بعدها ورقم السطر في الناتج الأصلي، مع طيّ تتبّع الاستثناءات.
    // يُرجع null إن لم يوجد خطأ.
    private String extractErrorsWithContext(String text) {
        final int MAX_PARA = 8;
        final int MAX_OWN = 30;
        String[] lines = text.split("\r?\n", -1);
        int n = lines.length;

        // ---- (أ) أخطاء التجميع المنظّمة ----
        java.util.LinkedHashMap<String, String> compile = new java.util.LinkedHashMap<>();
        java.util.LinkedHashMap<String, Integer> compileCount = new java.util.LinkedHashMap<>();
        boolean[] inCompile = new boolean[n];
        for (int i = 0; i < n; i++) {
            java.util.regex.Matcher m = JAVAC_ERR_RE.matcher(lines[i]);
            boolean kt = false;
            if (!m.find()) {
                m = KOTLIN_ERR_RE.matcher(lines[i]);
                if (!m.find()) continue;
                kt = true;
            }
            String file = shortPath(m.group(1));
            String ln = m.group(2);
            String col = m.group(3);
            String msg = m.group(4) == null ? "" : m.group(4).trim();
            String key = file + ":" + ln + "|" + msg;
            if (compile.containsKey(key)) {
                compileCount.put(key, compileCount.get(key) + 1);
                inCompile[i] = true;
                int dk = i + 1, dc = 0;
                while (dk < n && dc < 6 && !lines[dk].trim().isEmpty() && !JAVAC_ERR_RE.matcher(lines[dk]).find() && !KOTLIN_ERR_RE.matcher(lines[dk]).find()
                        && !lines[dk].startsWith("> Task") && !lines[dk].startsWith("FAILURE")
                        && !lines[dk].startsWith("Note:") && !lines[dk].matches("^\\d+ errors?\\s*$")) {
                    inCompile[dk] = true; dk++; dc++;
                }
                continue;
            }
            StringBuilder sb = new StringBuilder();
            sb.append("• ").append(file).append(':').append(ln);
            if (col != null) sb.append(':').append(col);
            sb.append("\n  ").append(msg.isEmpty() ? lines[i].trim() : msg);
            sb.append("\n  (الناتج الأصلي سطر ").append(i + 1).append(")");
            // سطر الكود + المؤشر + تفاصيل مثل symbol/location (حتى 6 أسطر غير فارغة)
            int k = i + 1, c = 0;
            while (k < n && c < 6 && !lines[k].trim().isEmpty() && !JAVAC_ERR_RE.matcher(lines[k]).find() && !KOTLIN_ERR_RE.matcher(lines[k]).find()
                    && !lines[k].startsWith("> Task") && !lines[k].startsWith("FAILURE")
                    && !lines[k].startsWith("Note:") && !lines[k].matches("^\\d+ errors?\\s*$")) {
                sb.append("\n  | ").append(lines[k]);
                inCompile[k] = true;
                k++; c++;
            }
            inCompile[i] = true;
            compile.put(key, sb.toString());
            compileCount.put(key, 1);
        }

        // ---- (ب) بقية الأخطاء العامة ----
        java.util.ArrayList<Integer> errs = new java.util.ArrayList<>();
        java.util.HashSet<String> seenGeneric = new java.util.HashSet<>();
        java.util.HashMap<String, Integer> genericCount = new java.util.HashMap<>();
        for (int i = 0; i < n; i++) {
            if (inCompile[i]) continue;
            String l = lines[i];
            if (!isErrLine(l) || STACK_FRAME_RE.matcher(l).find() || NOISE_RE.matcher(l).find()) continue;
            if (i == 0 && (l.startsWith("فشل") || l.startsWith("نجح") || l.startsWith("توقف"))) continue;
            if (!compile.isEmpty() && WRAPPER_RE.matcher(l).find()) continue;
            String t = l.trim();
            // أخطاء التجميع نفسها تتكرر داخل "What went wrong" و"Caused by"؛ نتجاهل ما سبق عرضه
            boolean dupOfCompile = false;
            for (String key : compile.keySet()) {
                String msgPart = key.substring(key.indexOf('|') + 1);
                if (!msgPart.isEmpty() && t.contains(msgPart)) { dupOfCompile = true; break; }
            }
            if (dupOfCompile) continue;
            genericCount.put(t, genericCount.containsKey(t) ? genericCount.get(t) + 1 : 1);
            if (seenGeneric.add(t)) errs.add(i);
        }
        if (compile.isEmpty() && errs.isEmpty()) return null;

        // ---- (ج) رأس التقرير ----
        StringBuilder sb = new StringBuilder();
        sb.append("== تقرير أخطاء لتسهيل التصحيح ==\n");
        String pn = currentProject();
        if (!pn.isEmpty()) sb.append("المشروع: ").append(pn).append('\n');
        String head = lines.length > 0 ? lines[0].trim() : "";
        if (head.startsWith("فشل") || head.startsWith("نجح") || head.startsWith("توقف")) sb.append("الحالة: ").append(head).append('\n');
        String failedTask = firstMatch(text, "(?m)^> Task (\\S+) FAILED");
        if (failedTask != null) sb.append("المهمة الفاشلة: ").append(failedTask).append('\n');
        String gradleV = firstMatch(text, "gradle-(\\d+\\.\\d+(?:\\.\\d+)?)-bin");
        String agpV = firstMatch(text, "com\\.android\\.tools\\.build:gradle:([\\d.]+)");
        String javaV = firstMatch(text, "JAVA_VERSION=([\\w.\\-]+)");
        StringBuilder env = new StringBuilder();
        if (gradleV != null) env.append("Gradle ").append(gradleV).append("  ");
        if (agpV != null) env.append("AGP ").append(agpV).append("  ");
        if (javaV != null) env.append("Java ").append(javaV).append("  ");
        if (env.length() > 0) sb.append("الإصدارات: ").append(env.toString().trim()).append('\n');
        sb.append("عدد أسطر الناتج: ").append(n).append(" • أخطاء تجميع: ").append(compile.size())
          .append(" • أخطاء أخرى: ").append(errs.size()).append('\n');
        String wrong = null;
        for (int i = 0; i < n; i++) {
            if (lines[i].contains("What went wrong")) {
                int k = i + 1;
                while (k < n && lines[k].trim().isEmpty()) k++;
                if (k < n) { wrong = lines[k].trim(); }
                break;
            }
        }
        if (wrong != null) sb.append("سبب الفشل حسب Gradle: ").append(wrong).append('\n');

        // الملفات المطلوب تعديلها
        if (!compile.isEmpty()) {
            java.util.LinkedHashMap<String, java.util.ArrayList<String>> byFile = new java.util.LinkedHashMap<>();
            for (String key : compile.keySet()) {
                String fl = key.substring(0, key.indexOf('|'));
                int ci = fl.lastIndexOf(':');
                String f = fl.substring(0, ci), l = fl.substring(ci + 1);
                if (!byFile.containsKey(f)) byFile.put(f, new java.util.ArrayList<String>());
                byFile.get(f).add(l);
            }
            sb.append("\n-- الملفات المطلوب فحصها --\n");
            for (java.util.Map.Entry<String, java.util.ArrayList<String>> e : byFile.entrySet()) {
                sb.append("• ").append(e.getKey()).append("  ← سطر ").append(android.text.TextUtils.join("، ", e.getValue())).append('\n');
            }
            sb.append("\n-- أخطاء التجميع --\n");
            for (String key : compile.keySet()) {
                sb.append(compile.get(key));
                int cnt = compileCount.get(key);
                if (cnt > 1) sb.append("\n  (تكرر ").append(cnt).append(" مرات في الناتج)");
                sb.append("\n\n");
            }
        }

        // ---- (د) بقية الأخطاء مع السياق ----
        if (!errs.isEmpty()) {
            boolean[] keep = new boolean[n];
            boolean[] isErr = new boolean[n];
            for (int e : errs) {
                isErr[e] = true;
                int ps = e, pe = e;
                while (ps > 0 && e - ps < MAX_OWN && !lines[ps - 1].trim().isEmpty()) ps--;
                while (pe < n - 1 && pe - e < MAX_OWN && !lines[pe + 1].trim().isEmpty()) pe++;
                int b = ps - 1;
                while (b >= 0 && lines[b].trim().isEmpty()) b--;
                int bEnd = b, cnt = 0;
                while (b >= 0 && !lines[b].trim().isEmpty() && cnt < MAX_PARA) { b--; cnt++; }
                int bStart = b + 1;
                int a = pe + 1;
                while (a < n && lines[a].trim().isEmpty()) a++;
                int aStart = a;
                cnt = 0;
                while (a < n && !lines[a].trim().isEmpty() && cnt < MAX_PARA) { a++; cnt++; }
                int aEnd = a - 1;
                for (int i = ps; i <= pe; i++) if (!inCompile[i] && !STACK_FRAME_RE.matcher(lines[i]).find() && !NOISE_RE.matcher(lines[i]).find()) keep[i] = true;
                if (bEnd >= bStart && bEnd >= 0) for (int i = bStart; i <= bEnd; i++) if (!inCompile[i] && !STACK_FRAME_RE.matcher(lines[i]).find() && !NOISE_RE.matcher(lines[i]).find()) keep[i] = true;
                if (aEnd >= aStart && aStart < n) for (int i = aStart; i <= aEnd; i++) if (!inCompile[i] && !STACK_FRAME_RE.matcher(lines[i]).find() && !NOISE_RE.matcher(lines[i]).find()) keep[i] = true;
            }
            sb.append("-- ملخص الأخطاء الأخرى --\n");
            int shown = 0;
            for (int e : errs) {
                String t = lines[e].trim();
                int c = genericCount.get(t);
                if (t.length() > 180) t = t.substring(0, 180) + "…";
                if (shown++ < 40) sb.append(e + 1).append(": ").append(t).append(c > 1 ? "  (×" + c + ")" : "").append('\n');
            }
            if (errs.size() > 40) sb.append("… و").append(errs.size() - 40).append(" أخرى\n");
            sb.append("\n-- التفاصيل مع السياق (الرقم = سطر الناتج الأصلي، > = سطر خطأ، تتبّع الاستثناءات مطويّ) --\n");
            int i = 0;
            boolean first = true;
            while (i < n) {
                if (!keep[i]) { i++; continue; }
                if (!first) {
                    int gs = i - 1;
                    while (gs >= 0 && !keep[gs]) gs--;
                    sb.append("   ⋯ (محذوف: ").append(gs + 2).append("–").append(i).append(") ⋯\n");
                } else if (i > 0) {
                    sb.append("   ⋯ (محذوف: 1–").append(i).append(") ⋯\n");
                }
                first = false;
                while (i < n && keep[i]) {
                    sb.append(String.format(java.util.Locale.US, "%5d%s ", i + 1, isErr[i] ? ">" : "|")).append(lines[i]).append('\n');
                    i++;
                }
            }
            int last = n - 1;
            while (last >= 0 && !keep[last]) last--;
            if (last < n - 1) sb.append("   ⋯ (محذوف: ").append(last + 2).append("–").append(n).append(") ⋯\n");
        }
        return sb.toString();
    }

    private void btnGridInit() {
        btnGrid = new LinearLayout(this);
        btnGrid.setOrientation(LinearLayout.VERTICAL);
        btnRow = null;
    }

    private void btnGrid(Button b) {
        if (btnGrid == null) btnGridInit();
        b.setTextSize(13);
        b.setAllCaps(false);
        b.setMinHeight(0);
        b.setMinimumHeight(0);
        if (btnRow == null || btnRow.getChildCount() >= 2) {
            btnRow = new LinearLayout(this);
            btnRow.setOrientation(LinearLayout.HORIZONTAL);
            btnGrid.addView(btnRow, new LinearLayout.LayoutParams(-1, -2));
        }
        btnRow.addView(b, new LinearLayout.LayoutParams(0, -2, 1f));
    }

    private void btnGridFlush() {
        if (btnRow != null && btnRow.getChildCount() == 1) {
            View pad = new View(this);
            btnRow.addView(pad, new LinearLayout.LayoutParams(0, 1, 1f));
        }
    }

    private void addSectionHeader(String title) {
        if (btnGrid == null) btnGridInit();
        float d = getResources().getDisplayMetrics().density;
        TextView header = new TextView(this);
        header.setText(title);
        header.setTextSize(13);
        header.setTypeface(null, Typeface.BOLD);
        int proC = proSectionBegin(title);
        header.setTextColor(proC != 0 ? proC : themeTextSecondary());
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(-1, -2);
        lp.topMargin = (int) (18 * d);
        lp.bottomMargin = (int) (6 * d);
        btnGrid.addView(header, lp);
    }

    private void addCard(String icon, String title, String subtitle, String colorHex, Runnable action) {
        if (btnGrid == null) btnGridInit();
        float d = getResources().getDisplayMetrics().density;
        LinearLayout card = new LinearLayout(this);
        card.setOrientation(LinearLayout.HORIZONTAL);
        card.setGravity(android.view.Gravity.CENTER_VERTICAL);
        card.setPadding((int) (14 * d), (int) (12 * d), (int) (14 * d), (int) (12 * d));
        card.setClickable(true);
        card.setFocusable(true);

        android.graphics.drawable.GradientDrawable bg = new android.graphics.drawable.GradientDrawable();
        bg.setColor(themeCardBg());
        bg.setCornerRadius(12 * d);
        bg.setStroke(themeStrokeW(d), themeCardStroke());
        card.setBackground(bg);

        View iconView = makeIconBadge(icon, colorHex, 38, 18);
        LinearLayout.LayoutParams iconLp = new LinearLayout.LayoutParams((int) (38 * d), (int) (38 * d));
        iconLp.rightMargin = (int) (12 * d);
        card.addView(iconView, iconLp);

        LinearLayout textCol = new LinearLayout(this);
        textCol.setOrientation(LinearLayout.VERTICAL);
        TextView titleView = new TextView(this);
        titleView.setText(title);
        titleView.setTextSize(15);
        titleView.setTypeface(null, Typeface.BOLD);
        titleView.setTextColor(themeTextPrimary());
        textCol.addView(titleView);
        if (subtitle != null && !subtitle.isEmpty()) {
            TextView subView = new TextView(this);
            subView.setText(subtitle);
            subView.setTextSize(12);
            subView.setTextColor(themeTextSecondary());
            textCol.addView(subView);
        }
        card.addView(textCol, new LinearLayout.LayoutParams(0, -2, 1f));

        TextView arrow = new TextView(this);
        arrow.setText("‹");
        arrow.setTextSize(18);
        arrow.setGravity(android.view.Gravity.CENTER);
        arrow.setTextColor(iconContrastColor(android.graphics.Color.parseColor(colorHex), themeCardBg()));
        android.graphics.drawable.GradientDrawable arrowBg = new android.graphics.drawable.GradientDrawable();
        arrowBg.setShape(android.graphics.drawable.GradientDrawable.OVAL);
        arrowBg.setColor(android.graphics.Color.parseColor("#33888888"));
        arrow.setBackground(arrowBg);
        LinearLayout.LayoutParams arrowLp = new LinearLayout.LayoutParams((int) (40 * d), (int) (40 * d));
        arrowLp.leftMargin = (int) (10 * d);
        card.addView(arrow, arrowLp);

        card.setOnClickListener(v -> action.run());

        LinearLayout.LayoutParams cardLp = new LinearLayout.LayoutParams(-1, -2);
        cardLp.bottomMargin = (int) (8 * d);
        btnGrid.addView(card, cardLp);
    }

    // زر رجوع واضح: كبسولة بخلفية وسهم ونص «رجوع» (بدل الرمز الصغير ‹)
