    private Button makeOutIconBtn(String icon, Runnable action) {
        Button b = new Button(this);
        b.setText(icon);
        b.setTextSize(20);
        b.setAllCaps(false);
        b.setMinWidth(0);
        b.setMinimumWidth(0);
        b.setMinHeight(0);
        b.setMinimumHeight(0);
        b.setPadding(dp(10), dp(8), dp(10), dp(8));
        android.util.TypedValue outValue = new android.util.TypedValue();
        getTheme().resolveAttribute(android.R.attr.selectableItemBackgroundBorderless, outValue, true);
        b.setBackgroundResource(outValue.resourceId);
        b.setTextColor(android.graphics.Color.parseColor("#E8E8E8"));
        LinearLayout.LayoutParams ilp = new LinearLayout.LayoutParams(-2, -2);
        ilp.leftMargin = dp(3);
        ilp.rightMargin = dp(3);
        b.setLayoutParams(ilp);
        b.setOnClickListener(v -> action.run());
        return b;
    }

    private void clearOutput() {
        if (out != null) out.setText("");
        Toast.makeText(this, "تم مسح الناتج", Toast.LENGTH_SHORT).show();
    }

    private android.app.Dialog taskDialog;
    private TextView taskDialogText;
    private ScrollView taskDialogScroll;
    private Button taskRestoreBtn;
    private volatile boolean taskUiStopped = false;

    private void showTaskRestoreBtn() {
        // الزر العائم "الناتج ▲" أُلغي نهائيًا بطلب المستخدم — هذي الدالة لا تفعل شيئًا الآن.
    }

    private void hideTaskRestoreBtn() {
        if (taskRestoreBtn != null) {
            android.view.ViewParent pp = taskRestoreBtn.getParent();
            if (pp instanceof android.view.ViewGroup) ((android.view.ViewGroup) pp).removeView(taskRestoreBtn);
            taskRestoreBtn = null;
        }
    }

    private void openFullscreenOutput() {
        showOutputDialog(out != null ? out.getText().toString() : "");
    }

    private void showOutputDialog(String s) {
        showOutputDialog(s, false);
    }

    // fromLegacyMenu=true: يضيف زر "◀ القائمة" صريح للرجوع للشاشة القديمة (تبقى محفوظة تحت النافذة أصلًا)
    private void showOutputDialog(String s, boolean fromLegacyMenu) {
        if (taskDialog != null && taskDialog.isShowing()) {
            taskDialogText.setText(s);
            return;
        }
        final android.app.Dialog dlg = new android.app.Dialog(this, android.R.style.Theme_Black_NoTitleBar_Fullscreen);
        LinearLayout r = new LinearLayout(this);
        r.setOrientation(LinearLayout.VERTICAL);
        r.setBackgroundColor(android.graphics.Color.parseColor("#1E1E1E"));

        // شريط «رجوع» عريض: يظهر إذا جاء الناتج بعد إغلاق قائمة/شاشة (مثل التنظيفات)
        final LinearLayout outBackBar = makeNavBackBar(() -> dlg.dismiss());
        r.addView(outBackBar, new LinearLayout.LayoutParams(-1, -2));
        termUpdateBackBtns();

        LinearLayout header = new LinearLayout(this);
        header.setOrientation(LinearLayout.HORIZONTAL);
        header.setGravity(android.view.Gravity.CENTER_VERTICAL);
        header.setBackgroundColor(android.graphics.Color.parseColor("#2D2D2D"));
        int p = dp(12);
        header.setPadding(p, p, p, p);

        if (fromLegacyMenu) {
            Button backBtn = new Button(this);
            backBtn.setText("\u25C0 القائمة");
            backBtn.setAllCaps(false);
            backBtn.setSingleLine(true);
            backBtn.setTextSize(13);
            backBtn.setTextColor(android.graphics.Color.WHITE);
            android.graphics.drawable.GradientDrawable backBg = new android.graphics.drawable.GradientDrawable();
            backBg.setColor(android.graphics.Color.parseColor("#1976D2"));
            backBg.setCornerRadius(dp(8));
            backBtn.setBackground(backBg);
            backBtn.setPadding(dp(12), dp(6), dp(12), dp(6));
            backBtn.setMinWidth(0);
            backBtn.setMinimumWidth(0);
            backBtn.setMinHeight(0);
            backBtn.setMinimumHeight(0);
            backBtn.setOnClickListener(v -> dlg.dismiss());
            LinearLayout.LayoutParams backLp = new LinearLayout.LayoutParams(-2, -2);
            backLp.rightMargin = dp(8);
            header.addView(backBtn, backLp);
        }

        TextView title = new TextView(this);
        title.setText("الناتج");
        title.setTextColor(android.graphics.Color.WHITE);
        title.setTextSize(15);
        title.setTypeface(null, Typeface.BOLD);
        header.addView(title, new LinearLayout.LayoutParams(0, -2, 1f));

        final TextView full = new TextView(this);
        full.setTypeface(Typeface.MONOSPACE);
        full.setTextSize(13);
        full.setTextColor(0xFFD4D4D4);
        full.setPadding(p, p, p, p);
        full.setTextIsSelectable(true);
        full.setTextDirection(View.TEXT_DIRECTION_LTR);
        full.setText(s);

        header.addView(makeOutIconBtn("\uD83D\uDCCB", () -> safeCopyToClipboard("out", full.getText())));
        header.addView(makeOutIconBtn("\u26A0", () -> copyErrorsOnly(full.getText())));
        header.addView(makeOutIconBtn("\uD83D\uDCE4", () -> shareText(full.getText().toString())));
        header.addView(makeOutIconBtn("\uD83D\uDDD1", () -> {
            full.setText("");
            clearOutput();
        }));
        header.addView(makeOutIconBtn("\u23F9", () -> {
            taskUiStopped = true;
            busy = false;
            dlg.dismiss();
            hideTaskRestoreBtn();
            Toast.makeText(this, "تم إيقاف عرض الناتج (قد تستمر العملية بالخلفية)", Toast.LENGTH_LONG).show();
        }));
        header.addView(makeOutIconBtn("\u2013", () -> {
            dlg.hide();
            showTaskRestoreBtn();
        }));
        header.addView(makeOutIconBtn("\u2715", () -> dlg.dismiss()));
        r.addView(header, new LinearLayout.LayoutParams(-1, -2));

        ScrollView fsv = new ScrollView(this);
        fsv.addView(full);
        r.addView(fsv, new LinearLayout.LayoutParams(-1, 0, 1f));

        // شريط إدخال أوامر داخل شاشة الناتج نفسها — لمن يريد العمل من هنا مباشرة بدل الرجوع للمحرر الرئيسي
        LinearLayout inBar = new LinearLayout(this);
        inBar.setOrientation(LinearLayout.VERTICAL);
        inBar.setBackgroundColor(android.graphics.Color.parseColor("#2D2D2D"));
        inBar.setPadding(p, p, p, p);

        View inDiv = new View(this);
        inDiv.setBackgroundColor(android.graphics.Color.parseColor("#404040"));
        r.addView(inDiv, new LinearLayout.LayoutParams(-1, dp(1)));

        final android.widget.EditText dlgInput = new android.widget.EditText(this);
        dlgInput.setTypeface(Typeface.MONOSPACE);
        dlgInput.setTextSize(13);
        dlgInput.setTextColor(0xFFD4D4D4);
        dlgInput.setHintTextColor(0xFF808080);
        dlgInput.setHint("sh / python3  (المجلد: /proj)");
        dlgInput.setTextDirection(View.TEXT_DIRECTION_LTR);
        dlgInput.setGravity(android.view.Gravity.TOP | android.view.Gravity.START);
        dlgInput.setSingleLine(false);
        tuneMultiLineInput(dlgInput, 2, 5);
        dlgInput.addTextChangedListener(new android.text.TextWatcher() {
            public void beforeTextChanged(CharSequence s2, int a, int b, int c) {}
            public void onTextChanged(CharSequence s2, int a, int b, int c) {}
            public void afterTextChanged(android.text.Editable e) { applyShHighlight(e); }
        });
        inBar.addView(dlgInput, new LinearLayout.LayoutParams(-1, -2));

        android.widget.HorizontalScrollView dlgBtnScroll = new android.widget.HorizontalScrollView(this);
        dlgBtnScroll.setHorizontalScrollBarEnabled(false);
        LinearLayout dlgRow = new LinearLayout(this);
        dlgRow.setOrientation(LinearLayout.HORIZONTAL);
        int dlgRowPad = dp(4);
        LinearLayout.LayoutParams dlgTopMargin = new LinearLayout.LayoutParams(-1, -2);
        dlgTopMargin.topMargin = dp(8);

        Runnable execFromDlg = () -> {
            String s2 = dlgInput.getText().toString();
            if (s2.trim().isEmpty()) return;
            termHist.add(s2);
            termHistPos = termHist.size();
            dlgInput.setText("");
            termExecLive(s2);
        };
        String[] dlgNames = {"تنفيذ", "إيقاف", "لصق", "مسح الإدخال"};
        String[] dlgColors = {"#4CAF50", "#F44336", "#3F51B5", "#FF9800"};
        Runnable[] dlgActions = {
                execFromDlg,
                () -> {
                    Process pr = termProc;
                    if (pr != null) {
                        killProcessTree(pr);
                        termProc = null;
                        busy = false;
                        Toast.makeText(this, "تم إيقاف العملية وإلغاؤها بالقوة", Toast.LENGTH_SHORT).show();
                    } else {
                        Toast.makeText(this, "لا توجد عملية جارية", Toast.LENGTH_SHORT).show();
                    }
                },
                () -> {
                    try {
                        ClipboardManager cm = (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
                        if (cm != null && cm.hasPrimaryClip() && cm.getPrimaryClip().getItemCount() > 0) {
                            CharSequence cs = cm.getPrimaryClip().getItemAt(0).coerceToText(this);
                            if (cs != null) dlgInput.setText(cs.toString());
                        }
                    } catch (Exception ignored) {}
                },
                () -> dlgInput.setText("")
        };
        for (int i = 0; i < dlgNames.length; i++) {
            Button bt = new Button(this);
            bt.setText(dlgNames[i]);
            bt.setAllCaps(false);
            bt.setSingleLine(true);
            bt.setTextSize(14);
            bt.setTextColor(android.graphics.Color.WHITE);
            bt.setTypeface(null, Typeface.BOLD);
            android.graphics.drawable.GradientDrawable btBg = new android.graphics.drawable.GradientDrawable();
            btBg.setColor(android.graphics.Color.parseColor(dlgColors[i]));
            btBg.setCornerRadius(dp(10));
            bt.setBackground(btBg);
            bt.setPadding(dp(14), dp(8), dp(14), dp(8));
            bt.setMinWidth(0);
            bt.setMinimumWidth(0);
            bt.setMinHeight(0);
            bt.setMinimumHeight(0);
            final Runnable act = dlgActions[i];
            bt.setOnClickListener(v -> act.run());
            LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(-2, -2);
            lp.setMarginEnd(dlgRowPad);
            dlgRow.addView(bt, lp);
        }
        dlgBtnScroll.addView(dlgRow);
        inBar.addView(dlgBtnScroll, dlgTopMargin);
        r.addView(inBar, new LinearLayout.LayoutParams(-1, -2));

        dlg.setContentView(r);
        dlg.setOnDismissListener(d -> { navBackBars.remove(outBackBar); taskDialog = null; taskDialogText = null; taskDialogScroll = null; hideTaskRestoreBtn(); });
        taskDialog = dlg;
        taskDialogText = full;
        taskDialogScroll = fsv;
        dlg.show();
        fsv.post(() -> fsv.fullScroll(View.FOCUS_DOWN));
    }

