    @Override
    protected void onCreate(Bundle b) {
        super.onCreate(b);
        try { System.setProperty("java.net.preferIPv6Addresses", "true"); } catch (Throwable ignored) {}
        live = this;
        new android.os.Handler(android.os.Looper.getMainLooper()).post(this::checkAutoExtract);
        if (Build.VERSION.SDK_INT < 29 && checkSelfPermission(Manifest.permission.WRITE_EXTERNAL_STORAGE) != PackageManager.PERMISSION_GRANTED) {
            requestPermissions(new String[]{Manifest.permission.WRITE_EXTERNAL_STORAGE}, 100);
        }
        applyKeepOn();
        new Thread(() -> {
            try {
                if (!buildRunning) {
                    final List<String> rec = TargetApplier.recoverStaleAll(projectsDir());
                    if (!rec.isEmpty()) runOnUiThread(() -> android.widget.Toast.makeText(this, "استُعيدت ملفات gradle الأصلية للمشاريع: " + rec, android.widget.Toast.LENGTH_LONG).show());
                }
            } catch (Throwable ignored) {}
        }).start();
        BuildService.restoreIfEnabled(this);
        termHome();
        new Thread(() -> {
            try { if (!busy) cleanCacheTemp(false); } catch (Throwable ignored) {}
        }).start();
    }

    @Override
    protected void onResume() {
        super.onResume();
        live = this;
        BuildService.restoreIfEnabled(this);
        offerResumeInterruptedBuild();
        // إن كانت هناك عملية جارية بدأتها نسخة سابقة من الواجهة، أعد رسم ناتجها الحالي.
        if (busy && out != null) termRenderBlocks();
        swRefresh();
        // انتهى بناء والتطبيق في الخلفية: اعرض لافتة التثبيت الآن بعد عودة المستخدم.
        final File pend = pendingInstallApk;
        if (pend != null) {
            pendingInstallApk = null;
            if (pend.isFile()) new android.os.Handler(android.os.Looper.getMainLooper()).post(() -> showInstallPrompt(pend));
        }
        // عملية انقطعت (قُتل التطبيق أو أُعيد تشغيل الهاتف قبل انتهائها): اعرض خيار الاستئناف.
        new android.os.Handler(android.os.Looper.getMainLooper()).post(this::checkInterruptedTask);
        // GitHub: افتح البناء الذي ضُغط إشعاره، واستأنف مراقبة عمليات بناء لم تنتهِ.
        new android.os.Handler(android.os.Looper.getMainLooper()).post(() -> {
            try { ghHandleNotificationIntent(); ghResumeWatches(); } catch (Throwable ignored) {}
        });
    }

    private void checkInterruptedTask() {
        if (interruptedDialogOpen || busy || isFinishing() || !BuildService.hasInterrupted(this)) return;
        android.content.SharedPreferences sp = uiPrefs();
        final String kind = sp.getString("rt_kind", "");
        final String name = sp.getString("rt_name", "");
        final String text = sp.getString("rt_text", "");
        long ts = sp.getLong("rt_ts", 0);
        if (kind.isEmpty()) return;
        // فُتح التطبيق تلقائيًا من الخدمة/المراقب بعد قتل العملية: استأنف فورًا بلا مربع حوار،
        // ثم أعد التطبيق للخلفية ليواصل العمل كما كان.
        final boolean autoBg = getIntent() != null && getIntent().getBooleanExtra("auto_resume", false);
        if (autoBg) {
            getIntent().removeExtra("auto_resume");
            final boolean isB = "build".equals(kind);
            boolean ok = isB ? !name.isEmpty() : (!name.isEmpty() && !text.trim().isEmpty());
            if (ok) {
                BuildService.clearTaskNote(this);
                if (isB) startTask(() -> buildExisting(name));
                else startTask(() -> termRun(name, text));
                new android.os.Handler(android.os.Looper.getMainLooper()).postDelayed(() -> {
                    try { moveTaskToBack(true); } catch (Throwable ignored) {}
                }, 2500);
                return;
            }
        }
        interruptedDialogOpen = true;
        String when = ts > 0 ? new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", java.util.Locale.US).format(new java.util.Date(ts)) : "";
        boolean isBuild = "build".equals(kind);
        String cmdShort = text.length() > 80 ? text.substring(0, 80) + "…" : text;
        String what = isBuild ? "بناء المشروع «" + name + "»" : "أمر في المشروع «" + name + "»:\n" + cmdShort;
        String msg = what + "\n\nانقطع قبل أن ينتهي" + (when.isEmpty() ? "" : " (بدأ " + when + ")")
                + " — غالبًا لأن النظام قتل التطبيق أو أُعيد تشغيل الهاتف.\n\n"
                + (isBuild ? "الاستئناف يعيد البناء من البداية (ويستفيد Gradle مما أنجزه سابقًا)." : "الاستئناف يعيد تنفيذ الأمر من البداية.");
        final boolean canResume = isBuild ? !name.isEmpty() : (!name.isEmpty() && !text.trim().isEmpty());
        android.app.AlertDialog.Builder b = new NavAlertBuilder().setTitle("انقطعت عملية سابقة").setMessage(msg);
        if (canResume) {
            b.setPositiveButton("استئناف", (d, w) -> {
                interruptedDialogOpen = false;
                BuildService.clearTaskNote(this);
                if (isBuild) startTask(() -> buildExisting(name));
                else startTask(() -> termRun(name, text));
            });
        }
        b.setNegativeButton("تجاهل", (d, w) -> {
            interruptedDialogOpen = false;
            BuildService.clearTaskNote(this);
        });
        final android.app.AlertDialog dlg = b.show();
        if (dlg != null) dlg.setOnDismissListener(x -> interruptedDialogOpen = false);
        // استئناف تلقائي بعد 3 ثوانٍ (يمكن للمستخدم الضغط «تجاهل» أو «استئناف» قبلها).
        // حماية: لا أكثر من 5 استئنافات تلقائية متتالية خلال دقيقتين حتى لا تدور الحلقة إلى ما لا نهاية.
        if (canResume && dlg != null) {
            if (!BuildService.consumeAutoResume(this)) return;
            final android.os.Handler h = new android.os.Handler(android.os.Looper.getMainLooper());
            final int[] left = {3};
            final Runnable tick = new Runnable() {
                @Override public void run() {
                    if (!dlg.isShowing()) return; // أغلقه المستخدم يدويًا (تجاهل/استئناف)
                    android.widget.Button pb = dlg.getButton(android.app.AlertDialog.BUTTON_POSITIVE);
                    if (left[0] <= 0) {
                        if (pb != null) pb.performClick(); // نفس مسار زر «استئناف»
                        return;
                    }
                    if (pb != null) pb.setText("استئناف (" + left[0] + ")");
                    left[0]--;
                    h.postDelayed(this, 1000);
                }
            };
            h.post(tick);
        }
    }

    @Override
    protected void onNewIntent(Intent intent) {
        super.onNewIntent(intent);
        setIntent(intent);
        if (intent != null && intent.getBooleanExtra("auto_resume", false)) {
            new android.os.Handler(android.os.Looper.getMainLooper()).post(this::checkInterruptedTask);
        }
        if (intent != null && intent.getBooleanExtra("l2s_pick_project", false)) {
            intent.removeExtra("l2s_pick_project");
            new android.os.Handler(android.os.Looper.getMainLooper()).post(() -> legacyPickFile(PICK_PROJECT));
        }
    }

