    protected void onDestroy() {
        if (live == this) live = null;
        super.onDestroy();
    }

    private String installGitCurl() {
        File base = toolsBase();
        File rootfs = findRoot(new File(getFilesDir(), "rootfs"), 2);
        if (rootfs == null || !new File(base, "bin/proot").exists()) {
            return "أولًا أكمل الخطوتين 1 و2 (الأدوات وDebian).";
        }
        progress("يتحقق من git وcurl...");
        Res chk = guestRun(base, rootfs, false, null, "/bin/sh", "-c", "command -v git && command -v curl");
        if (chk.code == 0) {
            return "git وcurl مثبّتان مسبقًا.\n\n" + chk.text;
        }
        progress("جارٍ تثبيت git وcurl (يحتاج إنترنت، قد يستغرق دقيقة)...");
        String script = "echo nameserver 8.8.8.8 > /etc/resolv.conf; apt-get update -y && apt-get install -y git curl";
        String r = guest(base, rootfs, script.startsWith("echo") ? null : null, "/bin/sh", "-c", script);
        Res chk2 = guestRun(base, rootfs, false, null, "/bin/sh", "-c", "git --version; curl --version | head -1");
        return "== نتيجة التثبيت ==\n" + r + "\n== التحقق ==\n" + chk2.text;
    }

    private String installPython() {
        File base = toolsBase();
        File rootfs = findRoot(new File(getFilesDir(), "rootfs"), 2);
        if (rootfs == null || !new File(base, "bin/proot").exists()) {
            return "أولًا أكمل الخطوتين 1 و2 (الأدوات وDebian).";
        }
        progress("يتحقق من بايثون...");
        Res chk = guestRun(base, rootfs, false, null, "/bin/sh", "-c", "command -v python3 && python3 --version && command -v pip3");
        if (chk.code == 0) {
            return "بايثون مثبّت مسبقًا.\n\n" + chk.text;
        }
        progress("جارٍ تثبيت بايثون وpip (يحتاج إنترنت، قد يستغرق دقيقة)...");
        String script = "echo nameserver 8.8.8.8 > /etc/resolv.conf; apt-get update -y && apt-get install -y python3 python3-pip";
        String r = guest(base, rootfs, null, "/bin/sh", "-c", script);
        Res chk2 = guestRun(base, rootfs, false, null, "/bin/sh", "-c", "python3 --version; pip3 --version");
        return "== نتيجة التثبيت ==\n" + r + "\n== التحقق ==\n" + chk2.text;
    }

