    private void pickFile(int code) {
        Intent i = new Intent(Intent.ACTION_OPEN_DOCUMENT);
        i.addCategory(Intent.CATEGORY_OPENABLE);
        i.setType("*/*");
        startActivityForResult(i, code);
    }

    // نفس pickFile لكن تسمح باختيار أكثر من ملف دفعة وحدة (خاصة حاليًا بـ"استيراد ذكي").
    private void pickFileMulti(int code) {
        if (code == PICK_SMART) { smartImportEntry(); return; }
        pickFileMultiAt(code, null);
    }

    private void pickFileMultiAt(int code, String initialUri) {
        Intent i = new Intent(Intent.ACTION_OPEN_DOCUMENT);
        i.addCategory(Intent.CATEGORY_OPENABLE);
        i.setType("*/*");
        i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true);
        if (initialUri != null && Build.VERSION.SDK_INT >= 26) {
            try { i.putExtra(android.provider.DocumentsContract.EXTRA_INITIAL_URI, Uri.parse(initialUri)); }
            catch (Throwable ignored) {}
        }
        startActivityForResult(i, code);
    }

    // ------------------------------------------------------------------
    // الاستيراد الذكي: تذكّر مجلدات الاستيراد (متعددة) وفتح المنتقي عليها مباشرة.
    // ------------------------------------------------------------------
    // كل سطر: uri \t label
    private java.util.ArrayList<String[]> smartPaths() {
        java.util.ArrayList<String[]> r = new java.util.ArrayList<>();
        String raw = uiPrefs().getString("smart_paths", "");
        for (String line : raw.split("\n")) {
            int t = line.indexOf('\t');
            if (t > 0) r.add(new String[]{line.substring(0, t), line.substring(t + 1)});
        }
        return r;
    }

    private void saveSmartPaths(java.util.ArrayList<String[]> l) {
        StringBuilder sb = new StringBuilder();
        for (String[] e : l) sb.append(e[0]).append('\t').append(e[1]).append('\n');
        uiPrefs().edit().putString("smart_paths", sb.toString()).apply();
    }

    // ---------------- مسارات الاستيراد اليدوية (بلا حد) + مسار خاص لكل مشروع ----------------

    private static final int PICK_IMPORT_DIR = 41;
    private int pendingDirMode = 0;            // 1 = إضافة لقائمة المسارات، 2 = ربط بمشروع
    private String pendingDirProject = "";

    private String friendlyDocLabel(String docId) {
        String l = docId.replaceFirst("^primary:", "التخزين الداخلي/").replaceFirst("/$", "");
        if (l.equals("التخزين الداخلي/")) l = "التخزين الداخلي";
        return l;
    }

    // مفتاح «عائلة المشروع»: الاسم بعد حذف لواحق النسخ (-updated-11 ، -v2 ، (3) ، _final ، -copy ...)
    // فيشترك كل تعديلات المشروع الواحد في نفس المسار حتى لو تغيّر اسم الملف مع كل نسخة.
    private String projectFamily(String proj) {
        if (proj == null) return "";
        String f = proj.toLowerCase(java.util.Locale.ROOT);
        String prev;
        do {
            prev = f;
            f = f.replaceAll("[-_.\\s]*\\(\\d+\\)$", "")
                 .replaceAll("[-_.\\s]*(updated|update|new|final|copy|v|ver|version|rev|build)?[-_.\\s]*\\d+$", "")
                 .replaceAll("[-_.\\s]+(updated|update|new|final|copy|fixed|latest)$", "");
        } while (!f.equals(prev));
        f = f.replaceAll("[-_.\\s]+$", "");
        return f.isEmpty() ? proj.toLowerCase(java.util.Locale.ROOT) : f;
    }

    private String[] parsePathValue(String v) {
        if (v == null) return null;
        int t = v.indexOf('\t');
        return t > 0 ? new String[]{v.substring(0, t), v.substring(t + 1)} : null;
    }

    // 1) ربط مباشر بهذا الاسم  2) ربط عائلة الاسم (أي نسخة سابقة)  3) null
    private String[] projectPath(String proj) {
        String[] r = parsePathValue(uiPrefs().getString("projpath:" + proj, null));
        if (r != null) return r;
        return parsePathValue(uiPrefs().getString("projfam:" + projectFamily(proj), null));
    }

    private void setProjectPath(String proj, String uri, String label) {
        uiPrefs().edit()
                .putString("projpath:" + proj, uri + "\t" + label)
                .putString("projfam:" + projectFamily(proj), uri + "\t" + label)
                .apply();
    }

    private void clearProjectPath(String proj) {
        uiPrefs().edit()
                .remove("projpath:" + proj)
                .remove("projfam:" + projectFamily(proj))
                .apply();
    }

    // آخر مجلد استُورد منه فعليًا (احتياط عندما لا يوجد ربط للمشروع)
    private void rememberLastImportPath(String uri, String label) {
        if (uri == null || uri.isEmpty()) return;
        uiPrefs().edit().putString("smart_last_path", uri + "\t" + (label == null ? "" : label)).apply();
    }

    // الدخول الرئيسي: مسار المشروع الحالي إن كان مخصصًا وكان الخيار مفعّلًا → يفتح مباشرة؛
    // وإلا قائمة المسارات المحفوظة؛ وإن لم يوجد أي مسار فالمنتقي الافتراضي.
    private void smartImportEntry() {
        String pn = currentProject();
        if (uiPrefs().getBoolean("smart_per_project", true) && pn != null && !pn.isEmpty()) {
            String[] pp = projectPath(pn);
            if (pp != null) { openPathOrPicker(pp[0], pp[1]); return; }
            // لا ربط لهذا المشروع ولا لعائلته → افتح آخر مجلد استُخدم إن وُجد
            String[] last = parsePathValue(uiPrefs().getString("smart_last_path", null));
            if (last != null) { openPathOrPicker(last[0], last[1]); return; }
        }
        int mode = uiPrefs().getInt("smart_open_mode", 0);
        if (mode == 2) { pickFileMultiAt(PICK_SMART, null); return; }   // منتقي الملفات العادي مباشرة
        if (mode == 1) {                                                // مسار افتراضي محدد مباشرة
            String dv = uiPrefs().getString("smart_default_path", null);
            int t = dv == null ? -1 : dv.indexOf('\t');
            if (t > 0) { openPathOrPicker(dv.substring(0, t), dv.substring(t + 1)); return; }
        }
        java.util.ArrayList<String[]> paths = smartPaths();
        if (paths.isEmpty()) { pickFileMultiAt(PICK_SMART, null); return; }
        showSmartPathChooser(false);
    }

    // manage=false (استيراد ذكي): قائمة المسارات المحفوظة فقط + «مكان آخر» — بلا أي إعدادات.
    // manage=true (مسارات الاستيراد من ⋮): إضافة/إعدادات/مسار المشروع، والنقر على مسار يفتح خياراته.
    private void showSmartPathChooser(final boolean manage) {
        final java.util.ArrayList<String[]> paths = smartPaths();
        final String pn = currentProject();
        final boolean hasProj = pn != null && !pn.isEmpty();
        final java.util.ArrayList<String> items = new java.util.ArrayList<>();
        for (String[] e : paths) items.add("\uD83D\uDCC2 " + e[1]);
        final int extraStart = items.size();
        if (manage) {
            items.add("\u2795 إضافة مسار جديد");
            items.add("\u2699 إعدادات المسارات");
            if (hasProj) items.add("\uD83D\uDCCC مسار المشروع «" + pn + "»");
        } else {
            items.add("\uD83D\uDD0D مكان آخر (يختاره النظام)");
        }

        final android.app.AlertDialog dlg = new NavAlertBuilder()
                .setTitle(manage ? "مسارات الاستيراد (اضغط على مسار لإدارته)" : "من أي مسار تستورد؟")
                .setItems(items.toArray(new String[0]), (d, which) -> {
                    if (which < paths.size()) {
                        if (manage) showPathOptions(paths, which);
                        else openPathOrPicker(paths.get(which)[0], paths.get(which)[1]);
                        return;
                    }
                    int k = which - extraStart;
                    if (!manage) { pickFileMultiAt(PICK_SMART, null); return; }
                    if (k == 0) pickImportFolder(1, "");
                    else if (k == 1) showPathSettings(true);
                    else if (hasProj && k == 2) showProjectPathDialog(pn);
                })
                .setOnCancelListener(d -> legacyAutoShowOutput = false)
                .create();
        dlg.show();
    }

    // ------------------------------------------------------------------
    // متصفح المسارات داخل التطبيق: يفتح مباشرة على المجلد الحقيقي المحفوظ (أي عمق:
    // Download/مجلد/مجلد آخر ...) ويتيح التنقل واختيار ملفات متعددة وحفظ أي مجلد كمسار.
    // ------------------------------------------------------------------
    private boolean isTreeDocUri(String u) {
        return u != null && u.contains("/tree/") && u.contains("/document/");
    }

    private void openPathOrPicker(String uri, String label) {
        rememberLastImportPath(uri, label);
        if (isTreeDocUri(uri)) {
            try {
                Uri du = Uri.parse(uri);
                String auth = du.getAuthority();
                String treeId = android.provider.DocumentsContract.getTreeDocumentId(du);
                String docId = android.provider.DocumentsContract.getDocumentId(du);
                Uri tree = android.provider.DocumentsContract.buildTreeDocumentUri(auth, treeId);
                new PathBrowser(tree, auth, treeId).start(docId);
                return;
            } catch (Throwable ignored) {}
        }
        pickFileMultiAt(PICK_SMART, uri);
    }

    private void saveFolderEntry(String uri, String label, boolean linkProject) {
        java.util.ArrayList<String[]> l = smartPaths();
        boolean exists = false;
        for (String[] e : l) if (e[0].equals(uri)) { exists = true; label = e[1]; break; }
        if (!exists) { l.add(new String[]{uri, label}); saveSmartPaths(l); }
        String pn = currentProject();
        if (linkProject && pn != null && !pn.isEmpty()) setProjectPath(pn, uri, label);
    }

    private class PathBrowser {
        final Uri tree;
        final String auth, treeId;
        String cur = "";
        final java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();
        final java.util.ArrayList<String[]> rows = new java.util.ArrayList<>();   // {docId, name, "1"=مجلد}
        final java.util.ArrayList<String[]> view = new java.util.ArrayList<>();   // {type, docId, text}
        final java.util.ArrayList<FileListHelper.Entry> shown = new java.util.ArrayList<>();  // العناصر بعد الفلترة والترتيب
        final java.util.HashMap<String, FileListHelper.Entry> byId = new java.util.HashMap<>();
        final FileListHelper.Prefs fprefs = FileListHelper.load(MainActivity.this);
        final java.util.LinkedHashSet<String> sel = new java.util.LinkedHashSet<>();
        android.app.AlertDialog dlg;
        TextView crumb;
        android.widget.BaseAdapter ad;

        PathBrowser(Uri tree, String auth, String treeId) {
            this.tree = tree; this.auth = auth; this.treeId = treeId;
        }

        String parentOf(String id) {
            if (id.equals(treeId)) return null;
            if (!"com.android.externalstorage.documents".equals(auth)) return null;
            int sl = id.lastIndexOf('/');
            if (sl > 0) { String p = id.substring(0, sl); if (p.startsWith(treeId)) return p; }
            return treeId;
        }

        String labelOf(String id) {
            return "com.android.externalstorage.documents".equals(auth) ? friendlyDocLabel(id) : id;
        }

        void start(final String startId) {
            final int p = dp(12);
            LinearLayout box = new LinearLayout(MainActivity.this);
            box.setOrientation(LinearLayout.VERTICAL);
            box.setPadding(p, p, p, 0);
            crumb = new TextView(MainActivity.this);
            crumb.setTextSize(12);
            crumb.setTextColor(0xFF1565C0);
            crumb.setTypeface(Typeface.MONOSPACE);
            crumb.setTextDirection(View.TEXT_DIRECTION_LTR);
            crumb.setPadding(0, 0, 0, dp(6));
            LinearLayout head = new LinearLayout(MainActivity.this);
            head.setOrientation(LinearLayout.HORIZONTAL);
            head.setGravity(android.view.Gravity.CENTER_VERTICAL);
            head.addView(crumb, new LinearLayout.LayoutParams(0, -2, 1f));
            TextView sortBtn = new TextView(MainActivity.this);
            sortBtn.setText("\u21C5 ترتيب");
            sortBtn.setTextSize(13);
            sortBtn.setTextColor(0xFFFFFFFF);
            sortBtn.setPadding(dp(12), dp(6), dp(12), dp(6));
            android.graphics.drawable.GradientDrawable sbg = new android.graphics.drawable.GradientDrawable();
            sbg.setCornerRadius(dp(14));
            sbg.setColor(0xFF1565C0);
            sortBtn.setBackground(sbg);
            sortBtn.setOnClickListener(v -> FileListHelper.showOptionsDialog(MainActivity.this, fprefs, () -> rebuild()));
            head.addView(sortBtn, new LinearLayout.LayoutParams(-2, -2));
            box.addView(head, new LinearLayout.LayoutParams(-1, -2));
            android.widget.ListView lv = new android.widget.ListView(MainActivity.this);
            ad = new android.widget.BaseAdapter() {
                @Override public int getCount() { return view.size(); }
                @Override public Object getItem(int i) { return view.get(i); }
                @Override public long getItemId(int i) { return i; }
                @Override public View getView(int i, View cv, android.view.ViewGroup parent) {
                    String[] vr = view.get(i);
                    if (vr[0].equals("dir") || vr[0].equals("file")) {
                        FileListHelper.Entry en = byId.get(vr[1]);
                        if (en != null) return FileListHelper.makeRow(MainActivity.this, en, fprefs,
                                en.dir ? null : Boolean.valueOf(sel.contains(en.id)));
                    }
                    TextView t = new TextView(MainActivity.this);
                    t.setTextSize(15);
                    t.setPadding(dp(8), dp(11), dp(8), dp(11));
                    t.setText(vr[2]);
                    return t;
                }
            };
            lv.setAdapter(ad);
            lv.setOnItemClickListener((parent, v, pos, id) -> onRow(view.get(pos)));
            box.addView(lv, new LinearLayout.LayoutParams(-1, dp(380)));

            dlg = new NavAlertBuilder()
                    .setTitle("تصفح واختيار الملفات")
                    .setView(box)
                    .setPositiveButton("استيراد", null)
                    .setNeutralButton("\uD83D\uDCBE حفظ المجلد", null)
                    .setNegativeButton("إغلاق", (d, w) -> legacyAutoShowOutput = false)
                    .create();
            dlg.show();
            dlg.getButton(android.app.AlertDialog.BUTTON_POSITIVE).setOnClickListener(v -> doImport());
            dlg.getButton(android.app.AlertDialog.BUTTON_NEUTRAL).setOnClickListener(v -> saveFolderDialog());
            load(startId);
        }

        void onRow(String[] r) {
            switch (r[0]) {
                case "up": {
                    String par = stack.isEmpty() ? parentOf(cur) : stack.pop();
                    if (par != null) load(par);
                    break;
                }
                case "dir":
                    stack.push(cur);
                    load(r[1]);
                    break;
                case "all": {
                    boolean allSel = true;
                    for (FileListHelper.Entry x : shown) if (!x.dir && !sel.contains(x.id)) { allSel = false; break; }
                    for (FileListHelper.Entry x : shown) if (!x.dir) { if (allSel) sel.remove(x.id); else sel.add(x.id); }
                    rebuild();
                    break;
                }
                case "file":
                    if (!sel.remove(r[1])) sel.add(r[1]);
                    rebuild();
                    break;
            }
        }

        void load(final String id) {
            new Thread(() -> {
                final java.util.ArrayList<String[]> r = new java.util.ArrayList<>();
                String err = null;
                try {
                    Uri kids = android.provider.DocumentsContract.buildChildDocumentsUriUsingTree(tree, id);
                    try (android.database.Cursor c = getContentResolver().query(kids, new String[]{
                            android.provider.DocumentsContract.Document.COLUMN_DOCUMENT_ID,
                            android.provider.DocumentsContract.Document.COLUMN_DISPLAY_NAME,
                            android.provider.DocumentsContract.Document.COLUMN_MIME_TYPE,
                            android.provider.DocumentsContract.Document.COLUMN_SIZE,
                            android.provider.DocumentsContract.Document.COLUMN_LAST_MODIFIED}, null, null, null)) {
                        if (c != null) while (c.moveToNext()) {
                            boolean dir = android.provider.DocumentsContract.Document.MIME_TYPE_DIR.equals(c.getString(2));
                            long sz = c.isNull(3) ? -1 : c.getLong(3);
                            long lm = c.isNull(4) ? 0 : c.getLong(4);
                            r.add(new String[]{c.getString(0), String.valueOf(c.getString(1)), dir ? "1" : "0",
                                    String.valueOf(sz), String.valueOf(lm)});
                        }
                    }
                } catch (Throwable e) { err = String.valueOf(e); }
                final String ferr = err;
                runOnUiThread(() -> {
                    if (ferr != null) {
                        Toast.makeText(MainActivity.this, "تعذّر فتح المجلد (ربما انتهت صلاحية الوصول). أعد إضافة المسار.\n" + ferr, Toast.LENGTH_LONG).show();
                        return;
                    }
                    cur = id;
                    rows.clear();
                    rows.addAll(r);
                    rebuild();
                });
            }).start();
        }

        void rebuild() {
            view.clear();
            if (!stack.isEmpty() || parentOf(cur) != null) view.add(new String[]{"up", "", "\u2B06  .."});
            java.util.ArrayList<FileListHelper.Entry> all = new java.util.ArrayList<>();
            for (String[] x : rows) {
                long sz = -1, lm = 0;
                try { sz = Long.parseLong(x[3]); lm = Long.parseLong(x[4]); } catch (Throwable ignored) {}
                FileListHelper.Entry en = new FileListHelper.Entry(x[0], x[1], x[2].equals("1"), sz, lm);
                en.uri = android.provider.DocumentsContract.buildDocumentUriUsingTree(tree, x[0]);
                all.add(en);
            }
            shown.clear();
            shown.addAll(FileListHelper.apply(all, fprefs));
            byId.clear();
            for (FileListHelper.Entry x : shown) byId.put(x.id, x);
            boolean anyFile = false;
            for (FileListHelper.Entry x : shown) if (!x.dir) { anyFile = true; break; }
            if (anyFile) view.add(new String[]{"all", "", "\u2611  تحديد كل ملفات هذا المجلد"});
            for (FileListHelper.Entry x : shown)
                view.add(new String[]{x.dir ? "dir" : "file", x.id, x.name});
            if (view.isEmpty()) view.add(new String[]{"none", "", "(مجلد فارغ)"});
            crumb.setText(labelOf(cur));
            ad.notifyDataSetChanged();
            android.widget.Button pb = dlg.getButton(android.app.AlertDialog.BUTTON_POSITIVE);
            if (pb != null) pb.setText("استيراد (" + sel.size() + ")");
        }

        void doImport() {
            if (sel.isEmpty()) {
                Toast.makeText(MainActivity.this, "اختر ملفًا واحدًا على الأقل", Toast.LENGTH_SHORT).show();
                return;
            }
            final java.util.ArrayList<Uri> us = new java.util.ArrayList<>();
            for (String id : sel) us.add(android.provider.DocumentsContract.buildDocumentUriUsingTree(tree, id));
            rememberLastImportPath(android.provider.DocumentsContract.buildDocumentUriUsingTree(tree, cur).toString(), labelOf(cur));
            if (uiPrefs().getBoolean("smart_auto_save", false)) {
                String u = android.provider.DocumentsContract.buildDocumentUriUsingTree(tree, cur).toString();
                saveFolderEntry(u, labelOf(cur), uiPrefs().getBoolean("smart_auto_link", true));
            }
            dlg.dismiss();
            startTask(() -> smartScanTask(us));
            autoShowLegacyOutputIfPending();
        }

        void saveFolderDialog() {
            final String uri = android.provider.DocumentsContract.buildDocumentUriUsingTree(tree, cur).toString();
            final String label = labelOf(cur);
            final android.widget.EditText et = new android.widget.EditText(MainActivity.this);
            et.setText(label);
            final String pn = currentProject();
            final boolean hasProj = pn != null && !pn.isEmpty();
            android.app.AlertDialog.Builder b = new NavAlertBuilder()
                    .setTitle("حفظ هذا المجلد كمسار")
                    .setView(et)
                    .setPositiveButton("حفظ", (d, w) -> {
                        String nn = et.getText().toString().trim();
                        if (nn.isEmpty()) nn = label;
                        saveFolderEntry(uri, nn.replace('\t', ' ').replace('\n', ' '), false);
                        Toast.makeText(MainActivity.this, "تم حفظ المسار", Toast.LENGTH_SHORT).show();
                    })
                    .setNegativeButton("إلغاء", null);
            if (hasProj) b.setNeutralButton("حفظ وربط بـ«" + pn + "»", (d, w) -> {
                String nn = et.getText().toString().trim();
                if (nn.isEmpty()) nn = label;
                saveFolderEntry(uri, nn.replace('\t', ' ').replace('\n', ' '), true);
                Toast.makeText(MainActivity.this, "حُفظ المسار وربط بالمشروع", Toast.LENGTH_SHORT).show();
            });
            b.show();
        }
    }

    // إعدادات المسارات: قائمة بحالة كل خيار؛ النقر يبدّل الخيار أو يفتح اختياره.
    private void showPathSettings(final boolean manage) {
        final int mode = uiPrefs().getInt("smart_open_mode", 0);
        String dv = uiPrefs().getString("smart_default_path", null);
        String dl = (dv != null && dv.indexOf('\t') > 0) ? dv.substring(dv.indexOf('\t') + 1) : "غير محدد";
        String modeTxt = mode == 0 ? "عرض قائمة المسارات"
                : mode == 1 ? "فتح مباشرة من مسار: " + dl : "فتح مباشرة منتقي الملفات العادي";
        final android.app.Dialog dlg = newScreen("showPathSettings" + ":" + String.valueOf(manage), () -> showPathSettings(manage));
        navPush("showSmartPathChooser", () -> showSmartPathChooser(manage));
        LinearLayout root = beginFullscreenCardDialog(dlg, "إعدادات مسارات الاستيراد");
        LinearLayout box = (LinearLayout) root.getTag();
        addMenuCard(box, "\uD83D\uDCC2", "طريقة فتح الاستيراد الذكي", modeTxt, "#2196F3", () -> {
            dlg.dismiss();
            showOpenModeDialog(manage);
        });
        addToggleCard(box, "\uD83D\uDCBE", "حفظ تلقائي لمجلد كل ملف أستورده", null, "#4CAF50",
                uiPrefs().getBoolean("smart_auto_save", false),
                on -> { uiPrefs().edit().putBoolean("smart_auto_save", on).apply(); return true; }, null);
        addToggleCard(box, "\uD83D\uDD17", "الحفظ التلقائي يربط المجلد بالمشروع الحالي", null, "#FF9800",
                uiPrefs().getBoolean("smart_auto_link", true),
                on -> { uiPrefs().edit().putBoolean("smart_auto_link", on).apply(); return true; }, null);
        addToggleCard(box, "\uD83D\uDCC1", "كل مشروع له مساره الخاص (يفتح مباشرة)", null, "#9C27B0",
                uiPrefs().getBoolean("smart_per_project", true),
                on -> { uiPrefs().edit().putBoolean("smart_per_project", on).apply(); return true; }, null);
        dlg.setContentView(root);
        dlg.show();
    }

    // طريقة فتح «استيراد ذكي»: القائمة (الحالي) / مسار محدد مباشرة / منتقي الملفات العادي مباشرة.
    private void showOpenModeDialog(final boolean manage) {
        final String[] modes = {
                "عرض قائمة المسارات (الوضع الحالي)",
                "فتح مباشرة من مسار محدد",
                "فتح مباشرة منتقي الملفات العادي"
        };
        int cur = uiPrefs().getInt("smart_open_mode", 0);
        new NavAlertBuilder()
                .setTitle("طريقة فتح الاستيراد الذكي")
                .setSingleChoiceItems(modes, cur, (d, which) -> {
                    d.dismiss();
                    if (which == 1) {
                        chooseDefaultPath(manage);
                    } else {
                        uiPrefs().edit().putInt("smart_open_mode", which).apply();
                        showPathSettings(manage);
                    }
                })
                .setOnCancelListener(d -> showPathSettings(manage))
                .show();
    }

    private void chooseDefaultPath(final boolean manage) {
        final java.util.ArrayList<String[]> paths = smartPaths();
        if (paths.isEmpty()) {
            Toast.makeText(this, "لا توجد مسارات محفوظة. أضف مسارًا أولًا.", Toast.LENGTH_LONG).show();
            showPathSettings(manage);
            return;
        }
        final String[] labels = new String[paths.size()];
        for (int i = 0; i < labels.length; i++) labels[i] = paths.get(i)[1];
        new NavAlertBuilder()
                .setTitle("اختر المسار الذي يفتح مباشرة")
                .setItems(labels, (d, which) -> {
                    uiPrefs().edit()
                            .putInt("smart_open_mode", 1)
                            .putString("smart_default_path", paths.get(which)[0] + "\t" + paths.get(which)[1])
                            .apply();
                    showPathSettings(manage);
                })
                .setOnCancelListener(d -> showPathSettings(manage))
                .show();
    }

    // حفظ تلقائي (إن فُعّل من الإعدادات): يحفظ المجلد الأب للملف المُختار في القائمة،
    // ويربطه بالمشروع الحالي إن فُعّل خيار الربط.
    private void autoSaveSmartFolder(Uri file) {
        if (!uiPrefs().getBoolean("smart_auto_save", false)) return;
        try {
            String authority = file.getAuthority();
            String docId = android.provider.DocumentsContract.getDocumentId(file);
            if ("com.android.providers.downloads.documents".equals(authority) && docId.startsWith("raw:")) {
                String path = docId.substring(4);
                String prefix = "/storage/emulated/0/";
                if (!path.startsWith(prefix)) return;
                docId = "primary:" + path.substring(prefix.length());
                authority = "com.android.externalstorage.documents";
            }
            if (!"com.android.externalstorage.documents".equals(authority)) return;
            int slash = docId.lastIndexOf('/');
            String parentId;
            if (slash > 0) parentId = docId.substring(0, slash);
            else {
                int colon = docId.indexOf(':');
                if (colon < 0) return;
                parentId = docId.substring(0, colon + 1);
            }
            String uri = android.provider.DocumentsContract.buildDocumentUri(authority, parentId).toString();
            String label = friendlyDocLabel(parentId);
            java.util.ArrayList<String[]> l = smartPaths();
            boolean exists = false;
            for (String[] e : l) if (e[0].equals(uri)) { exists = true; label = e[1]; break; }
            if (!exists) { l.add(new String[]{uri, label}); saveSmartPaths(l); }
            String pn = currentProject();
            if (uiPrefs().getBoolean("smart_auto_link", true) && pn != null && !pn.isEmpty()) {
                setProjectPath(pn, uri, label);
            }
        } catch (Throwable ignored) {}
    }

    private void showPathOptions(final java.util.ArrayList<String[]> paths, final int idx) {
        final String[] e = paths.get(idx);
        final String pn = currentProject();
        final boolean hasProj = pn != null && !pn.isEmpty();
        final java.util.ArrayList<String> items = new java.util.ArrayList<>();
        items.add("\u270F إعادة تسمية");
        items.add("\uD83D\uDDD1 حذف");
        if (hasProj) items.add("\uD83D\uDD17 ربط بالمشروع «" + pn + "»");
        new NavAlertBuilder()
                .setTitle(e[1])
                .setItems(items.toArray(new String[0]), (d, which) -> {
                    if (which == 0) {
                        final android.widget.EditText et = new android.widget.EditText(this);
                        et.setText(e[1]);
                        new NavAlertBuilder().setTitle("الاسم").setView(et)
                                .setPositiveButton("حفظ", (d2, w2) -> {
                                    String nn = et.getText().toString().trim();
                                    if (!nn.isEmpty()) { e[1] = nn.replace('\t', ' ').replace('\n', ' '); saveSmartPaths(paths); }
                                    showSmartPathChooser(true);
                                })
                                .setNegativeButton("إلغاء", (d2, w2) -> showSmartPathChooser(true)).show();
                    } else if (which == 1) {
                        new NavAlertBuilder().setTitle("حذف المسار؟").setMessage(e[1])
                                .setPositiveButton("حذف", (d2, w2) -> {
                                    paths.remove(idx);
                                    saveSmartPaths(paths);
                                    showSmartPathChooser(true);
                                })
                                .setNegativeButton("إلغاء", (d2, w2) -> showSmartPathChooser(true)).show();
                    } else if (which == 2) {
                        setProjectPath(pn, e[0], e[1]);
                        Toast.makeText(this, "رُبط المشروع «" + pn + "» بهذا المسار", Toast.LENGTH_SHORT).show();
                        showSmartPathChooser(true);
                    }
                })
                .show();
    }

    // مسار خاص بمشروع محدد: اختيار مجلد جديد، أو من المسارات المحفوظة، أو إزالة الربط.
    private void showProjectPathDialog(final String proj) {
        String[] cur = projectPath(proj);
        final java.util.ArrayList<String[]> paths = smartPaths();
        final java.util.ArrayList<String> items = new java.util.ArrayList<>();
        items.add("\uD83D\uDCC1 اختيار مجلد جديد لهذا المشروع");
        final int fromSaved = items.size();
        if (!paths.isEmpty()) items.add("\uD83D\uDCCB اختيار من مساراتي المحفوظة");
        final int clearIdx = items.size();
        if (cur != null) items.add("\u274C إزالة مسار المشروع");
        new NavAlertBuilder()
                .setTitle("مسار «" + proj + "»: " + (cur == null ? "غير محدد" : cur[1]))
                .setItems(items.toArray(new String[0]), (d, which) -> {
                    if (which == 0) {
                        pickImportFolder(2, proj);
                    } else if (!paths.isEmpty() && which == fromSaved) {
                        final String[] labels = new String[paths.size()];
                        for (int i = 0; i < labels.length; i++) labels[i] = paths.get(i)[1];
                        new NavAlertBuilder().setTitle("اختر مسارًا للمشروع")
                                .setItems(labels, (d2, w2) -> {
                                    setProjectPath(proj, paths.get(w2)[0], paths.get(w2)[1]);
                                    Toast.makeText(this, "تم ربط المسار", Toast.LENGTH_SHORT).show();
                                }).show();
                    } else if (cur != null && which == clearIdx) {
                        clearProjectPath(proj);
                        Toast.makeText(this, "أُزيل مسار المشروع", Toast.LENGTH_SHORT).show();
                    }
                })
                .show();
    }

    private void pickImportFolder(int mode, String proj) {
        pendingDirMode = mode;
        pendingDirProject = proj == null ? "" : proj;
        Intent i = new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);
        i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION | Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);
        startActivityForResult(i, PICK_IMPORT_DIR);
    }

    private void handleImportDirResult(Uri tree) {
        if (tree == null) return;
        try {
            try { getContentResolver().takePersistableUriPermission(tree, Intent.FLAG_GRANT_READ_URI_PERMISSION); }
            catch (Throwable ignored) {}
            String docId = android.provider.DocumentsContract.getTreeDocumentId(tree);
            final String uri = android.provider.DocumentsContract.buildDocumentUriUsingTree(tree, docId).toString();
            final String label = friendlyDocLabel(docId);
            if (pendingDirMode == 2 && !pendingDirProject.isEmpty()) {
                setProjectPath(pendingDirProject, uri, label);
                Toast.makeText(this, "رُبط «" + pendingDirProject + "» بالمسار: " + label, Toast.LENGTH_LONG).show();
                return;
            }
            final android.widget.EditText et = new android.widget.EditText(this);
            et.setText(label);
            new NavAlertBuilder()
                    .setTitle("اسم المسار")
                    .setView(et)
                    .setPositiveButton("حفظ", (d, w) -> {
                        String nn = et.getText().toString().trim();
                        if (nn.isEmpty()) nn = label;
                        nn = nn.replace('\t', ' ').replace('\n', ' ');
                        java.util.ArrayList<String[]> l = smartPaths();
                        for (int k = l.size() - 1; k >= 0; k--) if (l.get(k)[0].equals(uri)) l.remove(k);
                        l.add(new String[]{uri, nn});
                        saveSmartPaths(l);
                        Toast.makeText(this, "تم حفظ المسار", Toast.LENGTH_SHORT).show();
                        showSmartPathChooser(true);
                    })
                    .setNegativeButton("إلغاء", null)
                    .show();
        } catch (Throwable e) {
            Toast.makeText(this, "تعذّر قراءة المجلد", Toast.LENGTH_SHORT).show();
        }
    }
    // نسخة خاصة بالقائمة القديمة (legacyScreen): تعلّم على أن الاختيار جاء من هناك
    // كي يفتح onActivityResult نافذة الناتج تلقائيًا بعد انتهاء اختيار الملف.
    private void legacyPickFile(int code) {
        legacyAutoShowOutput = true;
        pickFile(code);
    }

    // نفس legacyPickFile لكن تسمح باختيار عدة ملفات دفعة وحدة.
