    // ------------------------------------------------------------------
    // التعرّف على المشروع نفسه مهما تغيّر اسم ملف الـ zip
    // الهوية = rootProject.name + applicationId (أو namespace)
    // ------------------------------------------------------------------
    private static String identityFrom(String settingsText, java.util.List<String> moduleTexts) {
        String root = null, app = null;
        if (settingsText != null) {
            java.util.regex.Matcher m = java.util.regex.Pattern.compile("rootProject\\.name\\s*=\\s*['\"]([^'\"]+)['\"]").matcher(settingsText);
            if (m.find()) root = m.group(1).trim();
        }
        java.util.regex.Pattern pa = java.util.regex.Pattern.compile("applicationId\\s*=?\\s*['\"]([^'\"]+)['\"]");
        java.util.regex.Pattern pn = java.util.regex.Pattern.compile("namespace\\s*=?\\s*['\"]([^'\"]+)['\"]");
        for (String t : moduleTexts) {
            java.util.regex.Matcher m = pa.matcher(t);
            if (m.find()) { app = m.group(1).trim(); break; }
        }
        if (app == null) for (String t : moduleTexts) {
            java.util.regex.Matcher m = pn.matcher(t);
            if (m.find()) { app = m.group(1).trim(); break; }
        }
        if (root == null && app == null) return null;
        return (root == null ? "" : root) + "|" + (app == null ? "" : app);
    }

    private static File firstExisting(File d, String a, String b) {
        File x = new File(d, a);
        if (x.isFile()) return x;
        x = new File(d, b);
        return x.isFile() ? x : null;
    }

    private String dirIdentity(File proj) {
        try {
            File root = proj;
            if (firstExisting(root, "settings.gradle", "settings.gradle.kts") == null) {
                File[] ks = proj.listFiles();
                if (ks != null && ks.length == 1 && ks[0].isDirectory()) root = ks[0];
            }
            File sf = firstExisting(root, "settings.gradle", "settings.gradle.kts");
            if (sf == null) return null;
            java.util.List<String> mods = new ArrayList<>();
            File[] subs = root.listFiles();
            if (subs != null) {
                java.util.Arrays.sort(subs);
                for (File sd : subs) {
                    if (!sd.isDirectory()) continue;
                    File bf = firstExisting(sd, "build.gradle", "build.gradle.kts");
                    String t = bf == null ? null : readSmall(bf);
                    if (t == null) continue;
                    if (sd.getName().equals("app")) mods.add(0, t); else mods.add(t);
                }
            }
            return identityFrom(readSmall(sf), mods);
        } catch (Throwable t) { return null; }
    }

    // يقرأ ملفات gradle الصغيرة من داخل الـ zip دون فكّه. rootPrefix: "" أو مجلد المشروع داخل الـ zip (مثل "App/")
    private String zipIdentity(Uri u, String rootPrefix) {
        java.util.HashMap<String, String> files = new java.util.HashMap<>();
        try (InputStream in = getContentResolver().openInputStream(u);
             ZipInputStream zin = new ZipInputStream(new BufferedInputStream(in, 1 << 16))) {
            ZipEntry e;
            while ((e = zin.getNextEntry()) != null) {
                if (e.isDirectory()) continue;
                String nm = e.getName().replace('\\', '/');
                if (!nm.startsWith(rootPrefix)) continue;
                String rel = nm.substring(rootPrefix.length());
                String[] seg = rel.split("/");
                String last = seg[seg.length - 1];
                boolean cand = (last.equals("settings.gradle") || last.equals("settings.gradle.kts")) && seg.length <= 2
                        || (last.equals("build.gradle") || last.equals("build.gradle.kts")) && seg.length <= 3;
                if (!cand || files.size() >= 14) continue;
                java.io.ByteArrayOutputStream bo = new java.io.ByteArrayOutputStream();
                byte[] buf = new byte[8192];
                int k;
                while ((k = zin.read(buf)) > 0 && bo.size() < 400000) bo.write(buf, 0, k);
                files.put(rel, bo.toString("UTF-8"));
            }
        } catch (Throwable t) { return null; }
        // اختر أقرب settings.gradle إلى الجذر
        String sKey = null;
        for (String k : files.keySet()) {
            if (!(k.endsWith("settings.gradle") || k.endsWith("settings.gradle.kts"))) continue;
            if (sKey == null || k.length() < sKey.length()) sKey = k;
        }
        if (sKey == null) return null;
        String base = sKey.substring(0, sKey.lastIndexOf('/') + 1);
        java.util.List<String> mods = new ArrayList<>();
        for (java.util.Map.Entry<String, String> en : files.entrySet()) {
            String k = en.getKey();
            if (!(k.endsWith("/build.gradle") || k.endsWith("/build.gradle.kts")) || !k.startsWith(base)) continue;
            String rest = k.substring(base.length());
            if (rest.indexOf('/') != rest.lastIndexOf('/')) continue; // وحدة مباشرة فقط: module/build.gradle
            if (rest.startsWith("app/")) mods.add(0, en.getValue()); else mods.add(en.getValue());
        }
        return identityFrom(files.get(sKey), mods);
    }

    private String findProjectByIdentity(String ident) {
        if (ident == null) return null;
        File[] ds = projectsDir().listFiles();
        if (ds == null) return null;
        String best = null;
        long bestT = -1;
        for (File d : ds) {
            if (!d.isDirectory()) continue;
            if (ident.equals(dirIdentity(d)) && d.lastModified() > bestT) { best = d.getName(); bestT = d.lastModified(); }
        }
        return best;
    }

