    // ================= بناء سريع: مقارنة zip بمشروع موجود وتطبيق التغييرات فقط =================

    private static boolean fbSkipName(String n) {
        return isBuildCacheDir(n) || n.equals(".git") || n.equals("local.properties") || n.equals(".DS_Store");
    }

    // جذر المشروع الفعلي: المجلد نفسه، أو مجلده الوحيد إن كان الـ zip/المشروع داخل مجلد واحد
    private File fbEffectiveRoot(File d) {
        if (new File(d, "gradlew").exists() || firstExisting(d, "settings.gradle", "settings.gradle.kts") != null) return d;
        File[] ks = d.listFiles();
        if (ks != null && ks.length == 1 && ks[0].isDirectory()) return ks[0];
        return d;
    }

    private void fbCollect(File base, File d, java.util.Map<String, File> out, int depth) {
        if (depth > 40) return;
        File[] ks = d.listFiles();
        if (ks == null) return;
        for (File k : ks) {
            if (fbSkipName(k.getName())) continue;
            if (k.isDirectory()) fbCollect(base, k, out, depth + 1);
            else out.put(base.toURI().relativize(k.toURI()).getPath(), k);
        }
    }

    private void fbPruneEmptyDirs(File d) {
        File[] ks = d.listFiles();
        if (ks == null) return;
        for (File k : ks) {
            if (!k.isDirectory() || fbSkipName(k.getName())) continue;
            fbPruneEmptyDirs(k);
            String[] left = k.list();
            if (left != null && left.length == 0) k.delete();
        }
    }

    // يختار المشروع الهدف (المطابق بالهوية أولًا ثم المحدّد حاليًا) ويسأل المستخدم
