    private void setProjectBuildStatus(String name, boolean success) {
        uiPrefs().edit().putString("build_status_" + name, success ? "ok" : "fail").apply();
    }

    // حالة خاصة: البناء أُوقف تلقائيًا بسبب تجاوز المهلة (وليس فشلًا برمجيًا عاديًا)
    private void setProjectBuildStatusTimeout(String name) {
        uiPrefs().edit().putString("build_status_" + name, "timeout").apply();
    }

    // ترتيب «الفاشلة أولًا»: فشل (محلي أو GitHub) ثم المهلة ثم لم يُبنَ ثم الفارغ ثم الناجح
    private int projectFailRank(String name) {
        String k = projectStatusKey(name);
        if (k.equals("fail") || uiPrefs().getString("gh_status_" + name, "").equals("fail")) return 0;
        if (k.equals("timeout")) return 1;
        if (k.equals("none")) return 2;
        if (k.equals("empty")) return 3;
        return 4;
    }

    // مفتاح حالة المشروع للتصفية: empty / ok / fail / timeout / none
    private String projectStatusKey(String name) {
        String[] kids = new File(projectsDir(), name).list();
        if (kids == null || kids.length == 0) return "empty";
        String st = uiPrefs().getString("build_status_" + name, "");
        return (st.equals("ok") || st.equals("fail") || st.equals("timeout")) ? st : "none";
    }

    private String projectStatusDot(String name) {
        String[] kids = new File(projectsDir(), name).list();
        if (kids == null || kids.length == 0) return "\uD83D\uDCED فارغ \u2022 ";
        String st = uiPrefs().getString("build_status_" + name, null);
        String gh = ghStatusBadge(name);
        if ("ok".equals(st)) return "\uD83D\uDFE2 نجح " + gh + "\u2022 ";
        if ("timeout".equals(st)) return "\uD83D\uDFE0 توقف بالمهلة " + gh + "\u2022 ";
        if ("fail".equals(st)) return "\uD83D\uDD34 فشل " + gh + "\u2022 ";
        return "\u26AA لم يُبنَ " + gh + "\u2022 ";
    }

    // شارة حالة آخر بناء على GitHub (محفوظة محليًا من آخر فحص): ok / fail / running / cancelled / none
    private String ghStatusBadge(String name) {
        String g = uiPrefs().getString("gh_status_" + name, "");
        switch (g) {
            case "ok": return "| GitHub \u2705 ";
            case "fail": return "| GitHub \u274C ";
            case "running": return "| GitHub \u23F3 ";
            case "cancelled": return "| GitHub \u23F9 ";
            case "none": return "| GitHub \u26AA ";
            default: return "";
        }
    }

    // يبحث عن مجلد أي توزيعة Gradle مستخرجة سبق تنزيلها داخل gradle-home
    // (عبر بناء سابق ناجح)، ويُرجع مساره الفعلي على الجهاز (host path)،
    // لإعادة استخدامها لاحقًا (كمسار bin، أو للوصول لملف الـ zip المجاور لها).
    private File findGradleHomeDir(File gh) { return findGradleHomeDir(gh, null); }

    // يختار ذكيًا أنسب توزيعة منزَّلة للمشروع (لا يربط بإصدار معيّن)، وإن لم يجد يرجع لأي توزيعة موجودة.
    private File findGradleHomeDir(File gh, File projectDir) {
        try {
            String v = GradleAdvisor.pickInstalled(gh, projectDir, null);
            if (v != null) {
                File d = GradleAdvisor.installedDir(gh, v);
                if (d != null && new File(d, "bin/gradle").exists()) return d;
            }
        } catch (Throwable ignored) {}
        File distsDir = new File(gh, "wrapper/dists");
        File[] verDirs = distsDir.listFiles(File::isDirectory);
        if (verDirs == null) return null;
        for (File vd : verDirs) {
            File[] hashDirs = vd.listFiles(File::isDirectory);
            if (hashDirs == null) continue;
            for (File hd : hashDirs) {
                File[] gDirs = hd.listFiles(File::isDirectory);
                if (gDirs == null) continue;
                for (File gd : gDirs) {
                    if (new File(gd, "bin/gradle").exists()) return gd;
                }
            }
        }
        return null;
    }

    // يولّد تلقائيًا ملفات gradlew/gradlew.bat/gradle-wrapper.jar الناقصة لأي مشروع،
    // باستخدام أي توزيعة Gradle سبق تنزيلها على الجهاز، دون أي تدخل يدوي من المستخدم.
    // يُرجع null عند النجاح، أو رسالة خطأ توضيحية عند الفشل.
    // إعداد المستخدم لكيفية التعامل مع ملف zip المحلي الذي يبنيه التطبيق تلقائيًا
    // لتوليد wrapper بدون إنترنت: "keep" يُبقيه بلا ضغط (الأسرع)، "compressed"
    // يُبقيه لكن مضغوطًا (توازن)، "delete" يحذفه بعد كل نجاح (يوفّر المساحة).
    private String gradleLocalDistMode() {
        return uiPrefs().getString("gradle_local_dist_mode", "keep");
    }

    // يبني ملف zip محلي لتوزيعة Gradle المستخرجة بالفعل على الجهاز، بدل الاعتماد
    // على وجود ملف zip الأصلي الذي نزّلته Gradle (فبعض الإصدارات لا تحتفظ به
    // بعد الاستخراج). يُبنى مرة واحدة فقط ويُعاد استخدامه في كل مرة لاحقة، إلا إذا
    // اختار المستخدم وضع "حذف بعد النجاح" في الإعدادات.
    private File buildLocalDistZip(File gh, File gradleHomeDir) {
        try {
            File cacheDir = new File(gh, "local-dist-cache");
            cacheDir.mkdirs();
            File zipFile = new File(cacheDir, gradleHomeDir.getName() + ".zip");
            if (zipFile.exists() && zipFile.length() > 0) return zipFile;
            File tmpZip = new File(cacheDir, gradleHomeDir.getName() + ".zip.tmp");
            boolean compressed = "compressed".equals(gradleLocalDistMode());
            try (ZipOutputStream zos = new ZipOutputStream(new BufferedOutputStream(new FileOutputStream(tmpZip), 1 << 16))) {
                zos.setLevel(compressed ? Deflater.DEFAULT_COMPRESSION : Deflater.NO_COMPRESSION);
                addDirToZip(zos, gradleHomeDir, gradleHomeDir.getName());
            }
            if (tmpZip.renameTo(zipFile)) return zipFile;
            return tmpZip.exists() ? tmpZip : null;
        } catch (Exception e) {
            return null;
        }
    }

    private String autoGenerateWrapper(File base, File rootfs, File sdk, File root) {
        File gh = new File(getFilesDir(), "gradle-home");
        gh.mkdirs();
        GradleAdvisor.fixExecBits(gh); // الجذر: ملف bin/gradle قد يفقد صلاحية التنفيذ فيفشل env: Permission denied
        File gradleHomeDir = findGradleHomeDir(gh, root);
        if (gradleHomeDir == null) {
            return "تعذّر التوليد التلقائي: لا يوجد إصدار Gradle مُنزَّل بعد على الجهاز (نزّل أي إصدار من «مدير Gradle» أو ابنِ مشروعًا يحتوي wrapper مرة واحدة).";
        }
        String ghRootRel = gradleHomeDir.getAbsolutePath().substring(gh.getAbsolutePath().length());
        String gradleBinDir = "/root/.gradle" + ghRootRel + "/bin";
        new File(gradleHomeDir, "bin/gradle").setExecutable(true, false);

        // ابحث عن ملف zip التوزيعة نفسه، المحفوظ عادة بجانب المجلد المستخرج
        // (نفس مجلد الـ hash)، لاستخدامه كمصدر محلي (file://) بدل الاتصال
        // بالإنترنت للتحقق من صحة الرابط — وهو ما تفعله مهمة wrapper افتراضيًا
        // حتى لو كانت التوزيعة موجودة أصلًا، وقد يفشل لأسباب شبكة مؤقتة.
        File hashDir = gradleHomeDir.getParentFile();
        File[] zips = hashDir != null ? hashDir.listFiles((d, nm) -> nm.endsWith(".zip")) : null;
        File localZipFile = (zips != null && zips.length > 0) ? zips[0] : null;
        boolean weBuiltZip = false;
        if (localZipFile == null) {
            // لم يُعثر على ملف zip الأصلي الذي نزّلته Gradle (قد لا تحتفظ به بعض
            // الإصدارات بعد الاستخراج) — ابنِ نسخة zip محلية من التوزيعة المستخرجة
            // الموجودة فعليًا على الجهاز بدل اللجوء للشبكة إطلاقًا.
            localZipFile = buildLocalDistZip(gh, gradleHomeDir);
            weBuiltZip = localZipFile != null;
        }
        final File builtZipForCleanup = weBuiltZip ? localZipFile : null;
        String localDistUrl = null;
        if (localZipFile != null) {
            String zRel = localZipFile.getAbsolutePath().substring(gh.getAbsolutePath().length());
            localDistUrl = "file:///root/.gradle" + zRel;
        }

        // ضبط DNS احتياطًا، في حال لم يوجد zip محلي واحتجنا فعليًا للاتصال بالإنترنت.
        try {
            File rc = new File(rootfs, "etc/resolv.conf");
            Compat.deleteIfExists(rc);
            Compat.write(rc, "nameserver 8.8.8.8\nnameserver 1.1.1.1\n".getBytes(StandardCharsets.UTF_8));
        } catch (Exception ignored) {}

        File wg = new File(getCacheDir(), "wrapgen_" + System.currentTimeMillis());
        wg.mkdirs();
        try {
            Compat.write(new File(wg, "settings.gradle"), new byte[0]);
        } catch (Exception e) {
            deleteRec(wg);
            return "فشل تجهيز مجلد التوليد: " + e;
        }
        List<String> c = new ArrayList<>();
        c.add(new File(base, "bin/proot").getAbsolutePath());
        c.add("--link2symlink");
        c.add("--kill-on-exit");
        c.add("-0");
        c.add("-r");
        c.add(rootfs.getAbsolutePath());
        for (String bnd : new String[]{"/dev", "/proc", "/sys", "/system"}) {
            c.add("-b");
            c.add(bnd);
        }
        if (new File("/apex").exists()) {
            c.add("-b");
            c.add("/apex");
        }
        c.add("-b"); c.add(base.getAbsolutePath() + ":/opt/l2s");
        c.add("-b"); c.add(sdk.getAbsolutePath() + ":/opt/sdk");
        c.add("-b"); c.add(gh.getAbsolutePath() + ":/root/.gradle");
        c.add("-b"); c.add(wg.getAbsolutePath() + ":/wrapgen");
        c.add("-w");
        c.add("/wrapgen");
        c.add("/usr/bin/env");
        c.add("-i");
        c.add("HOME=/root");
        c.add("PATH=" + gradleBinDir + ":/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin");
        c.add("LANG=C.UTF-8");
        c.add("TMPDIR=/tmp");
        c.add("ANDROID_HOME=/opt/sdk");
        c.add("JAVA_HOME=/usr/lib/jvm/java-21-openjdk-arm64");
        // نشغّل سكربت gradle عبر /bin/sh صراحةً: يعمل حتى لو فُقدت صلاحية التنفيذ (الحل الجذري)
        final List<String> prefix = new ArrayList<>(c);
        final String gradleScript = gradleBinDir + "/gradle";
        List<String> c1 = new ArrayList<>(prefix);
        c1.add("/bin/sh"); c1.add(gradleScript); c1.add("wrapper");
        if (localDistUrl != null) {
            c1.add("--gradle-distribution-url");
            c1.add(localDistUrl);
        } else {
            c1.add("--gradle-version");
            c1.add(gradleVersion(root));
        }
        c1.add("--console=plain");
        Res r = exec(base, 120, 60, null, c1);
        String localAttemptLog = (localDistUrl != null) ? r.text : null;
        if (r.code != 0 && localDistUrl != null) {
            // محاولة أخيرة: إن فشل المسار المحلي لأي سبب، أعد المحاولة بالرابط الرسمي عبر الإنترنت.
            List<String> c2 = new ArrayList<>(prefix);
            c2.add("/bin/sh"); c2.add(gradleScript); c2.add("wrapper");
            c2.add("--gradle-version"); c2.add(gradleVersion(root)); c2.add("--console=plain");
            r = exec(base, 120, 60, null, c2);
        }
        if (r.code != 0) {
            deleteRec(wg);
            String msg = "فشل التوليد التلقائي لـ wrapper (رمز الخروج " + r.code + "):\n" + r.text;
            if (localAttemptLog != null) {
                msg += "\n\n--- سجل المحاولة المحلية (file://) قبل هذه: ---\n" + localAttemptLog;
            }
            return msg;
        }
        try {
            File genGradlew = new File(wg, "gradlew");
            File genGradlewBat = new File(wg, "gradlew.bat");
            File genGradleDir = new File(wg, "gradle");
            if (!genGradlew.exists() || !genGradleDir.exists()) {
                return "التوليد انتهى لكن الملفات الناتجة غير مكتملة:\n" + r.text;
            }
            fmCopyRec(genGradlew, new File(root, "gradlew"), 0);
            new File(root, "gradlew").setExecutable(true, false);
            fmCopyRec(genGradlewBat, new File(root, "gradlew.bat"), 0);
            fmCopyRec(genGradleDir, new File(root, "gradle"), 0);
        } catch (Exception e) {
            return "فشل نسخ ملفات wrapper الناتجة إلى المشروع: " + e;
        } finally {
            deleteRec(wg);
        }
        if (builtZipForCleanup != null && "delete".equals(gradleLocalDistMode())) {
            builtZipForCleanup.delete();
        }
        return null;
    }

    private String buildExisting(String name) {
        final boolean preOn = preBuildBackupEnabled();
        String ts = preOn ? backupProjectNow(name) : null;
        String r = buildProjectCore(null, name);
        boolean ok = (!preOn || ts != null) && r != null && r.startsWith("نجح البناء");
        if (ok && ts != null && goodBackupEnabled() && lastGoodProjectTs(name) == null) markProjectGood(name, ts);
        if (r != null && r.startsWith("توقف تلقائي")) {
            setProjectBuildStatusTimeout(name);
        } else if (r != null && (r.startsWith("نجح البناء") || r.startsWith("فشل البناء"))) {
            setProjectBuildStatus(name, ok);
        }
        return r;
    }

    // غلاف: ينفّذ البناء ثم (إن فُعّل الخيار) يحدّث نسخة MainActivity.java الجاهزة للمشاركة
    private String buildProjectCore(Uri u, String existing) {
        String r = buildProjectCore0(u, existing);
        try {
            if (uiPrefs().getBoolean("auto_share_main", false)) {
                String pn = existing != null ? existing : uiPrefs().getString("proj", "");
                if (pn != null && new File(projectsDir(), pn).isDirectory()) {
                    String path = exportMainShareCopy(pn);
                    if (path != null && r != null) r = r + "\n📤 حُدّثت نسخة المشاركة: " + path;
                }
            }
        } catch (Throwable ignored) {}
        return r;
    }

    private String buildProjectCore0(Uri u, String existing) {
        File base = toolsBase();
        File rootfs = findRoot(new File(getFilesDir(), "rootfs"), 2);
        File sdk = new File(getFilesDir(), "sdk");
        if (!new File(base, "bin/proot").exists()) return "أولًا الخطوة 1 (الأدوات).";
        if (rootfs == null) return "أولًا الخطوة 2 (Debian).";
        if (!new File(sdk, "platforms/android-36/android.jar").exists()) return "أولًا الخطوة 4 (SDK).";

        File proj;
        int n = 0;
        if (existing != null) {
            proj = new File(projectsDir(), existing);
            if (!proj.isDirectory()) return "المشروع غير موجود: " + existing;
        } else {
            String forced = forcedProjectName;
            forcedProjectName = null;
            proj = new File(projectsDir(), forced != null ? forced : projectName(u));
            if (proj.isDirectory() && preBuildBackupEnabled()) {
                progress("نسخة احتياطية قبل التحديث...");
                try { backupProjectNow(proj.getName()); } catch (Throwable ignored) {}
            }
            progress("يفك المشروع...");
            // نحفظ مجلدات البناء السابقة (build و.gradle و.cxx) قبل الحذف لتُستعاد بعد الفك،
            // فيواصل Gradle من حيث توقّف بدل البدء من الصفر.
            File stash = new File(getFilesDir(), "stash_" + proj.getName());
            deleteRec(stash);
            int kept = stashBuildDirs(proj, proj, stash, 0);
            deleteRec(proj);
            proj.mkdirs();
            try {
                n = unzipTo(u, proj);
            } catch (Exception e) {
                restoreBuildDirs(stash, proj);
                deleteRec(stash);
                return "فشل فك المشروع: " + e;
            }
            if (kept > 0) {
                restoreBuildDirs(stash, proj);
                progress("استُعيدت ملفات البناء السابقة لمواصلة البناء");
            }
            deleteRec(stash);
            // اختر المشروع المرفوع حديثًا تلقائيًا كمشروع حالي في المحرر بدل إبقاء الاختيار القديم.
            uiPrefs().edit().putString("proj", proj.getName()).apply();
        }
        File root = proj;
        if (!new File(root, "gradle/wrapper/gradle-wrapper.jar").exists()) {
            File[] ks = proj.listFiles();
            if (ks != null && ks.length == 1 && ks[0].isDirectory()) root = ks[0];
        }
        // لا نبدأ تنزيل Gradle أو تشغيل البناء إذا كان settings.gradle يشير إلى ملف apply-from مفقود.
        // هذا خطأ في اكتمال المشروع المستورد، وليس مشكلة Java/Gradle؛ نعرض مسار الملف والحل مباشرة.
        try {
            List<String> missingSettings = ProjectDoctor.missingSettingsScripts(root);
            if (!missingSettings.isEmpty()) {
                StringBuilder msg = new StringBuilder("توقف البناء قبل تشغيل Gradle: settings.gradle يشير إلى ملف/ملفات غير موجودة:\n");
                for (String missing : missingSettings) msg.append("• ").append(missing).append('\n');
                msg.append("\nأعد استيراد المشروع كاملًا مع مجلداته الفرعية (مثل SharedModules إن كان مطلوبًا). لا تنشئ ملفًا فارغًا بدل الملف الأصلي.\n");
                msg.append("هذا الخطأ لا يُصلَح بتغيير إصدار Java أو Gradle.");
                return msg.toString();
            }
        } catch (Throwable checkError) {
            // الفحص الإضافي لا ينبغي أن يمنع المشاريع القديمة من البناء عند تعذّر الفحص نفسه.
        }

        if (!new File(root, "gradle/wrapper/gradle-wrapper.jar").exists()) {
            progress("لا توجد ملفات gradlew — يحاول التطبيق توليدها تلقائيًا...");
            String genErr = autoGenerateWrapper(base, rootfs, sdk, root);
            if (genErr != null) {
                return "لم أجد gradle/wrapper/gradle-wrapper.jar في المشروع (فُكّ " + n + " ملفًا).\n" + genErr;
            }
        }

        BuildService.noteTask(this, "build", proj.getName(), null);
        StringBuilder pre = new StringBuilder();
        String agpForced = null;
        final SigningStore.Plan plan = SigningStore.plan(this, proj.getName());
        if (plan.error != null) { signPlan = null; return "تم إيقاف البناء: " + plan.error; }
        signPlan = plan;
        pre.append(plan.note);
        try {
            String localProps = "sdk.dir=/opt/sdk\n";
            if (new File(rootfs, "usr/bin/cmake").exists()) localProps += "cmake.dir=/usr\n"; // cmake من Debian (يُثبَّت بخيار NDK)
            Compat.write(new File(root, "local.properties"), localProps.getBytes(StandardCharsets.UTF_8));
            try { if (TargetApplier.recoverIfStale(root)) pre.append("↩ استُعيدت ملفات gradle الأصلية من بناء سابق انقطع.\n"); } catch (Throwable ignored) {}
            try { pre.append(TargetApplier.applyIfEnabled(this, root)); } catch (Exception te) { pre.append("تعذّر تطبيق الإصدارات المستهدفة: ").append(te).append("\n"); }
            try {
                String at = uiPrefs().getString("agp_target", "");
                if (uiPrefs().getBoolean("agp_on_build", false) && !at.isEmpty()) {
                    agpForced = at;
                    if (TargetApplier.multiApis(this).isEmpty()) pre.append(ProjectDoctor.changeAgpTemp(root, at));
                }
            } catch (Exception ae) { pre.append("تعذّر تطبيق AGP المعتمد: ").append(ae).append("\n"); }
            if (ndkAutoPrepare(root, rootfs, pre)) {
                askInstallNdk(proj.getName());
                return pre.toString() + "تم إيقاف البناء: ثبّت NDK ثم أعد البناء.\n";
            }
            File wp = new File(root, "gradle/wrapper/gradle-wrapper.properties");
            String s = new String(Compat.readAllBytes(wp), StandardCharsets.UTF_8);
            String[] lines = s.split("\n", -1);
            // الإصدار الذي اختاره المستخدم في «مدير Gradle» (يدويًا أو تلقائيًا) يُفرض على wrapper المشروع.
            // إن لم يختر شيئًا يبقى wrapper المشروع كما هو (إلا الروابط المحلية file: فتُستبدل بالرسمي).
            String forcedGradle = null;
            try {
                if (uiPrefs().getBoolean("gradle_auto", false)) forcedGradle = GradleAdvisor.autoUrl(root);
                else if (!savedUrl("gradle_url").isEmpty()) forcedGradle = savedUrl("gradle_url");
            } catch (Exception ignored) {}
            String effV = forcedGradle != null ? GradleAdvisor.versionFromUrl(forcedGradle) : ProjectDoctor.wrapperVersion(root);
            String detectedAgp = null;
            try { detectedAgp = agpForced != null ? agpForced : GradleAdvisor.detectAgp(root); } catch (Throwable ignored) {}
            // L2S يشغّل Gradle بواسطة JDK 21: لا تسمح بتوزيعة أقدم من Gradle 8.5.
            // ارفع أيضًا إلى الحد الأدنى المطلوب من AGP، أيهما أعلى، حتى لو اختار المستخدم
            // إصدارًا أقدم أو كان wrapper الأصلي يشير إلى Gradle 7.5.
            String needV = GradleAdvisor.minimumGradleFor(root, detectedAgp, 21);
            if (needV != null && (effV == null || GradleAdvisor.cmp(effV, needV) < 0)) {
                String previous = effV == null ? "غير معروف" : effV;
                forcedGradle = GradleAdvisor.urlFor(needV);
                pre.append("✔ رُفع Gradle تلقائيًا من ").append(previous).append(" إلى ").append(needV)
                   .append(" لدعم Java 21");
                if (detectedAgp != null) pre.append(" والتوافق مع AGP ").append(detectedAgp);
                pre.append("\n");
                if (detectedAgp != null && detectedAgp.startsWith("7.")) {
                    pre.append("⚠ إصدار AGP القديم قد لا يتوافق مع Gradle الحديث؛ لم يغيّر L2S إصدار AGP تلقائيًا.\n");
                }
            }
            boolean dropSha = false;
            for (int i = 0; i < lines.length; i++) {
                if (lines[i].startsWith("distributionUrl=")) {
                    String curUrl = lines[i].substring("distributionUrl=".length()).replace("\\:", ":").trim();
                    String want = forcedGradle != null ? forcedGradle : (curUrl.contains("file") ? gradleUrl(root) : null);
                    if (want != null && !want.equals(curUrl)) {
                        lines[i] = "distributionUrl=" + want.replace(":", "\\:");
                        dropSha = true;
                        pre.append(curUrl.contains("file") ? "عُدّل رابط Gradle المحلي إلى الرسمي\n" : "✔ فُرض Gradle المختار في التطبيق: ").append(curUrl.contains("file") ? "" : want + "\n");
                    }
                }
            }
            if (dropSha) {
                List<String> kept = new ArrayList<>();
                for (String ln : lines) if (!ln.startsWith("distributionSha256Sum=")) kept.add(ln);
                lines = kept.toArray(new String[0]);
            }
            Compat.write(wp, Compat.join("\n", lines).getBytes(StandardCharsets.UTF_8));

            File wd = new File(base, "wrap");
            wd.mkdirs();
            File w = new File(wd, "aapt2");
            Compat.write(w, "#!/bin/sh\nLD_LIBRARY_PATH=/opt/l2s/lib exec /opt/l2s/bin/aapt2 \"$@\"\n".getBytes(StandardCharsets.UTF_8));
            w.setExecutable(true, false);
            installDlCacheWrappers(wd, rootfs);
            String skipNote = writeSkipRules(base, proj.getName());
            if (skipNote != null) pre.append(skipNote).append("\n");

            File rc = new File(rootfs, "etc/resolv.conf");
            Compat.deleteIfExists(rc);
            Compat.write(rc, "nameserver 8.8.8.8\nnameserver 1.1.1.1\n".getBytes(StandardCharsets.UTF_8));
        } catch (Exception e) {
            return "فشل تجهيز المشروع: " + e;
        }

        // تخطي Gradle: لا تغييرات منذ آخر بناء ناجح وAPK موجود وأحدث من كل ملفات المصدر
        curPreviewSkip = (System.currentTimeMillis() < pendingPreviewUntil) ? pendingPreviewSkip : null;
        curPreviewNoR8 = (System.currentTimeMillis() < pendingPreviewUntil) && pendingPreviewNoR8;
        pendingPreviewSkip = null; pendingPreviewUntil = 0; pendingPreviewNoR8 = false;
        if (curPreviewSkip != null && !curPreviewSkip.isEmpty()) pre.append("⏩ بناء معاينة: تُتخطى المهام: ").append(Compat.join("، ", curPreviewSkip)).append("\n");
        if (curPreviewNoR8) {
            pre.append("⏩ بناء معاينة: تعطيل R8/التصغير\n");
            try {
                Compat.write(new File(base, "preview.init.gradle"), Compat.join("\n", new String[]{
                        "allprojects { p ->",
                        "    p.pluginManager.withPlugin('com.android.application') {",
                        "        def ac = p.extensions.findByName('androidComponents')",
                        "        if (ac != null) {",
                        "            ac.beforeVariants(ac.selector().all()) { vb ->",
                        "                try { vb.minifyEnabled = false } catch (Throwable t) { }",
                        "                try { vb.shrinkResources = false } catch (Throwable t) { }",
                        "            }",
                        "        }",
                        "    }",
                        "}", ""}).getBytes(StandardCharsets.UTF_8));
            } catch (Exception ignored) { }
        }
        final boolean wantSkip = fbSkipGradle;
        fbSkipGradle = false;
        boolean skipGradle = false;
        if (wantSkip) {
            try {
                File[] ap = new File(root, apkRel()).listFiles((d, nm) -> nm.endsWith(".apk"));
                if (ap != null && ap.length > 0) {
                    long apkT = 0;
                    for (File a : ap) apkT = Math.max(apkT, a.lastModified());
                    java.util.Map<String, File> srcs = new java.util.HashMap<>();
                    fbCollect(root, root, srcs, 0);
                    long newest = 0;
                    for (java.util.Map.Entry<String, File> en : srcs.entrySet()) {
                        if (en.getKey().equals("gradle/wrapper/gradle-wrapper.properties")) continue; // يُعاد كتابته كل بناء
                        newest = Math.max(newest, en.getValue().lastModified());
                    }
                    skipGradle = apkT >= newest;
                }
            } catch (Throwable ignored) {}
        }

        // تحزيم AGP التزايدي يحدّث APK القديم في مكانه ويترك فراغًا من الأصفار (يضاعف الحجم).
        // حذف APK القديم قبل Gradle يجبر packageDebug على بناء APK جديد مضغوط.
        if (!skipGradle) {
            try {
                File[] oldApks = new File(root, apkRel()).listFiles((d, nm) -> nm.endsWith(".apk"));
                if (oldApks != null) for (File oa : oldApks) oa.delete();
            } catch (Throwable ignored) {}
        }

        final java.util.List<File> multiApkOut = new ArrayList<>();
        EmbedState embedState = null;
        if (!skipGradle && uiPrefs().getBoolean("embed_project", false)) {
            progress("يضمّن نسخة من المشروع داخل التطبيق...");
            embedState = embedProjectCopy(root, proj.getName(), pre);
        }

        File gh = new File(getFilesDir(), "gradle-home");
        gh.mkdirs();
        List<String> c = new ArrayList<>();
        c.add(new File(base, "bin/proot").getAbsolutePath());
        c.add("--link2symlink");
        c.add("--kill-on-exit");
        c.add("-0");
        c.add("-r");
        c.add(rootfs.getAbsolutePath());
        for (String bnd : new String[]{"/dev", "/proc", "/sys", "/system"}) {
            c.add("-b");
            c.add(bnd);
        }
        if (new File("/apex").exists()) {
            c.add("-b");
            c.add("/apex");
        }
        c.add("-b"); c.add(base.getAbsolutePath() + ":/opt/l2s");
        c.add("-b"); c.add(sdk.getAbsolutePath() + ":/opt/sdk");
        c.add("-b"); c.add(gh.getAbsolutePath() + ":/root/.gradle");
        File ah = new File(getFilesDir(), "android-home");
        ah.mkdirs();
        new File(rootfs, "root/.android").mkdirs();
        c.add("-b"); c.add(ah.getAbsolutePath() + ":/root/.android");
        if (plan.active) {
            new File(rootfs, "sign").mkdirs();
            c.add("-b"); c.add(SigningStore.root(this).getAbsolutePath() + ":/sign");
        }
        c.add("-b"); c.add(root.getAbsolutePath() + ":/proj");
        c.add("-w");
        c.add("/proj");
        c.add("/usr/bin/env");
        c.add("-i");
        c.add("HOME=/root");
        c.add("PATH=/opt/l2s/wrap:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin");
        c.add("L2S_DL_CACHE=" + (uiPrefs().getBoolean("dl_cache", true) ? "1" : "0"));
        c.add("L2S_MEMO=" + (uiPrefs().getBoolean("dl_cache", true) ? "1" : "0"));
        c.add("PYTHONPATH=/opt/l2s/wrap/py");
        c.add("PIP_CACHE_DIR=/root/.gradle/pip-cache");
        c.add("PIP_DISABLE_PIP_VERSION_CHECK=1");
        c.add("LANG=C.UTF-8");
        c.add("TMPDIR=/tmp");
        c.add("ANDROID_HOME=/opt/sdk");
        c.add("JAVA_HOME=/usr/lib/jvm/java-21-openjdk-arm64");
        c.addAll(plan.env);
        final List<String> preJava = new ArrayList<>(c);
        final List<String> safeHead = javaHead(preJava, null); // الإعداد الأصلي (-Xmx512m)
        final List<String> matchedJvm = projectJvmArgs(root);  // مطابقة org.gradle.jvmargs لتفادي Daemon إضافي
        final List<String> gradleHead = matchedJvm.isEmpty() ? safeHead : javaHead(preJava, matchedJvm);
        pre.append("ℹ إعدادات JVM لتشغيل Gradle: ")
           .append(matchedJvm.isEmpty() ? "أصلية (-Xmx512m)" : "مطابقة للمشروع (" + Compat.join(" ", matchedJvm) + ")").append("\n");

        long t0 = System.currentTimeMillis();
        buildRunning = true;
        markBuildRunning(proj.getName());
        int buildTimeoutMin = getBuildTimeoutMin();
        Res res;
        try {
            if (skipGradle) {
                res = new Res();
                res.code = 0;
                res.text = "⏭ لا تغييرات منذ آخر بناء ناجح — استُخدم APK الموجود دون تشغيل Gradle.\n";
            } else {
                final java.util.List<Integer> multi = skipGradle ? new ArrayList<Integer>() : TargetApplier.multiApis(this);
                if (multi.isEmpty()) {
                    res = runGradleSeq(base, gradleHead, safeHead, buildTimeoutMin, pre);
                } else {
                    TargetApplier.forgetBackups(root);
                    TargetApplier.setMarker(root, true);
                    StringBuilder mt = new StringBuilder();
                    int okCount = 0, lastFail = 1;
                    boolean anyTimeout = false;
                    for (int ai = 0; ai < multi.size(); ai++) {
                        int api = multi.get(ai);
                        progress("عدة APK (" + (ai + 1) + "/" + multi.size() + "): بناء API " + api + " ...");
                        pre.append("── API ").append(api).append(" ──\n").append(TargetApplier.applyMulti(root, api, sdk));
                        if (agpForced != null) { try { pre.append(ProjectDoctor.changeAgpTemp(root, agpForced)); } catch (Exception ae2) { pre.append("تعذّر AGP: ").append(ae2).append("\n"); } }
                        try {
                            File[] od = new File(root, apkRel()).listFiles((d, nm) -> nm.endsWith(".apk"));
                            if (od != null) for (File oa : od) oa.delete();
                        } catch (Throwable ignored) {}
                        Res r1 = runGradleSeq(base, gradleHead, safeHead, buildTimeoutMin, pre);
                        File[] ap1 = new File(root, apkRel()).listFiles((d, nm) -> nm.endsWith(".apk"));
                        if (r1.code == 0 && !r1.timedOut && ap1 != null && ap1.length > 0) {
                            try {
                                File nm1 = new File(getCacheDir(), proj.getName() + "-api" + api + ".apk");
                                Compat.copy(ap1[0], nm1);
                                multiApkOut.add(nm1);
                                okCount++;
                                mt.append("✔ API ").append(api).append(" نجح\n");
                            } catch (Exception ce) { mt.append("✘ API ").append(api).append(": تعذّر نسخ APK ").append(ce).append("\n"); lastFail = 1; }
                        } else {
                            lastFail = r1.code == 0 ? 1 : r1.code;
                            anyTimeout |= r1.timedOut;
                            mt.append("✘ API ").append(api).append(" فشل (رمز ").append(r1.code).append(")\n").append(r1.text).append("\n");
                            if (r1.timedOut) break;
                        }
                    }
                    pre.append(TargetApplier.restore(root));
                    TargetApplier.setMarker(root, false);
                    res = new Res();
                    res.timedOut = anyTimeout;
                    res.code = (okCount == multi.size()) ? 0 : lastFail;
                    res.text = "عدة APK: نجح " + okCount + " من " + multi.size() + "\n" + mt;
                }
            }
        } finally {
            buildRunning = false;
            restoreEmbed(embedState);
        }
        // انتهت العملية بنفسها (نجاح أو فشل عادي): لا حاجة للمواصلة. أما انقطاع التطبيق أو المهلة فتبقى العلامة.
        if (!res.timedOut) clearBuildRunning();
        long secs = (System.currentTimeMillis() - t0) / 1000;

        if (res.timedOut) {
            String pn = proj.getName();
            logAutoStop("build", pn, buildTimeoutMin);
            notifyAutoStop("توقف البناء تلقائيًا", "المشروع \"" + pn + "\" — تجاوز مهلة " + buildTimeoutMin + " دقيقة وأُلغي تلقائيًا.");
        }

        StringBuilder r = new StringBuilder();
        r.append(res.timedOut ? "توقف تلقائي (تجاوز المهلة) ⏱" : (res.code == 0 ? "نجح البناء ✔" : "فشل البناء ✘")).append(" | رمز الخروج ").append(res.code)
                .append(" | الزمن ").append(secs).append(" ثانية\n").append(pre);
        File[] apks;
        if (!multiApkOut.isEmpty()) {
            apks = multiApkOut.toArray(new File[0]);
        } else {
            apks = new File(root, apkRel()).listFiles((d, nm) -> nm.endsWith(".apk"));
            if (apks != null && apks.length > 0) {
                try {
                    File named = new File(getCacheDir(), proj.getName() + ("release".equals(plan.variant) ? "-release" : "") + ".apk");
                    Compat.copy(apks[0], named);
                    apks = new File[]{named};
                } catch (Exception ignored) {}
            }
        }
        if (apks != null && apks.length > 0) {
            for (File ap : apks) {
                if (plan.active || plan.unsigned || "release".equals(plan.variant)) r.append(SigningStore.certLine(this, ap, plan));
                String dl = copyToDownloads(ap);
                boolean dlOk = dl.contains("\u2714");
                if (!dlOk || !cleanAfterBuildEnabled()) {
                    try {
                        File dst = new File(getExternalFilesDir(null), ap.getName());
                        Compat.copy(ap, dst);
                        r.append("APK: ").append(dst.getAbsolutePath()).append(" (").append(fmtMb(dst.length())).append(")\n");
                    } catch (Exception e) {
                        r.append("تعذّر نسخ APK: ").append(e).append("\n");
                    }
                }
                r.append(dl).append("\n");
            }
            if (res.code == 0 && !res.timedOut) lastBuiltApk = apks[apks.length - 1];
        }
        if (res.code == 0 && !res.timedOut && !skipGradle) {
            progress("يحفظ نسخة احتياطية من المشروع الناجح...");
            String gm = saveGoodSnapshot(proj.getName());
            if (!gm.isEmpty()) r.append(gm).append("\n");
        }
        if (res.code == 0 && !res.timedOut && !skipGradle && cleanAfterBuildEnabled()
                && (apks == null || apks.length == 0 || !apks[0].getAbsolutePath().startsWith(root.getAbsolutePath()))) {
            long freed = cleanProjectBuild(root, false);
            if (freed > 0) r.append("نُظّفت ملفات البناء المؤقتة (").append(fmtSize(freed)).append(") ✔\n");
        }
        r.append("\n").append(res.text);
        return r.toString();
    }


    // تسلسل تشغيل Gradle المعتاد (سريع ثم إعادة بالتفاصيل عند الفشل) لبناء واحد.
    private Res runGradleSeq(File base, List<String> gradleHead, List<String> safeHead, int buildTimeoutMin, StringBuilder pre) {
        Res res;
        {
                // 1) سريع: بلا --info/--stacktrace ومع configuration-cache
                boolean useCc = true;
                writeLintOffInit(base);
                SigningStore.writeInit(base);
                SigningStore.writeHardenRules(base, signPlan);
                List<String> headNow = gradleHead;
                skipLintTasks = true;
                res = execLive(base, gradleCmd(headNow, true, false), buildTimeoutMin);
                // إن لم يوجد أحد مهام lint في المشروع (-x يفشل بـ "Cannot locate tasks") يعاد بدون الاستبعاد
                if (res.code != 0 && !res.timedOut && res.text != null
                        && (res.text.contains("Cannot locate tasks that match") || res.text.contains("Task 'lintVital"))
                        && !res.text.contains("lintVitalAnalyzeDebug FAILED")) {
                    skipLintTasks = false;
                    res = execLive(base, gradleCmd(headNow, true, false), buildTimeoutMin);
                }
                // تراجع آمن: إن فشل التشغيل بسبب الذاكرة/إقلاع JVM بالإعدادات المطابقة، يعاد بالإعدادات الأصلية
                if (headNow != safeHead && res.code != 0 && !res.timedOut && looksLikeJvmFailure(res)) {
                    progress("تعذّر التشغيل بإعدادات JVM المطابقة — يعيد بالإعدادات الأصلية ...");
                    pre.append("↩ تعذّر التشغيل بإعدادات JVM المطابقة للمشروع (ذاكرة/إقلاع) — أُعيد البناء بالإعدادات الأصلية.\n");
                    headNow = safeHead;
                    res = execLive(base, gradleCmd(headNow, true, false), buildTimeoutMin);
                }
                if (res.code != 0 && !res.timedOut && res.text.contains("Unknown command-line option '--configuration-cache")) {
                    useCc = false;
                    progress("هذه النسخة من Gradle لا تدعم configuration-cache — يعيد بدونه ...");
                    res = execLive(base, gradleCmd(headNow, false, false), buildTimeoutMin);
                }
                // 2) عند الفشل: يعيد بالتفاصيل الكاملة ليكتمل تقرير الأخطاء
                if (res.code != 0 && !res.timedOut) {
                    progress("فشل البناء — يعيده بالتفاصيل الكاملة (--info --stacktrace) للتقرير ...");
                    res = execLive(base, gradleCmd(headNow, useCc, true), buildTimeoutMin);
                }
                    }
        return res;
    }

    // يبني رأس أمر Java لتشغيل Gradle. jvmArgs فارغة أو null = الإعداد الأصلي (-Xmx512m).
    private List<String> javaHead(List<String> pre, List<String> jvmArgs) {
        List<String> h = new ArrayList<>(pre);
        h.add("/usr/bin/java");
        if (jvmArgs == null || jvmArgs.isEmpty()) h.add("-Xmx512m"); else h.addAll(jvmArgs);
        if (jvmArgs != null && !jvmArgs.isEmpty() && jvmOpensEnabled()) {
            // خيار تجريبي: نفس فتح الوحدات الذي يضيفه Gradle لعملية الـDaemon، ليرضى بتشغيل البناء في Java واحدة
            String[] ops = {"java.base/java.util", "java.base/java.lang", "java.base/java.lang.invoke",
                    "java.base/java.util.concurrent", "java.base/java.util.concurrent.atomic", "java.base/java.net",
                    "java.base/java.io", "java.base/java.nio.charset", "java.base/java.text",
                    "java.base/sun.nio.ch", "java.prefs/java.util.prefs"};
            for (String o : ops) h.add("--add-opens=" + o + "=ALL-UNNAMED");
            h.add("-Dfile.encoding=UTF-8");
        }
        h.add("-Djava.net.preferIPv4Stack=true");
        h.add("-classpath");
        h.add("gradle/wrapper/gradle-wrapper.jar");
        h.add("org.gradle.wrapper.GradleWrapperMain");
        return h;
    }

    // يقرأ org.gradle.jvmargs من gradle.properties في المشروع. يعيد قائمة فارغة عند أي شك (فيُستخدم الإعداد الأصلي).
    private List<String> projectJvmArgs(File root) {
        List<String> out = new ArrayList<>();
        try {
            File gp = new File(root, "gradle.properties");
            if (!gp.isFile()) return new ArrayList<>();
            String val = null;
            for (String ln : Compat.readAllLines(gp, StandardCharsets.UTF_8)) {
                String t = ln.trim();
                if (t.startsWith("#") || t.startsWith("!")) continue;
                int eq = t.indexOf('=');
                if (eq > 0 && t.substring(0, eq).trim().equals("org.gradle.jvmargs")) val = t.substring(eq + 1).trim();
            }
            if (val == null || val.isEmpty() || val.contains("\"") || val.contains("'") || val.contains("\\")) return new ArrayList<>();
            boolean hasXmx = false;
            for (String a : val.split("\\s+")) {
                if (!a.startsWith("-")) return new ArrayList<>();
                if (a.startsWith("-Xmx")) hasXmx = true;
                out.add(a);
            }
            if (!hasXmx) return new ArrayList<>();
        } catch (Throwable e) {
            return new ArrayList<>();
        }
        return out;
    }

    // هل الفشل ناتج عن إقلاع JVM أو الذاكرة (وليس خطأ في كود المشروع)؟
    private boolean looksLikeJvmFailure(Res r) {
        if (r.code == 137 || r.code == 134 || r.code == 139) return true;
        String t = r.text == null ? "" : r.text;
        return t.contains("OutOfMemoryError") || t.contains("Java heap space") || t.contains("GC overhead limit")
                || t.contains("Could not reserve enough space") || t.contains("Could not create the Java Virtual Machine")
                || t.contains("Error occurred during initialization of VM") || t.contains("Cannot allocate memory")
                || t.contains("unable to create native thread") || t.contains("daemon disappeared unexpectedly")
                || t.contains("Unrecognized VM option") || t.contains("Invalid maximum heap size");
    }

    private boolean skipLintTasks = true;
    // خطة التوقيع للبناء الجاري (النوع والمفتاح وإعدادات release) — تُحسب في بداية كل بناء من SigningStore
    private SigningStore.Plan signPlan = null;

    private String apkRel() {
        return "app/build/outputs/apk/" + (signPlan != null ? signPlan.variant : "debug");
    }

    // يكتب init script يعطّل مهام lintVital* (يُحمَّل عبر -I من /opt/l2s داخل proot)
    private void writeLintOffInit(File base) {
        try {
            String g = "allprojects {\n"
                + "    tasks.configureEach { t ->\n"
                + "        if (t.name.startsWith('lintVital') || t.name == 'generateDebugLintVitalReportModel' || t.name == 'generateReleaseLintVitalReportModel') { t.enabled = false }\n"
                + "    }\n"
                + "}\n";
            Compat.write(new File(base, "lint-off.init.gradle"), g.getBytes(StandardCharsets.UTF_8));
        } catch (Throwable ignored) {}
    }

    // يركّب أمر Gradle: head = أمر proot/java حتى GradleWrapperMain
    private List<String> gradleCmd(List<String> head, boolean configCache, boolean verbose) {
        List<String> c = new ArrayList<>(head);
        c.add(signPlan != null ? signPlan.task : "assembleDebug");
        c.add("--build-cache");
        c.add("--console=plain");
        if (warmDaemonEnabled()) {
            // خيار تجريبي: يبقى Gradle شغّالًا بعد البناء فلا يبدأ التالي من الصفر (يستهلك ذاكرة حتى انتهاء مهلة الخمول)
            c.add("-Dorg.gradle.daemon=true");
            c.add("-Dorg.gradle.daemon.idletimeout=" + (warmDaemonIdleMin() * 60000L));
        }
        boolean injecting = signPlan != null && signPlan.active;
        if (signPlan != null && signPlan.hardenFull) c.add("-Pandroid.enableR8.fullMode=true");
        if (injecting) {
            // كلمات السر تأتي من البيئة؛ لا نسمح لـ configuration-cache بتخزينها في مجلد المشروع
            c.add("-Dorg.gradle.configuration-cache=false");
        }
        if (configCache && !injecting) {
            c.add("--configuration-cache");
            c.add("--configuration-cache-problems=warn");
        }
        if (verbose) {
            c.add("--info");
            c.add("--stacktrace");
        }
        c.add("-Pandroid.aapt2FromMavenOverride=/opt/l2s/wrap/aapt2");
        // يعطّل فحوص lint الحيوية (lintVital*) لأنها تنهار على SDK الذي يحوي منصة بصيغة "37.0" (NumberFormatException)
        // ولا تؤثر على ناتج APK. الملف يُكتب قبل التشغيل في writeLintOffInit.
        c.add("-I");
        c.add("/opt/l2s/lint-off.init.gradle");
        if (signPlan != null && signPlan.init) { c.add("-I"); c.add("/opt/l2s/l2s-sign.init.gradle"); }
        if (curPreviewNoR8) { c.add("-I"); c.add("/opt/l2s/preview.init.gradle"); }
        if (curSkipTasksInit) { c.add("-I"); c.add("/opt/l2s/skip-tasks.init.gradle"); }
        if (curPreviewSkip != null) {
            for (String t : curPreviewSkip) { c.add("-x"); c.add(t); }
        }
        if (skipLintTasks) {
            // استبعاد صريح على مستوى أمر Gradle: يعمل حتى مع إعادة استخدام configuration-cache (حيث لا يُنفَّذ init script)
            String lv = (signPlan != null && "release".equals(signPlan.variant)) ? "Release" : "Debug";
            c.add("-x"); c.add("lintVitalAnalyze" + lv);
            c.add("-x"); c.add("lintVitalReport" + lv);
            c.add("-x"); c.add("lintVital" + lv);
            c.add("-x"); c.add("generate" + lv + "LintVitalReportModel");
        }
        return c;
    }

    private String copyToDownloads(File apk) {
        return protectFile(apk, "application/vnd.android.package-archive");
    }

    private String copyFileToDownloads(File src, String mimeType) {
        File apk = src;
        try {
            if (Build.VERSION.SDK_INT >= 29) {
                if (mimeType.equals("application/vnd.android.package-archive")) {
                    // احذف نسخة APK السابقة بنفس الاسم (تخص التطبيق فقط) كي لا تتراكم "name (1).apk"
                    try {
                        getContentResolver().delete(MediaStore.Downloads.EXTERNAL_CONTENT_URI,
                                MediaStore.Downloads.DISPLAY_NAME + "=?", new String[]{apk.getName()});
                    } catch (Exception ignored) {}
                }
                ContentValues cv = new ContentValues();
                cv.put(MediaStore.Downloads.DISPLAY_NAME, apk.getName());
                cv.put(MediaStore.Downloads.MIME_TYPE, mimeType);
                cv.put(MediaStore.Downloads.IS_PENDING, 1);
                Uri item = getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI, cv);
                if (item == null) return "تعذّر إنشاء ملف في Downloads (MediaStore أعاد null).";
                try (OutputStream os = getContentResolver().openOutputStream(item);
                     InputStream is = new FileInputStream(apk)) {
                    byte[] buf = new byte[65536];
                    int k;
                    while ((k = is.read(buf)) > 0) os.write(buf, 0, k);
                }
                cv.clear();
                cv.put(MediaStore.Downloads.IS_PENDING, 0);
                getContentResolver().update(item, cv, null, null);
                return "نُسخ إلى Downloads/" + apk.getName() + " ✔";
            } else {
                if (checkSelfPermission(Manifest.permission.WRITE_EXTERNAL_STORAGE) != PackageManager.PERMISSION_GRANTED) {
                    return "لم يُمنح إذن التخزين بعد. أعد فتح التطبيق ووافق على الإذن، ثم أعد البناء.";
                }
                File dir = Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS);
                dir.mkdirs();
                File dst = new File(dir, apk.getName());
                Compat.copy(apk, dst);
                return "نُسخ إلى " + dst.getAbsolutePath() + " ✔";
            }
        } catch (Exception e) {
            return "تعذّر النسخ إلى Downloads: " + e;
        }
    }

    // ------------------------------------------------------------------
    // مجلد النسخ الاحتياطي الدائم (اختياري): مجلد يختاره المستخدم عبر SAF
    // (قد يكون بطاقة SD خارجية أو مجلد مزامَن سحابيًا)، وتُحفظ فيه نسخة إضافية
    // من كل تصدير، لأنه خارج بيانات التطبيق ولا يُحذف مع إلغاء التثبيت.
    // ------------------------------------------------------------------
    private Uri backupFolderUri() {
        String s = uiPrefs().getString("backup_folder_uri", null);
        if (s == null || s.isEmpty()) return null;
        try { return Uri.parse(s); } catch (Exception e) { return null; }
    }

    private void setBackupFolderUri(Uri tree) {
        try {
            getContentResolver().takePersistableUriPermission(tree,
                    Intent.FLAG_GRANT_READ_URI_PERMISSION | Intent.FLAG_GRANT_WRITE_URI_PERMISSION);
        } catch (Exception ignored) {}
        uiPrefs().edit().putString("backup_folder_uri", tree.toString()).apply();
    }

    private void clearBackupFolderUri() {
        Uri old = backupFolderUri();
        if (old != null) {
            try {
                getContentResolver().releasePersistableUriPermission(old,
                        Intent.FLAG_GRANT_READ_URI_PERMISSION | Intent.FLAG_GRANT_WRITE_URI_PERMISSION);
            } catch (Exception ignored) {}
        }
        uiPrefs().edit().remove("backup_folder_uri").apply();
    }

    private void pickBackupFolder() {
        Intent i = new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);
        i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION | Intent.FLAG_GRANT_WRITE_URI_PERMISSION
                | Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);
        try {
            startActivityForResult(i, PICK_BACKUP_FOLDER);
        } catch (Exception e) {
            Toast.makeText(this, "تعذّر فتح منتقي المجلدات: " + e, Toast.LENGTH_LONG).show();
        }
    }

    // ينسخ ملفًا إلى مجلد النسخ الاحتياطي المخصص إن كان محددًا. يعيد "" إن لم يكن هناك مجلد محدد.
    private String copyFileToBackupFolder(File src, String mimeType) {
        Uri tree = backupFolderUri();
        if (tree == null) return "";
        try {
            String treeDocId = DocumentsContract.getTreeDocumentId(tree);
            Uri childrenUri = DocumentsContract.buildChildDocumentsUriUsingTree(tree, treeDocId);
            // احذف أي ملف قديم بنفس الاسم أولًا حتى لا تتراكم نسخ لا نهائية.
            try (android.database.Cursor c = getContentResolver().query(childrenUri,
                    new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID, DocumentsContract.Document.COLUMN_DISPLAY_NAME},
                    null, null, null)) {
                if (c != null) {
                    while (c.moveToNext()) {
                        if (src.getName().equals(c.getString(1))) {
                            Uri old = DocumentsContract.buildDocumentUriUsingTree(tree, c.getString(0));
                            try { DocumentsContract.deleteDocument(getContentResolver(), old); } catch (Exception ignored) {}
                        }
                    }
                }
            }
            Uri dirDoc = DocumentsContract.buildDocumentUriUsingTree(tree, treeDocId);
            Uri newFile = DocumentsContract.createDocument(getContentResolver(), dirDoc, mimeType, src.getName());
            if (newFile == null) return "تعذّر إنشاء ملف بمجلد النسخ الاحتياطي.";
            try (OutputStream os = getContentResolver().openOutputStream(newFile);
                 InputStream is = new FileInputStream(src)) {
                byte[] buf = new byte[65536];
                int k;
                while ((k = is.read(buf)) > 0) os.write(buf, 0, k);
            }
            return "نُسخ أيضًا إلى مجلد النسخ الاحتياطي المخصص ✔";
        } catch (Exception e) {
            return "تعذّر النسخ إلى مجلد النسخ الاحتياطي المخصص: " + e;
        }
    }

    // نقطة الحماية الموحّدة: تنسخ الملف إلى Downloads الحقيقي (دائمًا) وإلى مجلد النسخ الاحتياطي
    // المخصص إن كان محددًا. استخدم هذه بدل copyFileToDownloads مباشرة لأي مخرج يُراد حمايته
    // من ضياعه عند إلغاء تثبيت التطبيق.
    private String protectFile(File src, String mimeType) {
        StringBuilder r = new StringBuilder(copyFileToDownloads(src, mimeType));
        String custom = copyFileToBackupFolder(src, mimeType);
        if (!custom.isEmpty()) r.append("\n").append(custom);
        return r.toString();
    }

    private interface StreamOpener { InputStream open() throws java.io.IOException; }



    // فك تلقائي عند أول تشغيل إن وُجدت حزمة داخل assets
    private void checkAutoExtract() {
        if (new File(toolsBase(), "bin/aapt2").exists()) return;
        boolean has = false;
        try (InputStream t = getAssets().open("l2s-pack.zip")) { has = true; } catch (Exception ignored) {}
        if (!has) return;
        startTask(() -> importPackFrom(() -> getAssets().open("l2s-pack.zip")));
    }

    private File projectsDir() {
        File d = new File(getFilesDir(), "projects");
        d.mkdirs();
        return d;
    }

    private String projectName(Uri u) {
        String name = null;
        try (android.database.Cursor c = getContentResolver().query(u, new String[]{android.provider.OpenableColumns.DISPLAY_NAME}, null, null, null)) {
            if (c != null && c.moveToFirst()) name = c.getString(0);
        } catch (Exception ignored) {}
        if (name == null || name.isEmpty()) name = "project";
        if (name.toLowerCase().endsWith(".zip")) name = name.substring(0, name.length() - 4);
        name = name.replaceAll("[\\\\/:*?\"<>|\\s]", "_");
        if (name.isEmpty() || name.equals(".") || name.equals("..")) name = "project";
        return name;
    }

    private long sizeOf(File f) {
        if (Compat.isSymbolicLink(f)) return 0;
        if (f.isFile()) return f.length();
        File[] k = f.listFiles();
        long s = 0;
        if (k != null) for (File c : k) s += sizeOf(c);
        return s;
    }

    private String projectLabel(File d) {
        String line2 = String.format(java.util.Locale.US, "%.1f", sizeOf(d) / 1048576.0) + " م.ب | "
                + new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", java.util.Locale.US).format(new java.util.Date(d.lastModified()));
        return d.getName() + "\n\u202A" + line2 + "\u202C";
    }

    private java.util.Set<String> pinnedProjects() {
        return new java.util.HashSet<>(uiPrefs().getStringSet("pinned_projects", new java.util.HashSet<>()));
    }

    // نافذة خيارات ⋮ في «مشاريعي»: تثبيت/إزالة التثبيت مع خيار إلغاء
    private void confirmPinProject(final String name, final Runnable after) {
        boolean isPinned = pinnedProjects().contains(name);
        final String[] items = { isPinned ? "إزالة التثبيت" : "تثبيت المشروع", "إلغاء" };
        new NavAlertBuilder()
                .setTitle(name)
                .setItems(items, (d, which) -> {
                    if (which == 0) {
                        togglePinProject(name);
                        if (after != null) after.run();
                    }
                })
                .show();
    }

    private void togglePinProject(String name) {
        java.util.Set<String> pinned = pinnedProjects();
        if (pinned.contains(name)) {
            pinned.remove(name);
            Toast.makeText(this, "أُزيل التثبيت: " + name, Toast.LENGTH_SHORT).show();
        } else {
            pinned.add(name);
            Toast.makeText(this, "تم التثبيت: " + name, Toast.LENGTH_SHORT).show();
        }
        uiPrefs().edit().putStringSet("pinned_projects", pinned).apply();
    }

    private void addEmptyState(LinearLayout box, String icon, String message, String actionLabel, Runnable action) {
        LinearLayout col = new LinearLayout(this);
        col.setOrientation(LinearLayout.VERTICAL);
        col.setGravity(android.view.Gravity.CENTER_HORIZONTAL);
        col.setPadding(dp(24), dp(48), dp(24), dp(24));

        TextView iconView = new TextView(this);
        iconView.setText(icon);
        iconView.setTextSize(48);
        iconView.setGravity(android.view.Gravity.CENTER);
        col.addView(iconView, new LinearLayout.LayoutParams(-2, -2));

        TextView msg = new TextView(this);
        msg.setText(message);
        msg.setTextSize(14);
        msg.setTextColor(android.graphics.Color.parseColor("#757575"));
        msg.setGravity(android.view.Gravity.CENTER);
        LinearLayout.LayoutParams msgLp = new LinearLayout.LayoutParams(-2, -2);
        msgLp.topMargin = dp(12);
        msgLp.bottomMargin = dp(18);
        col.addView(msg, msgLp);

        if (actionLabel != null && action != null) {
            Button btn = new Button(this);
            btn.setText(actionLabel);
            btn.setAllCaps(false);
            btn.setTextColor(android.graphics.Color.WHITE);
            android.graphics.drawable.GradientDrawable bg = new android.graphics.drawable.GradientDrawable();
            bg.setColor(android.graphics.Color.parseColor("#FF9800"));
            bg.setCornerRadius(10 * getResources().getDisplayMetrics().density);
            btn.setBackground(bg);
            btn.setPadding(dp(20), dp(10), dp(20), dp(10));
            btn.setOnClickListener(v -> action.run());
            col.addView(btn, new LinearLayout.LayoutParams(-2, -2));
        }
        box.addView(col, new LinearLayout.LayoutParams(-1, -2));
    }

    // ------------------------------------------------------------------
    // مركز النسخ الاحتياطي والحماية: حذف التطبيق يمسح بياناته الداخلية بالكامل
    // (المشاريع، SDK، Debian، الأدوات، مفتاح التوقيع) بلا استثناء. هذه الشاشة
    // تجمع كل وسائل حماية تلك البيانات بنسخها خارج تخزين التطبيق.
    // ------------------------------------------------------------------
    private void showBackupCenter() {
        final android.app.Dialog dlg = newScreen("showBackupCenter", () -> showBackupCenter());
        LinearLayout root = beginFullscreenCardDialog(dlg, "النسخ الاحتياطي والحماية");
        LinearLayout box = (LinearLayout) root.getTag();

        TextView notice = new TextView(this);
        notice.setText("\u26A0\uFE0F إلغاء تثبيت التطبيق يمسح كل بياناته الداخلية نهائيًا (المشاريع، SDK، Debian، الأدوات، مفتاح التوقيع). الملفات المُصدَّرة من هنا فقط تُحفظ خارج التطبيق وتنجو من الحذف.");
        notice.setTextSize(12.5f);
        notice.setTextColor(themeTextSecondary());
        notice.setPadding(dp(4), dp(2), dp(4), dp(14));
        box.addView(notice);

        addMenuCardLP(box, "\uD83D\uDCE6", "نسخ حزمة كاملة", "اختر ما تريد تضمينه: الأدوات، SDK، Debian، المفتاح، Gradle", "#FF9800",
                () -> { dlg.dismiss(); showExportPackOptions(); }, null);

        addMenuCardLP(box, "\uD83D\uDD10", "خزنة مفاتيح التوقيع", "نسخة مشفّرة بكلمة سر تنجو من حذف التطبيق، مع الاستعادة", "#7C5CFF",
                () -> { dlg.dismiss(); Intent si = new Intent(this, SigningActivity.class); si.putExtra("l2s_open", "backup"); startActivity(si); }, null);

        addMenuCardLP(box, "\u2705", "نسخ المشاريع الناجحة", "آخر نسخة نجح بناؤها لكل مشروع — للرجوع إليها أو حفظها في الهاتف", "#4CAF50",
                () -> { dlg.dismiss(); showGoodProjectsList(); }, null);

        addToggleCard(box, "\u2705", "حفظ نسخة المشروع الناجح تلقائيًا",
                "تُحفظ نسخة بعد كل بناء ناجح", "#4CAF50", goodBackupEnabled(),
                on -> { uiPrefs().edit().putBoolean("good_backup_enabled", on).apply(); return true; }, null);

        addToggleCard(box, "\uD83D\uDCE5", "نسخة قبل كل بناء",
                "تُؤخذ نسخة من المشروع قبل كل بناء", "#FF9800", preBuildBackupEnabled(),
                on -> { uiPrefs().edit().putBoolean("prebuild_backup_enabled", on).apply(); return true; }, null);

        addToggleCard(box, "\uD83D\uDDDC", "حفظ zip تلقائي بعد كل بناء ناجح",
                "يُحفظ zip للمصدر في Downloads (وإلا تُحفظ اللقطة الداخلية فقط)", "#2196F3", goodZipAuto(),
                on -> { uiPrefs().edit().putBoolean("good_zip_auto", on).apply(); return true; }, null);

        addMenuCardLP(box, "\uD83D\uDCC1", "نسخ كل المشاريع دفعة واحدة", "أرشيف واحد لكل مشاريعك الحالية → Downloads", "#4CAF50",
                () -> { dlg.dismiss(); legacyStartTask(this::exportAllProjectsZip); }, null);

        Uri bf = backupFolderUri();
        backupCenterRefresh = () -> { if (dlg.isShowing()) { dlg.dismiss(); showBackupCenter(); } };
        addToggleCard(box, "\uD83D\uDCC2", "مجلد نسخ احتياطي دائم (اختياري)",
                "كل نسخة تُحفظ فيه أيضًا (وإلا تُحفظ في Downloads فقط)", "#2196F3", bf != null,
                on -> {
                    if (on) {
                        pickBackupFolder();
                    } else {
                        new NavAlertBuilder()
                                .setTitle("إلغاء مجلد النسخ الاحتياطي؟")
                                .setMessage("النسخ القادمة ستُحفظ في Downloads فقط. الملفات المحفوظة سابقًا بالمجلد المخصص تبقى كما هي.")
                                .setPositiveButton("إلغاء الربط", (d, w) -> {
                                    clearBackupFolderUri();
                                    Toast.makeText(this, "تم إلغاء مجلد النسخ الاحتياطي", Toast.LENGTH_SHORT).show();
                                    dlg.dismiss();
                                    showBackupCenter();
                                })
                                .setNegativeButton("تراجع", null)
                                .show();
                    }
                    return false; // الحالة الفعلية تتحدث عند إعادة بناء الشاشة بعد النتيجة
                }, null);

        dlg.setContentView(root);
        dlg.show();
    }

    private void showProjects() {
        final File[] ds0 = projectsDir().listFiles(File::isDirectory);
        final java.util.List<File> allProjects = new java.util.ArrayList<>();
        if (ds0 != null) allProjects.addAll(java.util.Arrays.asList(ds0));

        final android.app.Dialog dlg = newScreen("showProjects", () -> showProjects());
        LinearLayout root = beginFullscreenCardDialog(dlg, "مشاريعي (" + allProjects.size() + ")");
        LinearLayout box = (LinearLayout) root.getTag();

        addMenuCardLP(box, "\uD83D\uDEE1", "النسخ الاحتياطي والحماية",
                "حذف التطبيق يمسح مشاريعك — انسخها خارجه", "#FF9800",
                () -> { dlg.dismiss(); showBackupCenter(); }, null);

        if (allProjects.isEmpty()) {
            addEmptyState(box, "\uD83D\uDCC2", "لا توجد مشاريع بعد.", "استيراد مشروع", () -> {
                dlg.dismiss();
                pickFileMulti(PICK_SMART);
            });
            dlg.setContentView(root);
            dlg.show();
            return;
        }

        final java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", java.util.Locale.US);
        final java.util.Map<String, Long> sizeCache = new java.util.HashMap<>();

        // وضع التحديد المتعدد + الحذف الجماعي
        final boolean[] selectMode = {false};
        final java.util.Set<String> selected = new java.util.LinkedHashSet<>();
        final String[] query = {""};
        final Runnable[] refresh = new Runnable[1];
        final Runnable[] updateBar = new Runnable[1];

        // المشاريع الظاهرة حاليًا (بعد البحث) مرتّبة: المثبّتة أولًا ثم الأحدث
        final java.util.function.Supplier<java.util.List<File>> visible = () -> {
            java.util.Set<String> pinned = pinnedProjects();
            java.util.List<File> list = new java.util.ArrayList<>();
            final String fk = uiPrefs().getString("proj_filter", "all");
            final String sk = uiPrefs().getString("proj_sort", "recent");
            for (File d : allProjects) {
                if (!(query[0].isEmpty() || d.getName().toLowerCase(java.util.Locale.ROOT).contains(query[0]))) continue;
                if (!fk.equals("all")) {
                    String lk = projectStatusKey(d.getName());
                    String gk = uiPrefs().getString("gh_status_" + d.getName(), "");
                    boolean okF = fk.equals("ghok") ? gk.equals("ok") : fk.equals("ghfail") ? gk.equals("fail") : lk.equals(fk);
                    if (!okF) continue;
                }
                list.add(d);
            }
            java.util.Collections.sort(list, (a, b) -> {
                boolean pa = pinned.contains(a.getName()), pb = pinned.contains(b.getName());
                if (pa != pb) return pa ? -1 : 1;
                if (sk.equals("name")) return a.getName().compareToIgnoreCase(b.getName());
                if (sk.equals("fail")) {
                    int ra = projectFailRank(a.getName()), rb = projectFailRank(b.getName());
                    if (ra != rb) return ra - rb;
                }
                return Long.compare(b.lastModified(), a.lastModified());
            });
            return list;
        };

        // شريط الأدوات: تحديد / حذف الكل (وفي وضع التحديد: تحديد الكل / حذف المحدد / إنهاء)
        final LinearLayout bar = new LinearLayout(this);
        bar.setOrientation(LinearLayout.HORIZONTAL);
        bar.setPadding(dp(12), dp(8), dp(12), dp(4));
        root.addView(bar, 2, new LinearLayout.LayoutParams(-1, -2));

        updateBar[0] = () -> {
            bar.removeAllViews();
            if (!selectMode[0]) {
                bar.addView(makeProjectsBarBtn("\u2611 تحديد", "#2196F3", true, () -> {
                    selectMode[0] = true;
                    selected.clear();
                    refresh[0].run();
                }), projectsBarLp());
                bar.addView(makeProjectsBarBtn("\uD83D\uDDD1 حذف الكل", "#F44336", true, () -> {
                    java.util.List<String> names = new java.util.ArrayList<>();
                    for (File d : allProjects) names.add(d.getName());
                    confirmDeleteProjects(dlg, names, true);
                }), projectsBarLp());
            } else {
                final java.util.List<File> vis = visible.get();
                boolean allVisSelected = !vis.isEmpty();
                for (File d : vis) if (!selected.contains(d.getName())) { allVisSelected = false; break; }
                final boolean fAllSel = allVisSelected;
                bar.addView(makeProjectsBarBtn(fAllSel ? "إلغاء التحديد" : "تحديد الكل", "#2196F3", !vis.isEmpty(), () -> {
                    if (fAllSel) { for (File d : vis) selected.remove(d.getName()); }
                    else { for (File d : vis) selected.add(d.getName()); }
                    refresh[0].run();
                }), projectsBarLp());
                bar.addView(makeProjectsBarBtn("\uD83D\uDDD1 حذف (" + selected.size() + ")", "#F44336", !selected.isEmpty(), () -> {
                    confirmDeleteProjects(dlg, new java.util.ArrayList<>(selected), false);
                }), projectsBarLp());
                bar.addView(makeProjectsBarBtn("إنهاء", "#757575", true, () -> {
                    selectMode[0] = false;
                    selected.clear();
                    refresh[0].run();
                }), projectsBarLp());
            }
        };

        refresh[0] = () -> {
            java.util.Set<String> pinned = pinnedProjects();
            java.util.List<File> list = visible.get();
            box.removeAllViews();
            for (File d : list) {
                final String nm = d.getName();
                Long szL = sizeCache.get(nm);
                String sizeTxt = szL == null ? "..." : String.format(java.util.Locale.US, "%.1f", szL / 1048576.0);
                String sub = projectStatusDot(nm) + sizeTxt + " م.ب | " + sdf.format(new java.util.Date(d.lastModified()));
                if (selectMode[0]) {
                    boolean on = selected.contains(nm);
                    addMenuCardLP(box, "", nm, sub, on ? "#F44336" : "#FF9800", () -> {
                        if (!selected.remove(nm)) selected.add(nm);
                        refresh[0].run();
                    }, null);
                    styleSelectableCard((LinearLayout) box.getChildAt(box.getChildCount() - 1), on);
                } else {
                    boolean isPinned = pinned.contains(nm);
                    String icon = isPinned ? "\uD83D\uDCCC" : "\uD83D\uDCC2";
                    addMenuCardLP(box, icon, nm, sub, "#FF9800", () -> {
                        dlg.dismiss();
                        projectActions(nm);
                    }, () -> confirmPinProject(nm, () -> refresh[0].run()));
                }
            }
            if (list.isEmpty()) {
                addEmptyState(box, "\uD83D\uDD0D", "لا نتائج مطابقة.", null, null);
            }
            updateBar[0].run();
        };

        if (allProjects.size() > 15) {
            LinearLayout searchRow = new LinearLayout(this);
            searchRow.setOrientation(LinearLayout.HORIZONTAL);
            searchRow.setPadding(dp(12), dp(8), dp(12), dp(4));
            final android.widget.EditText search = new android.widget.EditText(this);
            search.setHint("بحث في المشاريع...");
            search.setSingleLine(true);
            search.addTextChangedListener(new android.text.TextWatcher() {
                public void beforeTextChanged(CharSequence s, int a, int b, int c) {}
                public void onTextChanged(CharSequence s, int a, int b, int c) {}
                public void afterTextChanged(android.text.Editable s) {
                    query[0] = s.toString().trim().toLowerCase(java.util.Locale.ROOT);
                    refresh[0].run();
                }
            });
            searchRow.addView(search, new LinearLayout.LayoutParams(0, -2, 1f));
            root.addView(searchRow, 2, new LinearLayout.LayoutParams(-1, -2));
        }

        // تصفية وترتيب حسب الحالة (تُحفظ بين الجلسات)
        final String[] fKeys = {"all", "ok", "fail", "timeout", "none", "empty", "ghok", "ghfail"};
        final String[] fLabels = {"الكل", "\uD83D\uDFE2 نجح", "\uD83D\uDD34 فشل", "\uD83D\uDFE0 توقف بالمهلة", "\u26AA لم يُبنَ", "\uD83D\uDCED فارغ", "GitHub \u2705 نجح", "GitHub \u274C فشل"};
        final String[] sKeys = {"recent", "fail", "name"};
        final String[] sLabels = {"الأحدث تعديلًا", "الفاشلة أولًا", "الاسم"};
        String curF = uiPrefs().getString("proj_filter", "all");
        String curS = uiPrefs().getString("proj_sort", "recent");
        String fl = fLabels[0], sl = sLabels[0];
        for (int i = 0; i < fKeys.length; i++) if (fKeys[i].equals(curF)) fl = fLabels[i];
        for (int i = 0; i < sKeys.length; i++) if (sKeys[i].equals(curS)) sl = sLabels[i];
        LinearLayout fsRow = new LinearLayout(this);
        fsRow.setOrientation(LinearLayout.HORIZONTAL);
        fsRow.setPadding(dp(12), dp(4), dp(12), dp(4));
        fsRow.addView(makeProjectsBarBtn("\uD83D\uDD0E " + fl, curF.equals("all") ? "#607D8B" : "#009688", true, () ->
                new NavAlertBuilder().setTitle("تصفية حسب الحالة").setItems(fLabels, (d, which) -> {
                    uiPrefs().edit().putString("proj_filter", fKeys[which]).apply();
                    dlg.dismiss();
                    showProjects();
                }).show()), projectsBarLp());
        fsRow.addView(makeProjectsBarBtn("\u2195 " + sl, curS.equals("recent") ? "#607D8B" : "#009688", true, () ->
                new NavAlertBuilder().setTitle("ترتيب المشاريع").setItems(sLabels, (d, which) -> {
                    uiPrefs().edit().putString("proj_sort", sKeys[which]).apply();
                    dlg.dismiss();
                    showProjects();
                }).show()), projectsBarLp());
        root.addView(fsRow, 2, new LinearLayout.LayoutParams(-1, -2));

        refresh[0].run();
        dlg.setContentView(root);
        dlg.show();

        new Thread(() -> {
            for (File d : allProjects) sizeCache.put(d.getName(), sizeOf(d));
            runOnUiThread(() -> { if (dlg.isShowing()) refresh[0].run(); });
        }).start();

        // حالة GitHub لكل المشاريع المربوطة تُحدَّث تلقائيًا في الخلفية
        ghRefreshProjectStatuses(allProjects, () -> { if (dlg.isShowing()) refresh[0].run(); });
    }

    // تمييز واضح لحالة التحديد: المحدد = دائرة حمراء ممتلئة بـ ✓ بيضاء + بطاقة بإطار وخلفية حمراء،
    // غير المحدد = دائرة فارغة بإطار رمادي. تُخفى سهم الدخول لأن اللمس هنا للتحديد فقط.
    private void styleSelectableCard(LinearLayout card, boolean on) {
        float d = getResources().getDisplayMetrics().density;
        android.graphics.drawable.GradientDrawable cardBg = new android.graphics.drawable.GradientDrawable();
        cardBg.setCornerRadius(12 * d);
        if (on) {
            cardBg.setColor(isDark() ? 0xFF3A1F1F : 0xFFFDECEA);
            cardBg.setStroke((int) (2 * d), 0xFFF44336);
        } else {
            cardBg.setColor(themeCardBg());
            cardBg.setStroke(themeStrokeW(d), themeCardStroke());
        }
        card.setBackground(cardBg);

        TextView icon = (TextView) card.getChildAt(0);
        android.graphics.drawable.GradientDrawable ic = new android.graphics.drawable.GradientDrawable();
        ic.setShape(android.graphics.drawable.GradientDrawable.OVAL);
        if (on) {
            ic.setColor(0xFFF44336);
            icon.setText("\u2713");
            icon.setTextColor(0xFFFFFFFF);
            icon.setTextSize(20);
            icon.setTypeface(null, Typeface.BOLD);
        } else {
            ic.setColor(0x00000000);
            ic.setStroke((int) (2 * d), 0xFF9E9E9E);
            icon.setText("");
        }
        icon.setBackground(ic);

        View arrow = card.getChildAt(card.getChildCount() - 1);
        arrow.setVisibility(View.GONE);
    }

    private LinearLayout.LayoutParams projectsBarLp() {
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(0, -2, 1f);
        lp.leftMargin = dp(3);
        lp.rightMargin = dp(3);
        return lp;
    }

    private Button makeProjectsBarBtn(String text, String colorHex, boolean enabled, Runnable action) {
        Button b = new Button(this);
        b.setText(text);
        b.setAllCaps(false);
        b.setTextSize(13);
        b.setSingleLine(true);
        b.setTextColor(android.graphics.Color.WHITE);
        android.graphics.drawable.GradientDrawable bg = new android.graphics.drawable.GradientDrawable();
        bg.setColor(android.graphics.Color.parseColor(colorHex));
        bg.setCornerRadius(10 * getResources().getDisplayMetrics().density);
        b.setBackground(bg);
        b.setPadding(dp(8), dp(8), dp(8), dp(8));
        b.setEnabled(enabled);
        b.setAlpha(enabled ? 1f : 0.45f);
        b.setOnClickListener(v -> action.run());
        return b;
    }

    // تأكيد حذف عدة مشاريع (المحدد أو الكل) ثم تنفيذ الحذف كمهمة خلفية
    private void confirmDeleteProjects(final android.app.Dialog dlg, final java.util.List<String> names, final boolean all) {
        if (names.isEmpty()) return;
        final int n = names.size();
        StringBuilder list = new StringBuilder();
        for (int i = 0; i < names.size() && i < 8; i++) list.append("• ").append(names.get(i)).append("\n");
        if (n > 8) list.append("… و").append(n - 8).append(" مشروع آخر\n");
        String title = all ? "حذف كل المشاريع (" + n + ")؟" : "حذف " + n + " مشروع محدد؟";
        new NavAlertBuilder()
                .setTitle(title)
                .setMessage(list + "\nسيُحذف كل ما سبق مع ملفاته من الجهاز نهائيًا ولا يمكن التراجع.")
                .setPositiveButton("حذف", (d, w) -> {
                    if (busy) {
                        Toast.makeText(this, "توجد عملية جارية", Toast.LENGTH_SHORT).show();
                        return;
                    }
                    dlg.dismiss();
                    navReset();
                    startTask(() -> deleteProjectsNow(names));
                })
                .setNegativeButton("إلغاء", null)
                .show();
    }

    private String deleteProjectsNow(java.util.List<String> names) {
        int ok = 0;
        java.util.List<String> failed = new java.util.ArrayList<>();
        java.util.Set<String> pinned = pinnedProjects();
        android.content.SharedPreferences.Editor ed = uiPrefs().edit();
        int i = 0;
        for (String n : names) {
            i++;
            progress("يحذف " + i + "/" + names.size() + ": " + n);
            File f = new File(projectsDir(), n);
            deleteRec(f);
            if (f.exists()) {
                failed.add(n);
            } else {
                ok++;
                pinned.remove(n);
                ed.remove("build_status_" + n).remove("gh_status_" + n).remove("gh_status_ts_" + n);
            }
        }
        ed.putStringSet("pinned_projects", pinned).apply();
        StringBuilder r = new StringBuilder("تم حذف " + ok + " من " + names.size() + " مشروع ✔");
        if (!failed.isEmpty()) {
            r.append("\nتعذّر حذف: ");
            for (int k = 0; k < failed.size(); k++) r.append(k == 0 ? "" : "، ").append(failed.get(k));
        }
        return r.toString();
    }

    private void projectActions(final String name) {
        final android.app.Dialog dlg = newScreen("projectActions" + ":" + String.valueOf(name), () -> projectActions(name));
        LinearLayout root = beginFullscreenCardDialog(dlg, name);
        LinearLayout box = (LinearLayout) root.getTag();

        addMenuSectionHeader(box, "المشروع");
        addMenuCard(box, "\u25B6", "بناء", "#4CAF50", () -> { dlg.dismiss(); buildWithSpaceCheck(name); });
        addMenuCard(box, "\u270F", "إعادة تسمية", "#FF9800", () -> { dlg.dismiss(); renameProject(name); });
        addMenuCard(box, "\uD83D\uDCCB", "نسخ (بدون مساس بالأصل)", "#009688", () -> { dlg.dismiss(); duplicateProject(name); });
        addMenuCard(box, "\uD83D\uDDD1", "حذف", "#F44336", () -> { dlg.dismiss(); confirmDelete(name); });
        addMenuCard(box, "\u2705", "فحص التوافق", "#009688", () -> { dlg.dismiss(); startTask(() -> checkProject(name)); });
        addMenuCard(box, "\uD83D\uDD0F", "توقيع هذا المشروع", "#7C5CFF", () -> { dlg.dismiss(); Intent si = new Intent(this, SigningActivity.class); si.putExtra("l2s_project", name); startActivity(si); });
        addMenuCard(box, "\uD83D\uDCCC", "مسار الاستيراد لهذا المشروع", "#FF9800", () -> { dlg.dismiss(); showProjectPathDialog(name); });

        addMenuSectionHeader(box, "الوصول");
        addMenuCard(box, "\uD83D\uDCC1", "ملفات", "#FFC107", () -> { dlg.dismiss(); fileManager(name); });
        addMenuCard(box, "\uD83D\uDDA5", "طرفية", "#607D8B", () -> { dlg.dismiss(); termScreen(name, ""); });
        if (ghEnabled()) addMenuCard(box, "\uD83D\uDC19", "GitHub", "#424242", () -> { dlg.dismiss(); ghProjectSetup(name); });

        addMenuSectionHeader(box, "النسخ والتصدير");
        addMenuCard(box, "\uD83D\uDD52", "النسخ الاحتياطية", "#3F51B5", () -> { dlg.dismiss(); showProjectBackups(name); });
        addMenuCard(box, "\uD83D\uDCE6", "تصدير كـ zip", "#795548", () -> { dlg.dismiss(); exportProjectZip(name); });
        addMenuCard(box, "\uD83D\uDCDD", "تصدير كـ md (داخل zip)", "#009688", () -> { dlg.dismiss(); exportProjectMd(name); });
        addMenuCard(box, "\uD83D\uDCE5", "استيراد md معدَّل (md أو zip)", "#00796B", () -> {
            dlg.dismiss();
            mdImportProject = name;
            uiPrefs().edit().putString("md_import_project", name).apply();
            pickFile(PICK_MD_IMPORT);
        });

        dlg.setContentView(root);
        dlg.show();
    }

    private void exportProjectZip(final String name) {
        startTask(() -> {
            File src = new File(projectsDir(), name);
            if (!src.exists() || !src.isDirectory()) return "المشروع غير موجود: " + name;
            File tmp = new File(getCacheDir(), name + ".zip");
            long t0 = System.currentTimeMillis();
            progress("يضغط مشروع " + name + " ...");
            try (ZipOutputStream zos = new ZipOutputStream(new BufferedOutputStream(new FileOutputStream(tmp), 1 << 16))) {
                zos.setLevel(Deflater.BEST_COMPRESSION);
                addProjectToZip(zos, src, name, 0);
            } catch (Exception e) {
                tmp.delete();
                return "فشل الضغط: " + e;
            }
            long secs = (System.currentTimeMillis() - t0) / 1000;
            String copyMsg = protectFile(tmp, "application/zip");
            tmp.delete();
            return "تم تصدير المشروع كـ zip ✔ | الزمن " + secs + " ثانية\n" + copyMsg;
        });
    }

    // ===== تصدير المشروع كملف md واحد (داخل zip) للتعديل في مواقع الذكاء الاصطناعي =====
    // الصيغة: شجرة الملفات ثم لكل ملف نصي سطر "## FILE: المسار" وبعده كتلة كود.
    private static final java.util.Set<String> MD_BIN_EXT = new java.util.HashSet<>(Arrays.asList(
            "png", "jpg", "jpeg", "gif", "webp", "bmp", "ico", "jar", "aar", "apk", "aab", "so", "class", "dex",
            "zip", "gz", "tar", "7z", "keystore", "jks", "ttf", "otf", "woff", "woff2", "mp3", "mp4", "wav", "ogg",
            "pdf", "bin", "dat", "db", "sqlite", "arsc"));
    private static final long MD_MAX_FILE = 512L * 1024L;

    private static boolean mdIsGradleModule(File d) {
        return new File(d, "build.gradle").exists() || new File(d, "build.gradle.kts").exists()
                || new File(d, "pom.xml").exists() || new File(d, "CMakeLists.txt").exists();
    }

    private void mdCollect(File dir, String rel, int depth, List<File> files, List<String> rels) {
        File[] kids = dir.listFiles();
        if (kids == null) return;
        Arrays.sort(kids, (a, b) -> a.getName().compareToIgnoreCase(b.getName()));
        for (File k : kids) {
            if (Compat.isSymbolicLink(k)) continue;
            String n = k.getName();
            String r = rel.isEmpty() ? n : rel + "/" + n;
            if (k.isDirectory()) {
                if (n.equals(".git") || n.equals(".idea") || n.equals(".gradle") || n.equals(".cxx")) continue;
                if (n.equals("build") && (depth <= 1 || mdIsGradleModule(dir))) continue; // مخرجات البناء في أي عمق (مثل SharedModules/j2v8/build)
                mdCollect(k, r, depth + 1, files, rels);
            } else {
                files.add(k);
                rels.add(r);
            }
        }
    }

    private static String mdLang(String fileName) {
        int i = fileName.lastIndexOf('.');
        String e = i < 0 ? "" : fileName.substring(i + 1).toLowerCase(java.util.Locale.US);
        switch (e) {
            case "gradle": return "groovy";
            case "kts": return "kotlin";
            case "kt": return "kotlin";
            case "md": return "markdown";
            case "yml": return "yaml";
            case "txt": case "pro": case "": return "";
            default: return e;
        }
    }

    // يقرأ الملف كنص UTF-8 سليم، أو يعيد null إن كان ثنائيًا/كبيرًا/غير UTF-8
    private String mdReadText(File f) {
        try {
            String n = f.getName();
            int i = n.lastIndexOf('.');
            if (i >= 0 && MD_BIN_EXT.contains(n.substring(i + 1).toLowerCase(java.util.Locale.US))) return null;
            if (f.length() > MD_MAX_FILE) return null;
            byte[] b = Compat.readAllBytes(f);
            for (byte x : b) if (x == 0) return null;
            return StandardCharsets.UTF_8.newDecoder()
                    .onMalformedInput(java.nio.charset.CodingErrorAction.REPORT)
                    .onUnmappableCharacter(java.nio.charset.CodingErrorAction.REPORT)
                    .decode(java.nio.ByteBuffer.wrap(b)).toString();
        } catch (Throwable e) {
            return null;
        }
    }

    private static String mdFence(String content) {
        int max = 0, run = 0;
        for (int i = 0; i < content.length(); i++) {
            if (content.charAt(i) == '`') { run++; if (run > max) max = run; } else run = 0;
        }
        StringBuilder f = new StringBuilder();
        for (int i = 0; i < Math.max(3, max + 1); i++) f.append('`');
        return f.toString();
    }

    // سبب عدم تضمين الملف (null = يُضمَّن). الأسباب: حساس / ثنائي / كبير / ليس UTF-8
    private String mdSkipReason(File f, String text) {
        String n = f.getName().toLowerCase(java.util.Locale.US);
        if (n.equals("local.properties") || n.equals("keystore.properties") || n.equals("signing.properties")
                || n.equals(".env") || n.endsWith(".pem") || n.endsWith(".p12") || n.endsWith(".pfx")) return "حساس";
        int i = n.lastIndexOf('.');
        if (i >= 0 && MD_BIN_EXT.contains(n.substring(i + 1))) return "ثنائي";
        if (f.length() > MD_MAX_FILE) return "كبير";
        if (text == null) return "ثنائي/غير UTF-8";
        return null;
    }

    private static int mdCountLines(String t) {
        if (t.isEmpty()) return 0;
        int c = 1;
        for (int i = 0; i < t.length(); i++) if (t.charAt(i) == '\n') c++;
        if (t.endsWith("\n")) c--;
        return c;
    }

    // وصف مختصر للملف غير المضمَّن (مثل ImageSize في markitdown): أبعاد الصورة أو الحجم
    private String mdSkipInfo(File f, String reason) {
        String n = f.getName().toLowerCase(java.util.Locale.US);
        String extra = "";
        if (n.endsWith(".png") || n.endsWith(".jpg") || n.endsWith(".jpeg") || n.endsWith(".webp") || n.endsWith(".gif") || n.endsWith(".bmp")) {
            try {
                android.graphics.BitmapFactory.Options o = new android.graphics.BitmapFactory.Options();
                o.inJustDecodeBounds = true;
                android.graphics.BitmapFactory.decodeFile(f.getAbsolutePath(), o);
                if (o.outWidth > 0) extra = " " + o.outWidth + "x" + o.outHeight;
            } catch (Throwable ignored) {}
        }
        return "  (غير مضمَّن: " + reason + extra + " — " + fmtSize(f.length()) + ")";
    }

    private void exportProjectMd(final String name) {
        startTask(() -> {
            File src = new File(projectsDir(), name);
            if (!src.exists() || !src.isDirectory()) return "المشروع غير موجود: " + name;
            long t0 = System.currentTimeMillis();
            progress("يجمع ملفات المشروع " + name + " في ملف md ...");
            File mdTmp = new File(getCacheDir(), name + ".md");
            File zipTmp = new File(getCacheDir(), name + "-md.zip");
            int textCount = 0, skipCount = 0;
            try {
                List<File> files = new ArrayList<>();
                List<String> rels = new ArrayList<>();
                mdCollect(src, "", 0, files, rels);
                String[] texts = new String[files.size()];
                String[] reasons = new String[files.size()];
                long totalBytes = 0;
                for (int i = 0; i < files.size(); i++) {
                    File cf = files.get(i);
                    totalBytes += cf.length();
                    String why = mdSkipReason(cf, null);
                    if (why != null && why.equals("حساس")) { reasons[i] = why; skipCount++; continue; }
                    texts[i] = mdReadText(cf);
                    reasons[i] = mdSkipReason(cf, texts[i]);
                    if (reasons[i] != null) { texts[i] = null; skipCount++; } else textCount++;
                }
                String stamp = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", java.util.Locale.US).format(new java.util.Date());
                try (java.io.Writer w = new java.io.BufferedWriter(new java.io.OutputStreamWriter(new FileOutputStream(mdTmp), StandardCharsets.UTF_8), 1 << 16)) {
                    w.write("# مشروع: " + name + "\n\n");
                    w.write("> مُصدَّر من L2SBuilder بتاريخ " + stamp + "\n");
                    w.write(">\n");
                    w.write("> كل ملف نصي يبدأ بسطر `## FILE: المسار` ثم كتلة كود تحوي محتواه كاملًا.\n");
                    w.write("> عند طلب التعديل من الذكاء الاصطناعي: اطلب منه إعادة كل ملف معدَّل كاملًا بنفس سطر `## FILE:` والمسار نفسه.\n");
                    w.write("> الملفات الثنائية والكبيرة (> 512KB) والحساسة (local.properties، مفاتيح التوقيع) غير مضمَّنة، وسبب ذلك مكتوب أمام كل ملف في الشجرة.\n");
                    w.write("> لا تحذف ولا تعدّل الملفات غير المضمَّنة؛ تبقى كما هي في المشروع عند الاستيراد.\n\n");
                    w.write("## ملخص\n\n");
                    w.write("- إجمالي الملفات: " + files.size() + " (" + fmtSize(totalBytes) + ")\n");
                    w.write("- مضمَّن كاملًا: " + textCount + " | غير مضمَّن: " + skipCount + "\n\n");
                    w.write("## شجرة الملفات\n\n```\n");
                    for (int i = 0; i < files.size(); i++) {
                        if (texts[i] == null) w.write(rels.get(i) + mdSkipInfo(files.get(i), reasons[i]) + "\n");
                        else w.write(rels.get(i) + "  (" + mdCountLines(texts[i]) + " سطر، " + fmtSize(files.get(i).length()) + ")\n");
                    }
                    w.write("```\n");
                    for (int i = 0; i < files.size(); i++) {
                        if (texts[i] == null) continue;
                        String t = texts[i];
                        String fence = mdFence(t);
                        w.write("\n## FILE: " + rels.get(i) + "\n\n");
                        w.write(fence + mdLang(files.get(i).getName()) + "\n");
                        w.write(t);
                        if (!t.endsWith("\n")) w.write("\n");
                        w.write(fence + "\n");
                    }
                }
                progress("يضغط ملف md داخل zip ...");
                byte[] buf = new byte[1 << 16];
                try (ZipOutputStream zos = new ZipOutputStream(new BufferedOutputStream(new FileOutputStream(zipTmp), 1 << 16))) {
                    zos.setLevel(Deflater.BEST_COMPRESSION);
                    zos.putNextEntry(new ZipEntry(name + ".md"));
                    try (InputStream in = new FileInputStream(mdTmp)) {
                        int r;
                        while ((r = in.read(buf)) > 0) zos.write(buf, 0, r);
                    }
                    zos.closeEntry();
                }
            } catch (Throwable e) {
                mdTmp.delete();
                zipTmp.delete();
                return "فشل تصدير md: " + e;
            }
            long mdSize = mdTmp.length();
            mdTmp.delete();
            long secs = (System.currentTimeMillis() - t0) / 1000;
            String copyMsg = protectFile(zipTmp, "application/zip");
            zipTmp.delete();
            return "تم تصدير المشروع كـ md داخل zip ✔ | " + textCount + " ملف نصي"
                    + (skipCount > 0 ? "، " + skipCount + " غير مضمَّن (ثنائي/كبير)" : "")
                    + " | حجم md " + fmtSize(mdSize) + " | الزمن " + secs + " ثانية\n" + copyMsg;
        });
    }

    // ===== استيراد md معدَّل (أو zip يحويه) وتطبيقه على المشروع =====
    // zip بلا كلمة سر أو بكلمة سر (ZipCrypto): تُجرَّب كلمة السر الافتراضية تلقائيًا، وإلا يُسأل المستخدم.
    private byte[] mdReadUri(Uri u) throws IOException {
        try (InputStream in = getContentResolver().openInputStream(u)) {
            if (in == null) throw new IOException("تعذّر فتح الملف");
            java.io.ByteArrayOutputStream bos = new java.io.ByteArrayOutputStream();
            byte[] buf = new byte[1 << 16];
            long tot = 0;
            int r;
            while ((r = in.read(buf)) > 0) {
                tot += r;
                if (tot > 64L * 1024 * 1024) throw new IOException("الملف كبير جدًا (أكثر من 64MB)");
                bos.write(buf, 0, r);
            }
            return bos.toByteArray();
        }
    }

    private void mdImportBegin(final String name, final Uri u) { mdImportBegin(name, u, false); }

    // create=true (من «استيراد ذكي»): إن لم يوجد المشروع يُنشأ جديدًا، وإن وُجد تُقارَن الملفات ويُطبَّق المعدَّل فقط.
    private void mdImportBegin(final String name, final Uri u, final boolean create) {
        final StringBuilder note = termNoteStart("📥 استيراد md للمشروع " + name + ": جارٍ قراءة الملف... ⏳");
        new Thread(() -> {
            final byte[] data;
            try {
                data = mdReadUri(u);
            } catch (Throwable e) {
                termNoteSet(note, "📥 تعذّرت قراءة الملف: " + e.getMessage());
                return;
            }
            if (data.length >= 4 && data[0] == 'P' && data[1] == 'K') {
                final List<ZipCryptoReader.Entry> mds = new ArrayList<>();
                try {
                    for (ZipCryptoReader.Entry e : ZipCryptoReader.list(data)) {
                        if (!e.isDirectory() && e.name.toLowerCase(java.util.Locale.US).endsWith(".md")) mds.add(e);
                    }
                } catch (Throwable e) {
                    termNoteSet(note, "📥 تعذّرت قراءة zip: " + e.getMessage());
                    return;
                }
                if (mds.isEmpty()) {
                    termNoteSet(note, "📥 لا يوجد ملف md داخل هذا zip");
                    return;
                }
                mdImportZip(name, data, mds, null, note, create);
            } else {
                mdImportText(name, new String(data, StandardCharsets.UTF_8), note, create);
            }
        }).start();
    }

    // تُنفَّذ في خيط خلفي. pw == null ⇒ تُجرَّب كلمة السر الافتراضية للتطبيق ثم يُطلب من المستخدم.
    private void mdImportZip(final String name, final byte[] data, final List<ZipCryptoReader.Entry> mds,
                             final String pw, final StringBuilder note, final boolean create) {
        String text = null;
        try {
            for (ZipCryptoReader.Entry e : mds) {
                String t;
                if (e.isEncrypted()) {
                    t = new String(ZipCryptoReader.read(data, e, pw != null ? pw : EMBED_ZIP_PASSWORD), StandardCharsets.UTF_8);
                } else {
                    t = new String(ZipCryptoReader.read(data, e, null), StandardCharsets.UTF_8);
                }
                if (text == null) text = t;
                if (t.contains("FILE:")) { text = t; break; }
            }
        } catch (ZipCryptoReader.WrongPasswordException w) {
            mdAskPassword(name, data, mds, note, pw != null, create);
            return;
        } catch (Throwable e) {
            termNoteSet(note, "📥 تعذّر فتح zip: " + e.getMessage());
            return;
        }
        mdImportText(name, text == null ? "" : text, note, create);
    }

    private void mdAskPassword(final String name, final byte[] data, final List<ZipCryptoReader.Entry> mds,
                               final StringBuilder note, final boolean wrong, final boolean create) {
        runOnUiThread(() -> {
            termNoteSet(note, "📥 الملف محمي بكلمة سر — بانتظار إدخالها");
            final android.widget.EditText et = new android.widget.EditText(this);
            et.setHint("كلمة سر zip");
            et.setSingleLine(true);
            new NavAlertBuilder()
                    .setTitle(wrong ? "كلمة السر غير صحيحة" : "الملف محمي بكلمة سر")
                    .setMessage("أدخل كلمة السر لفتح zip.\nإن لم تكن متوفرة: اضغط إلغاء، واستورد ملف md مباشرة (بدون zip) فلا يحتاج كلمة سر.")
                    .setView(et)
                    .setPositiveButton("فتح", (d, w) -> {
                        final String p = et.getText().toString();
                        termNoteSet(note, "📥 جارٍ فتح zip ... ⏳");
                        new Thread(() -> mdImportZip(name, data, mds, p, note, create)).start();
                    })
                    .setNegativeButton("إلغاء", (d, w) -> termNoteSet(note, "📥 أُلغي الاستيراد"))
                    .setOnCancelListener(d -> termNoteSet(note, "📥 أُلغي الاستيراد"))
                    .show();
        });
    }

    // تُنفَّذ في خيط خلفي: تحلّل md وتقارنه بالمشروع ثم تعرض نافذة التأكيد.
    private void mdImportText(final String name0, final String text, final StringBuilder note, final boolean create) {
        String hn = create ? mdHeaderName(text) : null;
        final String name = hn != null ? hn : name0;
        final MdProject.Result r = MdProject.parse(text);
        if (r.items.isEmpty()) {
            termNoteSet(note, "📥 لم أجد في الملف أي قسم بصيغة «## FILE: المسار» يتبعه كتلة كود"
                    + (r.truncated > 0 ? " (الردّ يبدو مقطوعًا)" : ""));
            return;
        }
        final File proj = new File(projectsDir(), name);
        boolean newTmp = false;
        if (!proj.isDirectory()) {
            if (create && !proj.exists() && proj.mkdirs()) {
                newTmp = true;
            } else {
                termNoteSet(note, "📥 المشروع غير موجود: " + name);
                return;
            }
        }
        final boolean isNew = newTmp;
        String canonTmp;
        try {
            canonTmp = proj.getCanonicalPath() + File.separator;
        } catch (IOException e) {
            termNoteSet(note, "📥 تعذّر فحص مسار المشروع: " + e.getMessage());
            return;
        }
        final String canon = canonTmp;
        final List<MdProject.Item> todo = new ArrayList<>();
        int same = 0, bad = r.badPaths;
        for (MdProject.Item it : r.items) {
            File f = new File(proj, it.path);
            try {
                if (!f.getCanonicalPath().startsWith(canon)) { bad++; continue; }
            } catch (IOException e) { bad++; continue; }
            if (!f.isFile()) {
                it.status = 2;
                todo.add(it);
            } else {
                boolean eq = false;
                try {
                    String old = new String(Compat.readAllBytes(f), StandardCharsets.UTF_8);
                    eq = old.equals(it.content) || (old + "\n").equals(it.content);
                } catch (Throwable ignored) {}
                if (eq) same++;
                else { it.status = 1; todo.add(it); }
            }
        }
        final int fSame = same, fBad = bad;
        if (todo.isEmpty()) {
            if (isNew) deleteRec(proj);
            termNoteSet(note, "📥 لا توجد تغييرات: كل الملفات (" + fSame + ") مطابقة للمشروع الحالي");
            return;
        }
        int nChanged = 0, nNew = 0;
        StringBuilder list = new StringBuilder();
        int shown = 0;
        for (MdProject.Item it : todo) {
            if (it.status == 1) nChanged++; else nNew++;
            if (shown < 30) { list.append(it.status == 1 ? "✏️ " : "➕ ").append(it.path).append("\n"); shown++; }
        }
        if (todo.size() > shown) list.append("... و").append(todo.size() - shown).append(" ملفات أخرى\n");
        final StringBuilder msg = new StringBuilder();
        msg.append("معدَّل: ").append(nChanged).append(" | جديد: ").append(nNew).append(" | بلا تغيير: ").append(fSame).append("\n\n");
        msg.append(list);
        if (r.truncated > 0) msg.append("\n⚠️ آخر قسم في الملف غير مكتمل (الردّ مقطوع) وتم تجاهله.");
        if (fBad > 0) msg.append("\n⚠️ تم تجاهل ").append(fBad).append(" مسار غير آمن.");
        if (isNew) msg.append("\n\nسيُنشأ مشروع جديد باسم «" + name + "».");
        else msg.append("\n\nستُحفظ نسخة احتياطية من المشروع قبل التطبيق (تجدها في «النسخ الاحتياطية»).");
        final int fChanged = nChanged, fNew = nNew;
        runOnUiThread(() -> {
            termNoteSet(note, "📥 تم تحليل md: " + fChanged + " معدَّل، " + fNew + " جديد — بانتظار تأكيدك");
            new NavAlertBuilder()
                    .setTitle((isNew ? "إنشاء مشروع من md: " : "تطبيق md على ") + name)
                    .setMessage(msg.toString())
                    .setPositiveButton(isNew ? "أنشئ" : "طبّق", (d, w) -> {
                        termNoteSet(note, "📥 جارٍ تطبيق التغييرات ... ⏳");
                        startTask(() -> mdApply(name, todo, isNew));
                    })
                    .setNegativeButton("إلغاء", (d, w) -> {
                        if (isNew) deleteRec(proj);
                        termNoteSet(note, "📥 أُلغي الاستيراد");
                    })
                    .setOnCancelListener(d -> {
                        if (isNew) deleteRec(proj);
                        termNoteSet(note, "📥 أُلغي الاستيراد");
                    })
                    .show();
        });
    }

    private String mdApply(String name, List<MdProject.Item> todo) { return mdApply(name, todo, false); }

    private String mdApply(String name, List<MdProject.Item> todo, boolean isNew) {
        File proj = new File(projectsDir(), name);
        if (!proj.isDirectory()) return "المشروع غير موجود: " + name;
        String ts = null;
        if (!isNew) {
            progress("نسخة احتياطية قبل التطبيق ...");
            ts = backupProjectNow(name);
        }
        int changed = 0, added = 0, failed = 0;
        try {
            String canon = proj.getCanonicalPath() + File.separator;
            for (MdProject.Item it : todo) {
                try {
                    File f = new File(proj, it.path);
                    if (!f.getCanonicalPath().startsWith(canon)) { failed++; continue; }
                    File par = f.getParentFile();
                    if (par != null) par.mkdirs();
                    Compat.write(f, it.content.getBytes(StandardCharsets.UTF_8));
                    termAppend((it.status == 1 ? "✏️ " : "➕ ") + it.path + "\n");
                    if (it.status == 1) changed++; else added++;
                } catch (Throwable e) {
                    failed++;
                    termAppend("⚠️ فشل: " + it.path + " — " + e.getMessage() + "\n");
                }
            }
        } catch (Throwable e) {
            return "فشل التطبيق: " + e;
        }
        if (isNew && added > 0) uiPrefs().edit().putString("proj", name).apply();
        return (isNew ? "تم إنشاء المشروع «" + name + "» من md ✔ | ملفات " + added
                : "تم تطبيق md على «" + name + "» ✔ | معدَّل " + changed + " | جديد " + added
                + (failed > 0 ? " | فشل " + failed : "")
                + (ts != null ? "\nنسخة احتياطية قبل التطبيق: " + ts : ""));
    }

    private void confirmDelete(final String name) {
        new NavAlertBuilder()
                .setTitle("حذف " + name + "؟")
                .setMessage("سيُحذف المشروع وكل ملفاته من الجهاز.")
                .setPositiveButton("حذف", (d, w) -> startTask(() -> {
                    deleteRec(new File(projectsDir(), name));
                    SigningStore.deleteProfile(this, name);
                    return "تم حذف " + name;
                }))
                .setNegativeButton("إلغاء", null)
                .show();
    }

    private void renameProject(final String oldName) {
        final android.widget.EditText et = new android.widget.EditText(this);
        et.setText(oldName);
        et.setSelectAllOnFocus(true);
        new NavAlertBuilder()
                .setTitle("اسم جديد للمشروع")
                .setView(et)
                .setPositiveButton("تسمية", (d, w) -> {
                    String nn = et.getText().toString().trim();
                    nn = nn.replaceAll("[\\\\/:*?\"<>|\\s]", "_");
                    if (nn.isEmpty() || nn.equals(".") || nn.equals("..")) {
                        termMsg("اسم غير صالح.");
                        return;
                    }
                    if (nn.equals(oldName)) return;
                    File src = new File(projectsDir(), oldName);
                    File dst = new File(projectsDir(), nn);
                    if (dst.exists()) {
                        termMsg("يوجد مشروع بهذا الاسم: " + nn);
                        return;
                    }
                    if (!src.renameTo(dst)) {
                        termMsg("فشلت إعادة التسمية.");
                        return;
                    }
                    try { SigningStore.renameProfile(this, oldName, nn); } catch (Exception ignored) {}
                    try { new File(getCacheDir(), oldName + ".apk").delete(); } catch (Exception ignored) {}
                    try {
                        File ext = getExternalFilesDir(null);
                        if (ext != null) new File(ext, oldName + ".apk").delete();
                    } catch (Exception ignored) {}
                    termMsg("تمت التسمية: " + oldName + " ← " + nn + "\nالناتج القادم: " + nn + ".apk");
                    showProjects();
                })
                .setNegativeButton("إلغاء", null)
                .show();
    }

    private void duplicateProject(final String oldName) {
        final File src = new File(projectsDir(), oldName);
        final String suggested = fmUniqueName(projectsDir(), oldName).getName();

        final android.widget.EditText et = new android.widget.EditText(this);
        et.setText(suggested);
        et.setSelectAllOnFocus(true);

        new NavAlertBuilder()
                .setTitle("نسخ المشروع")
                .setMessage("سيُنسخ \"" + oldName + "\" بالكامل إلى مشروع جديد بهذا الاسم.\nالمشروع الأصلي لن يتغيّر إطلاقًا.")
                .setView(et)
                .setPositiveButton("نسخ", (d, w) -> {
                    String nn = et.getText().toString().trim();
                    nn = nn.replaceAll("[\\\\/:*?\"<>|\\s]", "_");
                    if (nn.isEmpty() || nn.equals(".") || nn.equals("..")) {
                        termMsg("اسم غير صالح.");
                        return;
                    }
                    if (nn.equals(oldName)) {
                        termMsg("اختر اسمًا مختلفًا عن اسم المشروع الأصلي.");
                        return;
                    }
                    final String finalName = nn;
                    final File dst = new File(projectsDir(), finalName);
                    if (dst.exists()) {
                        termMsg("يوجد مشروع بهذا الاسم بالفعل: " + finalName);
                        return;
                    }

                    progress("جارٍ نسخ \"" + oldName + "\" إلى \"" + finalName + "\" ...\nالأصل لن يتأثر.");

                    new Thread(() -> {
                        String err = null;
                        try {
                            fmCopyRec(src, dst, 0);
                        } catch (Throwable t) {
                            err = t.getClass().getSimpleName() + ": " + t.getMessage();
                            try { deleteRec(dst); } catch (Exception ignored) {}
                        }
                        final String ferr = err;
                        runOnUiThread(() -> {
                            if (ferr != null) {
                                termMsg("❌ فشل نسخ المشروع:\n" + ferr);
                            } else {
                                termMsg("✅ تم النسخ بنجاح\n"
                                        + oldName + " → " + finalName
                                        + "\n\nالمشروع الأصلي \"" + oldName + "\" سليم ولم يتغيّر.");
                            }
                            showProjects();
                        });
                    }).start();
                })
                .setNegativeButton("إلغاء", null)
                .show();
    }

    private String smartImport(final Uri u) {
        progress("يفحص محتوى الملف...");
        final java.util.ArrayList<String> roots = new java.util.ArrayList<>();
        int total = 0;
        try (InputStream in = getContentResolver().openInputStream(u);
             ZipInputStream zin = new ZipInputStream(new BufferedInputStream(in, 1 << 16))) {
            ZipEntry e;
            while ((e = zin.getNextEntry()) != null) {
                total++;
                if (e.isDirectory()) continue;
                String nm = e.getName().replace('\\', '/');
                String base = nm.substring(nm.lastIndexOf('/') + 1);
                if (base.equals("settings.gradle") || base.equals("settings.gradle.kts")) {
                    int k = nm.lastIndexOf('/');
                    String r = k < 0 ? "" : nm.substring(0, k + 1);
                    if (!roots.contains(r)) roots.add(r);
                }
            }
        } catch (Exception ex) {
            return "الملف ليس zip صالحًا، أو تعذّرت قراءته: " + ex
                    + "\n(الاستيراد الذكي يدعم zip فقط حاليًا.)";
        }
        if (roots.isEmpty()) {
            return "فحصت " + total + " عنصرًا ولم أجد مشروع أندرويد (settings.gradle).";
        }
        final java.util.ArrayList<String> top = new java.util.ArrayList<>();
        for (String r : roots) {
            boolean nested = false;
            for (String o : roots) if (!o.equals(r) && r.startsWith(o)) nested = true;
            if (!nested) top.add(r);
        }
        final String zipName = projectName(u);
        if (top.size() == 1) {
            final String r = top.get(0);
            String mt = null;
            try { mt = findProjectByIdentity(zipIdentity(u, r)); } catch (Throwable ignored) {}
            final String match = (mt != null && !mt.equals(zipName)) ? mt : null;
            runOnUiThread(() -> {
                NavAlertBuilder b = new NavAlertBuilder();
                b.setTitle("وجدت مشروعًا")
                 .setMessage("المجلد: " + (r.isEmpty() ? "(الجذر)" : r) + "\nالاسم: " + zipName
                         + (match != null ? "\n\nيبدو أنه نسخة معدّلة من «" + match + "». التحديث يحتفظ بالبناء السابق." : "\nاستيراد؟"));
                if (match != null) {
                    b.setPositiveButton("حدّث «" + match + "»", (d, w) -> startTask(() -> importRoots(u, top, match)));
                    b.setNeutralButton("جديد باسم الملف", (d, w) -> startTask(() -> importRoots(u, top, zipName)));
                } else {
                    b.setPositiveButton("استيراد", (d, w) -> startTask(() -> importRoots(u, top, zipName)));
                }
                b.setNegativeButton("إلغاء", null).show();
            });
        } else {
            final String[] labels = new String[top.size()];
            final boolean[] on = new boolean[top.size()];
            for (int i = 0; i < labels.length; i++) labels[i] = top.get(i).isEmpty() ? "(الجذر)" : top.get(i);
            runOnUiThread(() -> new NavAlertBuilder()
                    .setTitle("وجدت " + top.size() + " مشاريع، اختر")
                    .setView(switchListView(labels, on))
                    .setPositiveButton("استيراد", (d, w) -> {
                        final java.util.ArrayList<String> pick = new java.util.ArrayList<>();
                        for (int i = 0; i < on.length; i++) if (on[i]) pick.add(top.get(i));
                        if (pick.isEmpty()) return;
                        startTask(() -> importRoots(u, pick, zipName));
                    })
                    .setNegativeButton("إلغاء", null)
                    .show());
        }
        return "وجدت " + top.size() + " مشروعًا. اختر ما تريد استيراده.";
    }

    private String importRoots(Uri u, java.util.List<String> picks, String zipName) {
        java.util.HashMap<String, File> dst = new java.util.HashMap<>();
        java.util.HashMap<String, String> names = new java.util.HashMap<>();
        for (String r : picks) {
            String nm;
            if (picks.size() == 1) nm = zipName;
            else if (r.isEmpty()) nm = zipName;
            else {
                String t = r.substring(0, r.length() - 1);
                nm = t.substring(t.lastIndexOf('/') + 1);
            }
            nm = nm.replaceAll("[\\\\/:*?\"<>|\\s]", "_");
            if (nm.isEmpty() || nm.equals(".") || nm.equals("..")) nm = "project";
            String base = nm;
            int c = 2;
            while (names.containsValue(nm)) nm = base + "_" + (c++);
            names.put(r, nm);
            File d = new File(projectsDir(), nm);
            File st = new File(getFilesDir(), "stash_" + nm);
            deleteRec(st);
            stashBuildDirs(d, d, st, 0);
            deleteRec(d);
            d.mkdirs();
            dst.put(r, d);
        }
        int n = 0;
        try (InputStream in = getContentResolver().openInputStream(u);
             ZipInputStream zin = new ZipInputStream(new BufferedInputStream(in, 1 << 16))) {
            byte[] buf = new byte[65536];
            ZipEntry e;
            while ((e = zin.getNextEntry()) != null) {
                String nm = e.getName().replace('\\', '/');
                String hit = null;
                for (String r : picks) {
                    if (nm.startsWith(r) && (hit == null || r.length() > hit.length())) hit = r;
                }
                if (hit == null) continue;
                String rel = nm.substring(hit.length());
                if (rel.isEmpty()) continue;
                File root = dst.get(hit);
                File f = new File(root, rel);
                if (!f.getCanonicalPath().startsWith(root.getCanonicalPath() + File.separator)) continue;
                if (e.isDirectory()) {
                    f.mkdirs();
                    continue;
                }
                f.getParentFile().mkdirs();
                try (FileOutputStream fo = new FileOutputStream(f)) {
                    int k;
                    while ((k = zin.read(buf)) > 0) fo.write(buf, 0, k);
                }
                n++;
            }
        } catch (Exception ex) {
            for (String nm2 : names.values()) { File st2 = new File(getFilesDir(), "stash_" + nm2); restoreBuildDirs(st2, new File(projectsDir(), nm2)); deleteRec(st2); }
            return "فشل الاستيراد: " + ex;
        }
        for (String nm2 : names.values()) { File st2 = new File(getFilesDir(), "stash_" + nm2); restoreBuildDirs(st2, new File(projectsDir(), nm2)); deleteRec(st2); }
        StringBuilder r = new StringBuilder("تم الاستيراد ✔ | ملفات: " + n + "\n");
        for (String k : names.keySet()) r.append("- ").append(names.get(k)).append("\n");
        r.append("افتح الزر 9 للبناء.");
        return r.toString();
    }

    private static class SmartItem {
        String kind, root, entry, label, name;
        File stage;
        Uri src;          // الملف المصدر الذي وُجد فيه هذا العنصر (يدعم الفحص متعدد الملفات)
        String srcZipName; // اسم الملف المصدر (بدون امتداد)، يُستخدم كاسم افتراضي للمشروع
        boolean gz;        // العنصر مصدره ملف tar.gz كامل وليس مدخلًا داخل zip
    }

    private static int segIndex(String nm, String m) {
        if (nm.startsWith(m)) return 0;
        int k = nm.indexOf("/" + m);
        return k < 0 ? -1 : k + 1;
    }

    private static SmartItem mkItem(String kind, String root, String entry, String label) {
        SmartItem s = new SmartItem();
        s.kind = kind;
        s.root = root;
        s.entry = entry;
        s.label = label;
        return s;
    }

    private static String rootLabel(String r) {
        return r.isEmpty() ? "(الجذر)" : r;
    }

    private String compLabel(String c) {
        switch (c) {
            case "sdk": return "SDK";
            case "gradle": return "مكتبات Gradle";
            case "tools": return "أدوات L2S";
            case "rootfs": return "Debian rootfs";
            case "key": return "مفتاح التوقيع";
            default: return c;
        }
    }

    private String dirOf(String c) {
        switch (c) {
            case "gradle": return "gradle-home";
            default: return c;
        }
    }

    // يفحص ملفًا واحدًا ويعيد قائمة العناصر المكتشفة فيه (بدون وسم src/srcZipName/gz —
    // تلك تُضبط من المستدعي smartScanTask بعد الإعادة).
    private java.util.ArrayList<SmartItem> smartScanOne(final Uri u, boolean[] isGzOut, int[] totalOut) {
        final java.util.ArrayList<String> projRoots = new java.util.ArrayList<>();
        String sdkRoot = null, gradleRoot = null, toolsRoot = null, keyEntry = null, gzEntry = null;
        boolean isGz = false;
        int total = 0;
        boolean zipFallback = false;
        // مشاريع md المكتشفة: {اسم المدخل داخل zip (فارغ لملف md مباشر), عدد الملفات أو "?", "1" إن كان محميًا بكلمة سر}
        final java.util.ArrayList<String[]> mdFound = new java.util.ArrayList<>();
        try (InputStream raw = getContentResolver().openInputStream(u);
             BufferedInputStream in = new BufferedInputStream(raw, 1 << 16)) {
            in.mark(8);
            int b1 = in.read(), b2 = in.read();
            in.reset();
            if (b1 == 0x1f && b2 == 0x8b) {
                isGz = true;
            } else if (!(b1 == 'P' && b2 == 'K')) {
                // ليس zip ولا gzip: يُعامل كملف نصي، فإن كان md بصيغة «## FILE:» فهو مشروع md غير مضغوط
                total = 1;
                byte[] all = readCapped(in, 64L << 20);
                if (all != null) {
                    String t = new String(all, StandardCharsets.UTF_8);
                    if (t.contains("FILE:")) {
                        int c = MdProject.parse(t).items.size();
                        if (c > 0) mdFound.add(new String[]{"", String.valueOf(c), "0"});
                    }
                }
            } else try {
                ZipInputStream zin = new ZipInputStream(in);
                ZipEntry e;
                while ((e = zin.getNextEntry()) != null) {
                    total++;
                    if (e.isDirectory()) continue;
                    String nm = e.getName().replace('\\', '/');
                    String base = nm.substring(nm.lastIndexOf('/') + 1);
                    String low = base.toLowerCase();
                    int i;
                    if (low.endsWith(".md")) {
                        try {
                            byte[] mb = readCapped(zin, 8L << 20);
                            if (mb != null) {
                                String t = new String(mb, StandardCharsets.UTF_8);
                                if (t.contains("FILE:")) {
                                    int c = MdProject.parse(t).items.size();
                                    if (c > 0) mdFound.add(new String[]{nm, String.valueOf(c), "0"});
                                }
                            }
                        } catch (IOException ignoredMd) {}
                    }
                    if (base.equals("settings.gradle") || base.equals("settings.gradle.kts")) {
                        String r = nm.substring(0, nm.length() - base.length());
                        if (!projRoots.contains(r)) projRoots.add(r);
                    }
                    if (sdkRoot == null) {
                        i = segIndex(nm, "build-tools/");
                        if (i < 0) i = segIndex(nm, "platforms/android-");
                        if (i >= 0) sdkRoot = nm.substring(0, i);
                    }
                    if (gradleRoot == null) {
                        i = segIndex(nm, "caches/modules-2/");
                        if (i < 0) i = segIndex(nm, "wrapper/dists/");
                        if (i >= 0) gradleRoot = nm.substring(0, i);
                    }
                    if (toolsRoot == null && (nm.equals("bin/aapt2") || nm.endsWith("/bin/aapt2"))) {
                        toolsRoot = nm.substring(0, nm.length() - 9);
                    }
                    if (keyEntry == null && (low.endsWith(".keystore") || low.endsWith(".jks"))) keyEntry = nm;
                    if (gzEntry == null && (low.endsWith(".tar.gz") || low.endsWith(".tgz"))) gzEntry = nm;
                }
            } catch (java.util.zip.ZipException ze) {
                // zip مشفَّر (ZipCrypto): ZipInputStream لا يدعمه، نكمل بقارئ التطبيق الخاص
                zipFallback = true;
            }
        } catch (Exception ex) {
            isGzOut[0] = false;
            totalOut[0] = -1; // إشارة فشل القراءة
            return null;
        }

        if (zipFallback) {
            try {
                byte[] data = mdReadUri(u);
                for (ZipCryptoReader.Entry e : ZipCryptoReader.list(data)) {
                    if (e.isDirectory() || !e.name.toLowerCase(java.util.Locale.US).endsWith(".md")) continue;
                    total++;
                    try {
                        byte[] mb = ZipCryptoReader.read(data, e, e.isEncrypted() ? EMBED_ZIP_PASSWORD : null);
                        String t = new String(mb, StandardCharsets.UTF_8);
                        if (t.contains("FILE:")) {
                            int c = MdProject.parse(t).items.size();
                            if (c > 0) mdFound.add(new String[]{e.name, String.valueOf(c), "0"});
                        }
                    } catch (ZipCryptoReader.WrongPasswordException w) {
                        mdFound.add(new String[]{e.name, "?", "1"});
                    } catch (Throwable ignoredMd) {}
                }
            } catch (Throwable ex) {
                isGzOut[0] = false;
                totalOut[0] = -1;
                return null;
            }
            if (total == 0) total = 1;
        }

        final java.util.ArrayList<SmartItem> items = new java.util.ArrayList<>();
        java.util.ArrayList<String> compRoots = new java.util.ArrayList<>();
        if (isGz) {
            items.add(mkItem("rootfs", "", null, "Debian rootfs (ملف tar.gz)"));
        } else {
            if (sdkRoot != null) { items.add(mkItem("sdk", sdkRoot, null, "SDK: " + rootLabel(sdkRoot))); compRoots.add(sdkRoot); }
            if (gradleRoot != null) { items.add(mkItem("gradle", gradleRoot, null, "مكتبات Gradle: " + rootLabel(gradleRoot))); compRoots.add(gradleRoot); }
            if (toolsRoot != null) { items.add(mkItem("tools", toolsRoot, null, "أدوات L2S: " + rootLabel(toolsRoot))); compRoots.add(toolsRoot); }
            if (keyEntry != null) items.add(mkItem("key", "", keyEntry, "مفتاح التوقيع: " + keyEntry));
            if (gzEntry != null) items.add(mkItem("rootfs", "", gzEntry, "Debian rootfs: " + gzEntry));
            for (String r : projRoots) {
                boolean skip = false;
                for (String o : projRoots) if (!o.equals(r) && r.startsWith(o)) skip = true;
                for (String c : compRoots) if (!c.isEmpty() && r.startsWith(c)) skip = true;
                if (!skip) items.add(mkItem("project", r, null, "مشروع: " + rootLabel(r)));
            }
        }
        for (String[] m : mdFound) {
            String lbl = "ملف md: " + (m[0].isEmpty() ? "" : m[0] + " — ")
                    + ("1".equals(m[2]) ? "محمي بكلمة سر" : m[1] + " ملف");
            items.add(mkItem("md", "", m[0].isEmpty() ? null : m[0], lbl));
        }
        isGzOut[0] = isGz;
        totalOut[0] = total;
        return items;
    }

    // يقرأ حتى cap بايت؛ يعيد null إن تجاوز الحد.
    private static byte[] readCapped(InputStream in, long cap) throws IOException {
        java.io.ByteArrayOutputStream bos = new java.io.ByteArrayOutputStream();
        byte[] buf = new byte[1 << 16];
        long tot = 0;
        int r;
        while ((r = in.read(buf)) > 0) {
            tot += r;
            if (tot > cap) return null;
            bos.write(buf, 0, r);
        }
        return bos.toByteArray();
    }

    // اسم المشروع الافتراضي لملف md/zip: بلا .zip ولا .md ولا اللاحقة -md التي يضيفها التصدير.
    private String mdBaseName(Uri u) {
        String n = projectName(u);
        String low = n.toLowerCase(java.util.Locale.US);
        if (low.endsWith(".md")) n = n.substring(0, n.length() - 3);
        low = n.toLowerCase(java.util.Locale.US);
        if (low.endsWith("-md") && n.length() > 3) n = n.substring(0, n.length() - 3);
        return n.isEmpty() ? "project" : n;
    }

    // يستخرج اسم المشروع من سطر العنوان «# مشروع: الاسم» الذي يكتبه التصدير (أو null).
    private static String mdHeaderName(String text) {
        int lim = Math.min(text.length(), 400);
        java.util.regex.Matcher m = java.util.regex.Pattern
                .compile("^#\\s*(?:مشروع|Project)\\s*:\\s*(.+?)\\s*$", java.util.regex.Pattern.MULTILINE)
                .matcher(text.substring(0, lim));
        if (!m.find()) return null;
        String n = m.group(1).replaceAll("[\\\\/:*?\"<>|\\s]", "_");
        if (n.isEmpty() || n.equals(".") || n.equals("..")) return null;
        return n;
    }

    // يدعم فحص عدة ملفات دفعة وحدة (اختيار متعدد من "استيراد ذكي"): يفحص كل ملف على حدة
    // ويجمع كل العناصر المكتشفة في قائمة واحدة، مع وسم كل عنصر بملفه المصدر.
    private String smartScanTask(final java.util.List<Uri> uris) {
        final boolean multi = uris.size() > 1;
        final java.util.ArrayList<SmartItem> items = new java.util.ArrayList<>();
        final StringBuilder failNotes = new StringBuilder();
        int filesOk = 0, totalEntries = 0;
        for (Uri u : uris) {
            String fileName = projectName(u);
            progress(multi ? ("يفحص: " + fileName + " ...") : "يفحص محتوى الملف...");
            boolean[] isGzOut = new boolean[1];
            int[] totalOut = new int[1];
            java.util.ArrayList<SmartItem> fileItems = smartScanOne(u, isGzOut, totalOut);
            if (totalOut[0] < 0) {
                failNotes.append("- ").append(fileName).append(": تعذّرت قراءة الملف\n");
                continue;
            }
            filesOk++;
            totalEntries += totalOut[0];
            for (SmartItem it : fileItems) {
                it.src = u;
                it.srcZipName = fileName;
                it.gz = isGzOut[0];
                if (multi) it.label = "[" + fileName + "] " + it.label;
            }
            items.addAll(fileItems);
        }

        if (items.isEmpty()) {
            StringBuilder r = new StringBuilder();
            r.append("فحصت ").append(uris.size()).append(multi ? " ملفات" : " ملفًا")
                    .append(" (").append(totalEntries).append(" عنصرًا) ولم أجد ما أعرفه (مشروع، SDK، Gradle، أدوات، مفتاح، rootfs، مشروع md).\n");
            if (failNotes.length() > 0) r.append(failNotes);
            return r.toString();
        }

        final String[] labels = new String[items.size()];
        final boolean[] on = new boolean[items.size()];
        for (int i = 0; i < labels.length; i++) labels[i] = items.get(i).label;
        if (items.size() == 1) on[0] = true;
        final int filesOkF = filesOk;
        runOnUiThread(() -> new NavAlertBuilder()
                .setTitle(multi
                        ? ("وجدت " + items.size() + " عنصرًا عبر " + filesOkF + " ملفات، اختر ما تستورده")
                        : ("وجدت " + items.size() + " عنصرًا، اختر ما تستورده"))
                .setView(switchListView(labels, on))
                .setPositiveButton("استيراد", (d, w) -> {
                    final java.util.ArrayList<SmartItem> pick = new java.util.ArrayList<>();
                    for (int i = 0; i < on.length; i++) if (on[i]) pick.add(items.get(i));
                    if (pick.isEmpty()) return;
                    final java.util.ArrayList<SmartItem> mdPicks = new java.util.ArrayList<>();
                    final java.util.ArrayList<SmartItem> otherPicks = new java.util.ArrayList<>();
                    for (SmartItem it : pick) (it.kind.equals("md") ? mdPicks : otherPicks).add(it);
                    // مشاريع md: كل واحد يمر بتحليله ونافذة تأكيده (مع طلب كلمة السر عند الحاجة)
                    java.util.HashSet<Uri> seenMd = new java.util.HashSet<>();
                    for (SmartItem it : mdPicks) {
                        if (seenMd.add(it.src)) mdImportBegin(mdBaseName(it.src), it.src, true);
                    }
                    if (!otherPicks.isEmpty()) startTask(() -> smartApply(otherPicks));
                })
                .setNegativeButton("إلغاء", null)
                .show());
        StringBuilder r = new StringBuilder();
        r.append("وجدت ").append(items.size()).append(" عنصرًا");
        if (multi) r.append(" عبر ").append(filesOk).append(" من ").append(uris.size()).append(" ملفات");
        r.append(". اختر ما تريد استيراده.\n");
        if (failNotes.length() > 0) r.append("تعذّرت قراءة بعض الملفات:\n").append(failNotes);
        return r.toString();
    }

    private String smartApply(java.util.List<SmartItem> picks) {
        File files = getFilesDir();
        for (SmartItem it : picks) {
            if (!it.kind.equals("project") && new File(files, "backup/" + it.kind).exists()) {
                return "توجد نسخة احتياطية سابقة (" + compLabel(it.kind) + "). احذفها أو استرجعها من الزر 11 أولًا. لم يتغير شيء.";
            }
        }
        // ملفات المصدر المتفرّدة المشاركة في هذا الاستيراد (قد تكون أكثر من ملف واحد).
        final java.util.LinkedHashSet<Uri> srcUris = new java.util.LinkedHashSet<>();
        for (SmartItem it : picks) srcUris.add(it.src);
        {
            long total = 0;
            for (Uri su : srcUris) total += Math.max(0L, uriSize(su));
            long need = Math.max(300L << 20, total * 12 / 10);
            long freeNow = files.getUsableSpace();
            if (freeNow < need) {
                return "المساحة الحرة " + fmtSize(freeNow) + " أقل من الحد الأدنى المقدَّر " + fmtSize(need)
                        + " لفك " + (srcUris.size() > 1 ? "هذه الملفات" : "هذا الملف") + ". لم يتغير شيء. أفرغ مساحة ثم أعد المحاولة.";
            }
        }
        File staging = new File(files, "staging");
        deleteRec(staging);
        staging.mkdirs();
        int nProj = 0;
        for (SmartItem it : picks) if (it.kind.equals("project")) nProj++;
        java.util.HashSet<String> used = new java.util.HashSet<>();
        for (SmartItem it : picks) {
            if (it.kind.equals("project")) {
                String nm;
                if (nProj == 1 || it.root.isEmpty()) nm = it.srcZipName;
                else {
                    String t = it.root.substring(0, it.root.length() - 1);
                    nm = t.substring(t.lastIndexOf('/') + 1);
                }
                nm = nm.replaceAll("[\\\\/:*?\"<>|\\s]", "_");
                if (nm.isEmpty() || nm.equals(".") || nm.equals("..")) nm = "project";
                String b = nm;
                int c = 2;
                while (!used.add(nm)) nm = b + "_" + (c++);
                it.name = nm;
                it.stage = new File(staging, "proj/" + nm);
            } else {
                it.stage = new File(staging, it.kind);
            }
            it.stage.mkdirs();
        }

        int n = 0;
        // يمر على كل ملف مصدر على حدة، ويفك منه فقط العناصر المختارة القادمة منه.
        for (Uri u : srcUris) {
            final java.util.ArrayList<SmartItem> subset = new java.util.ArrayList<>();
            for (SmartItem it : picks) if (it.src.equals(u)) subset.add(it);
            if (subset.isEmpty()) continue;
            try (InputStream raw = getContentResolver().openInputStream(u);
                 BufferedInputStream in = new BufferedInputStream(raw, 1 << 16)) {
                if (subset.get(0).gz) {
                    progress("يفك rootfs...");
                    readTarGzCore(new GZIPInputStream(in, 1 << 16), subset.get(0).stage);
                } else {
                    ZipInputStream zin = new ZipInputStream(in);
                    byte[] buf = new byte[65536];
                    ZipEntry e;
                    while ((e = zin.getNextEntry()) != null) {
                        String nm = e.getName().replace('\\', '/');
                        SmartItem best = null;
                        int bs = -1;
                        for (SmartItem it : subset) {
                            int sc;
                            if (it.entry != null) sc = nm.equals(it.entry) ? 1000000 + nm.length() : -1;
                            else sc = nm.startsWith(it.root) ? it.root.length() * 2 + (it.kind.equals("project") ? 0 : 1) : -1;
                            if (sc > bs) { bs = sc; best = it; }
                        }
                        if (best == null || e.isDirectory() && best.entry != null) continue;
                        if (best.kind.equals("rootfs")) {
                            progress("يفك rootfs (قد يطول)...");
                            InputStream ent = new java.io.FilterInputStream(zin) {
                                @Override public void close() {}
                            };
                            readTarGzCore(new GZIPInputStream(ent, 1 << 16), best.stage);
                            continue;
                        }
                        File f;
                        if (best.kind.equals("key")) {
                            f = new File(best.stage, "debug.keystore");
                        } else {
                            String rel = nm.substring(best.root.length());
                            if (rel.isEmpty()) continue;
                            f = new File(best.stage, rel);
                            if (!f.getCanonicalPath().startsWith(best.stage.getCanonicalPath() + File.separator)) continue;
                            if (e.isDirectory()) {
                                f.mkdirs();
                                continue;
                            }
                        }
                        f.getParentFile().mkdirs();
                        try (FileOutputStream fo = new FileOutputStream(f)) {
                            int k;
                            while ((k = zin.read(buf)) > 0) fo.write(buf, 0, k);
                        }
                        if (!best.kind.equals("project") && !best.kind.equals("key")) f.setExecutable(true, false);
                        if (++n % 500 == 0) progress("يفك... " + n + " ملفًا");
                    }
                }
            } catch (Exception ex) {
                deleteRec(staging);
                return "فشل الفك: " + ex + "\nلم يتغير شيء. قد تكون المساحة غير كافية.";
            }
        }

        for (SmartItem it : picks) {
            boolean ok;
            switch (it.kind) {
                case "project":
                    ok = new File(it.stage, "settings.gradle").exists() || new File(it.stage, "settings.gradle.kts").exists();
                    break;
                case "sdk":
                    ok = new File(it.stage, "build-tools").isDirectory() || new File(it.stage, "platforms").isDirectory();
                    break;
                case "gradle":
                    ok = new File(it.stage, "caches/modules-2").isDirectory() || new File(it.stage, "wrapper/dists").isDirectory();
                    break;
                case "tools":
                    ok = new File(it.stage, "bin/aapt2").exists();
                    break;
                case "key":
                    ok = new File(it.stage, "debug.keystore").exists();
                    break;
                default:
                    ok = findRoot(it.stage, 2) != null;
            }
            if (!ok) {
                deleteRec(staging);
                return it.label + "\nلم يجتز الفحص بعد الفك. لم يتغير شيء.";
            }
        }

        StringBuilder r = new StringBuilder("تم الاستيراد ✔ | ملفات: " + n + "\n");
        boolean anyBackup = false;
        for (SmartItem it : picks) {
            if (it.kind.equals("project")) {
                File d = new File(projectsDir(), it.name);
                deleteRec(d);
                boolean movedOk = it.stage.renameTo(d);
                r.append("- مشروع ").append(it.name).append(movedOk ? " ✔\n" : " ✘ تعذّر النقل\n");
                // اختر آخر مشروع تم استيراده تلقائيًا كمشروع حالي في المحرر (إن استُورد أكثر من مشروع دفعة واحدة، يبقى الأخير في القائمة هو المختار).
                if (movedOk) {
                    uiPrefs().edit().putString("proj", it.name).apply();
                    final String justImported = it.name;
                    runOnUiThread(() -> new NavAlertBuilder()
                            .setTitle("بدء البناء")
                            .setMessage("بناء المشروع: " + justImported + "؟")
                            .setPositiveButton("بناء", (d2, w) -> buildWithSpaceCheck(justImported))
                            .setNegativeButton("لاحقًا", null)
                            .show());
                }
            } else {
                String err = swapIn(it);
                if (err == null) {
                    r.append("- ").append(compLabel(it.kind)).append(" ✔ (القديم في النسخة الاحتياطية)\n");
                    anyBackup = true;
                } else {
                    r.append("- ").append(compLabel(it.kind)).append(" ✘ ").append(err).append("\n");
                }
            }
        }
        deleteRec(staging);
        if (anyBackup) {
            r.append("افتح الزر 11 لحذف النسخة الاحتياطية بعد التأكد، أو لاسترجاع القديم.");
            runOnUiThread(() -> new NavAlertBuilder()
                    .setTitle("تم الاستبدال")
                    .setMessage("القديم محفوظ. جرّب بناء مشروع، فإن نجح احذف النسخة الاحتياطية، وإن فشل استرجعها.")
                    .setPositiveButton("النسخ الاحتياطية", (d, w) -> showBackups())
                    .setNegativeButton("لاحقًا", null)
                    .show());
        }
        return r.toString();
    }

    private String swapIn(SmartItem it) {
        File files = getFilesDir();
        File bkRoot = new File(files, "backup");
        bkRoot.mkdirs();
        File bk = new File(bkRoot, it.kind);
        if (it.kind.equals("key")) {
            try {
                File target = new File(files, "android-home/debug.keystore");
                bk.mkdirs();
                if (target.exists()) {
                    Compat.copy(target, new File(bk, "debug.keystore"));
                }
                target.getParentFile().mkdirs();
                Compat.copy(new File(it.stage, "debug.keystore"), target);
                return null;
            } catch (Exception ex) {
                return "فشل: " + ex;
            }
        }
        File target = new File(files, dirOf(it.kind));
        boolean had = target.exists();
        if (had && !target.renameTo(bk)) return "تعذّر نقل القديم إلى النسخة الاحتياطية";
        if (!it.stage.renameTo(target)) {
            if (had) bk.renameTo(target);
            return "تعذّر وضع الجديد، أُعيد القديم";
        }
        return null;
    }

    private void showBackups() {
        final File[] ds0 = new File(getFilesDir(), "backup").listFiles(File::isDirectory);
        if (ds0 == null || ds0.length == 0) {
            termMsg("لا توجد نسخ احتياطية.");
            return;
        }
        java.util.Arrays.sort(ds0, (x, y) -> x.getName().compareTo(y.getName()));
        final File[] ds = ds0;

        final android.app.Dialog dlg = newScreen("showBackups", () -> showBackups());
        LinearLayout root = beginFullscreenCardDialog(dlg, "النسخ الاحتياطية (" + ds.length + ")");
        LinearLayout box = (LinearLayout) root.getTag();

        final java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", java.util.Locale.US);
        final java.util.Set<String> selected = new java.util.LinkedHashSet<>();
        final java.util.Map<String, Long> sizes = new java.util.concurrent.ConcurrentHashMap<>();
        final boolean[] selectMode = {false};
        final boolean[] alive = {true};
        dlg.setOnDismissListener(x -> alive[0] = false);

        final Runnable[] refresh = new Runnable[1];
        refresh[0] = () -> {
            box.removeAllViews();
            boolean allSel = selected.size() == ds.length;
            long selBytes = 0;
            for (String n : selected) { Long z = sizes.get(n); if (z != null) selBytes += z; }

            addMenuCard(box, selectMode[0] ? "\u2716" : "\u2611", selectMode[0] ? "إنهاء التحديد المتعدد" : "تحديد متعدد",
                    selectMode[0] ? "اضغط على النسخ لتحديدها" : "اختر عدة نسخ واحذفها دفعة واحدة", "#3F51B5", () -> {
                        selectMode[0] = !selectMode[0];
                        if (!selectMode[0]) selected.clear();
                        refresh[0].run();
                    });

            if (selectMode[0]) {
                addSelectCard(box, allSel, allSel ? "إلغاء تحديد الكل" : "تحديد الكل",
                        selected.size() + " / " + ds.length + " نسخة", "#3F51B5", () -> {
                            if (allSel) selected.clear();
                            else for (File f : ds) selected.add(f.getName());
                            refresh[0].run();
                        });
                if (!selected.isEmpty()) {
                    addMenuCard(box, "\uD83E\uDDF9", "حذف المحدد (" + selected.size() + ")",
                            "سيتحرر " + fmtSize(selBytes), "#F44336", () -> {
                                final java.util.List<String> names = new java.util.ArrayList<>(selected);
                                StringBuilder l = new StringBuilder();
                                for (String n : names) l.append("• ").append(compLabel(n)).append("\n");
                                new NavAlertBuilder()
                                        .setTitle("حذف " + names.size() + " نسخة احتياطية؟")
                                        .setMessage(l + "\nلن تستطيع الاسترجاع بعد ذلك.")
                                        .setPositiveButton("حذف", (d2, w2) -> {
                                            dlg.dismiss();
                                            startTask(() -> deleteSeveralBackups(names));
                                        })
                                        .setNegativeButton("إلغاء", null)
                                        .show();
                            });
                }
            }

            addMenuCard(box, "\uD83D\uDDD1", "حذف كل النسخ الاحتياطية", ds.length + " نسخة", "#F44336", () -> {
                final java.util.List<String> names = new java.util.ArrayList<>();
                for (File f : ds) names.add(f.getName());
                new NavAlertBuilder()
                        .setTitle("حذف كل النسخ الاحتياطية؟")
                        .setMessage("سيُحذف " + names.size() + " نسخة، ولن تستطيع الاسترجاع بعد ذلك.")
                        .setPositiveButton("حذف الكل", (d2, w2) -> {
                            dlg.dismiss();
                            startTask(() -> deleteSeveralBackups(names));
                        })
                        .setNegativeButton("إلغاء", null)
                        .show();
            });

            addMenuSectionHeader(box, "النسخ");
            for (File d : ds) {
                final String comp = d.getName();
                Long z = sizes.get(comp);
                String sub = sdf.format(new java.util.Date(d.lastModified())) + "  •  " + (z == null ? "يُحسب..." : fmtSize(z));
                if (selectMode[0]) {
                    addSelectCard(box, selected.contains(comp), compLabel(comp), sub, "#F44336", () -> {
                        if (!selected.remove(comp)) selected.add(comp);
                        refresh[0].run();
                    });
                } else {
                    addMenuCard(box, "\uD83D\uDD52", compLabel(comp), sub, "#3F51B5", () -> backupActions(comp, dlg));
                }
            }
        };
        refresh[0].run();

        dlg.setContentView(root);
        dlg.show();

        // حساب الأحجام في الخلفية لأن نسخ rootfs/SDK قد تكون كبيرة
        new Thread(() -> {
            for (File f : ds) sizes.put(f.getName(), dirSize(f));
            runOnUiThread(() -> { if (alive[0]) refresh[0].run(); });
        }).start();
    }

    private String deleteSeveralBackups(java.util.List<String> names) {
        StringBuilder sb = new StringBuilder();
        int ok = 0;
        for (String n : names) {
            try {
                deleteRec(new File(getFilesDir(), "backup/" + n));
                ok++;
                sb.append("• ").append(compLabel(n)).append("\n");
            } catch (Throwable e) {
                sb.append("✖ ").append(compLabel(n)).append(": ").append(e).append("\n");
            }
        }
        return "تم حذف " + ok + " من " + names.size() + " نسخة احتياطية:\n" + sb;
    }

    private void backupActions(final String comp, final android.app.Dialog parentDlg) {
        final android.app.Dialog dlg = newScreen("backupActions" + ":" + String.valueOf(comp), () -> backupActions(comp, parentDlg));
        LinearLayout root = beginFullscreenCardDialog(dlg, compLabel(comp));
        LinearLayout box = (LinearLayout) root.getTag();

        addMenuCard(box, "\u267B", "استرجاع القديم (يُتخلى عن الجديد)", "#4CAF50", () -> {
            new NavAlertBuilder()
                    .setTitle("استرجاع القديم؟")
                    .setMessage("سيُحذف الحالي ويعود القديم.")
                    .setPositiveButton("نعم", (d2, w2) -> {
                        dlg.dismiss();
                        if (parentDlg != null) parentDlg.dismiss();
                        startTask(() -> restoreBackup(comp));
                    })
                    .setNegativeButton("إلغاء", null)
                    .show();
        });
        addMenuCard(box, "\uD83D\uDDD1", "حذف النسخة الاحتياطية", "#F44336", () -> {
            new NavAlertBuilder()
                    .setTitle("حذف النسخة الاحتياطية؟")
                    .setMessage("لن تستطيع الاسترجاع بعد ذلك.")
                    .setPositiveButton("نعم", (d2, w2) -> {
                        dlg.dismiss();
                        if (parentDlg != null) parentDlg.dismiss();
                        startTask(() -> deleteBackup(comp));
                    })
                    .setNegativeButton("إلغاء", null)
                    .show();
        });

        dlg.setContentView(root);
        dlg.show();
    }

    private String deleteBackup(String comp) {
        deleteRec(new File(getFilesDir(), "backup/" + comp));
        return "حُذفت النسخة الاحتياطية: " + compLabel(comp);
    }

    private String restoreBackup(String comp) {
        File files = getFilesDir();
        File bk = new File(files, "backup/" + comp);
        if (!bk.exists()) return "لا توجد نسخة احتياطية.";
        if (comp.equals("key")) {
            try {
                File target = new File(files, "android-home/debug.keystore");
                File old = new File(bk, "debug.keystore");
                if (old.exists()) Compat.copy(old, target);
                else target.delete();
                deleteRec(bk);
                return "تم استرجاع مفتاح التوقيع القديم ✔";
            } catch (Exception ex) {
                return "فشل الاسترجاع: " + ex;
            }
        }
        File target = new File(files, dirOf(comp));
        File trash = new File(files, "trash-" + comp);
        deleteRec(trash);
        boolean had = target.exists();
        if (had && !target.renameTo(trash)) return "تعذّر الاسترجاع، لم يتغير شيء.";
        if (!bk.renameTo(target)) {
            if (had) trash.renameTo(target);
            return "فشل الاسترجاع، لم يتغير شيء.";
        }
        deleteRec(trash);
        return "تم استرجاع " + compLabel(comp) + " القديم ✔";
    }

    private static String fmtMb(long b) {
        return String.format(java.util.Locale.US, "%.2f ميغابايت", b / 1048576.0);
    }

    private static String fmtSize(long b) {
        if (b < 0) return "؟";
        if (b >= 1073741824L) return String.format(java.util.Locale.US, "%.2f GB", b / 1073741824.0);
        if (b >= 1048576L) return String.format(java.util.Locale.US, "%.1f MB", b / 1048576.0);
        if (b >= 1024L) return String.format(java.util.Locale.US, "%.1f KB", b / 1024.0);
        return b + " B";
    }

    private long uriSize(Uri u) {
        try (android.content.res.AssetFileDescriptor a = getContentResolver().openAssetFileDescriptor(u, "r")) {
            return a == null ? -1 : a.getLength();
        } catch (Exception e) {
            return -1;
        }
    }

    // حساب حجم سريع وقابل للإلغاء (walkFileTree يقرأ الخصائص مع القائمة بدل stat لكل ملف، ولا يتبع الروابط)
    private long dirSizeCancelable(File d, final java.util.concurrent.atomic.AtomicBoolean cancel) {
        return Compat.dirSize(d, cancel);
    }

    private long dirSize(File d) {
        long s = 0;
        File[] ks = d.listFiles();
        if (ks == null) return 0;
        for (File k : ks) {
            if (Compat.isSymbolicLink(k)) continue;
            if (k.isDirectory()) s += dirSize(k);
            else s += k.length();
        }
        return s;
    }

    private static String listDirs(File d, String prefix) {
        File[] ks = d.listFiles(File::isDirectory);
        if (ks == null) return "";
        java.util.ArrayList<String> l = new java.util.ArrayList<>();
        for (File k : ks) if (prefix == null || k.getName().startsWith(prefix)) l.add(k.getName());
        java.util.Collections.sort(l);
        return android.text.TextUtils.join("، ", l);
    }

    private static String orNone(String s) {
        return s.isEmpty() ? "لا شيء" : s;
    }

    private static String firstLines(String s, int n) {
        if (s == null) return "";
        String[] ls = s.trim().split("\n");
        StringBuilder b = new StringBuilder();
        for (int i = 0; i < ls.length && i < n; i++) b.append("  ").append(ls[i].trim()).append("\n");
        return b.toString();
    }

    private static String readSmall(File f) {
        try {
            if (!f.isFile() || f.length() > 300000) return null;
            return new String(Compat.readAllBytes(f), StandardCharsets.UTF_8);
        } catch (Exception e) {
            return null;
        }
    }

    private static java.util.ArrayList<String> findAll(String text, String re) {
        java.util.ArrayList<String> l = new java.util.ArrayList<>();
        java.util.regex.Matcher m = java.util.regex.Pattern.compile(re).matcher(text);
        while (m.find()) if (!l.contains(m.group(1))) l.add(m.group(1));
        return l;
    }

    private static String cleanVer(String v) {
        return v == null ? null : v.replaceAll("[^0-9.].*$", "");
    }

    private static int numPart(String s) {
        try { return Integer.parseInt(s.replaceAll("\\D", "")); } catch (Exception e) { return 0; }
    }

    private static int verCmp(String a, String b) {
        String[] x = a.split("\\."), y = b.split("\\.");
        for (int i = 0; i < Math.max(x.length, y.length); i++) {
            int p = i < x.length ? numPart(x[i]) : 0;
            int q = i < y.length ? numPart(y[i]) : 0;
            if (p != q) return p < q ? -1 : 1;
        }
        return 0;
    }

    private static String maxVer(java.util.List<String> l) {
        String best = null;
        for (String v : l) {
            String c = cleanVer(v);
            if (c == null || c.isEmpty()) continue;
            if (best == null || verCmp(c, best) > 0) best = c;
        }
        return best;
    }

    private static String minGradleFor(String agp) {
        return agp == null ? null : GradleAdvisor.minGradleFor(agp); // جدول واحد في GradleAdvisor
    }

    private static String androidName(int api) {
        switch (api) {
            case 26: return "8.0";
            case 27: return "8.1";
            case 28: return "9";
            case 29: return "10";
            case 30: return "11";
            case 31: return "12";
            case 32: return "12L";
            case 33: return "13";
            case 34: return "14";
            case 35: return "15";
            case 36: return "16";
            case 37: return "17";
            default: return "؟";
        }
    }

    private static int jdkMajor(File rf) {
        int best = 0;
        if (rf == null) return 0;
        File[] ks = new File(rf, "usr/lib/jvm").listFiles();
        if (ks != null) {
            for (File k : ks) {
                java.util.regex.Matcher m = java.util.regex.Pattern.compile("^java-(\\d+)-").matcher(k.getName());
                if (m.find()) best = Math.max(best, Integer.parseInt(m.group(1)));
            }
        }
        return best;
    }

    private static int maxPlatform(File sdk) {
        int best = 0;
        File[] pl = new File(sdk, "platforms").listFiles(File::isDirectory);
        if (pl != null) {
            for (File p : pl) {
                java.util.regex.Matcher m = java.util.regex.Pattern.compile("^android-(\\d+)").matcher(p.getName());
                if (m.find()) best = Math.max(best, Integer.parseInt(m.group(1)));
            }
        }
        return best;
    }

    private static boolean hasPlatform(File sdk, String n) {
        File[] pl = new File(sdk, "platforms").listFiles(File::isDirectory);
        if (pl == null) return false;
        for (File p : pl) {
            String s = p.getName();
            if (s.equals("android-" + n) || s.startsWith("android-" + n + "-") || s.startsWith("android-" + n + ".")) return true;
        }
        return false;
    }

    private static java.util.ArrayList<String> gradleInstalled(File gh) {
        java.util.ArrayList<String> l = new java.util.ArrayList<>();
        File[] ds = new File(gh, "wrapper/dists").listFiles(File::isDirectory);
        if (ds != null) {
            for (File d : ds) {
                java.util.regex.Matcher m = java.util.regex.Pattern.compile("^gradle-([0-9][0-9.]*)-").matcher(d.getName());
                if (m.find()) l.add(m.group(1));
            }
        }
        return l;
    }

    private static java.util.ArrayList<String> agpCached(File gh) {
        java.util.ArrayList<String> l = new java.util.ArrayList<>();
        l.addAll(GradleAdvisor.cachedAgps(gh));
        return l;
    }

    private static String spaceFlag(long free) {
        long gb = 1073741824L;
        if (free < gb) return "  ✘ قليلة جدًا";
        if (free < 3 * gb) return "  ⚠ قد لا تكفي لاستيراد SDK أو rootfs";
        return "  ✔";
    }

    private void buildWithSpaceCheck(final String name) {
        final long free = getFilesDir().getUsableSpace();
        if (free >= 1073741824L) {
            startTask(() -> buildExisting(name));
            return;
        }
        new NavAlertBuilder()
                .setTitle("المساحة قليلة")
                .setMessage("المتاح " + fmtSize(free) + " فقط. البناء يحتاج عادة أكثر من 1 GB (تقدير مني)، وقد يفشل.\nمتابعة؟")
                .setPositiveButton("متابعة", (d, w) -> startTask(() -> buildExisting(name)))
                .setNegativeButton("إلغاء", null)
                .show();
    }

