            tabs.addView(autoBtn, new LinearLayout.LayoutParams(0, -2, 1f));
            Button manBtn = new Button(this);
            manBtn.setText("\uD83D\uDD0D بحث يدوي");
            manBtn.setAllCaps(false);
            manBtn.setBackgroundColor(android.graphics.Color.parseColor(!autoMode[0] ? "#4CAF50" : "#E0E0E0"));
            manBtn.setTextColor(!autoMode[0] ? android.graphics.Color.WHITE : android.graphics.Color.parseColor("#424242"));
            manBtn.setOnClickListener(v -> { autoMode[0] = false; rebuild[0].run(); });
            tabs.addView(manBtn, new LinearLayout.LayoutParams(0, -2, 1f));
