    private void collectFiles(File dir, java.util.List<File> out) {
        File[] kids = dir.listFiles();
        if (kids == null) return;
        for (File k : kids) {
            if (k.isDirectory()) collectFiles(k, out);
            else out.add(k);
        }
    }

    // استيراد دفعي: يفك أرشيف ZIP في مجلد مؤقت، ثم يطابق كل ملف بداخله
    // مع نظيره في المشروع تلقائيًا بنفس آلية "استيراد من التنزيلات" (اسم الملف فقط).
    // الملفات بدون تطابق واحد واضح (صفر أو أكثر من تطابق) تُترك دون تغيير.
    private String handleZipImportUri(Uri u, File root, File currentDir) {
        if (root == null) return "لم يُحدَّد المشروع الهدف — أعد المحاولة من داخل مدير الملفات.";
        progress("يفك الأرشيف...");
        File tmp = new File(getCacheDir(), "zipimport_" + System.currentTimeMillis());
        tmp.mkdirs();
        int extracted;
        try {
            extracted = unzipTo(u, tmp);
        } catch (Exception e) {
            deleteRec(tmp);
            return "فشل فك الأرشيف: " + e;
        }
        if (extracted == 0) {
            deleteRec(tmp);
            return "الأرشيف فارغ أو لا يحتوي أي ملفات قابلة للفك.";
        }
        progress("يطابق " + extracted + " ملفًا مع المشروع...");
        java.util.List<File> files = new java.util.ArrayList<>();
        collectFiles(tmp, files);
        int replaced = 0, noMatch = 0, multi = 0, failed = 0;
        StringBuilder detail = new StringBuilder();
        for (File src : files) {
            java.util.List<File> matches = new java.util.ArrayList<>();
            findInProject(root, src.getName(), matches, 0);
            if (matches.size() == 1) {
                File target = matches.get(0);
                try {
                    if (target.exists()) {
                        File bak = new File(target.getParentFile(), target.getName() + ".bak");
                        Compat.copy(target, bak);
                    }
                    target.getParentFile().mkdirs();
                    Compat.copy(src, target);
                    replaced++;
                    if (detail.length() < 2500) {
                        detail.append("\u2705 ").append(src.getName()).append(" \u2192 ").append(fmRelPath(root, target.getParentFile())).append("\n");
                    }
                } catch (Exception e) {
                    failed++;
                }
            } else if (matches.isEmpty()) {
                noMatch++;
            } else {
                multi++;
            }
        }
        deleteRec(tmp);
        StringBuilder r = new StringBuilder();
        r.append("استيراد ZIP دفعي — النتيجة:\n\n");
        r.append("\u2705 استُبدل تلقائيًا: ").append(replaced).append("\n");
        r.append("\u2753 بدون تطابق بالمشروع (تُرك كما هو): ").append(noMatch).append("\n");
        r.append("\u26A0 تطابقات متعددة (يحتاج اختيارًا يدويًا عبر \u201Cاستيراد من التنزيلات\u201D لكل ملف): ").append(multi).append("\n");
        if (failed > 0) r.append("\u274C فشل نسخها: ").append(failed).append("\n");
        if (replaced > 0) r.append("\n(احتُفظ بنسخة .bak لكل ملف استُبدل — يمكن استعادتها من مدير الملفات)\n\nتفصيل الملفات المستبدلة:\n").append(detail);
        return r.toString();
    }

    // نفس فكرة "استيراد دفعي من ZIP" (المطابقة بالاسم واستبدال الملف في مكانه الصحيح)،
    // لكن مع فرق واحد: أي ملف بدون أي تطابق بالاسم لا يُترك، بل يُضاف في المسار
    // الموجود له داخل الـ zip نفسه (نسبةً لجذر المشروع) — لتغطية حالة "إضافة" أو
    // "جزء ناقص كليًا" لم يكن موجودًا بالمشروع أصلًا. زر "استيراد دفعي من ZIP" الأصلي
    // ودالته handleZipImportUri لم يُمسّا؛ هذه دالة مستقلة تمامًا بزر خاص بها.
    private String handleZipImportUriWithAdd(Uri u, File root, File currentDir) {
        if (root == null) return "لم يُحدَّد المشروع الهدف — أعد المحاولة من داخل مدير الملفات.";
        progress("يفك الأرشيف...");
        File tmp = new File(getCacheDir(), "zipimportadd_" + System.currentTimeMillis());
        tmp.mkdirs();
        int extracted;
        try {
            extracted = unzipTo(u, tmp);
        } catch (Exception e) {
            deleteRec(tmp);
            return "فشل فك الأرشيف: " + e;
        }
        if (extracted == 0) {
            deleteRec(tmp);
            return "الأرشيف فارغ أو لا يحتوي أي ملفات قابلة للفك.";
        }
        progress("يطابق " + extracted + " ملفًا مع المشروع...");
        java.util.List<File> files = new java.util.ArrayList<>();
        collectFiles(tmp, files);
        String rootPath;
        try {
            rootPath = root.getCanonicalPath() + File.separator;
        } catch (Exception e) {
            deleteRec(tmp);
            return "فشل تحديد مسار المشروع: " + e;
        }
        int replaced = 0, added = 0, multi = 0, failed = 0;
        StringBuilder detail = new StringBuilder();
        for (File src : files) {
            String rel = fmRelPath(tmp, src); // مسار الملف داخل الـ zip نسبةً لجذره
            java.util.List<File> matches = new java.util.ArrayList<>();
            findInProject(root, src.getName(), matches, 0);
            try {
                if (matches.size() == 1) {
                    File target = matches.get(0);
                    if (target.exists()) {
                        File bak = new File(target.getParentFile(), target.getName() + ".bak");
                        Compat.copy(target, bak);
                    }
                    target.getParentFile().mkdirs();
                    Compat.copy(src, target);
                    replaced++;
                    if (detail.length() < 2500) {
                        detail.append("\u2705 عُدِّل: ").append(src.getName()).append(" \u2192 ").append(fmRelPath(root, target.getParentFile())).append("\n");
                    }
                } else if (matches.isEmpty()) {
                    // لا يوجد تطابق بالاسم إطلاقًا — يُضاف كملف جديد في مساره من الـ zip.
                    File target = new File(root, rel);
                    if (!target.getCanonicalPath().startsWith(rootPath)) { failed++; continue; }
                    target.getParentFile().mkdirs();
                    Compat.copy(src, target);
                    added++;
                    if (detail.length() < 2500) {
                        detail.append("\u2795 أُضيف: ").append(rel).append("\n");
                    }
                } else {
                    multi++;
                }
            } catch (Exception e) {
                failed++;
            }
        }
        deleteRec(tmp);
        StringBuilder r = new StringBuilder();
        r.append("استيراد ودمج من ZIP — النتيجة:\n\n");
        r.append("\u2705 عُدِّل (تطابق بالاسم): ").append(replaced).append("\n");
        r.append("\u2795 أُضيف (لا يوجد تطابق، أُضيف في مساره من الأرشيف): ").append(added).append("\n");
        r.append("\u26A0 تطابقات متعددة بالاسم (يحتاج اختيارًا يدويًا عبر \u201Cاستيراد من التنزيلات\u201D لكل ملف): ").append(multi).append("\n");
        if (failed > 0) r.append("\u274C فشل: ").append(failed).append("\n");
        if (replaced > 0) r.append("\n(احتُفظ بنسخة .bak لكل ملف عُدِّل — يمكن استعادتها من مدير الملفات)\n");
        r.append("\nتفصيل:\n").append(detail);
        return r.toString();
    }

    private void termScreen(final String projectName, final String initial) {
        final android.widget.EditText et = new android.widget.EditText(this);
        et.setText(initial);
        et.setTypeface(Typeface.MONOSPACE);
        et.setTextSize(12);
        et.setTextDirection(View.TEXT_DIRECTION_LTR);
        et.setGravity(android.view.Gravity.TOP | android.view.Gravity.START);
        et.setMinLines(10);
        et.setSingleLine(false);
        et.setHint("sh / python3 (المجلد الحالي: /proj)");
        ScrollView sv3 = new ScrollView(this);
        sv3.addView(et);
        new NavAlertBuilder()
                .setTitle("طرفية: " + projectName)
                .setView(sv3)
                .setPositiveButton("تنفيذ", (d, w) -> {
                    final String cmdText = et.getText().toString();
                    startTask(() -> termRun(projectName, cmdText));
                })
                .setNeutralButton("لصق", (d, w) -> {
                    String clip = "";
                    try {
                        android.content.ClipboardManager cm = (android.content.ClipboardManager) getSystemService(CLIPBOARD_SERVICE);
                        if (cm != null && cm.hasPrimaryClip() && cm.getPrimaryClip().getItemCount() > 0) {
                            CharSequence cs = cm.getPrimaryClip().getItemAt(0).coerceToText(this);
                            if (cs != null) clip = cs.toString();
                        }
                    } catch (Exception ignored) {}
                    termScreen(projectName, clip);
                })
                .setNegativeButton("إغلاق", null)
                .show();
    }

    private String termRun(String projectName, String script) {
        File base = toolsBase();
        File rootfs = findRoot(new File(getFilesDir(), "rootfs"), 2);
        File sdk = new File(getFilesDir(), "sdk");
        if (!new File(base, "bin/proot").exists()) return "أولًا الخطوة 1 (الأدوات).";
        if (rootfs == null) return "أولًا الخطوة 2 (Debian).";
        if (script.trim().isEmpty()) return "لا يوجد أمر.";
        BuildService.noteTask(this, "cmd", projectName, script);
        File proj = new File(projectsDir(), projectName);
        File root = proj;
        if (!new File(root, "gradle/wrapper/gradle-wrapper.jar").exists()) {
            File[] ks = proj.listFiles();
            if (ks != null && ks.length == 1 && ks[0].isDirectory()) root = ks[0];
        }
        try {
            File rc = new File(rootfs, "etc/resolv.conf");
            Compat.deleteIfExists(rc);
            Compat.write(rc, "nameserver 8.8.8.8\nnameserver 1.1.1.1\n".getBytes(StandardCharsets.UTF_8));
            new File(rootfs, "tmp").mkdirs();
            Compat.write(new File(rootfs, "tmp/term.sh"), script.getBytes(StandardCharsets.UTF_8));
        } catch (Exception e) {
            return "فشل التجهيز: " + e;
        }
        List<String> c = new ArrayList<>();
        c.add(new File(base, "bin/proot").getAbsolutePath());
        c.add("--link2symlink");
        c.add("--kill-on-exit");
        c.add("-0");
        c.add("-r");
        c.add(rootfs.getAbsolutePath());
        for (String bnd : new String[]{"/dev", "/proc", "/sys", "/system"}) {
            c.add("-b");
            c.add(bnd);
        }
        if (new File("/apex").exists()) {
            c.add("-b");
            c.add("/apex");
        }
        c.add("-b"); c.add(base.getAbsolutePath() + ":/opt/l2s");
        c.add("-b"); c.add(sdk.getAbsolutePath() + ":/opt/sdk");
        c.add("-b"); c.add(root.getAbsolutePath() + ":/proj");
        c.add("-w");
        c.add("/proj");
        c.add("/usr/bin/env");
        c.add("-i");
        c.add("HOME=/root");
        c.add("P=/proj");
        c.add("PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin");
        c.add("LANG=C.UTF-8");
        c.add("TMPDIR=/tmp");
        c.add("/bin/sh");
        c.add("/tmp/term.sh");
        Res r = exec(base, 600, 3000, null, c);
        String t = r.text == null ? "" : r.text;
        return "$ [طرفية " + projectName + "]  رمز الخروج: " + r.code + "\n\n" + t;
    }

