    // ====== نظام ألوان الثيم المركزي (يُستخدم في كل البطاقات/الحوارات/الشاشة القديمة) ======
    private int themeDialogBg() { return isPro() ? 0xFF0A0D14 : isAmoled() ? 0xFF000000 : isDark() ? 0xFF121212 : 0xFFFAFAFA; }
    private int themeCardBg()   {
        if (isPro()) return proSecColor != 0 ? proBlend(0xFF11151D, proSecColor, 0.10f) : 0xFF11151D;
        return isAmoled() ? 0xFF0A0A0A : isDark() ? 0xFF1E1E1E : 0xFFFFFFFF;
    }
    private int themeCardStroke() {
        if (isPro()) return proSecColor != 0 ? proSecColor : 0xFF5C6BC0;
        return isDark() ? 0xFF2C2C2C : 0xFFE0E0E0;
    }
    // سمك إطار البطاقة: أسمك قليلًا في الوضع الداكن المتطور ليظهر الإطار الملوّن بوضوح
    private int themeStrokeW(float d) { return isPro() ? Math.max(2, (int) (1.6f * d)) : (int) (1 * d); }

    // ====== الوضع الداكن المتطور: كل قسم له لون، وكل خيار داخله بإطار بذلك اللون ======
    private int proSecColor = 0;      // لون القسم الحالي (0 = بلا قسم بعد)
    private int proSecCounter = 0;    // عدّاد للأقسام غير المعرّفة مسبقًا (تدوير الألوان)
    private final int[] PRO_PALETTE = {0xFF00BCD4, 0xFFFF9800, 0xFF4CAF50, 0xFFE91E63, 0xFFFFC107, 0xFF7C5CFF, 0xFF26A69A, 0xFFFF5252, 0xFFC0CA33, 0xFF42A5F5};

    private boolean isPro() { return isDark() && uiPrefs().getString("theme", "auto").equals("pro"); }

    private int proBlend(int base, int over, float a) {
        int r = (int) (android.graphics.Color.red(base) * (1 - a) + android.graphics.Color.red(over) * a);
        int g = (int) (android.graphics.Color.green(base) * (1 - a) + android.graphics.Color.green(over) * a);
        int b = (int) (android.graphics.Color.blue(base) * (1 - a) + android.graphics.Color.blue(over) * a);
        return 0xFF000000 | (r << 16) | (g << 8) | b;
    }

    private void proSectionReset() { proSecColor = 0; proSecCounter = 0; }

    // يحدّد لون القسم عند رسم عنوانه، ويعيد اللون (أو 0 خارج الوضع المتطور)
    private int proSectionBegin(String title) {
        if (!isPro()) return 0;
        switch (title == null ? "" : title) {
            case "الوصول السريع": proSecColor = 0xFFFFC107; break;
            case "الإعداد والطرفية": proSecColor = 0xFF00BCD4; break;
            case "المشروع": proSecColor = 0xFF4CAF50; break;
            case "الواجهة": proSecColor = 0xFFE91E63; break;
            case "الاتصال والصيانة": proSecColor = 0xFFFF9800; break;
            case "أخرى": proSecColor = 0xFFC0CA33; break;
            default: proSecColor = PRO_PALETTE[(proSecCounter++) % PRO_PALETTE.length];
        }
        return proSecColor;
    }
