    private String[] projectNames() {
        File[] ds = projectsDir().listFiles(File::isDirectory);
        if (ds == null) return new String[0];
        java.util.Arrays.sort(ds, (a, c) -> Long.compare(c.lastModified(), a.lastModified()));
        String[] r = new String[ds.length];
        for (int i = 0; i < ds.length; i++) r[i] = ds[i].getName();
        return r;
    }

    // "" = بلا مشروع، "auto" = آخر مشروع
    private String currentProject() {
        String sel = uiPrefs().getString("proj", "auto");
        String[] names = projectNames();
        if (sel.equals("none")) return "";
        if (sel.equals("auto")) return names.length > 0 ? names[0] : "";
        for (String n : names) if (n.equals(sel)) return n;
        return names.length > 0 ? names[0] : "";
    }

    private String projectBarLabel() {
        String sel = uiPrefs().getString("proj", "auto");
        String cur = currentProject();
        if (sel.equals("none")) return "بلا مشروع ▾";
        if (sel.equals("auto")) return "تلقائي: " + (cur.isEmpty() ? "-" : cur) + " ▾";
        return cur + " ▾";
    }

    private static final java.util.regex.Pattern SH_COMMENT = java.util.regex.Pattern.compile("#.*");
    private static final java.util.regex.Pattern SH_STRING = java.util.regex.Pattern.compile("\"(?:[^\"\\\\]|\\\\.)*\"|'(?:[^'\\\\]|\\\\.)*'");
    private static final java.util.regex.Pattern SH_VAR = java.util.regex.Pattern.compile("\\$\\{?[A-Za-z_][A-Za-z0-9_]*\\}?|\\$[0-9@#*?]");
    private static final java.util.regex.Pattern SH_NUMBER = java.util.regex.Pattern.compile("\\b\\d+(\\.\\d+)?\\b");
    private static final java.util.regex.Pattern SH_KEYWORD = java.util.regex.Pattern.compile(
            "\\b(if|then|else|elif|fi|for|do|done|while|until|case|esac|function|return|echo|cd|export|source|exit|break|continue"
                    + "|local|readonly|shift|trap|set|unset|printf|read"
                    + "|def|import|from|as|class|try|except|finally|with|lambda|pass|yield|global|nonlocal|assert|raise"
                    + "|and|or|not|in|is|None|True|False|print|self)\\b");

    private void applyShHighlight(android.text.Editable e) {
        for (android.text.style.ForegroundColorSpan sp : e.getSpans(0, e.length(), android.text.style.ForegroundColorSpan.class)) {
            e.removeSpan(sp);
        }
        String s = e.toString();
        applySpan(e, SH_KEYWORD.matcher(s), 0xFF569CD6);
        applySpan(e, SH_NUMBER.matcher(s), 0xFFB5CEA8);
        applySpan(e, SH_VAR.matcher(s), 0xFF4EC9B0);
        applySpan(e, SH_STRING.matcher(s), 0xFFCE9178);
        applySpan(e, SH_COMMENT.matcher(s), 0xFF6A9955);
    }

    private void applySpan(android.text.Editable e, java.util.regex.Matcher m, int color) {
        while (m.find()) {
            e.setSpan(new android.text.style.ForegroundColorSpan(color), m.start(), m.end(), android.text.Spannable.SPAN_EXCLUSIVE_EXCLUSIVE);
        }
    }

    // سويتش «الخلفية» في الشريط العلوي: يُشغّل/يُطفئ وضع Termux (خدمة أمامية + WakeLock).
    private android.widget.Switch makeBgSwitch(int fg) {
        android.widget.Switch sw = new android.widget.Switch(this);
        sw.setText("خلفية");
        sw.setTextSize(11);
        sw.setTextColor(fg);
        // المسار: أحمر عند الإيقاف (مقفل)، أخضر عند التشغيل. المقبض دائرة بيضاء.
        android.graphics.drawable.GradientDrawable trackOff = new android.graphics.drawable.GradientDrawable();
        trackOff.setColor(0xFFE53935);
        trackOff.setCornerRadius(dp(11));
        trackOff.setSize(dp(44), dp(22));
        android.graphics.drawable.GradientDrawable trackOn = new android.graphics.drawable.GradientDrawable();
        trackOn.setColor(0xFF43A047);
        trackOn.setCornerRadius(dp(11));
        trackOn.setSize(dp(44), dp(22));
        android.graphics.drawable.StateListDrawable track = new android.graphics.drawable.StateListDrawable();
        track.addState(new int[]{android.R.attr.state_checked}, trackOn);
        track.addState(new int[]{}, trackOff);
        sw.setTrackDrawable(track);

        android.graphics.drawable.GradientDrawable thumb = new android.graphics.drawable.GradientDrawable();
        thumb.setShape(android.graphics.drawable.GradientDrawable.OVAL);
        thumb.setColor(0xFFFFFFFF);
        thumb.setStroke(dp(1), 0x33000000);
        thumb.setSize(dp(20), dp(20));
        sw.setThumbDrawable(thumb);

        sw.setChecked(BuildService.isPersistent(this));
        final boolean[] syncing = {false};
        sw.setOnCheckedChangeListener((b, on) -> { if (!syncing[0]) setBgMode(on); });
        // يتحدّث السويتش تلقائيًا عند إيقاف الوضع من الخدمة (خمول أو زر الإشعار)
        final android.content.SharedPreferences.OnSharedPreferenceChangeListener bgListener = (prefs, key) -> {
            if (!"bgmode".equals(key)) return;
            final boolean v = BuildService.isPersistent(MainActivity.this);
            sw.post(() -> {
                if (sw.isChecked() != v) { syncing[0] = true; sw.setChecked(v); syncing[0] = false; }
            });
        };
        sw.setTag(bgListener);
        sw.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener() {
            @Override public void onViewAttachedToWindow(View v) {
                uiPrefs().registerOnSharedPreferenceChangeListener(bgListener);
                boolean cur = BuildService.isPersistent(MainActivity.this);
                if (sw.isChecked() != cur) { syncing[0] = true; sw.setChecked(cur); syncing[0] = false; }
            }
            @Override public void onViewDetachedFromWindow(View v) {
                uiPrefs().unregisterOnSharedPreferenceChangeListener(bgListener);
            }
        });
        sw.setOnLongClickListener(v -> { showBgSetupDialog(true); return true; });
        return sw;
    }


    // ===== سويتش موحّد لكل خيارات التشغيل/الإيقاف: أحمر = متوقف ، أخضر = مشغّل =====
    private void styleToggleSwitch(android.widget.Switch sw) {
        android.graphics.drawable.GradientDrawable trackOff = new android.graphics.drawable.GradientDrawable();
        trackOff.setColor(0xFFE53935);
        trackOff.setCornerRadius(dp(14));
        trackOff.setSize(dp(52), dp(28));
        android.graphics.drawable.GradientDrawable trackOn = new android.graphics.drawable.GradientDrawable();
        trackOn.setColor(0xFF43A047);
        trackOn.setCornerRadius(dp(14));
        trackOn.setSize(dp(52), dp(28));
        android.graphics.drawable.StateListDrawable track = new android.graphics.drawable.StateListDrawable();
        track.addState(new int[]{android.R.attr.state_checked}, trackOn);
        track.addState(new int[]{}, trackOff);
        sw.setTrackDrawable(track);
        android.graphics.drawable.GradientDrawable thumb = new android.graphics.drawable.GradientDrawable();
        thumb.setShape(android.graphics.drawable.GradientDrawable.OVAL);
        thumb.setColor(0xFFFFFFFF);
        thumb.setStroke(dp(1), 0x33000000);
        thumb.setSize(dp(24), dp(24));
        sw.setThumbDrawable(thumb);
        sw.setShowText(false);
    }

    private android.widget.Switch makeToggleSwitch(boolean on) {
        android.widget.Switch sw = new android.widget.Switch(this);
        styleToggleSwitch(sw);
        sw.setChecked(on);
        return sw;
    }

    // بطاقة إعداد بسويتش (بدل نص «مفعّل/متوقف»). onChange يرجع true لتثبيت الحالة الجديدة، أو false للتراجع عنها.
    private android.widget.Switch addToggleCard(LinearLayout container, String icon, String title, String subtitle, String colorHex,
                                               boolean on, java.util.function.Predicate<Boolean> onChange, Runnable longPress) {
        float d = getResources().getDisplayMetrics().density;
        LinearLayout card = new LinearLayout(this);
        card.setOrientation(LinearLayout.HORIZONTAL);
        card.setGravity(android.view.Gravity.CENTER_VERTICAL);
        card.setPadding((int) (14 * d), (int) (12 * d), (int) (14 * d), (int) (12 * d));

        android.graphics.drawable.GradientDrawable bg = new android.graphics.drawable.GradientDrawable();
        bg.setColor(themeCardBg());
        bg.setCornerRadius(12 * d);
        bg.setStroke(themeStrokeW(d), themeCardStroke());
        card.setBackground(bg);

        if (icon != null) {
            View iconView = makeIconBadge(icon, colorHex, 38, 18);
            LinearLayout.LayoutParams iconLp = new LinearLayout.LayoutParams((int) (38 * d), (int) (38 * d));
            iconLp.rightMargin = (int) (12 * d);
            card.addView(iconView, iconLp);
        }

        LinearLayout textCol = new LinearLayout(this);
        textCol.setOrientation(LinearLayout.VERTICAL);
        TextView titleView = new TextView(this);
        titleView.setText(title);
        titleView.setTextSize(15);
        titleView.setTypeface(null, Typeface.BOLD);
        titleView.setTextColor(themeTextPrimary());
        textCol.addView(titleView);
        if (subtitle != null && !subtitle.isEmpty()) {
            TextView subView = new TextView(this);
            subView.setText(subtitle);
            subView.setTextSize(12);
            subView.setTextColor(themeTextSecondary());
            textCol.addView(subView);
        }
        card.addView(textCol, new LinearLayout.LayoutParams(0, -2, 1f));

        final android.widget.Switch sw = makeToggleSwitch(on);
        LinearLayout.LayoutParams swLp = new LinearLayout.LayoutParams(-2, -2);
        swLp.leftMargin = (int) (10 * d);
        card.addView(sw, swLp);
        final boolean[] reverting = {false};
        sw.setOnCheckedChangeListener((b, isOn) -> {
            if (reverting[0]) return;
            boolean keep = onChange == null || onChange.test(isOn);
            if (!keep) { reverting[0] = true; b.setChecked(!isOn); reverting[0] = false; }
        });

        attachClickAndLongPress(card, sw::toggle, longPress);

        LinearLayout.LayoutParams cardLp = new LinearLayout.LayoutParams(-1, -2);
        cardLp.bottomMargin = (int) (8 * d);
        container.addView(card, cardLp);
        return sw;
    }

    // قائمة اختيار متعدد بسويتش (بدل صناديق الاختيار): كل صف سويتش أحمر/أخضر يكتب حالته في on[i].
    private View switchListView(final String[] labels, final boolean[] on) {
        ScrollView sv = new ScrollView(this);
        LinearLayout box = new LinearLayout(this);
        box.setOrientation(LinearLayout.VERTICAL);
        box.setBackgroundColor(termMenuBgColor());
        int p = dp(12);
        box.setPadding(p, p, p, p);
        for (int i = 0; i < labels.length; i++) {
            final int idx = i;
            addToggleCard(box, null, labels[i], null, "#607D8B", on[i], v -> { on[idx] = v; return true; }, null);
        }
        sv.addView(box);
        return sv;
    }

    private Runnable backupCenterRefresh;

    // خيارات تشغيل/إيقاف يمكن ظهورها كاختصارات في «الوصول السريع» — تُعرض كسويتش أيضًا.
    private boolean isToggleId(String id) {
        switch (id) {
            case "notify_done": case "quick_mode": case "d_term_keepon": case "auto_share_main":
            case "install_prompt": case "open_prompt": case "embed_project": case "copy_err_on_fail":
            case "d_gh_tokmode_toggle": case "d_gh_msgmode_toggle": case "d_botbtn_display_toggle":
                return true;
            default: return false;
        }
    }
    private boolean toggleGet(String id) {
        switch (id) {
            case "notify_done": return uiPrefs().getBoolean("notify_done", true);
            case "auto_share_main": return uiPrefs().getBoolean("auto_share_main", false);
            case "install_prompt": return uiPrefs().getBoolean("install_prompt", true);
            case "open_prompt": return uiPrefs().getBoolean("open_prompt", true);
            case "embed_project": return uiPrefs().getBoolean("embed_project", false);
            case "copy_err_on_fail": return uiPrefs().getBoolean("copy_err_on_fail", false);
            case "quick_mode": return uiPrefs().getString("outmode", "cum").equals("single");
            case "d_term_keepon": return uiPrefs().getBoolean("keepon", true);
            case "d_gh_tokmode_toggle": return uiPrefs().getString("gh_tokmode", "shared").equals("shared");
            case "d_gh_msgmode_toggle": return uiPrefs().getString("gh_msgmode", "manual").equals("auto");
            case "d_botbtn_display_toggle": return botTextMode();
            default: return false;
        }
    }
    private void toggleSet(String id, boolean on) {
        switch (id) {
            case "notify_done": uiPrefs().edit().putBoolean("notify_done", on).apply(); break;
            case "auto_share_main": uiPrefs().edit().putBoolean("auto_share_main", on).apply(); break;
            case "install_prompt": uiPrefs().edit().putBoolean("install_prompt", on).apply(); break;
            case "open_prompt": uiPrefs().edit().putBoolean("open_prompt", on).apply(); break;
            case "embed_project": uiPrefs().edit().putBoolean("embed_project", on).apply(); break;
            case "copy_err_on_fail": uiPrefs().edit().putBoolean("copy_err_on_fail", on).apply(); break;
            case "quick_mode": uiPrefs().edit().putString("outmode", on ? "single" : "cum").apply(); termHome(); break;
            case "d_term_keepon": uiPrefs().edit().putBoolean("keepon", on).apply(); termHome(); break;
            case "d_gh_tokmode_toggle": uiPrefs().edit().putString("gh_tokmode", on ? "shared" : "perproj").apply(); break;
            case "d_gh_msgmode_toggle": uiPrefs().edit().putString("gh_msgmode", on ? "auto" : "manual").apply(); break;
            case "d_botbtn_display_toggle": uiPrefs().edit().putString("bot_display_mode", on ? "text" : "icon").apply(); termHome(); break;
        }
    }
