    private void ghEditToken(final String projectName) { ghEditToken(projectName, null); }

    private void ghEditToken(final String projectName, final Runnable after) {
        final String key = projectName == null ? "gh_token_shared" : "gh_token_proj_" + projectName;
        final android.widget.EditText et = new android.widget.EditText(this);
        et.setHint("ghp_xxxxxxxxxxxxxxxxxxxx");
        et.setText(uiPrefs().getString(key, ""));
        new NavAlertBuilder()
                .setTitle(projectName == null ? "رمز GitHub المشترك" : "رمز GitHub لهذا المشروع")
                .setMessage("Settings → Developer settings → Personal access tokens (fine-grained) بصلاحية Contents: Read and write، و Administration إن رغبت بإنشاء مستودعات تلقائيًا.")
                .setView(et)
                .setPositiveButton("حفظ", (d, w) -> {
                    uiPrefs().edit().putString(key, et.getText().toString().trim()).apply();
                    Toast.makeText(this, "تم الحفظ", Toast.LENGTH_SHORT).show();
                    if (after != null && !et.getText().toString().trim().isEmpty()) after.run();
                })
                .setNegativeButton("إلغاء", null)
                .show();
    }

    private String ghToken(String projectName) {
        boolean shared = uiPrefs().getString("gh_tokmode", "shared").equals("shared");
        return uiPrefs().getString(shared ? "gh_token_shared" : "gh_token_proj_" + projectName, "");
    }

    private void ghProjectSetup(final String pn) {
        if (ghBlocked()) return;
        String mode = uiPrefs().getString("gh_repomode_" + pn, "existing");
        final String url = uiPrefs().getString("gh_repourl_" + pn, "");
        final boolean isExisting = mode.equals("existing");

        final android.app.Dialog dlg = newScreen("ghProjectSetup" + ":" + String.valueOf(pn), () -> ghProjectSetup(pn));
        LinearLayout root = beginFullscreenCardDialog(dlg, "GitHub \u2014 " + pn);
        LinearLayout box = (LinearLayout) root.getTag();

        addToggleCard(box, "\u2699", "إنشاء المستودع تلقائيًا عند أول رفع", "إيقاف = استخدام رابط مستودع جاهز", "#424242", !isExisting,
                on -> {
                    uiPrefs().edit().putString("gh_repomode_" + pn, on ? "create" : "existing").apply();
                    dlg.dismiss();
                    ghProjectSetup(pn);
                    return true;
                }, null);
        addMenuCard(box, "\uD83D\uDD17", isExisting ? "رابط المستودع" : "اسم المستودع الجديد",
                isExisting ? (url.isEmpty() ? "(غير محدد)" : url) : url, "#3F51B5", () -> {
            final android.widget.EditText et = new android.widget.EditText(this);
            et.setText(url);
            et.setHint(isExisting ? "https://github.com/user/repo.git" : "اسم المستودع الجديد (مثلًا my-app)");
            new NavAlertBuilder()
                    .setTitle(isExisting ? "رابط المستودع" : "اسم المستودع الجديد")
                    .setView(et)
                    .setPositiveButton("حفظ", (d2, w2) -> {
                        uiPrefs().edit().putString("gh_repourl_" + pn, et.getText().toString().trim()).apply();
                        dlg.dismiss();
                        ghProjectSetup(pn);
                    })
                    .setNegativeButton("إلغاء", null)
                    .show();
        });
        if (uiPrefs().getString("gh_tokmode", "shared").equals("perproj")) {
            addMenuCard(box, "\uD83D\uDD11", "رمز الدخول لهذا المشروع", "#009688", () -> {
                dlg.dismiss();
                ghEditToken(pn);
            });
        }
        addMenuCard(box, "\u2B06", "رفع إلى GitHub", isExisting ? "يرفع الملفات الجديدة والمعدّلة إلى المستودع أعلاه" : "ينشئ المستودع ثم يرفع المشروع إليه", "#4CAF50", () -> ghPushFromSetup(pn));
        if (isExisting && !url.trim().isEmpty()) {
            addMenuCard(box, "\u26A1", "رفع تعديلات فقط (ملف / zip / md / أي صيغة)", "ارفع جزءًا من المشروع أو كله من هاتفك؛ يُرفع المختلف فقط إلى المستودع أعلاه", "#8BC34A", () ->
                    ghProjectRepo(pn, (full, br) -> ghDeltaStart(full, br, "")));
        }

        // ===== البناء والتطبيق والسجلات لهذا المشروع (على المستودع المحفوظ) =====
        if (isExisting && !url.trim().isEmpty()) {
            final TextView stTv = new TextView(this);
            stTv.setText("\u23F3 يفحص حالة آخر بناء ...");
            stTv.setTextSize(14);
            stTv.setTextColor(themeTextSecondary());
            stTv.setPadding(dp(6), dp(8), dp(6), dp(8));
            box.addView(stTv, new LinearLayout.LayoutParams(-1, -2));
            ghProjectStatus(pn, dlg, stTv);
            addMenuSectionHeader(box, "البناء (GitHub Actions)");
            addMenuCard(box, "\u25B6", "تشغيل البناء", "يشغّل Workflow على الفرع الافتراضي", "#4CAF50", () ->
                    ghProjectRepo(pn, (full, br) -> { dlg.dismiss(); ghWorkflows(full, br); }));
            addMenuCard(box, "\uD83D\uDCCB", "سجل البناء", "كل عمليات البناء، ومن كل واحدة: تثبيت/تنزيل التطبيق وتنزيل السجل", "#3F51B5", () ->
                    ghProjectRepo(pn, (full, br) -> { dlg.dismiss(); ghRuns(full, br); }));
            addMenuSectionHeader(box, "التطبيق");
            addMenuCard(box, "\uD83D\uDCF2", "تثبيت آخر تطبيق مبني", "ينزّل APK آخر بناء ناجح ويفتح شاشة التثبيت مباشرة", "#4CAF50", () ->
                    ghProjectRepo(pn, (full, br) -> { dlg.dismiss(); ghLatest(full, br, true, run -> ghApkTask(full, run.optLong("id"), true)); }));
            addMenuCard(box, "\u2B07", "تنزيل آخر APK", "يحفظ APK آخر بناء ناجح في Downloads بلا تثبيت", "#009688", () ->
                    ghProjectRepo(pn, (full, br) -> { dlg.dismiss(); ghLatest(full, br, true, run -> ghApkTask(full, run.optLong("id"), false)); }));
            addMenuSectionHeader(box, "السجل");
            addMenuCard(box, "\uD83D\uDCE6", "تنزيل سجل آخر بناء (zip)", "ناجحًا كان أو فاشلًا", "#3F51B5", () ->
                    ghProjectRepo(pn, (full, br) -> { dlg.dismiss(); ghLatest(full, br, false, run -> ghLogsTask(full, run.optLong("id"), run.optInt("run_number"))); }));
            addMenuCard(box, "\uD83D\uDCC2", "فتح المستودع في مدير GitHub", "الملفات والفروع وطلبات الدمج", "#607D8B", () ->
                    ghProjectRepo(pn, (full, br) -> { dlg.dismiss(); ghRepo(full, br); }));
        } else {
            ghNote(box, "بعد حفظ رابط مستودع جاهز (أو أول رفع ينشئ المستودع) تظهر هنا أزرار تشغيل البناء وتثبيت التطبيق وتنزيل السجلات.");
        }

        dlg.setContentView(root);
        dlg.show();
    }

    // يحوّل رابط المستودع المحفوظ لهذا المشروع إلى owner/repo ويجلب فرعه الافتراضي، ثم يمرّرهما للمستهلك
    private void ghProjectRepo(final String pn, final java.util.function.BiConsumer<String, String> use) {
        if (ghBlocked()) return;
        if (ghMgrToken().isEmpty()) { ghToast("سجّل الدخول إلى GitHub أولًا."); ghLogin(); return; }
        final String val = uiPrefs().getString("gh_repourl_" + pn, "").trim();
        if (val.isEmpty()) { ghToast("أدخل رابط المستودع أولًا."); return; }
        final String full = ghRepoOf(val);
        if (full == null) { ghToast("تعذّر فهم رابط المستودع."); return; }
        this.<String>ghAsync(() -> new JSONObject(ghGet("/repos/" + full)).optString("default_branch", "main"), (br, err) -> {
            if (err != null) { ghToast("تعذّر الوصول للمستودع: " + err); return; }
            use.accept(full, br);
        });
    }

    // يفحص آخر عملية بناء على المستودع المحفوظ ويعرض حالتها (نجح / فشل / قيد التنفيذ / فارغ) ويحفظها للقائمة
    private void ghProjectStatus(final String pn, final android.app.Dialog dlg, final TextView tv) {
        if (!ghEnabled() || ghMgrToken().isEmpty()) { tv.setText("سجّل الدخول إلى GitHub لعرض حالة البناء."); return; }
        final String full = ghRepoOf(uiPrefs().getString("gh_repourl_" + pn, ""));
        if (full == null) { tv.setText(""); return; }
        this.<JSONObject>ghAsync(() -> ghLatestStatus(full), (o, err) -> {
            if (err != null) { if (dlg.isShowing()) tv.setText("تعذّر فحص حالة البناء: " + err); return; }
            String st = o.optString("st");
            uiPrefs().edit().putString("gh_status_" + pn, st).putLong("gh_status_ts_" + pn, System.currentTimeMillis()).apply();
            String t;
            switch (st) {
                case "ok": t = "\u2705 آخر بناء (#" + o.optInt("num") + ") نجح"; break;
                case "fail": t = "\u274C آخر بناء (#" + o.optInt("num") + ") فشل"; break;
                case "cancelled": t = "\u23F9 آخر بناء (#" + o.optInt("num") + ") أُلغي"; break;
                case "running": t = "\u23F3 بناء #" + o.optInt("num") + " قيد التنفيذ"; break;
                default: t = "\u26AA فارغ: لا توجد عمليات بناء بعد"; break;
            }
            if (dlg.isShowing()) tv.setText(t + (st.equals("none") ? "" : " \u2022 " + o.optString("date")));
        });
    }

    private void ghEnsureGitInstalled(Runnable onReady) {
        Toast.makeText(this, "يتحقق من git...", Toast.LENGTH_SHORT).show();
        new Thread(() -> {
            File base = toolsBase();
            File rootfs = findRoot(new File(getFilesDir(), "rootfs"), 2);
            if (rootfs == null || !new File(base, "bin/proot").exists()) {
                runOnUiThread(() -> Toast.makeText(this, "أكمل الإعداد الأولي أولًا (proot/Debian).", Toast.LENGTH_LONG).show());
                return;
            }
            Res chk = guestRun(base, rootfs, false, null, "/bin/sh", "-c", "command -v git");
            if (chk.code == 0) {
                runOnUiThread(onReady);
                return;
            }
            runOnUiThread(() -> Toast.makeText(this, "جارٍ تثبيت git (مرة واحدة فقط) ...", Toast.LENGTH_LONG).show());
            guestRun(base, rootfs, false, null, "/bin/sh", "-c",
                    "echo nameserver 8.8.8.8 > /etc/resolv.conf; apt-get update -y && apt-get install -y git curl");
            Res chk2 = guestRun(base, rootfs, false, null, "/bin/sh", "-c", "command -v git");
            runOnUiThread(() -> {
                if (chk2.code == 0) onReady.run();
                else Toast.makeText(this, "فشل تثبيت git. تحقّق من الاتصال بالإنترنت وحاول مجددًا.", Toast.LENGTH_LONG).show();
            });
        }).start();
    }

    // ====================================================================
    // مدير GitHub الكامل (عبر GitHub REST API): مستودعات، ملفات، تعديل، فروع،
    // إيداعات، طلبات دمج (قرارات)، مشاكل، إشعارات، تنزيل/رفع مشاريع.
    // يعمل بالرمز المشترك المحفوظ في «تعديل الرمز المشترك».
    // ====================================================================
    private static final String GH_API = "https://api.github.com";
    private static final int PICK_GH_UPLOAD = 16;
    private String ghUpFull, ghUpBranch, ghUpDir; // وجهة «رفع ملفات من الهاتف»

    private interface GhWork<T> { T run() throws Exception; }
    private interface GhDone<T> { void done(T r, String err); }
    private interface GhUi<T> { void run(T r) throws Exception; }

    private static final class GhScreen {
        android.app.Dialog dlg;
        LinearLayout root, box;
        boolean alive = true;
    }

    private <T> void ghAsync(final GhWork<T> w, final GhDone<T> d) {
        new Thread(() -> {
            T r = null;
            String err = null;
            try {
                r = w.run();
            } catch (Throwable e) {
                err = e.getMessage() == null ? e.toString() : e.getMessage();
            }
            final T fr = r;
            final String fe = err;
            runOnUiThread(() -> d.done(fr, fe));
        }).start();
    }

    private static final String GH_OFF_MSG = "GitHub متوقف (شغّله من إعدادات GitHub)";

    private boolean ghEnabled() { return uiPrefs().getBoolean("gh_enabled", true); }

    // يُستخدم عند فتح أي شاشة GitHub: إن كان متوقفًا لا يُفتح شيء
    private boolean ghBlocked() {
        if (ghEnabled()) return false;
        Toast.makeText(this, GH_OFF_MSG, Toast.LENGTH_LONG).show();
        return true;
    }

    private String ghMgrToken() { return uiPrefs().getString("gh_token_shared", "").trim(); }

    private static String ghEnc(String s) { return android.net.Uri.encode(s); }
    private static String ghEncPath(String p) { return android.net.Uri.encode(p, "/"); }

    private static String ghDate(String iso) {
        if (iso == null) return "";
        return iso.length() >= 16 ? iso.substring(0, 10) + " " + iso.substring(11, 16) : iso;
    }

    private static String jsonOf(Object... kv) {
        JSONObject o = new JSONObject();
        try {
            for (int i = 0; i + 1 < kv.length; i += 2) if (kv[i + 1] != null) o.put((String) kv[i], kv[i + 1]);
        } catch (Exception ignored) {}
        return o.toString();
    }

    private volatile boolean ghViaNetwork = true;
    // مهلة الاتصال لكل محاولة (تتصاعد مع كل إعادة محاولة في ghHttp): 15ث ثم 30ث ثم 45ث
    private final ThreadLocal<Integer> ghConnTo = new ThreadLocal<>();

    // يفتح الاتصال عبر شبكة أندرويد النشطة (كالمتصفح) أو عبر الطريقة العادية
    private java.net.HttpURLConnection ghOpenUrl(String url) throws IOException {
        java.net.URL u = new java.net.URL(url);
        if (ghViaNetwork) {
            try {
                android.net.ConnectivityManager cm = (android.net.ConnectivityManager) getSystemService(CONNECTIVITY_SERVICE);
                android.net.Network n = cm == null ? null : cm.getActiveNetwork();
                if (n != null) return (java.net.HttpURLConnection) n.openConnection(u);
            } catch (Throwable ignored) {}
        }
        return (java.net.HttpURLConnection) u.openConnection();
    }

    private java.net.HttpURLConnection ghConn(String method, String path, String accept) throws Exception {
        if (!ghEnabled()) throw new IOException(GH_OFF_MSG);
        String tok = ghMgrToken();
        if (tok.isEmpty()) throw new IOException("لا يوجد رمز GitHub — سجّل الدخول من مدير GitHub");
        String url = path.startsWith("http") ? path : GH_API + path;
        java.net.HttpURLConnection c = ghOpenUrl(url);
        Integer cto = ghConnTo.get();
        c.setConnectTimeout(cto == null ? 20000 : cto);
        c.setReadTimeout(60000);
        c.setInstanceFollowRedirects(true);
        try {
            c.setRequestMethod(method);
        } catch (java.net.ProtocolException pe) {
            try {
                java.lang.reflect.Field f = java.net.HttpURLConnection.class.getDeclaredField("method");
                f.setAccessible(true);
                f.set(c, method);
            } catch (Throwable t2) {
                throw pe;
            }
        }
        c.setRequestProperty("Authorization", "Bearer " + tok);
        c.setRequestProperty("Accept", accept == null ? "application/vnd.github+json" : accept);
        c.setRequestProperty("X-GitHub-Api-Version", "2022-11-28");
        c.setRequestProperty("User-Agent", "L2SBuilder");
        return c;
    }

    private IOException ghError(int rc, String body) {
        String msg = body;
        try { msg = new JSONObject(body).optString("message", body); } catch (Throwable ignored) {}
        if (rc == 401) msg = "الرمز غير صالح أو منتهي";
        else if (rc == 403 && msg.toLowerCase(java.util.Locale.US).contains("rate limit")) msg = "تجاوزت حد الطلبات، حاول بعد قليل";
        String tr = ghTr(msg);
        return new IOException(rc + ": " + tr + (tr.equals(msg) ? "" : "\n(" + msg + ")"));
    }

    // ترجمة رسائل GitHub الإنجليزية الشائعة إلى العربية (يبقى النص الأصلي بين قوسين للرجوع إليه)
    private static String ghTr(String m) {
        if (m == null) return "";
        String l = m.toLowerCase(java.util.Locale.US);
        String[][] t = {
            {"without `workflow` scope", "الرمز ينقصه صلاحية workflow: GitHub يرفض رفع أو تعديل ملفات .github/workflows بدونها"},
            {"refusing to allow", "الرمز ينقصه صلاحية workflow: GitHub يرفض رفع أو تعديل ملفات .github/workflows بدونها"},
            {"bad credentials", "الرمز غير صالح أو منتهي"},
            {"requires authentication", "يتطلب تسجيل الدخول"},
            {"resource not accessible", "الرمز لا يملك الصلاحية الكافية لهذا الإجراء"},
            {"must have admin rights", "تحتاج صلاحية مدير (Admin) على المستودع"},
            {"secondary rate limit", "طلبات كثيرة بسرعة، انتظر دقيقة ثم أعد المحاولة"},
            {"abuse detection", "طلبات كثيرة بسرعة، انتظر دقيقة ثم أعد المحاولة"},
            {"name already exists", "هذا الاسم مستخدم مسبقًا"},
            {"repository creation failed", "فشل إنشاء المستودع"},
            {"validation failed", "فشل التحقق من البيانات المدخلة"},
            {"workflow_dispatch", "ملف الـ Workflow لا يحوي workflow_dispatch للتشغيل اليدوي (أضف on: workflow_dispatch)"},
            {"does not match", "الملف تغيّر على GitHub منذ آخر تحميل، أعد فتحه ثم حاول مجددًا"},
            {"merge conflict", "يوجد تعارض في الدمج يجب حله أولًا"},
            {"not mergeable", "طلب الدمج غير قابل للدمج الآن"},
            {"reference already exists", "الفرع موجود مسبقًا"},
            {"reference does not exist", "الفرع غير موجود"},
            {"git repository is empty", "المستودع فارغ"},
            {"repository access blocked", "الوصول إلى المستودع محظور"},
            {"too large", "الملف أو الرد كبير جدًا"},
            {"service unavailable", "خدمة GitHub غير متاحة مؤقتًا، حاول لاحقًا"},
            {"server error", "خطأ مؤقت في خادم GitHub، حاول لاحقًا"},
            {"not found", "غير موجود، أو لا تملك صلاحية الوصول إليه (تأكد من الاسم وصلاحيات الرمز)"},
            {"forbidden", "ممنوع: لا تملك الصلاحية لهذا الإجراء"},
            {"unauthorized", "غير مصرّح: تحقق من الرمز"},
        };
        for (String[] e : t) if (l.contains(e[0])) return e[1];
        return m;
    }

