    private byte[] ghHttpBytes(String method, String path, String json, String accept, long cap) throws Exception {
        java.net.HttpURLConnection c = ghConn(method, path, accept);
        try {
            if (json != null) {
                c.setDoOutput(true);
                c.setRequestProperty("Content-Type", "application/json; charset=utf-8");
                byte[] b = json.getBytes(StandardCharsets.UTF_8);
                c.setFixedLengthStreamingMode(b.length);
                try (OutputStream os = c.getOutputStream()) { os.write(b); }
            }
            int rc = c.getResponseCode();
            InputStream is = rc >= 400 ? c.getErrorStream() : c.getInputStream();
            byte[] body = new byte[0];
            if (is != null) {
                try (InputStream in = is) {
                    byte[] all = readCapped(in, cap);
                    if (all == null) throw new IOException("الرد كبير جدًا");
                    body = all;
                }
            }
            if (rc >= 400) throw ghError(rc, new String(body, StandardCharsets.UTF_8));
            return body;
        } finally {
            c.disconnect();
        }
    }

    // فشل في مرحلة الاتصال (لم يصل الطلب للخادم أصلًا) → إعادة المحاولة آمنة حتى لطلبات الكتابة
    private static boolean ghIsConnectPhase(Throwable e) {
        if (e instanceof java.net.UnknownHostException || e instanceof java.net.NoRouteToHostException
                || e instanceof java.net.ConnectException) return true;
        String m = String.valueOf(e.getMessage()).toLowerCase(java.util.Locale.US);
        return m.contains("failed to connect") || m.contains("connect timed out") || m.contains("unable to resolve host");
    }

    private String ghHttp(String method, String path, String json, String accept) throws Exception {
        final boolean isGet = "GET".equals(method);
        final boolean gitData = path != null && path.contains("/git/"); // blobs/trees/commits/refs: إعادتها آمنة
        final int tries = isGet ? 4 : 3;
        final boolean origNet = ghViaNetwork;
        try {
            for (int i = 1; ; i++) {
                ghConnTo.set(Math.min(15000 * i, 45000));
                if (i > 1) ghViaNetwork = (i % 2 == 1) ? origNet : !origNet; // بدّل مسار الشبكة بين المحاولات
                try {
                    return new String(ghHttpBytes(method, path, json, accept, 64L << 20), StandardCharsets.UTF_8);
                } catch (java.net.SocketException | java.net.SocketTimeoutException | java.net.UnknownHostException e) {
                    boolean canRetry = isGet || gitData || ghIsConnectPhase(e);
                    if (!canRetry || i >= tries) {
                        ghViaNetwork = origNet;
                        if (ghIsConnectPhase(e)) {
                            throw new IOException("تعذّر الاتصال بـ GitHub بعد " + i + " محاولات (الخطأ من الشبكة وليس من الملفات).\n"
                                    + "التفاصيل: " + e.getMessage() + "\n"
                                    + "جرّب: تبديل الشبكة (واي فاي ↔ بيانات)، أو تشغيل/إيقاف VPN، أو تغيير DNS إلى 1.1.1.1، ثم أعد الرفع (الملفات المرفوعة مسبقًا لن تُرفع من جديد).", e);
                        }
                        throw e;
                    }
                    try { progress("تعذّر الاتصال بـ GitHub — إعادة المحاولة " + i + "/" + (tries - 1) + " ..."); } catch (Throwable ignored) {}
                    Thread.sleep(2000L * i);
                }
            }
        } finally {
            ghConnTo.remove();
        }
    }

    private String ghGet(String path) throws Exception { return ghHttp("GET", path, null, null); }

    // ---------- أدوات واجهة ----------
    private GhScreen ghOpen(String key, String title, Runnable reopen) {
        final GhScreen s = new GhScreen();
        s.dlg = newScreen(key, reopen);
        s.root = beginFullscreenCardDialog(s.dlg, title);
        s.box = (LinearLayout) s.root.getTag();
        s.dlg.setOnDismissListener(x -> s.alive = false);
        s.dlg.setContentView(s.root);
        s.dlg.show();
        return s;
    }

    private void ghNote(LinearLayout box, String text) {
        TextView tv = new TextView(this);
        tv.setText(text);
        tv.setTextSize(13);
        tv.setTextColor(themeTextSecondary());
        tv.setLineSpacing(0f, 1.15f);
        tv.setTextIsSelectable(true);
        tv.setPadding(dp(6), dp(8), dp(6), dp(8));
        box.addView(tv, new LinearLayout.LayoutParams(-1, -2));
    }

    private <T> void ghLoad(final GhScreen s, final Runnable retry, final GhWork<T> work, final GhUi<T> render) {
        s.box.removeAllViews();
        ghNote(s.box, "⏳ جارٍ التحميل ...");
        this.<T>ghAsync(work, (r, err) -> {
            if (!s.alive) return;
            s.box.removeAllViews();
            if (err != null) {
                ghNote(s.box, "✖ " + err);
                addMenuCard(s.box, "\uD83D\uDD04", "إعادة المحاولة", "#2196F3", () -> { s.dlg.dismiss(); retry.run(); });
                addMenuCard(s.box, "\uD83D\uDD11", "تسجيل الدخول", "#3F51B5", () -> { s.dlg.dismiss(); ghLogin(); });
                return;
            }
            try {
                render.run(r);
            } catch (Throwable e) {
                ghNote(s.box, "✖ تعذّر عرض النتيجة: " + e);
            }
        });
    }

    private void ghToast(String m) { Toast.makeText(this, m, Toast.LENGTH_LONG).show(); }

    private void ghShowText(String title, String text) {
        final String t = text == null || text.isEmpty() ? "(فارغ)" : (text.length() > 60000 ? text.substring(0, 60000) + "\n... (مقتطع)" : text);
        TextView tv = new TextView(this);
        tv.setText(t);
        tv.setTypeface(Typeface.MONOSPACE);
        tv.setTextSize(11);
        tv.setTextIsSelectable(true);
        tv.setTextDirection(View.TEXT_DIRECTION_LTR);
        tv.setPadding(dp(14), dp(8), dp(14), dp(8));
        ScrollView sv = new ScrollView(this);
        sv.addView(tv);
        new NavAlertBuilder()
                .setTitle(title)
                .setView(sv)
                .setPositiveButton("نسخ", (d, w) -> {
                    ClipboardManager cm = (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
                    if (cm != null) cm.setPrimaryClip(ClipData.newPlainText(title, t));
                    Toast.makeText(this, "تم النسخ", Toast.LENGTH_SHORT).show();
                })
                .setNegativeButton("إغلاق", null)
                .show();
    }

    // يسأل عن رسالة الالتزام (أو يولّدها تلقائيًا حسب الإعداد)
    private void ghAskMessage(final String suggestion, final java.util.function.Consumer<String> ok) {
        if (uiPrefs().getString("gh_msgmode", "manual").equals("auto")) {
            String stamp = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", java.util.Locale.US).format(new java.util.Date());
            ok.accept(suggestion + " — " + stamp);
            return;
        }
        final android.widget.EditText et = new android.widget.EditText(this);
        et.setText(suggestion);
        et.setSelectAllOnFocus(true);
        new NavAlertBuilder()
                .setTitle("رسالة الالتزام")
                .setView(et)
                .setPositiveButton("تنفيذ", (d, w) -> {
                    String m = et.getText().toString().trim();
                    ok.accept(m.isEmpty() ? suggestion : m);
                })
                .setNegativeButton("إلغاء", null)
                .show();
    }

    private void ghPrompt(String title, String hint, String initial, final java.util.function.Consumer<String> ok) {
        final android.widget.EditText et = new android.widget.EditText(this);
        et.setHint(hint);
        et.setText(initial == null ? "" : initial);
        et.setTextDirection(View.TEXT_DIRECTION_LTR);
        new NavAlertBuilder()
                .setTitle(title)
                .setView(et)
                .setPositiveButton("موافق", (d, w) -> {
                    String v = et.getText().toString().trim();
                    if (!v.isEmpty()) ok.accept(v);
                })
                .setNegativeButton("إلغاء", null)
                .show();
    }

    private void ghConfirm(String title, String msg, final Runnable yes) {
        new NavAlertBuilder()
                .setTitle(title)
                .setMessage(msg)
                .setPositiveButton("نعم", (d, w) -> yes.run())
                .setNegativeButton("إلغاء", null)
                .show();
    }

