    // ---------- استهلاك GitHub Actions (عام / خاص / المتبقي / الإنفاق) ----------
    // يقرأ تقرير الفوترة: GET /users/{login}/settings/billing/usage (يحتاج رمزًا بصلاحية user أو Plan:read،
    // والحساب على نظام الفوترة المحسّن). حد الإنفاق لا يوفّر GitHub API لقراءته لحساب شخصي،
    // لذلك يُحفظ محليًا ويُعدَّل من الشاشة نفسها.
    private void ghUsage() {
        if (ghBlocked()) return;
        final GhScreen s = ghOpen("ghUsage", "استهلاك Actions", () -> ghUsage());
        this.<double[]>ghLoad(s, () -> ghUsage(), () -> {
            String login = uiPrefs().getString("gh_login", "");
            if (login.isEmpty()) login = new JSONObject(ghGet("/user")).optString("login");
            java.util.Calendar cal = java.util.Calendar.getInstance(java.util.TimeZone.getTimeZone("UTC"));
            int y = cal.get(java.util.Calendar.YEAR), m = cal.get(java.util.Calendar.MONTH) + 1;
            // خريطة المستودعات: الاسم الكامل (صغير) -> هل هو خاص
            java.util.HashMap<String, Boolean> priv = new java.util.HashMap<>();
            for (int p = 1; p <= 5; p++) {
                org.json.JSONArray a = new org.json.JSONArray(ghGet("/user/repos?per_page=100&affiliation=owner&page=" + p));
                for (int i = 0; i < a.length(); i++) {
                    JSONObject r = a.getJSONObject(i);
                    priv.put(r.optString("full_name").toLowerCase(java.util.Locale.US), r.optBoolean("private"));
                }
                if (a.length() < 100) break;
            }
            JSONObject rep = new JSONObject(ghGet("/users/" + ghEnc(login) + "/settings/billing/usage?year=" + y + "&month=" + m));
            org.json.JSONArray items = rep.optJSONArray("usageItems");
            double pub = 0, privRaw = 0, privWeighted = 0, unknown = 0, spent = 0;
            if (items != null) for (int i = 0; i < items.length(); i++) {
                JSONObject it = items.getJSONObject(i);
                if (!it.optString("product").toLowerCase(java.util.Locale.US).contains("actions")) continue;
                spent += it.optDouble("netAmount", 0);
                if (!it.optString("unitType").toLowerCase(java.util.Locale.US).contains("minute")) continue;
                double q = it.optDouble("quantity", 0);
                String sku = it.optString("sku").toLowerCase(java.util.Locale.US);
                double mult = sku.contains("macos") ? 10 : sku.contains("windows") ? 2 : 1; // مضاعفات الحصة
                String rn = it.optString("repositoryName").toLowerCase(java.util.Locale.US);
                if (!rn.isEmpty() && !rn.contains("/")) rn = login.toLowerCase(java.util.Locale.US) + "/" + rn;
                Boolean isPriv = priv.get(rn);
                if (isPriv == null) unknown += q;
                else if (isPriv) { privRaw += q; privWeighted += q * mult; }
                else pub += q;
            }
            return new double[]{pub, privRaw, privWeighted, unknown, spent, y, m};
        }, r -> {
            final double free = uiPrefs().getFloat("gh_free_minutes", 2000f);
            final double limit = uiPrefs().getFloat("gh_budget_limit", 0f);
            double remain = Math.max(0, free - r[2]);
            int pct = free > 0 ? (int) Math.min(100, Math.round(r[2] * 100 / free)) : 0;
            // موعد تجديد الحصة: بداية الشهر التالي 00:00 بتوقيت UTC
            java.util.Calendar rc = java.util.Calendar.getInstance(java.util.TimeZone.getTimeZone("UTC"));
            rc.set(java.util.Calendar.DAY_OF_MONTH, 1);
            rc.set(java.util.Calendar.HOUR_OF_DAY, 0);
            rc.set(java.util.Calendar.MINUTE, 0);
            rc.set(java.util.Calendar.SECOND, 0);
            rc.set(java.util.Calendar.MILLISECOND, 0);
            rc.add(java.util.Calendar.MONTH, 1);
            long msLeft = rc.getTimeInMillis() - System.currentTimeMillis();
            long daysLeft = Math.max(0, (msLeft + 86400000L - 1) / 86400000L);
            long hoursLeft = Math.max(0, msLeft / 3600000L);
            java.text.SimpleDateFormat rf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", java.util.Locale.US);
            addMenuCard(s.box, "\u23F3", "تتجدد الحصة بعد " + daysLeft + " يوم",
                    "الموعد: " + rf.format(rc.getTime()) + " (بتوقيت جهازك) • المتبقي نحو " + hoursLeft + " ساعة", "#673AB7", () -> {});
            addMenuSectionHeader(s.box, "الخاص (يُخصم من الحصة)");
            addMenuCard(s.box, "\uD83D\uDD12", "المستخدم: " + Math.round(r[2]) + " دقيقة",
                    "الدقائق الفعلية " + Math.round(r[1]) + " • النسبة " + pct + "% من " + Math.round(free), "#F44336", () -> {});
            addMenuCard(s.box, "\u2705", "المتبقي: " + Math.round(remain) + " دقيقة",
                    remain <= 0 ? "انتهت الحصة — أي بناء إضافي قد يُحاسَب أو يتوقف" : "من حصتك المجانية الشهرية", "#4CAF50", () -> {});
            addMenuSectionHeader(s.box, "العام (مجاني بلا حد)");
            addMenuCard(s.box, "\uD83C\uDF10", "المستخدم: " + Math.round(r[0]) + " دقيقة", "لا يُخصم من الحصة", "#2196F3", () -> {});
            addMenuSectionHeader(s.box, "الإنفاق");
            addMenuCard(s.box, "\uD83D\uDCB5", String.format(java.util.Locale.US, "الإنفاق الفعلي: $%.2f", r[4]),
                    r[4] > 0 ? "⚠ تجاوزت الحصة المجانية" : "لا يوجد إنفاق", r[4] > 0 ? "#FF9800" : "#607D8B", () -> {});
            addMenuCard(s.box, "\uD83D\uDEE1", String.format(java.util.Locale.US, "حد الإنفاق: $%.2f", limit),
                    "قيمة محفوظة محليًا (لا يمكن قراءتها من GitHub) — اضغط للتعديل", "#795548", () ->
                    ghPrompt("حد الإنفاق بالدولار", "مثال: 0", String.valueOf(limit), v -> {
                        try { uiPrefs().edit().putFloat("gh_budget_limit", Float.parseFloat(v.trim())).apply(); } catch (Exception e) { ghToast("رقم غير صالح"); return; }
                        s.dlg.dismiss(); ghUsage();
                    }));
            addMenuCard(s.box, "\u2699", "حصة الدقائق المجانية: " + Math.round(free),
                    "2000 للحساب المجاني، 3000 لـ Pro — اضغط للتعديل", "#009688", () ->
                    ghPrompt("الدقائق المجانية شهريًا", "2000", String.valueOf(Math.round(free)), v -> {
                        try { uiPrefs().edit().putFloat("gh_free_minutes", Float.parseFloat(v.trim())).apply(); } catch (Exception e) { ghToast("رقم غير صالح"); return; }
                        s.dlg.dismiss(); ghUsage();
                    }));
            if (r[3] > 0) ghNote(s.box, "ℹ " + Math.round(r[3]) + " دقيقة لمستودعات لم تُعرف خصوصيتها (محذوفة أو لمنظمة) ولم تُحتسب.");
            addMenuCard(s.box, "\uD83D\uDD04", "تحديث", "#2196F3", () -> { s.dlg.dismiss(); ghUsage(); });
        });
    }


    // ---------- إعدادات المستودع والبناء ----------
    private void ghToggleVisibility(final GhScreen s, final String full, final String br, final boolean isPriv) {
        String msg = isPriv
                ? "سيصبح المستودع عامًا: أي شخص يستطيع رؤية الكود وتحميله، والبناء عليه مجاني بلا حد.\n\nتأكد أنه لا يحوي مفاتيح أو كلمات مرور أو ملف توقيع."
                : "سيصبح المستودع خاصًا: يختفي من البحث، وتُحذف نجومه ومتابعوه نهائيًا، ويُحسب بناؤه من حصة الدقائق الشهرية.";
        ghConfirm(isPriv ? "تحويل إلى عام؟" : "تحويل إلى خاص؟", msg, () ->
                this.<String>ghAsync(() -> ghHttp("PATCH", "/repos/" + full, jsonOf("private", !isPriv), null), (r, err) -> {
                    if (err != null) { ghToast("فشل التحويل: " + err); return; }
                    ghToast(isPriv ? "أصبح المستودع عامًا ✔" : "أصبح المستودع خاصًا ✔");
                    s.dlg.dismiss();
                    ghRepo(full, br);
                }));
    }

    private void ghRenameRepo(final GhScreen s, final String full) {
        final String old = full.substring(full.indexOf('/') + 1);
        ghPrompt("اسم المستودع الجديد", "my-app", old, v -> {
            final String nn = v.replaceAll("[^A-Za-z0-9._-]", "-");
            if (nn.equals(old)) return;
            this.<String>ghAsync(() -> new JSONObject(ghHttp("PATCH", "/repos/" + full, jsonOf("name", nn), null)).optString("full_name"), (nf, err) -> {
                if (err != null) { ghToast("فشلت إعادة التسمية: " + err); return; }
                ghToast("تمت إعادة التسمية ✔");
                s.dlg.dismiss();
                ghRepo(nf, null);
            });
        });
    }

