    // ---------- تصفح الملفات ----------
    private void ghBrowse(final String full, final String br, final String path) {
        final GhScreen s = ghOpen("ghBrowse:" + full + ":" + br + ":" + path, full + (path.isEmpty() ? "" : "/" + path), () -> ghBrowse(full, br, path));
        this.<String>ghLoad(s, () -> ghBrowse(full, br, path),
                () -> ghGet("/repos/" + full + "/contents/" + ghEncPath(path) + "?ref=" + ghEnc(br)), body -> {
            if (body.trim().startsWith("{")) { s.dlg.dismiss(); ghOpenFile(full, br, path); return; }
            org.json.JSONArray a = new org.json.JSONArray(body);
            java.util.ArrayList<JSONObject> items = new java.util.ArrayList<>();
            for (int i = 0; i < a.length(); i++) items.add(a.getJSONObject(i));
            java.util.Collections.sort(items, (x, y) -> {
                boolean dx = "dir".equals(x.optString("type")), dy = "dir".equals(y.optString("type"));
                if (dx != dy) return dx ? -1 : 1;
                return x.optString("name").compareToIgnoreCase(y.optString("name"));
            });
            ghNote(s.box, "الفرع: " + br);
            if (!path.isEmpty()) {
                final String parent = path.contains("/") ? path.substring(0, path.lastIndexOf('/')) : "";
                addMenuCard(s.box, "\u2B05", "..", "#9E9E9E", () -> { s.dlg.dismiss(); ghBrowse(full, br, parent); });
            }
            for (final JSONObject it : items) {
                final String type = it.optString("type");
                final String name = it.optString("name");
                final String p = it.optString("path");
                if (type.equals("dir")) {
                    addMenuCard(s.box, "\uD83D\uDCC1", name, "#FF9800", () -> { s.dlg.dismiss(); ghBrowse(full, br, p); });
                } else if (type.equals("file")) {
                    addMenuCard(s.box, "\uD83D\uDCC4", name, fmtSize(it.optLong("size")), "#607D8B", () -> { s.dlg.dismiss(); ghOpenFile(full, br, p); });
                } else {
                    addMenuCard(s.box, "\uD83D\uDD17", name, type + " (غير مدعوم)", "#9E9E9E", () -> ghToast("هذا النوع غير مدعوم هنا"));
                }
            }
            if (items.isEmpty()) ghNote(s.box, "المجلد فارغ.");
            addMenuSectionHeader(s.box, "إجراءات");
            addMenuCard(s.box, "\uD83D\uDCC4", "+ ملف جديد", "اكتب اسمه (يمكن إضافة مجلد مثل src/Main.java)", "#3F51B5", () ->
                    ghPrompt("ملف جديد", "اسم الملف", "", v -> {
                        String np = path.isEmpty() ? v : path + "/" + v;
                        s.dlg.dismiss();
                        ghNewFile(full, br, np);
                    }));
            addMenuCard(s.box, "\uD83D\uDCE5", "رفع ملفات من الهاتف إلى هنا", "تُحفظ كإيداع على GitHub", "#8BC34A", () -> {
                ghUpFull = full;
                ghUpBranch = br;
                ghUpDir = path;
                Intent i = new Intent(Intent.ACTION_OPEN_DOCUMENT);
                i.addCategory(Intent.CATEGORY_OPENABLE);
                i.setType("*/*");
                i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true);
                startActivityForResult(i, PICK_GH_UPLOAD);
            });
            addMenuCard(s.box, "\u26A1", "رفع تعديلات فقط (ملف / zip / md / أي صيغة)", "يقارن بالمستودع ويرفع المختلف فقط؛ الملفات الجديدة بلا مسار تُوضع هنا", "#8BC34A", () -> ghDeltaStart(full, br, path));
        });
    }

    private static final class GhFile {
        String sha;
        long size;
        byte[] data; // null = كبير جدًا للعرض
    }

    private void ghOpenFile(final String full, final String br, final String path) {
        final String fname = path.contains("/") ? path.substring(path.lastIndexOf('/') + 1) : path;
        final GhScreen s = ghOpen("ghFile:" + full + ":" + br + ":" + path, fname, () -> ghOpenFile(full, br, path));
        this.<GhFile>ghLoad(s, () -> ghOpenFile(full, br, path), () -> {
            String ep = "/repos/" + full + "/contents/" + ghEncPath(path) + "?ref=" + ghEnc(br);
            JSONObject m = new JSONObject(ghGet(ep));
            if (!"file".equals(m.optString("type"))) throw new IOException("هذا ليس ملفًا");
            GhFile f = new GhFile();
            f.sha = m.optString("sha");
            f.size = m.optLong("size");
            String enc = m.optString("content", "");
            if (!enc.isEmpty() && "base64".equals(m.optString("encoding"))) {
                f.data = android.util.Base64.decode(enc, android.util.Base64.DEFAULT);
            } else if (f.size == 0) {
                f.data = new byte[0];
            } else if (f.size <= 1536L * 1024L) {
                f.data = ghHttpBytes("GET", ep, null, "application/vnd.github.raw", 4L << 20);
            }
            return f;
        }, f -> {
            ghNote(s.box, fmtSize(f.size) + " • الفرع " + br + " • sha " + f.sha.substring(0, Math.min(7, f.sha.length())));
            if (f.data != null && looksText(f.data)) {
                ghEditorView(s, full, br, path, f.sha, new String(f.data, StandardCharsets.UTF_8));
            } else {
                ghNote(s.box, f.data == null ? "الملف كبير جدًا للعرض والتعديل هنا." : "ملف ثنائي: لا يمكن عرضه كنص.");
                addMenuCard(s.box, "\u2B07", "حفظ نسخة في التنزيلات", "#009688", () -> ghSaveToDownloads(full, br, path, fname));
                ghFileTail(s, full, br, path, f.sha);
            }
        });
    }

    private void ghNewFile(final String full, final String br, final String path) {
        final String fname = path.contains("/") ? path.substring(path.lastIndexOf('/') + 1) : path;
        GhScreen s = ghOpen("ghNewFile:" + full + ":" + br + ":" + path, "جديد: " + fname, () -> ghNewFile(full, br, path));
        ghNote(s.box, "ملف جديد في " + full + " (الفرع " + br + "): " + path);
        ghEditorView(s, full, br, path, null, "");
    }

    private void ghEditorView(final GhScreen s, final String full, final String br, final String path, final String sha, String text) {
        final android.widget.EditText et = new android.widget.EditText(this);
        et.setText(text);
        et.setTypeface(Typeface.MONOSPACE);
        et.setTextSize(12);
        et.setTextDirection(View.TEXT_DIRECTION_LTR);
        et.setGravity(android.view.Gravity.TOP | android.view.Gravity.START);
        et.setMinLines(12);
        et.setSingleLine(false);
        et.setTextColor(themeTextPrimary());
        s.box.addView(et, new LinearLayout.LayoutParams(-1, -2));
        final String fname = path.contains("/") ? path.substring(path.lastIndexOf('/') + 1) : path;
        addMenuCard(s.box, "\uD83D\uDCBE", "حفظ على GitHub (إيداع)", sha == null ? "إنشاء الملف" : "تحديث الملف", "#4CAF50", () ->
                ghAskMessage((sha == null ? "Add " : "Update ") + fname, msg -> {
                    ghToast("جارٍ الحفظ ...");
                    this.<String>ghAsync(() -> {
                        String b64 = android.util.Base64.encodeToString(ghFixWorkflowBytes(path, et.getText().toString().getBytes(StandardCharsets.UTF_8)), android.util.Base64.NO_WRAP);
                        return ghHttp("PUT", "/repos/" + full + "/contents/" + ghEncPath(path), jsonOf("message", msg, "content", b64, "sha", sha, "branch", br), null);
                    }, (r, err) -> {
                        if (err != null) { ghToast("فشل الحفظ: " + err); return; }
                        ghToast("تم الحفظ ✔");
                        s.dlg.dismiss();
                        ghOpenFile(full, br, path);
                    });
                }));
        addMenuCard(s.box, "\uD83D\uDCCB", "نسخ المحتوى", "#009688", () -> {
            ClipboardManager cm = (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
            if (cm != null) cm.setPrimaryClip(ClipData.newPlainText(fname, et.getText().toString()));
            Toast.makeText(this, "تم النسخ", Toast.LENGTH_SHORT).show();
        });
        if (sha != null) {
            addMenuCard(s.box, "\u2B07", "حفظ نسخة في التنزيلات", "#009688", () -> ghSaveToDownloads(full, br, path, fname));
            ghFileTail(s, full, br, path, sha);
        }
    }

    private void ghFileTail(final GhScreen s, final String full, final String br, final String path, final String sha) {
        final String fname = path.contains("/") ? path.substring(path.lastIndexOf('/') + 1) : path;
        final String parent = path.contains("/") ? path.substring(0, path.lastIndexOf('/')) : "";
        addMenuCard(s.box, "\uD83D\uDDD1", "حذف الملف", "إيداع حذف على GitHub", "#F44336", () ->
                ghConfirm("حذف " + fname + "؟", "سيُحذف الملف من الفرع " + br + " بإيداع جديد.", () ->
                        ghAskMessage("Delete " + fname, msg ->
                                this.<String>ghAsync(() -> ghHttp("DELETE", "/repos/" + full + "/contents/" + ghEncPath(path),
                                        jsonOf("message", msg, "sha", sha, "branch", br), null), (r, err) -> {
                                    if (err != null) { ghToast("فشل الحذف: " + err); return; }
                                    ghToast("تم الحذف ✔");
                                    s.dlg.dismiss();
                                    ghBrowse(full, br, parent);
                                }))));
    }

    private void ghSaveToDownloads(final String full, final String br, final String path, final String fname) {
        startTask(() -> {
            File tmp = new File(getCacheDir(), "gh_" + System.currentTimeMillis() + "_" + fname.replaceAll("[\\\\/:*?\"<>|\\s]", "_"));
            try {
                progress("ينزّل " + fname + " ...");
                byte[] b = ghHttpBytes("GET", "/repos/" + full + "/contents/" + ghEncPath(path) + "?ref=" + ghEnc(br), null, "application/vnd.github.raw", 100L << 20);
                Compat.write(tmp, b);
                return "تم تنزيل " + fname + " ✔\n" + protectFile(tmp, "application/octet-stream");
            } catch (Throwable e) {
                return "فشل التنزيل: " + e.getMessage();
            } finally {
                tmp.delete();
            }
        });
    }

    // يُستدعى من onActivityResult: رفع ملفات الهاتف إلى المجلد المحدد
    private String ghUploadUris(final java.util.List<Uri> uris) {
        final String full = ghUpFull, br = ghUpBranch, dir = ghUpDir == null ? "" : ghUpDir;
        if (full == null || br == null) return "لا توجد وجهة رفع محددة.";
        int ok = 0, fail = 0;
        StringBuilder log = new StringBuilder();
        for (Uri u : uris) {
            String name = fmQueryDisplayName(u);
            if (name == null || name.isEmpty()) name = "file_" + System.currentTimeMillis();
            String path = dir.isEmpty() ? name : dir + "/" + name;
            try (InputStream in = getContentResolver().openInputStream(u)) {
                long maxB = ghMaxFile();
                byte[] data = in == null ? null : readCapped(in, Math.min(GH_MEM_FILE, maxB));
                if (data == null) {
                    if (in == null) throw new IOException("تعذّرت قراءة الملف");
                    if (maxB <= GH_MEM_FILE) throw new IOException("الملف أكبر من الحد المحدد في الإعدادات (" + (maxB >> 20) + " م.ب)");
                    ghUploadUriBig(full, br, path, u, name, maxB);
                } else {
                    progress("يرفع " + path + " ...");
                    ghPutFile(full, br, path, data, "Add " + name);
                }
                ok++;
                log.append("✔ ").append(path).append("\n");
            } catch (Throwable e) {
                fail++;
                log.append("✘ ").append(path).append(": ").append(e.getMessage()).append("\n");
            }
        }
        return "رفع إلى " + full + " (" + br + "): نجح " + ok + (fail > 0 ? "، فشل " + fail : "") + "\n" + log;
    }

    // ملف كبير من الهاتف: ينسخ إلى ملف مؤقت (بحد الإعدادات) ثم يرفعه بثًّا ويُودعه في إيداع مستقل
    private void ghUploadUriBig(String full, String br, String path, Uri u, String name, long maxB) throws Exception {
        File tmp = File.createTempFile("ghup", ".bin", getCacheDir());
        try {
            long tot = 0;
            try (InputStream in2 = getContentResolver().openInputStream(u); java.io.OutputStream os = new java.io.FileOutputStream(tmp)) {
                if (in2 == null) throw new IOException("تعذّرت قراءة الملف");
                byte[] buf = new byte[64 * 1024];
                int n;
                while ((n = in2.read(buf)) > 0) {
                    tot += n;
                    if (tot > maxB) throw new IOException("أكبر من الحد المحدد في الإعدادات (" + (maxB >> 20) + " م.ب)"
                            + (maxB >= (99L << 20) ? " — وحد GitHub 100 م.ب، يحتاج Git LFS" : ""));
                    os.write(buf, 0, n);
                }
            }
            progress("يرفع ملفًا كبيرًا: " + path + " (" + (tot >> 20) + " م.ب) ...");
            String blob = ghUploadBlobStreamRetry(full, tmp);
            String parent = new JSONObject(ghGet("/repos/" + full + "/git/ref/heads/" + ghEncPath(br))).getJSONObject("object").getString("sha");
            String baseTree = new JSONObject(ghGet("/repos/" + full + "/git/commits/" + parent)).getJSONObject("tree").getString("sha");
            JSONObject te = ghTreeEntry(path, "100644");
            te.put("sha", blob);
            JSONObject tb = new JSONObject();
            tb.put("base_tree", baseTree);
            tb.put("tree", new org.json.JSONArray().put(te));
            String newTree = new JSONObject(ghHttpRetry("POST", "/repos/" + full + "/git/trees", tb.toString())).getString("sha");
            JSONObject cb = new JSONObject();
            cb.put("message", "Add " + name);
            cb.put("tree", newTree);
            cb.put("parents", new org.json.JSONArray().put(parent));
            String nc = new JSONObject(ghHttpRetry("POST", "/repos/" + full + "/git/commits", cb.toString())).getString("sha");
            ghHttpRetry("PATCH", "/repos/" + full + "/git/refs/heads/" + ghEncPath(br), jsonOf("sha", nc));
        } finally {
            tmp.delete();
        }
    }

    private void ghPutFile(String full, String br, String path, byte[] data, String msg) throws Exception {
        data = ghFixWorkflowBytes(path, data);
        String sha = null;
        try {
            sha = new JSONObject(ghGet("/repos/" + full + "/contents/" + ghEncPath(path) + "?ref=" + ghEnc(br))).optString("sha", null);
        } catch (IOException e) {
            if (!String.valueOf(e.getMessage()).startsWith("404")) throw e;
        }
        String b64 = android.util.Base64.encodeToString(data, android.util.Base64.NO_WRAP);
        ghHttp("PUT", "/repos/" + full + "/contents/" + ghEncPath(path), jsonOf("message", msg, "content", b64, "sha", sha, "branch", br), null);
    }

    // ====================================================================
    // رفع التعديلات فقط إلى GitHub
    // يقبل: ملفًا واحدًا أو عدة ملفات، zip، tar.gz، md (بصيغة «## FILE: المسار»)، أو أي صيغة أخرى.
    // سواء كان جزءًا من المشروع أو المشروع كاملًا. يقارن المحتوى بما في المستودع (SHA)،
    // ثم ينشئ إيداعًا واحدًا بالمختلف فقط. لا يحذف شيئًا إلا إن اخترت «نسخة كاملة».
    // ====================================================================
    private static final int PICK_GH_DELTA = 17;
    private boolean ghDeltaMirror = false;

    private static final class GhDelta {
        String path;
        File f;
        boolean isNew;
        String mode;
    }

    // dir: مجلد داخل المستودع تُوضع فيه الملفات الجديدة التي لا مسار لها (فارغ = الجذر)
    private void ghDeltaStart(final String full, final String br, final String dir) {
        if (ghBlocked()) return;
        if (ghMgrToken().isEmpty()) { ghToast("سجّل الدخول إلى GitHub أولًا."); ghLogin(); return; }
        new NavAlertBuilder().setTitle("رفع التعديلات إلى " + full + " (" + br + ")")
                .setItems(new CharSequence[]{
                        "\u270F\uFE0F تعديلات فقط (يضيف ويحدّث ولا يحذف شيئًا)",
                        "\uD83D\uDCE6 نسخة كاملة من المشروع (يحذف من GitHub ما ليس فيها)"}, (d, w) -> {
                    ghDeltaMirror = (w == 1);
                    ghUpFull = full;
                    ghUpBranch = br;
                    ghUpDir = dir == null ? "" : dir;
                    Intent i = new Intent(Intent.ACTION_OPEN_DOCUMENT);
                    i.addCategory(Intent.CATEGORY_OPENABLE);
                    i.setType("*/*");
                    i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE, true);
                    try {
                        startActivityForResult(i, PICK_GH_DELTA);
                    } catch (Throwable e) {
                        ghToast("تعذّر فتح منتقي الملفات: " + e.getMessage());
                    }
                })
                .setNegativeButton("إلغاء", null)
                .show();
    }

    // رفع مشروع من ملف zip واحد: نفس مسار ghDeltaTask (فك مؤقت، مقارنة SHA، إيداع بالمختلف فقط)
    private void ghDeltaStartZip(final String full, final String br) {
        if (ghBlocked()) return;
        if (ghMgrToken().isEmpty()) { ghToast("سجّل الدخول إلى GitHub أولًا."); ghLogin(); return; }
        new NavAlertBuilder().setTitle("رفع zip إلى " + full + " (" + br + ")")
                .setItems(new CharSequence[]{
                        "\u270F\uFE0F تحديث وإضافة فقط (لا يحذف شيئًا)",
                        "\uD83D\uDCE6 نسخة كاملة (يحذف من GitHub ما ليس في الـ zip)"}, (d, w) -> {
                    ghDeltaMirror = (w == 1);
                    ghUpFull = full;
                    ghUpBranch = br;
                    ghUpDir = "";
                    Intent i = new Intent(Intent.ACTION_OPEN_DOCUMENT);
                    i.addCategory(Intent.CATEGORY_OPENABLE);
                    i.setType("*/*");
                    i.putExtra(Intent.EXTRA_MIME_TYPES, new String[]{"application/zip", "application/x-zip-compressed", "application/octet-stream"});
                    i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE, false);
                    try {
                        startActivityForResult(i, PICK_GH_DELTA);
                    } catch (Throwable e) {
                        ghToast("تعذّر فتح منتقي الملفات: " + e.getMessage());
                    }
                })
                .setNegativeButton("إلغاء", null)
                .show();
    }

    // مسارات لا تُرفع أبدًا من الأرشيفات (مخرجات بناء ومؤقتات المحررات)
    private static boolean ghSkipRel(String rel, boolean skipBuild) {
        String[] seg = rel.split("/");
        for (int i = 0; i < seg.length; i++) {
            String s = seg[i];
            if (s.equals(".DS_Store") || s.equals("Thumbs.db") || s.startsWith("._")) return true;
            if (i == seg.length - 1) continue;
            if (s.equals(".git") || s.equals(".idea") || s.equals("__MACOSX") || s.equals("node_modules")) return true;
            if (s.equals(".gradle") || s.equals(".cxx")) return true;
            if (skipBuild && s.equals("build")) return true;
        }
        return false;
    }

    private static boolean ghIsGradleMarker(String p) {
        return p.equals("settings.gradle") || p.equals("settings.gradle.kts") || p.equals("build.gradle")
                || p.equals("build.gradle.kts") || p.equals("gradlew");
    }

    private static void ghAddSfx(java.util.HashMap<String, java.util.ArrayList<String>> m, String key, String full) {
        java.util.ArrayList<String> l = m.get(key);
        if (l == null) { l = new java.util.ArrayList<>(); m.put(key, l); }
        l.add(full);
    }

    private static void ghListSome(StringBuilder sb, String prefix, java.util.List<String> l, int max) {
        for (int i = 0; i < l.size() && i < max; i++) sb.append("  ").append(prefix).append(l.get(i)).append("\n");
        if (l.size() > max) sb.append("  ").append(prefix).append("... و").append(l.size() - max).append(" أخرى\n");
    }

    private static void ghListFiles(File base, File d, java.util.List<String> rels) {
        File[] ks = d.listFiles();
        if (ks == null) return;
        for (File k : ks) {
            if (k.isDirectory()) ghListFiles(base, k, rels);
            else rels.add(base.toURI().relativize(k.toURI()).getPath());
        }
    }

    // يسأل المستخدم (من خيط الخلفية) أن يختار من قائمة. يعيد الفهرس، أو -2 عند الإلغاء/انتهاء المهلة.
    private int ghAskChoice(final String title, final java.util.List<String> labels) {
        final java.util.concurrent.atomic.AtomicInteger ch = new java.util.concurrent.atomic.AtomicInteger(-1);
        final java.util.concurrent.CountDownLatch latch = new java.util.concurrent.CountDownLatch(1);
        runOnUiThread(() -> {
            try {
                android.app.AlertDialog.Builder b = new NavAlertBuilder()
                        .setTitle(title)
                        .setItems(labels.toArray(new CharSequence[0]), (d, w) -> ch.set(w))
                        .setNegativeButton("إلغاء التعديل", (d, w) -> ch.set(-2))
                        .setCancelable(false);
                b.setOnDismissListener(dd -> { ch.compareAndSet(-1, -2); latch.countDown(); });
                b.show();
            } catch (Throwable ex) {
                ch.set(-2);
                latch.countDown();
            }
        });
        try {
            if (!latch.await(30, TimeUnit.MINUTES)) return -2;
        } catch (InterruptedException e) {
            return -2;
        }
        return ch.get();
    }

    // نافذة تأكيد قبل الرفع: ملخص التغييرات + رسالة الإيداع. تعيد الرسالة، أو null عند الإلغاء.
    private String ghDeltaConfirm(final String title, final String summary, final String suggestion, boolean forceAsk) {
        if (!forceAsk && uiPrefs().getString("gh_msgmode", "manual").equals("auto")) {
            String stamp = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm", java.util.Locale.US).format(new java.util.Date());
            return suggestion + " — " + stamp;
        }
        final java.util.concurrent.atomic.AtomicReference<String> res = new java.util.concurrent.atomic.AtomicReference<>(null);
        final java.util.concurrent.CountDownLatch latch = new java.util.concurrent.CountDownLatch(1);
        runOnUiThread(() -> {
            try {
                LinearLayout box = new LinearLayout(this);
                box.setOrientation(LinearLayout.VERTICAL);
                int p = dp(14);
                box.setPadding(p, p, p, 0);
                ScrollView sv = new ScrollView(this);
                TextView tv = new TextView(this);
                tv.setText(summary);
                tv.setTextSize(13);
                tv.setTextIsSelectable(true);
                sv.addView(tv);
                box.addView(sv, new LinearLayout.LayoutParams(-1, dp(260)));
                final android.widget.EditText et = new android.widget.EditText(this);
                et.setText(suggestion);
                et.setSelectAllOnFocus(true);
                box.addView(et, new LinearLayout.LayoutParams(-1, -2));
                android.app.AlertDialog.Builder b = new NavAlertBuilder()
                        .setTitle(title)
                        .setView(box)
                        .setPositiveButton("ارفع", (d, w) -> {
                            String m = et.getText().toString().trim();
                            res.set(m.isEmpty() ? suggestion : m);
                        })
                        .setNegativeButton("إلغاء", null)
                        .setCancelable(false);
                b.setOnDismissListener(dd -> latch.countDown());
                b.show();
            } catch (Throwable ex) {
                latch.countDown();
            }
        });
        try {
            if (!latch.await(30, TimeUnit.MINUTES)) return null;
        } catch (InterruptedException e) {
            return null;
        }
        return res.get();
    }

    private String ghCreateBlob(String full, byte[] data) throws Exception {
        String b64 = android.util.Base64.encodeToString(data, android.util.Base64.NO_WRAP);
        for (int attempt = 0; ; attempt++) {
            try {
                return new JSONObject(ghHttp("POST", "/repos/" + full + "/git/blobs", jsonOf("content", b64, "encoding", "base64"), null)).getString("sha");
            } catch (IOException ioe) {
                String m = String.valueOf(ioe.getMessage());
                if (attempt < 2 && (m.startsWith("403") || m.startsWith("429"))) {
                    progress("انتظار حد GitHub ...");
                    Thread.sleep(20000);
                } else {
                    throw ioe;
                }
            }
        }
    }

    private static void ghCopyStream(InputStream in, File dst) throws IOException {
        File par = dst.getParentFile();
        if (par != null) par.mkdirs();
        try (FileOutputStream fo = new FileOutputStream(dst)) {
            byte[] buf = new byte[65536];
            int k;
            while ((k = in.read(buf)) > 0) fo.write(buf, 0, k);
        }
    }

    // ---- فك الأرشيفات إلى مجلد مؤقت (على القرص لا في الذاكرة) ----
    private int ghExtractZip(File src, File dst, boolean skipBuild) throws Exception {
        int n = 0;
        try (ZipInputStream zin = new ZipInputStream(new BufferedInputStream(new FileInputStream(src), 1 << 16))) {
            ZipEntry e;
            while ((e = zin.getNextEntry()) != null) {
                if (e.isDirectory()) continue;
                String rel = normalize(e.getName().replace('\\', '/'));
                if (rel == null || ghSkipRel(rel, skipBuild)) continue;
                try {
                    ghCopyStream(zin, new File(dst, rel));
                    n++;
                } catch (IOException ex) {
                    // تعارض ملف/مجلد بالاسم نفسه: نتجاوز هذا الملف فقط
                }
            }
        }
        return n;
    }

    // zip محمي بكلمة سر (التطبيق نفسه يصدّر بكلمة سر الافتراضي): نجرّب ZipCryptoReader
    private int ghExtractZipCrypto(File src, File dst, boolean skipBuild) throws Exception {
        if (src.length() > 64L * 1024 * 1024) throw new IOException("zip المحمي كبير جدًا (أكثر من 64MB)");
        byte[] data = Compat.readAllBytes(src);
        int n = 0;
        for (ZipCryptoReader.Entry e : ZipCryptoReader.list(data)) {
            if (e.isDirectory()) continue;
            String rel = normalize(e.name.replace('\\', '/'));
            if (rel == null || ghSkipRel(rel, skipBuild)) continue;
            byte[] b = ZipCryptoReader.read(data, e, e.isEncrypted() ? EMBED_ZIP_PASSWORD : null);
            File f = new File(dst, rel);
            File par = f.getParentFile();
            if (par != null) par.mkdirs();
            Compat.write(f, b);
            n++;
        }
        return n;
    }

    private boolean ghIsTarGz(File src) {
        try (InputStream in = new GZIPInputStream(new BufferedInputStream(new FileInputStream(src), 1 << 16))) {
            byte[] h = new byte[512];
            if (!readFully(in, h, 512)) return false;
            return h[257] == 'u' && h[258] == 's' && h[259] == 't' && h[260] == 'a' && h[261] == 'r';
        } catch (Throwable e) {
            return false;
        }
    }

    private int ghExtractTarGz(File src, File dst, boolean skipBuild) throws Exception {
        int n = 0;
        try (InputStream raw = new FileInputStream(src);
             InputStream in = new GZIPInputStream(new BufferedInputStream(raw, 1 << 16), 1 << 16)) {
            byte[] hdr = new byte[512];
            byte[] buf = new byte[1 << 16];
            String longName = null;
            String[] pax = new String[2];
            while (true) {
                if (!readFully(in, hdr, 512)) break;
                if (isZero(hdr)) break;
                String name = cstr(hdr, 0, 100);
                long size = parseSize(hdr, 124, 12);
                char type = (char) (hdr[156] & 0xff);
                boolean posix = hdr[257] == 'u' && hdr[258] == 's' && hdr[259] == 't' && hdr[260] == 'a' && hdr[261] == 'r';
                if (posix) {
                    String prefix = cstr(hdr, 345, 155);
                    if (!prefix.isEmpty()) name = prefix + "/" + name;
                }
                long pad = (512 - (size % 512)) % 512;
                if (type == 'L' || type == 'K' || type == 'x') {
                    byte[] data = readBytes(in, size);
                    skipFully(in, pad);
                    if (type == 'L') longName = cstr(data, 0, data.length);
                    else if (type == 'x') parsePax(data, pax);
                    continue;
                }
                if (type == 'g') { skipFully(in, size + pad); continue; }
                if (longName != null) name = longName;
                if (pax[0] != null) name = pax[0];
                longName = null;
                pax[0] = null;
                pax[1] = null;
                String rel = normalize(name);
                boolean regular = (type == '0' || type == (char) 0 || type == '7') && !name.endsWith("/");
                if (regular && rel != null && !ghSkipRel(rel, skipBuild)) {
                    File f = new File(dst, rel);
                    File par = f.getParentFile();
                    if (par != null) par.mkdirs();
                    FileOutputStream fo = null;
                    try { fo = new FileOutputStream(f); } catch (IOException ex) { fo = null; }
                    if (fo == null) {
                        skipFully(in, size + pad);
                    } else {
                        try {
                            long left = size;
                            while (left > 0) {
                                int k = in.read(buf, 0, (int) Math.min(buf.length, left));
                                if (k < 0) throw new EOFException();
                                fo.write(buf, 0, k);
                                left -= k;
                            }
                        } finally {
                            fo.close();
                        }
                        skipFully(in, pad);
                        n++;
                    }
                } else {
                    skipFully(in, size + pad);
                }
            }
        }
        return n;
    }

    // نص md بصيغة التصدير («## FILE: المسار» + كتلة كود): يكتب كل ملف إلى inDir ويسجله في inc. يعيد عدد الملفات.
    private int ghAddMd(String text, File inDir, java.util.Map<String, File> inc, StringBuilder notes, String srcName) {
        MdProject.Result r = MdProject.parse(text);
        if (r.items.isEmpty()) return 0;
        int n = 0, bad = r.badPaths;
        for (MdProject.Item it : r.items) {
            String rel = normalize(it.path == null ? null : it.path.replace('\\', '/'));
            if (rel == null) { bad++; continue; }
            try {
                File f = new File(inDir, rel);
                File par = f.getParentFile();
                if (par != null) par.mkdirs();
                Compat.write(f, it.content.getBytes(StandardCharsets.UTF_8));
                inc.put(rel, f);
                n++;
            } catch (Throwable e) {
                bad++;
            }
        }
        notes.append("\uD83D\uDCDD ").append(srcName).append(" (md): ").append(n).append(" ملف");
        if (r.truncated > 0) notes.append(" ⚠ آخر قسم مقطوع وتم تجاهله");
        if (bad > 0) notes.append(" ⚠ تجاهل ").append(bad).append(" مسار غير آمن");
        notes.append("\n");
        return n;
    }

    // يقرأ مصدرًا واحدًا (ملف من الهاتف) ويضيف ملفاته إلى inc بمسارات نسبية.
    private void ghDeltaIngest(Uri u, File tmp, File inDir, java.util.Map<String, File> inc,
                               StringBuilder notes, boolean skipBuild, int idx) throws Exception {
        String name = fmQueryDisplayName(u);
        if (name == null || name.isEmpty()) name = "file_" + System.currentTimeMillis();
        name = name.replace('\\', '/');
        name = name.substring(name.lastIndexOf('/') + 1);
        if (name.isEmpty()) name = "file_" + System.currentTimeMillis();

        File src = new File(tmp, "src_" + idx);
        try (InputStream in = getContentResolver().openInputStream(u)) {
            if (in == null) throw new IOException("تعذّر فتح الملف");
            ghCopyStream(in, src);
        }
        byte[] head = new byte[4];
        int hn;
        try (FileInputStream fi = new FileInputStream(src)) { hn = fi.read(head); }
        boolean isZip = hn >= 4 && head[0] == 'P' && head[1] == 'K';
        boolean isGz = hn >= 2 && (head[0] & 0xff) == 0x1f && (head[1] & 0xff) == 0x8b;

        File stage = null;
        int count = -1;
        if (isZip) {
            stage = new File(tmp, "stage_" + idx);
            stage.mkdirs();
            try {
                count = ghExtractZip(src, stage, skipBuild);
            } catch (java.util.zip.ZipException ze) {
                deleteRec(stage);
                stage.mkdirs();
                count = ghExtractZipCrypto(src, stage, skipBuild);
            }
        } else if (isGz && ghIsTarGz(src)) {
            stage = new File(tmp, "stage_" + idx);
            stage.mkdirs();
            count = ghExtractTarGz(src, stage, skipBuild);
        }

        if (stage != null) {
            java.util.List<String> rels = new ArrayList<>();
            ghListFiles(stage, stage, rels);
            // أرشيف كل ما فيه ملفات md بصيغة التصدير = مشروع مُصدَّر كـ md (مثل «تصدير كـ md»)
            boolean mdOnly = !rels.isEmpty();
            for (String r : rels) if (!r.toLowerCase(java.util.Locale.US).endsWith(".md")) { mdOnly = false; break; }
            if (mdOnly) {
                int got = 0;
                for (String r : rels) {
                    File f = new File(stage, r);
                    if (f.length() > 64L * 1024 * 1024) continue;
                    String t = new String(Compat.readAllBytes(f), StandardCharsets.UTF_8);
                    if (t.contains("FILE:")) got += ghAddMd(t, inDir, inc, notes, name + "/" + r);
                }
                if (got > 0) return;
            }
            for (String r : rels) {
                File to = new File(inDir, r);
                File par = to.getParentFile();
                if (par != null) par.mkdirs();
                try {
                    Compat.move(new File(stage, r), to);
                } catch (Throwable e) {
                    copyOne(new File(stage, r), to);
                }
                inc.put(r, to);
            }
            notes.append(isZip ? "\uD83D\uDCE6 " : "\uD83D\uDDDC ").append(name).append(": ").append(count).append(" ملف\n");
            return;
        }

        // ملف عادي: إن كان نصًّا بصيغة md للمشروع نفككه، وإلا يُرفع كما هو بالاسم نفسه
        if (src.length() <= 16L * 1024 * 1024) {
            byte[] data = Compat.readAllBytes(src);
            if (looksText(data)) {
                String t = new String(data, StandardCharsets.UTF_8);
                if (t.contains("FILE:") && ghAddMd(t, inDir, inc, notes, name) > 0) return;
            }
        }
        File to = new File(inDir, name);
        copyOne(src, to);
        inc.put(name, to);
        notes.append("\uD83D\uDCC4 ").append(name).append("\n");
    }

    // إن كانت كل الملفات داخل مجلد غلاف واحد (مثل MyProject/app/...) لا وجود له في المستودع: نزيله.
    private java.util.Map<String, File> ghStripWrapper(java.util.Map<String, File> inc,
                                                       java.util.HashMap<String, java.util.ArrayList<String>> sfx,
                                                       StringBuilder notes) {
        java.util.Map<String, File> cur = inc;
        for (int round = 0; round < 3; round++) {
            String s = null;
            boolean ok = !cur.isEmpty();
            for (String k : cur.keySet()) {
                int sl = k.indexOf('/');
                if (sl <= 0) { ok = false; break; }
                String seg = k.substring(0, sl);
                if (s == null) s = seg;
                else if (!s.equals(seg)) { ok = false; break; }
            }
            if (!ok || s == null) break;
            int mNow = 0, mStrip = 0;
            boolean markerStrip = false;
            for (String k : cur.keySet()) {
                String st = k.substring(s.length() + 1);
                if (sfx.containsKey(k)) mNow++;
                if (sfx.containsKey(st)) mStrip++;
                if (ghIsGradleMarker(st)) markerStrip = true;
            }
            boolean strip = mStrip > mNow || (mStrip == 0 && mNow == 0 && markerStrip);
            if (!strip) break;
            java.util.LinkedHashMap<String, File> nx = new java.util.LinkedHashMap<>();
            for (java.util.Map.Entry<String, File> en : cur.entrySet()) nx.put(en.getKey().substring(s.length() + 1), en.getValue());
            notes.append("ℹ أُزيل مجلد الغلاف «").append(s).append("/» من مسارات الملفات\n");
            cur = nx;
        }
        return cur;
    }

    private String ghDeltaTask(final java.util.List<Uri> uris) {
        final String full = ghUpFull, br = ghUpBranch;
        final String baseDir = ghUpDir == null ? "" : ghUpDir;
        boolean mirrorReq = ghDeltaMirror;
        if (full == null || br == null) return "لا توجد وجهة رفع محددة.";
        File tmp = new File(getCacheDir(), "gh_delta_" + System.currentTimeMillis());
        tmp.mkdirs();
        try {
            // 1) حالة الفرع على GitHub
            progress("يقرأ حالة الفرع على GitHub ...");
            String parent = new JSONObject(ghGet("/repos/" + full + "/git/ref/heads/" + ghEncPath(br))).getJSONObject("object").getString("sha");
            String baseTree = new JSONObject(ghGet("/repos/" + full + "/git/commits/" + parent)).getJSONObject("tree").getString("sha");
            JSONObject rt = new JSONObject(ghGet("/repos/" + full + "/git/trees/" + baseTree + "?recursive=1"));
            final boolean truncated = rt.optBoolean("truncated", false);
            java.util.HashMap<String, String> remote = new java.util.HashMap<>();
            java.util.HashMap<String, String> rmode = new java.util.HashMap<>();
            org.json.JSONArray rtree = rt.getJSONArray("tree");
            boolean remoteHasBuild = false;
            for (int i = 0; i < rtree.length(); i++) {
                JSONObject e = rtree.getJSONObject(i);
                if (!"blob".equals(e.optString("type"))) continue;
                String p = e.getString("path");
                remote.put(p, e.getString("sha"));
                rmode.put(p, e.optString("mode", "100644"));
                if (p.startsWith("build/") || p.contains("/build/")) remoteHasBuild = true;
            }
            java.util.HashMap<String, java.util.ArrayList<String>> sfx = new java.util.HashMap<>();
            for (String p : remote.keySet()) {
                ghAddSfx(sfx, p, p);
                int i = -1;
                while ((i = p.indexOf('/', i + 1)) >= 0) ghAddSfx(sfx, p.substring(i + 1), p);
            }

            // 2) اقرأ كل ما رفعه المستخدم (ملفات/zip/tar.gz/md) إلى مجلد مؤقت
            File inDir = new File(tmp, "in");
            inDir.mkdirs();
            java.util.LinkedHashMap<String, File> inc0 = new java.util.LinkedHashMap<>();
            StringBuilder notes = new StringBuilder();
            int idx = 0;
            for (Uri u : uris) {
                progress("يقرأ الملف المرفوع " + (idx + 1) + "/" + uris.size() + " ...");
                try {
                    ghDeltaIngest(u, tmp, inDir, inc0, notes, !remoteHasBuild, idx);
                } catch (Throwable e) {
                    notes.append("✘ تعذّرت قراءة ملف: ").append(e.getMessage()).append("\n");
                }
                idx++;
            }
            if (inc0.isEmpty()) return "لا توجد ملفات صالحة للرفع.\n" + notes;
            java.util.Map<String, File> inc = ghStripWrapper(inc0, sfx, notes);

            // 3) طابق كل ملف بمساره الصحيح داخل المستودع (مسار كامل أو جزء منه أو اسم الملف فقط)
            int bareUnmatched = 0;
            for (String k : inc.keySet()) if (k.indexOf('/') < 0 && !remote.containsKey(k) && !sfx.containsKey(k)) bareUnmatched++;
            final boolean askSimilar = bareUnmatched <= 10;
            java.util.LinkedHashMap<String, File> targets = new java.util.LinkedHashMap<>();
            java.util.List<String> mapped = new ArrayList<>();
            for (java.util.Map.Entry<String, File> en : inc.entrySet()) {
                final String k = en.getKey();
                File f = en.getValue();
                String target = null;
                final String newPath = (k.indexOf('/') < 0 && !baseDir.isEmpty()) ? baseDir + "/" + k : k;
                if (remote.containsKey(k)) {
                    target = k;
                } else {
                    java.util.ArrayList<String> cs = sfx.get(k);
                    if (cs != null && cs.size() == 1) {
                        target = cs.get(0);
                    } else if (cs != null && cs.size() > 1) {
                        java.util.List<String> labels = new ArrayList<>(cs);
                        java.util.Collections.sort(labels, (a, b) -> a.length() != b.length() ? a.length() - b.length() : a.compareTo(b));
                        int nCand = labels.size();
                        labels.add("➕ ملف جديد: " + newPath);
                        progress("⏸ بانتظار اختيارك في النافذة («" + k + "» موجود في أكثر من مكان) ...");
                        int pick = ghAskChoice("«" + k + "» موجود في أكثر من مكان — أين تضعه؟", labels);
                        if (pick < 0) return "↩ أُلغي الرفع بطلبك، ولم يُرفع أي شيء.";
                        if (pick < nCand) target = labels.get(pick);
                    } else if (k.indexOf('/') < 0 && askSimilar) {
                        int dot = k.lastIndexOf('.');
                        String stem = (dot > 0 ? k.substring(0, dot) : k).toLowerCase(java.util.Locale.ROOT);
                        String ext = (dot > 0 ? k.substring(dot) : "").toLowerCase(java.util.Locale.ROOT);
                        final java.util.HashMap<String, Integer> scm = new java.util.HashMap<>();
                        java.util.List<String> cands = new ArrayList<>();
                        for (String rp : remote.keySet()) {
                            if (inc.containsKey(rp)) continue;
                            String cn = rp.substring(rp.lastIndexOf('/') + 1);
                            int cd = cn.lastIndexOf('.');
                            String cstem = (cd > 0 ? cn.substring(0, cd) : cn).toLowerCase(java.util.Locale.ROOT);
                            String cext = (cd > 0 ? cn.substring(cd) : "").toLowerCase(java.util.Locale.ROOT);
                            if (!cext.equals(ext)) continue;
                            int sc = fbNameSimilarity(stem, cstem);
                            if (sc < 0) continue;
                            scm.put(rp, sc);
                            cands.add(rp);
                        }
                        if (!cands.isEmpty()) {
                            java.util.Collections.sort(cands, (a, b) -> {
                                int d = scm.get(a) - scm.get(b);
                                return d != 0 ? d : a.compareTo(b);
                            });
                            while (cands.size() > 8) cands.remove(cands.size() - 1);
                            progress("⏸ بانتظار اختيارك في النافذة (اسم «" + k + "» يشبه ملفًا في المستودع) ...");
                            int pick = fbAskDup(k, cands);
                            if (pick == -2) return "↩ أُلغي الرفع بطلبك، ولم يُرفع أي شيء.";
                            if (pick == -1) return "أُلغي الرفع: لم تختر خلال 30 دقيقة، ولم يُرفع أي شيء.";
                            if (pick >= 0 && pick < cands.size()) target = cands.get(pick);
                        }
                    }
                }
                if (target == null) target = newPath;
                if (!target.equals(k)) mapped.add("↻ " + k + " → " + target);
                targets.put(target, f);
            }

            boolean bigNow = false;
            for (File bf : targets.values()) if (bf.length() > ghMaxFile() && bf.length() <= GH_ASSET_MAX) { bigNow = true; break; }
            ghWfPlan(remote, bigNow);
            // 4) قارن بالمستودع: جديد / معدّل / مطابق
            java.util.List<GhDelta> chg = new ArrayList<>();
            java.util.List<String> added = new ArrayList<>(), changed = new ArrayList<>(), skipped = new ArrayList<>();
            java.util.LinkedHashMap<String, File> bigMap = new java.util.LinkedHashMap<>();
            java.util.HashSet<String> present = new java.util.HashSet<>(targets.keySet());
            int same = 0;
            int ti = 0;
            for (java.util.Map.Entry<String, File> en : targets.entrySet()) {
                String path = en.getKey();
                File f = en.getValue();
                if ((++ti % 25) == 0) progress("يقارن الملفات " + ti + "/" + targets.size() + " ...");
                String low = path.toLowerCase(java.util.Locale.US);
                if (path.equals("local.properties") || low.endsWith(".keystore") || low.endsWith(".jks")) {
                    skipped.add(path);
                    continue;
                }
                if (f.length() > ghMaxFile()) {
                    if (!ghLargeMode().equals("skip") && f.length() <= GH_ASSET_MAX) bigMap.put(path, f);
                    else skipped.add(path);
                    continue;
                }
                String lsha;
                if (f.length() > GH_MEM_FILE) lsha = ghBlobShaFile(f);
                else lsha = ghBlobSha(ghFixWf(path, Compat.readAllBytes(f)));
                String rsha = remote.get(path);
                if (lsha.equals(rsha)) { same++; continue; }
                GhDelta g = new GhDelta();
                g.path = path;
                g.f = f;
                g.isNew = rsha == null;
                String m = rmode.get(path);
                g.mode = m != null ? m : ((path.equals("gradlew") || path.endsWith("/gradlew") || path.endsWith(".sh")) ? "100755" : "100644");
                chg.add(g);
                (g.isNew ? added : changed).add(path);
            }

            // 5) المطابقة الكاملة (اختيارية): حذف ما ليس في النسخة المرفوعة، داخل نطاق المشروع فقط
            java.util.List<String> dels = new ArrayList<>();
            String mirrorNote = "";
            if (mirrorReq) {
                if (truncated) {
                    mirrorNote = "⚠ شجرة المستودع كبيرة (مبتورة من GitHub) فلم يُحذف شيء؛ رُفعت التعديلات فقط.\n";
                } else if (targets.size() < 3) {
                    mirrorNote = "⚠ المطابقة الكاملة تحتاج نسخة كاملة من المشروع؛ رُفعت التعديلات فقط ولم يُحذف شيء.\n";
                } else {
                    String scope = "";
                    String first = null;
                    boolean allSame = true;
                    for (String p : targets.keySet()) {
                        int sl = p.indexOf('/');
                        if (sl <= 0) { allSame = false; break; }
                        String seg = p.substring(0, sl);
                        if (first == null) first = seg;
                        else if (!first.equals(seg)) { allSame = false; break; }
                    }
                    if (allSame && first != null) scope = first + "/";
                    int scoped = 0;
                    for (String rp : remote.keySet()) {
                        if (!rp.startsWith(scope)) continue;
                        scoped++;
                        if (present.contains(rp)) continue;
                        String rl = rp.toLowerCase(java.util.Locale.US);
                        if (rp.startsWith(".github/") || rp.equals(".gitignore") || rp.equals(".gitattributes") || rp.equals("large-files.json")
                                || rl.startsWith("license") || rl.startsWith("readme")
                                || rl.equals("local.properties") || rl.endsWith(".keystore") || rl.endsWith(".jks")) continue;
                        dels.add(rp);
                    }
                    java.util.Collections.sort(dels);
                    if (scoped > 0 && dels.size() * 2 > scoped)
                        mirrorNote = "⚠ تحذير: سيُحذف أكثر من نصف ملفات المستودع (" + dels.size() + " من " + scoped + ") — تأكد أن هذه نسخة كاملة.\n";
                }
            }

            if (chg.isEmpty() && dels.isEmpty() && bigMap.isEmpty()) {
                return "لا توجد تغييرات للرفع: كل الملفات (" + same + ") مطابقة لـ GitHub."
                        + (skipped.isEmpty() ? "" : "\nمتجاهل (مفاتيح/محلي/كبير): " + skipped.size())
                        + (notes.length() > 0 ? "\n\n" + notes : "");
            }

            // 6) ملخص + تأكيد + رسالة الإيداع
            StringBuilder sum = new StringBuilder();
            sum.append("الوجهة: ").append(full).append(" (").append(br).append(")\n");
            sum.append("جديد: ").append(added.size()).append(" | معدّل: ").append(changed.size());
            if (mirrorReq) sum.append(" | محذوف: ").append(dels.size());
            sum.append(" | بلا تغيير: ").append(same);
            if (!skipped.isEmpty()) sum.append(" | متجاهل: ").append(skipped.size());
            sum.append("\n");
            if (!mirrorNote.isEmpty()) sum.append("\n").append(mirrorNote);
            sum.append("\n");
            ghListSome(sum, "➕ ", added, 25);
            ghListSome(sum, "✏️ ", changed, 25);
            ghListSome(sum, "\uD83D\uDDD1 ", dels, 25);
            if (!bigMap.isEmpty()) sum.append("📦 ملفات كبيرة (").append(bigMap.size()).append("): تُعالج عبر ").append(ghLargeModeShort()).append(" بعد التأكيد\n");
            for (int i = 0; i < mapped.size() && i < 10; i++) sum.append(mapped.get(i)).append("\n");
            if (truncated) sum.append("\n⚠ شجرة المستودع مبتورة: قد تظهر ملفات موجودة كأنها جديدة.\n");
            if (notes.length() > 0) sum.append("\n").append(notes);
            String sugg;
            if (chg.size() + dels.size() <= 3) {
                StringBuilder nm = new StringBuilder();
                for (GhDelta g : chg) nm.append(nm.length() > 0 ? ", " : "").append(g.path.substring(g.path.lastIndexOf('/') + 1));
                for (String d : dels) nm.append(nm.length() > 0 ? ", " : "").append("-").append(d.substring(d.lastIndexOf('/') + 1));
                sugg = "Update " + nm + " via L2SBuilder";
            } else {
                sugg = "Update " + (chg.size() + dels.size()) + " files via L2SBuilder";
            }
            progress("⏸ بانتظار تأكيدك في النافذة (" + chg.size() + " ملف للرفع) ...");
            String msg = ghDeltaConfirm("رفع التعديلات إلى GitHub", sum.toString(), sugg, mirrorReq && !dels.isEmpty());
            if (msg == null) return "↩ أُلغي الرفع بطلبك، ولم يُرفع أي شيء.";

            // 7) أنشئ الإيداع: الملفات النصية مضمّنة، والثنائية عبر blobs، والحذف بـ sha=null
            GhLarge lg = ghLargeProcess(full, br, bigMap, remote);
            org.json.JSONArray entries = new org.json.JSONArray();
            int done = 0;
            for (GhDelta g : chg) {
                done++;
                if (g.f.length() > GH_MEM_FILE) {
                    progress("يرفع ملفًا كبيرًا (" + done + "/" + chg.size() + "): " + g.path + " (" + (g.f.length() >> 20) + " م.ب)");
                    JSONObject teb = ghTreeEntry(g.path, g.mode);
                    teb.put("sha", ghUploadBlobStreamRetry(full, g.f));
                    entries.put(teb);
                    continue;
                }
                byte[] data = ghFixWf(g.path, Compat.readAllBytes(g.f));
                JSONObject te = ghTreeEntry(g.path, g.mode);
                String asText = null;
                if (looksText(data)) {
                    String t = new String(data, StandardCharsets.UTF_8);
                    if (java.util.Arrays.equals(t.getBytes(StandardCharsets.UTF_8), data)) asText = t;
                }
                if (asText != null) {
                    te.put("content", asText);
                } else {
                    progress("يرفع ملفًا ثنائيًا (" + done + "/" + chg.size() + "): " + g.path);
                    te.put("sha", ghCreateBlob(full, data));
                }
                entries.put(te);
            }
            for (String d : dels) {
                JSONObject te = ghTreeEntry(d, "100644");
                te.put("sha", JSONObject.NULL);
                entries.put(te);
            }
            ghMergeLarge(entries, lg);
            ghPatchRemoteWorkflows(full, br, entries, remote);
            if (entries.length() == 0) return "لا توجد تغييرات للرفع: كل الملفات (" + same + ") مطابقة لـ GitHub." + lg.summary();
            progress("ينشئ الإيداع (جديد " + added.size() + "، معدّل " + changed.size() + (dels.isEmpty() ? "" : "، محذوف " + dels.size()) + ") ...");
            JSONObject tb = new JSONObject();
            tb.put("base_tree", baseTree);
            tb.put("tree", entries);
            String newTree = new JSONObject(ghHttp("POST", "/repos/" + full + "/git/trees", tb.toString(), null)).getString("sha");
            JSONObject cb = new JSONObject();
            cb.put("message", msg);
            cb.put("tree", newTree);
            cb.put("parents", new org.json.JSONArray().put(parent));
            String newCommit = new JSONObject(ghHttp("POST", "/repos/" + full + "/git/commits", cb.toString(), null)).getString("sha");
            ghHttp("PATCH", "/repos/" + full + "/git/refs/heads/" + ghEncPath(br), jsonOf("sha", newCommit), null);
            return "تم رفع التعديلات إلى " + full + " (" + br + ") ✔\nجديد: " + added.size() + " | معدّل: " + changed.size()
                    + (dels.isEmpty() ? "" : " | محذوف: " + dels.size()) + " | بلا تغيير: " + same
                    + (skipped.isEmpty() ? "" : " | متجاهل (مفاتيح/محلي/كبير): " + skipped.size())
                    + "\nالإيداع: " + newCommit.substring(0, 7)
                    + (mapped.isEmpty() ? "" : "\n" + android.text.TextUtils.join("\n", mapped))
                    + lg.summary();
        } catch (Throwable e) {
            String m = String.valueOf(e.getMessage());
            if (m.startsWith("409") || m.contains("empty")) m += "\nإن كان المستودع فارغًا: أنشئ فيه أول ملف من «تصفح الملفات» ثم أعد الرفع.";
            return "فشل رفع التعديلات: " + m;
        } finally {
            deleteRec(tmp);
        }
    }

    // ---------- الفروع ----------
    private void ghBranches(final String full, final String cur) {
        final GhScreen s = ghOpen("ghBranches:" + full, "الفروع", () -> ghBranches(full, cur));
        this.<org.json.JSONArray>ghLoad(s, () -> ghBranches(full, cur), () -> new org.json.JSONArray(ghGet("/repos/" + full + "/branches?per_page=100")), a -> {
            for (int i = 0; i < a.length(); i++) {
                final JSONObject b = a.getJSONObject(i);
                final String name = b.optString("name");
                final String sha = b.getJSONObject("commit").optString("sha");
                addSelectCard(s.box, name.equals(cur), name, (b.optBoolean("protected") ? "\uD83D\uDEE1 محمي • " : "") + sha.substring(0, Math.min(7, sha.length())), "#4CAF50", () ->
                        new NavAlertBuilder().setTitle(name).setItems(new CharSequence[]{
                                "التبديل إلى هذا الفرع", "إنشاء فرع جديد منه", "طلب دمج منه إلى فرع آخر", "حذف الفرع"}, (d, w) -> {
                            if (w == 0) { s.dlg.dismiss(); ghRepo(full, name); }
                            else if (w == 1) ghPrompt("اسم الفرع الجديد", "feature-x", "", nn -> {
                                final String nb = nn.replaceAll("[^A-Za-z0-9._/-]", "-");
                                this.<String>ghAsync(() -> ghHttp("POST", "/repos/" + full + "/git/refs", jsonOf("ref", "refs/heads/" + nb, "sha", sha), null), (r, err) -> {
                                    if (err != null) { ghToast("فشل: " + err); return; }
                                    ghToast("تم إنشاء الفرع ✔");
                                    s.dlg.dismiss();
                                    ghRepo(full, nb);
                                });
                            });
                            else if (w == 2) ghNewPull(full, name);
                            else ghConfirm("حذف الفرع " + name + "؟", "لا يمكن التراجع.", () ->
                                    this.<String>ghAsync(() -> ghHttp("DELETE", "/repos/" + full + "/git/refs/heads/" + ghEncPath(name), null, null), (r, err) -> {
                                        if (err != null) { ghToast("فشل: " + err); return; }
                                        ghToast("تم حذف الفرع ✔");
                                        s.dlg.dismiss();
                                        ghBranches(full, cur.equals(name) ? "main" : cur);
                                    }));
                        }).show());
            }
        });
    }

    // ---------- الإيداعات ----------
    // ---------- فلتر الإيداعات ----------
    private String cfKey = "", cfStatus = "", cfAuthor = "", cfText = "", cfSince = "", cfUntil = "", cfPath = "", cfSort = ""; // cfSort: "" الأحدث أولًا، old الأقدم أولًا، fail الفاشلة أولًا، ok الناجحة أولًا

    private void cfReset() { cfStatus = ""; cfAuthor = ""; cfText = ""; cfSince = ""; cfUntil = ""; cfPath = ""; cfSort = ""; }

    private boolean cfActive() {
        return !(cfStatus.isEmpty() && cfAuthor.isEmpty() && cfText.isEmpty() && cfSince.isEmpty() && cfUntil.isEmpty() && cfPath.isEmpty() && cfSort.isEmpty());
    }

    private static String cfStatusAr(String st) {
        switch (st) {
            case "ok": return "ناجحة ✅";
            case "fail": return "فاشلة ❌";
            case "run": return "جارية ⏳";
            case "skip": return "ملغاة/متخطّاة ⏹";
            case "none": return "بدون بناء";
            default: return "الكل";
        }
    }

    private String cfSummary() {
        if (!cfActive()) return "بدون فلتر — اضغط لتصفية الإيداعات";
        java.util.ArrayList<String> p = new java.util.ArrayList<>();
        if (!cfStatus.isEmpty()) p.add("الحالة: " + cfStatusAr(cfStatus));
        if (!cfAuthor.isEmpty()) p.add("الكاتب: " + cfAuthor);
        if (!cfText.isEmpty()) p.add("نص: " + cfText);
        if (!cfSince.isEmpty()) p.add("من " + cfSince);
        if (!cfUntil.isEmpty()) p.add("إلى " + cfUntil);
        if (!cfPath.isEmpty()) p.add("مسار: " + cfPath);
        if (!cfSort.isEmpty()) p.add("ترتيب: " + cfSortAr(cfSort));
        return android.text.TextUtils.join(" • ", p);
    }

    private static String cfDaysAgo(int d) {
        java.util.Calendar c = java.util.Calendar.getInstance();
        c.add(java.util.Calendar.DAY_OF_YEAR, -d);
        return new java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US).format(c.getTime());
    }

    private void cfApply(final GhScreen s, final String full, final String br) {
        s.dlg.dismiss();
        ghCommits(full, br, 1);
    }

    private void cfDateDialog(final GhScreen s, final String full, final String br, final boolean since) {
        final String cur = since ? cfSince : cfUntil;
        final String[] items = {"اليوم", "آخر 7 أيام", "آخر 30 يومًا", "تاريخ محدد (YYYY-MM-DD)", "إزالة"};
        new NavAlertBuilder().setTitle(since ? "من تاريخ" : "إلى تاريخ").setItems(items, (d, w) -> {
            if (w == 4) { if (since) cfSince = ""; else cfUntil = ""; cfApply(s, full, br); return; }
            if (w == 3) {
                ghPrompt(since ? "من تاريخ" : "إلى تاريخ", "YYYY-MM-DD (فارغ للإزالة)", cur, v -> {
                    String t = v == null ? "" : v.trim();
                    if (!t.isEmpty() && !t.matches("\\d{4}-\\d{2}-\\d{2}")) { ghToast("الصيغة: 2026-10-09"); return; }
                    if (since) cfSince = t; else cfUntil = t;
                    cfApply(s, full, br);
                });
                return;
            }
            String dv = w == 0 ? cfDaysAgo(0) : w == 1 ? cfDaysAgo(7) : cfDaysAgo(30);
            if (since) cfSince = dv; else cfUntil = dv;
            cfApply(s, full, br);
        }).show();
    }

    private static String cfSortAr(String so) {
        switch (so) {
            case "old": return "الأقدم أولًا";
            case "fail": return "الفاشلة أولًا";
            case "ok": return "الناجحة أولًا";
            default: return "الأحدث أولًا";
        }
    }

    // ترتيب الحالة عند الفرز: الأصغر يظهر أولًا
    private static int cfRank(String st, String mode) {
        String want = mode.equals("fail") ? "fail" : "ok";
        if (want.equals(st)) return 0;
        if (st == null) return 3;
        return 1;
    }

    // يملأ خريطة sha -> حالة البناء من سجل عمليات Actions للفرع
    private void ghFillCi(String full, String br, int fromPage, int pages, java.util.HashMap<String, String> ci) {
        try {
            for (int pg = fromPage; pg < fromPage + pages; pg++) {
                org.json.JSONArray rs = new JSONObject(ghGet("/repos/" + full + "/actions/runs?branch=" + ghEnc(br) + "&per_page=100&page=" + pg)).optJSONArray("workflow_runs");
                if (rs == null || rs.length() == 0) break;
                for (int k = 0; k < rs.length(); k++) {
                    JSONObject r = rs.getJSONObject(k);
                    String hs = r.optString("head_sha");
                    String stt = r.optString("status");
                    String con = r.optString("conclusion", "");
                    String v;
                    if (!"completed".equals(stt)) v = "run";
                    else if ("success".equals(con)) v = "ok";
                    else if ("cancelled".equals(con) || "skipped".equals(con) || "neutral".equals(con)) v = "skip";
                    else v = "fail";
                    String prev = ci.get(hs);
                    if (prev == null || "fail".equals(v) || ("run".equals(v) && !"fail".equals(prev)) || ("ok".equals(v) && "skip".equals(prev))) ci.put(hs, v);
                }
                if (rs.length() < 100) break;
            }
        } catch (Exception ignored) {}
    }

    private TextView cfChip(String label, boolean on, final Runnable action) {
        TextView t = new TextView(this);
        t.setText(label);
        t.setTextSize(13);
        t.setGravity(android.view.Gravity.CENTER);
        t.setTextColor(on ? 0xFFFFFFFF : themeTextPrimary());
        android.graphics.drawable.GradientDrawable g = new android.graphics.drawable.GradientDrawable();
        g.setCornerRadius(dp(18));
        g.setColor(on ? 0xFF1E88E5 : (isDark() ? 0xFF2C2C2C : 0xFFE0E0E0));
        t.setBackground(g);
        t.setPadding(dp(14), dp(8), dp(14), dp(8));
        t.setOnClickListener(v -> action.run());
        return t;
    }

    private void cfRow(LinearLayout box, TextView... chips) {
        android.widget.HorizontalScrollView hs = new android.widget.HorizontalScrollView(this);
        hs.setHorizontalScrollBarEnabled(false);
        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        for (TextView c : chips) {
            LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(-2, -2);
            lp.setMargins(dp(4), dp(4), dp(4), dp(4));
            row.addView(c, lp);
        }
        hs.addView(row);
        box.addView(hs, new LinearLayout.LayoutParams(-1, -2));
    }

    // أزرار سريعة: الحالة + الترتيب
    private void cfQuickBar(final GhScreen s, final String full, final String br) {
        final String[] st = {"", "ok", "fail", "run"};
        final String[] stL = {"الكل", "✅ ناجح", "❌ فاشل", "⏳ جارٍ"};
        TextView[] a = new TextView[st.length];
        for (int i = 0; i < st.length; i++) {
            final String v = st[i];
            a[i] = cfChip(stL[i], cfStatus.equals(v), () -> { cfStatus = v; cfApply(s, full, br); });
        }
        cfRow(s.box, a);
        final String[] so = {"", "old", "fail", "ok"};
        final String[] soL = {"⬇ الأحدث أولًا", "⬆ الأقدم أولًا", "❌ الفاشلة أولًا", "✅ الناجحة أولًا"};
        TextView[] b = new TextView[so.length];
        for (int i = 0; i < so.length; i++) {
            final String v = so[i];
            b[i] = cfChip(soL[i], cfSort.equals(v), () -> { cfSort = v; cfApply(s, full, br); });
        }
        cfRow(s.box, b);
    }

    private void cfDialog(final GhScreen s, final String full, final String br) {
        final String[] items = {
                "الحالة: " + cfStatusAr(cfStatus),
                "الترتيب: " + cfSortAr(cfSort),
                "الكاتب: " + (cfAuthor.isEmpty() ? "الكل" : cfAuthor),
                "بحث في الرسالة: " + (cfText.isEmpty() ? "—" : cfText),
                "من تاريخ: " + (cfSince.isEmpty() ? "—" : cfSince),
                "إلى تاريخ: " + (cfUntil.isEmpty() ? "—" : cfUntil),
                "مسار ملف/مجلد: " + (cfPath.isEmpty() ? "—" : cfPath),
                "مسح كل الفلاتر"};
        new NavAlertBuilder().setTitle("فلتر الإيداعات").setItems(items, (d, w) -> {
            switch (w) {
                case 0: {
                    final String[] ids = {"", "ok", "fail", "run", "skip", "none"};
                    String[] names = new String[ids.length];
                    for (int i = 0; i < ids.length; i++) names[i] = cfStatusAr(ids[i]);
                    new NavAlertBuilder().setTitle("حالة البناء").setItems(names, (d2, w2) -> { cfStatus = ids[w2]; cfApply(s, full, br); }).show();
                    break;
                }
                case 1: {
                    final String[] ids = {"", "old", "fail", "ok"};
                    String[] names = new String[ids.length];
                    for (int i = 0; i < ids.length; i++) names[i] = cfSortAr(ids[i]);
                    new NavAlertBuilder().setTitle("ترتيب الإيداعات").setItems(names, (d2, w2) -> { cfSort = ids[w2]; cfApply(s, full, br); }).show();
                    break;
                }
                case 2:
                    ghPrompt("الكاتب", "اسم أو معرّف (فارغ للكل)", cfAuthor, v -> { cfAuthor = v == null ? "" : v.trim(); cfApply(s, full, br); });
                    break;
                case 3:
                    ghPrompt("بحث في رسالة الإيداع", "نص (فارغ للإلغاء)", cfText, v -> { cfText = v == null ? "" : v.trim(); cfApply(s, full, br); });
                    break;
                case 4: cfDateDialog(s, full, br, true); break;
                case 5: cfDateDialog(s, full, br, false); break;
                case 6:
                    ghPrompt("مسار ملف أو مجلد", "مثال: app/src/main (فارغ للإلغاء)", cfPath, v -> { cfPath = v == null ? "" : v.trim(); cfApply(s, full, br); });
                    break;
                default:
                    cfReset();
                    cfApply(s, full, br);
            }
        }).show();
    }

    private void ghCommits(final String full, final String br, final int page) {
        if (!(full + ":" + br).equals(cfKey)) { cfKey = full + ":" + br; cfReset(); }
        final GhScreen s = ghOpen("ghCommits:" + full + ":" + br + ":" + page, "الإيداعات — " + br, () -> ghCommits(full, br, page));
        final java.util.HashMap<String, String> ci = new java.util.HashMap<>(); // sha -> ok / fail / run / skip
        final boolean client = !cfStatus.isEmpty() || !cfAuthor.isEmpty() || !cfText.isEmpty() || !cfSort.isEmpty();
        final int[] meta = {0, 0}; // [إجمالي المطابق، هل توجد صفحة تالية]
        this.<org.json.JSONArray>ghLoad(s, () -> ghCommits(full, br, page),
                () -> {
                    String q = "";
                    if (!cfSince.isEmpty()) q += "&since=" + ghEnc(cfSince + "T00:00:00Z");
                    if (!cfUntil.isEmpty()) q += "&until=" + ghEnc(cfUntil + "T23:59:59Z");
                    if (!cfPath.isEmpty()) q += "&path=" + ghEncPath(cfPath);
                    if (!client) {
                        org.json.JSONArray cs = new org.json.JSONArray(ghGet("/repos/" + full + "/commits?sha=" + ghEnc(br) + "&per_page=30&page=" + page + q));
                        ghFillCi(full, br, page, 1, ci);
                        meta[0] = cs.length();
                        meta[1] = cs.length() >= 30 ? 1 : 0;
                        return cs;
                    }
                    // وضع الفلترة/الترتيب العام: تحميل حتى 500 إيداع ثم التصفية والترتيب ثم التقسيم لصفحات من 30
                    java.util.ArrayList<JSONObject> all = new java.util.ArrayList<>();
                    for (int pg = 1; pg <= 5; pg++) {
                        org.json.JSONArray part = new org.json.JSONArray(ghGet("/repos/" + full + "/commits?sha=" + ghEnc(br) + "&per_page=100&page=" + pg + q));
                        for (int k = 0; k < part.length(); k++) all.add(part.getJSONObject(k));
                        if (part.length() < 100) break;
                    }
                    ghFillCi(full, br, 1, 5, ci);
                    java.util.ArrayList<JSONObject> res = new java.util.ArrayList<>();
                    for (JSONObject c : all) {
                        String sh = c.optString("sha");
                        String cs0 = ci.get(sh);
                        if (!cfStatus.isEmpty() && !(cfStatus.equals("none") ? cs0 == null : cfStatus.equals(cs0))) continue;
                        JSONObject cmj = c.getJSONObject("commit");
                        if (!cfAuthor.isEmpty()) {
                            JSONObject au0 = cmj.optJSONObject("author");
                            JSONObject gu = c.optJSONObject("author");
                            String hay = ((au0 == null ? "" : au0.optString("name")) + " " + (gu == null ? "" : gu.optString("login"))).toLowerCase(java.util.Locale.ROOT);
                            if (!hay.contains(cfAuthor.toLowerCase(java.util.Locale.ROOT))) continue;
                        }
                        if (!cfText.isEmpty() && !cmj.optString("message", "").toLowerCase(java.util.Locale.ROOT).contains(cfText.toLowerCase(java.util.Locale.ROOT))) continue;
                        res.add(c);
                    }
                    if (cfSort.equals("old")) java.util.Collections.reverse(res);
                    else if (cfSort.equals("fail") || cfSort.equals("ok")) {
                        final String first = cfSort;
                        java.util.Collections.sort(res, (x, y) -> Integer.compare(cfRank(ci.get(x.optString("sha")), first), cfRank(ci.get(y.optString("sha")), first)));
                    }
                    meta[0] = res.size();
                    int from = (page - 1) * 30, to = Math.min(res.size(), from + 30);
                    meta[1] = to < res.size() ? 1 : 0;
                    org.json.JSONArray out = new org.json.JSONArray();
                    for (int k = from; k < to; k++) out.put(res.get(k));
                    return out;
                }, a -> {
            addMenuCard(s.box, "\uD83D\uDD04", "تحديث", "إعادة تحميل الإيداعات وحالة البناء", "#2196F3", () -> { s.dlg.dismiss(); ghCommits(full, br, page); });
            cfQuickBar(s, full, br);
            addMenuCard(s.box, "\uD83D\uDD0D", "فلتر متقدّم", cfSummary(), "#009688", () -> cfDialog(s, full, br));
            int shown = 0;
            for (int i = 0; i < a.length(); i++) {
                JSONObject c = a.getJSONObject(i);
                final String sha = c.optString("sha");
                {
                    String cs0 = ci.get(sha);
                    if (!cfStatus.isEmpty() && !(cfStatus.equals("none") ? cs0 == null : cfStatus.equals(cs0))) continue;
                    if (!cfAuthor.isEmpty()) {
                        JSONObject au0 = c.getJSONObject("commit").optJSONObject("author");
                        JSONObject gu = c.optJSONObject("author");
                        String hay = ((au0 == null ? "" : au0.optString("name")) + " " + (gu == null ? "" : gu.optString("login"))).toLowerCase(java.util.Locale.ROOT);
                        if (!hay.contains(cfAuthor.toLowerCase(java.util.Locale.ROOT))) continue;
                    }
                    if (!cfText.isEmpty() && !c.getJSONObject("commit").optString("message", "").toLowerCase(java.util.Locale.ROOT).contains(cfText.toLowerCase(java.util.Locale.ROOT))) continue;
                }
                shown++;
                JSONObject cm = c.getJSONObject("commit");
                String msg = cm.optString("message", "");
                String first = msg.contains("\n") ? msg.substring(0, msg.indexOf('\n')) : msg;
                JSONObject au = cm.optJSONObject("author");
                String who = au == null ? "" : au.optString("name") + " • " + ghDate(au.optString("date"));
                String cst = ci.get(sha);
                String ico = "\uD83D\uDD38", stTxt = "", col = "#3F51B5";
                if ("ok".equals(cst)) { ico = "\u2705"; stTxt = "✔ نجح البناء • "; col = "#4CAF50"; }
                else if ("fail".equals(cst)) { ico = "\u274C"; stTxt = "✘ فشل البناء • "; col = "#F44336"; }
                else if ("run".equals(cst)) { ico = "\u23F3"; stTxt = "⏳ البناء جارٍ • "; col = "#FF9800"; }
                else if ("skip".equals(cst)) { ico = "\u23F9"; stTxt = "أُلغي/تُخطّي البناء • "; col = "#9E9E9E"; }
                addMenuCard(s.box, ico, first, stTxt + who + " • " + sha.substring(0, Math.min(7, sha.length())), col, () -> { s.dlg.dismiss(); ghCommitDetail(full, br, sha, page); });
            }
            if (a.length() == 0) ghNote(s.box, "لا مزيد من الإيداعات.");
            else if (shown == 0) ghNote(s.box, "لا توجد إيداعات تطابق الفلتر.");
            if (client) ghNote(s.box, "المطابق: " + meta[0] + " إيداع (من آخر 500 إيداع كحد أقصى)");
            if (page > 1) addMenuCard(s.box, "\u2B05", "الصفحة السابقة", "#9E9E9E", () -> { s.dlg.dismiss(); ghCommits(full, br, page - 1); });
            if (meta[1] == 1) addMenuCard(s.box, "\u27A1", "الصفحة التالية", "#9E9E9E", () -> { s.dlg.dismiss(); ghCommits(full, br, page + 1); });
        });
    }

    private void ghCommitDetail(final String full, final String br, final String sha, final int page) {
        final GhScreen s = ghOpen("ghCommit:" + full + ":" + sha, "إيداع " + sha.substring(0, Math.min(7, sha.length())), () -> ghCommitDetail(full, br, sha, page));
        this.<JSONObject>ghLoad(s, () -> ghCommitDetail(full, br, sha, page), () -> new JSONObject(ghGet("/repos/" + full + "/commits/" + sha)), c -> {
            JSONObject cm = c.getJSONObject("commit");
            ghNote(s.box, cm.optString("message") + "\n\n" + cm.getJSONObject("author").optString("name") + " • " + ghDate(cm.getJSONObject("author").optString("date")));
            JSONObject st = c.optJSONObject("stats");
            if (st != null) ghNote(s.box, "+" + st.optInt("additions") + "  −" + st.optInt("deletions"));
            org.json.JSONArray fs = c.optJSONArray("files");
            if (fs != null) {
                addMenuSectionHeader(s.box, "الملفات (" + fs.length() + ")");
                for (int i = 0; i < fs.length(); i++) {
                    final JSONObject f = fs.getJSONObject(i);
                    addMenuCard(s.box, "\uD83D\uDCC4", f.optString("filename"), ghFileStatusAr(f.optString("status")) + " • +" + f.optInt("additions") + " −" + f.optInt("deletions"), "#607D8B", () ->
                            ghShowText(f.optString("filename"), f.optString("patch", "(لا يوجد فرق نصي)")));
                }
            }
            addMenuCard(s.box, "\u21A9", "التراجع عن هذا الإيداع", "يعيد الملفات كما كانت قبله (إيداع جديد، لا يضيع شيء)", "#FF9800", () ->
                    ghConfirm("التراجع عن الإيداع؟", "سيُنشأ إيداع جديد يعيد الملفات التي غيّرها هذا الإيداع إلى حالتها السابقة (الملفات المحذوفة ترجع، والمعدّلة ترجع للنسخة القديمة، والمضافة تُحذف).\nالفرع: " + br, () -> {
                        ghToast("جارٍ التراجع ...");
                        this.<String>ghAsync(() -> ghRevertCommit(full, br, sha), (r, err) -> {
                            if (err != null) { ghToast("فشل التراجع: " + err); return; }
                            ghToast(r);
                        });
                    }));
            addMenuCard(s.box, "\uD83D\uDCCB", "نسخ SHA الكامل", "#009688", () -> {
                ClipboardManager cm2 = (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
                if (cm2 != null) cm2.setPrimaryClip(ClipData.newPlainText("sha", sha));
                Toast.makeText(this, "تم النسخ", Toast.LENGTH_SHORT).show();
            });
        });
    }

    // يتراجع عن إيداع: ينشئ إيداعًا جديدًا فوق رأس الفرع يعيد ملفات ذلك الإيداع إلى حالتها قبله.
    private String ghRevertCommit(String full, String br, String sha) throws Exception {
        JSONObject c = new JSONObject(ghGet("/repos/" + full + "/commits/" + sha));
        org.json.JSONArray parents = c.optJSONArray("parents");
        if (parents == null || parents.length() == 0) throw new Exception("هذا أول إيداع في المستودع، لا يمكن التراجع عنه");
        String parentSha = parents.getJSONObject(0).getString("sha");
        org.json.JSONArray fs = c.optJSONArray("files");
        if (fs == null || fs.length() == 0) throw new Exception("لا توجد ملفات في هذا الإيداع");
        if (fs.length() >= 300) throw new Exception("عدد الملفات كبير جدًا للتراجع التلقائي");
        String head = new JSONObject(ghGet("/repos/" + full + "/git/ref/heads/" + ghEncPath(br))).getJSONObject("object").getString("sha");
        String headTree = new JSONObject(ghGet("/repos/" + full + "/git/commits/" + head)).getJSONObject("tree").getString("sha");
        org.json.JSONArray entries = new org.json.JSONArray();
        int restored = 0, removed = 0;
        for (int i = 0; i < fs.length(); i++) {
            JSONObject f = fs.getJSONObject(i);
            String st = f.optString("status");
            String name = f.optString("filename");
            if (st.equals("added")) {
                JSONObject te = ghTreeEntry(name, "100644");
                te.put("sha", JSONObject.NULL);
                entries.put(te);
                removed++;
                continue;
            }
            String oldName = st.equals("renamed") ? f.optString("previous_filename", name) : name;
            if (st.equals("renamed")) {
                JSONObject te = ghTreeEntry(name, "100644");
                te.put("sha", JSONObject.NULL);
                entries.put(te);
            }
            String blob = new JSONObject(ghGet("/repos/" + full + "/contents/" + ghEncPath(oldName) + "?ref=" + ghEnc(parentSha))).getString("sha");
            String mode = (oldName.equals("gradlew") || oldName.endsWith("/gradlew") || oldName.endsWith(".sh")) ? "100755" : "100644";
            JSONObject te = ghTreeEntry(oldName, mode);
            te.put("sha", blob);
            entries.put(te);
            restored++;
        }
        JSONObject tb = new JSONObject();
        tb.put("base_tree", headTree);
        tb.put("tree", entries);
        String newTree = new JSONObject(ghHttp("POST", "/repos/" + full + "/git/trees", tb.toString(), null)).getString("sha");
        String first = c.getJSONObject("commit").optString("message", "");
        if (first.contains("\n")) first = first.substring(0, first.indexOf('\n'));
        JSONObject cb = new JSONObject();
        cb.put("message", "Revert \"" + first + "\" (" + sha.substring(0, 7) + ")");
        cb.put("tree", newTree);
        cb.put("parents", new org.json.JSONArray().put(head));
        String newCommit = new JSONObject(ghHttp("POST", "/repos/" + full + "/git/commits", cb.toString(), null)).getString("sha");
        ghHttp("PATCH", "/repos/" + full + "/git/refs/heads/" + ghEncPath(br), jsonOf("sha", newCommit), null);
        return "تم التراجع ✔ — أُعيد " + restored + " ملف" + (removed > 0 ? "، وحُذف " + removed + " ملف مضاف" : "");
    }

    // ---------- طلبات الدمج (القرارات) ----------
    private void ghPulls(final String full, final String br, final String state) {
        final GhScreen s = ghOpen("ghPulls:" + full + ":" + state, "طلبات الدمج", () -> ghPulls(full, br, state));
        this.<org.json.JSONArray>ghLoad(s, () -> ghPulls(full, br, state),
                () -> new org.json.JSONArray(ghGet("/repos/" + full + "/pulls?state=" + state + "&per_page=50&sort=updated&direction=desc")), a -> {
            final String other = state.equals("open") ? "closed" : "open";
            addMenuCard(s.box, "\uD83D\uDD04", state.equals("open") ? "عرض المغلقة" : "عرض المفتوحة", "#9E9E9E", () -> { s.dlg.dismiss(); ghPulls(full, br, other); });
            addMenuCard(s.box, "\u2795", "طلب دمج جديد", "من الفرع " + br, "#9C27B0", () -> ghNewPull(full, br));
            if (a.length() == 0) ghNote(s.box, "لا توجد طلبات " + (state.equals("open") ? "مفتوحة" : "مغلقة") + ".");
            for (int i = 0; i < a.length(); i++) {
                JSONObject p = a.getJSONObject(i);
                final int n = p.optInt("number");
                String sub = p.getJSONObject("user").optString("login") + ": " + p.getJSONObject("head").optString("ref") + " → "
                        + p.getJSONObject("base").optString("ref") + " • " + ghDate(p.optString("updated_at"))
                        + (p.optBoolean("draft") ? " • مسودة" : "");
                addMenuCard(s.box, p.optString("merged_at", "").isEmpty() || p.isNull("merged_at") ? "\uD83D\uDD00" : "\u2705", "#" + n + " " + p.optString("title"), sub, "#9C27B0", () -> { s.dlg.dismiss(); ghPullDetail(full, n); });
            }
        });
    }

    private void ghNewPull(final String full, final String head) {
        this.<org.json.JSONArray>ghAsync(() -> new org.json.JSONArray(ghGet("/repos/" + full + "/branches?per_page=100")), (a, err) -> {
            if (err != null) { ghToast(err); return; }
            final java.util.ArrayList<String> names = new java.util.ArrayList<>();
            try { for (int i = 0; i < a.length(); i++) { String n = a.getJSONObject(i).optString("name"); if (!n.equals(head)) names.add(n); } } catch (Exception ignored) {}
            if (names.isEmpty()) { ghToast("لا يوجد فرع آخر للدمج إليه."); return; }
            new NavAlertBuilder().setTitle("الدمج من " + head + " إلى:").setItems(names.toArray(new CharSequence[0]), (d, w) -> {
                final String base = names.get(w);
                ghPrompt("عنوان طلب الدمج", "العنوان", "دمج " + head + " في " + base, title ->
                        this.<String>ghAsync(() -> ghHttp("POST", "/repos/" + full + "/pulls", jsonOf("title", title, "head", head, "base", base), null), (r, e2) -> {
                            if (e2 != null) { ghToast("فشل: " + e2); return; }
                            ghToast("تم إنشاء طلب الدمج ✔");
                            try { ghPullDetail(full, new JSONObject(r).optInt("number")); } catch (Exception ignored) {}
                        }));
            }).show();
        });
    }

    private static String ghMergeState(String st) {
        switch (st == null ? "" : st) {
            case "clean": return "جاهز للدمج ✔";
            case "dirty": return "يوجد تعارضات ✘";
            case "blocked": return "محظور (مراجعة أو فحوص مطلوبة)";
            case "behind": return "متأخر عن الفرع الأساسي";
            case "unstable": return "الفحوص الآلية فاشلة أو جارية";
            case "draft": return "مسودة";
            default: return st == null || st.isEmpty() ? "غير معروف بعد" : st;
        }
    }

    private void ghPullDetail(final String full, final int n) {
        final GhScreen s = ghOpen("ghPull:" + full + ":" + n, "طلب دمج #" + n, () -> ghPullDetail(full, n));
        this.<JSONObject>ghLoad(s, () -> ghPullDetail(full, n), () -> new JSONObject(ghGet("/repos/" + full + "/pulls/" + n)), p -> {
            final boolean open = "open".equals(p.optString("state"));
            final boolean merged = p.optBoolean("merged");
            final String headRef = p.getJSONObject("head").optString("ref");
            String body = p.optString("body", "");
            if (body.equals("null")) body = "";
            ghNote(s.box, p.optString("title") + "\n"
                    + p.getJSONObject("user").optString("login") + ": " + headRef + " → " + p.getJSONObject("base").optString("ref") + "\n"
                    + "الحالة: " + (merged ? "تم دمجه ✔" : open ? "مفتوح" : "مغلق") + (open ? " • " + ghMergeState(p.optString("mergeable_state")) : "") + "\n"
                    + "ملفات " + p.optInt("changed_files") + " • +" + p.optInt("additions") + " −" + p.optInt("deletions") + " • تعليقات " + p.optInt("comments") + "\n"
                    + (body.isEmpty() ? "" : "\n" + body));
            addMenuCard(s.box, "\uD83D\uDCC4", "الملفات المتغيرة", "اعرض الفروق لكل ملف", "#607D8B", () -> ghPullFiles(full, n));
            addMenuCard(s.box, "\uD83D\uDCAC", "التعليقات", "اقرأ وأضف تعليقًا", "#009688", () -> ghComments(full, n));
            if (open) {
                addMenuSectionHeader(s.box, "القرار");
                addMenuCard(s.box, "\u2705", "مراجعة (موافقة / طلب تعديلات)", "#4CAF50", () -> ghReview(full, n, s));
                addMenuCard(s.box, "\uD83D\uDD00", "دمج الآن", "اختر طريقة الدمج", "#9C27B0", () -> ghMergeDialog(full, n, headRef, s));
                addMenuCard(s.box, "\u26D4", "إغلاق بدون دمج", "#F44336", () ->
                        ghConfirm("إغلاق الطلب #" + n + "؟", "يمكنك إعادة فتحه لاحقًا.", () ->
                                this.<String>ghAsync(() -> ghHttp("PATCH", "/repos/" + full + "/pulls/" + n, jsonOf("state", "closed"), null), (r, err) -> {
                                    if (err != null) { ghToast("فشل: " + err); return; }
                                    ghToast("تم الإغلاق");
                                    s.dlg.dismiss();
                                    ghPullDetail(full, n);
                                })));
            } else if (!merged) {
                addMenuCard(s.box, "\u21A9", "إعادة فتح", "#4CAF50", () ->
                        this.<String>ghAsync(() -> ghHttp("PATCH", "/repos/" + full + "/pulls/" + n, jsonOf("state", "open"), null), (r, err) -> {
                            if (err != null) { ghToast("فشل: " + err); return; }
                            s.dlg.dismiss();
                            ghPullDetail(full, n);
                        }));
            }
        });
    }

    private void ghPullFiles(final String full, final int n) {
        final GhScreen s = ghOpen("ghPullFiles:" + full + ":" + n, "ملفات #" + n, () -> ghPullFiles(full, n));
        this.<org.json.JSONArray>ghLoad(s, () -> ghPullFiles(full, n), () -> new org.json.JSONArray(ghGet("/repos/" + full + "/pulls/" + n + "/files?per_page=100")), a -> {
            for (int i = 0; i < a.length(); i++) {
                final JSONObject f = a.getJSONObject(i);
                addMenuCard(s.box, "\uD83D\uDCC4", f.optString("filename"), ghFileStatusAr(f.optString("status")) + " • +" + f.optInt("additions") + " −" + f.optInt("deletions"), "#607D8B", () ->
                        ghShowText(f.optString("filename"), f.optString("patch", "(لا يوجد فرق نصي)")));
            }
            if (a.length() == 0) ghNote(s.box, "لا توجد ملفات.");
        });
    }

    private void ghReview(final String full, final int n, final GhScreen s) {
        new NavAlertBuilder().setTitle("المراجعة").setItems(new CharSequence[]{"موافقة ✅", "طلب تعديلات ✏️ (مع تعليق)", "تعليق فقط 💬"}, (d, w) -> {
            final String event = w == 0 ? "APPROVE" : w == 1 ? "REQUEST_CHANGES" : "COMMENT";
            if (w == 0) {
                this.<String>ghAsync(() -> ghHttp("POST", "/repos/" + full + "/pulls/" + n + "/reviews", jsonOf("event", event), null), (r, err) -> {
                    if (err != null) { ghToast("فشل: " + err); return; }
                    ghToast("تمت الموافقة ✔");
                });
            } else {
                ghPrompt("نص المراجعة", "اكتب ملاحظتك", "", txt ->
                        this.<String>ghAsync(() -> ghHttp("POST", "/repos/" + full + "/pulls/" + n + "/reviews", jsonOf("event", event, "body", txt), null), (r, err) -> {
                            if (err != null) { ghToast("فشل: " + err); return; }
                            ghToast("تم الإرسال ✔");
                        }));
            }
        }).show();
    }

    private void ghMergeDialog(final String full, final int n, final String headRef, final GhScreen s) {
        new NavAlertBuilder().setTitle("طريقة الدمج").setItems(new CharSequence[]{
                "دمج عادي (Merge commit)", "دمج مضغوط (Squash)", "إعادة تأسيس (Rebase)"}, (d, w) -> {
            final String method = w == 0 ? "merge" : w == 1 ? "squash" : "rebase";
            ghConfirm("دمج الطلب #" + n + "؟", "سيُطبَّق الدمج على الفرع الأساسي فورًا.", () ->
                    this.<String>ghAsync(() -> ghHttp("PUT", "/repos/" + full + "/pulls/" + n + "/merge", jsonOf("merge_method", method), null), (r, err) -> {
                        if (err != null) { ghToast("فشل الدمج: " + err); return; }
                        ghToast("تم الدمج ✔");
                        new NavAlertBuilder().setTitle("حذف الفرع " + headRef + "؟")
                                .setMessage("اكتمل الدمج. هل تريد حذف فرع الطلب؟")
                                .setPositiveButton("احذف", (d2, w2) ->
                                        this.<String>ghAsync(() -> ghHttp("DELETE", "/repos/" + full + "/git/refs/heads/" + ghEncPath(headRef), null, null), (r2, e2) -> {
                                            ghToast(e2 != null ? "تعذّر حذف الفرع: " + e2 : "تم حذف الفرع ✔");
                                            s.dlg.dismiss();
                                            ghPullDetail(full, n);
                                        }))
                                .setNegativeButton("أبقِه", (d2, w2) -> { s.dlg.dismiss(); ghPullDetail(full, n); })
                                .show();
                    }));
        }).show();
    }

    // ---------- المشاكل ----------
    private void ghIssues(final String full, final String br, final String state) {
        final GhScreen s = ghOpen("ghIssues:" + full + ":" + state, "المشاكل", () -> ghIssues(full, br, state));
        this.<org.json.JSONArray>ghLoad(s, () -> ghIssues(full, br, state),
                () -> new org.json.JSONArray(ghGet("/repos/" + full + "/issues?state=" + state + "&per_page=50&sort=updated")), a -> {
            final String other = state.equals("open") ? "closed" : "open";
            addMenuCard(s.box, "\uD83D\uDD04", state.equals("open") ? "عرض المغلقة" : "عرض المفتوحة", "#9E9E9E", () -> { s.dlg.dismiss(); ghIssues(full, br, other); });
            addMenuCard(s.box, "\u2795", "مشكلة جديدة", "#F44336", () -> ghNewIssue(full, s, br));
            int shown = 0;
            for (int i = 0; i < a.length(); i++) {
                JSONObject it = a.getJSONObject(i);
                if (it.has("pull_request")) continue;
                shown++;
                final int n = it.optInt("number");
                addMenuCard(s.box, "\uD83D\uDC1E", "#" + n + " " + it.optString("title"),
                        it.getJSONObject("user").optString("login") + " • " + ghDate(it.optString("updated_at")) + " • تعليقات " + it.optInt("comments"), "#F44336", () -> { s.dlg.dismiss(); ghIssueDetail(full, br, n); });
            }
            if (shown == 0) ghNote(s.box, "لا توجد مشاكل.");
        });
    }

    private void ghNewIssue(final String full, final GhScreen s, final String br) {
        LinearLayout lay = new LinearLayout(this);
        lay.setOrientation(LinearLayout.VERTICAL);
        lay.setPadding(dp(16), dp(8), dp(16), dp(8));
        final android.widget.EditText t = new android.widget.EditText(this);
        t.setHint("العنوان");
        lay.addView(t);
        final android.widget.EditText b = new android.widget.EditText(this);
        b.setHint("الوصف (اختياري)");
        b.setMinLines(4);
        b.setGravity(android.view.Gravity.TOP | android.view.Gravity.START);
        lay.addView(b);
        new NavAlertBuilder().setTitle("مشكلة جديدة").setView(lay).setPositiveButton("إنشاء", (d, w) -> {
            final String title = t.getText().toString().trim();
            if (title.isEmpty()) return;
            this.<String>ghAsync(() -> ghHttp("POST", "/repos/" + full + "/issues", jsonOf("title", title, "body", b.getText().toString()), null), (r, err) -> {
                if (err != null) { ghToast("فشل: " + err); return; }
                ghToast("تم الإنشاء ✔");
                s.dlg.dismiss();
                ghIssues(full, br, "open");
            });
        }).setNegativeButton("إلغاء", null).show();
    }

    private void ghIssueDetail(final String full, final String br, final int n) {
        final GhScreen s = ghOpen("ghIssue:" + full + ":" + n, "مشكلة #" + n, () -> ghIssueDetail(full, br, n));
        this.<JSONObject>ghLoad(s, () -> ghIssueDetail(full, br, n), () -> new JSONObject(ghGet("/repos/" + full + "/issues/" + n)), it -> {
            final boolean open = "open".equals(it.optString("state"));
            String body = it.optString("body", "");
            if (body.equals("null")) body = "";
            StringBuilder lb = new StringBuilder();
            org.json.JSONArray ls = it.optJSONArray("labels");
            if (ls != null) for (int i = 0; i < ls.length(); i++) lb.append(ls.getJSONObject(i).optString("name")).append(" ");
            ghNote(s.box, it.optString("title") + "\n" + it.getJSONObject("user").optString("login") + " • " + (open ? "مفتوحة" : "مغلقة")
                    + (lb.length() > 0 ? "\n\uD83C\uDFF7 " + lb : "") + (body.isEmpty() ? "" : "\n\n" + body));
            addMenuCard(s.box, "\uD83D\uDCAC", "التعليقات (" + it.optInt("comments") + ")", "اقرأ وأضف تعليقًا", "#009688", () -> ghComments(full, n));
            addMenuCard(s.box, open ? "\u2705" : "\u21A9", open ? "إغلاق المشكلة" : "إعادة فتح", open ? "#F44336" : "#4CAF50", () ->
                    this.<String>ghAsync(() -> ghHttp("PATCH", "/repos/" + full + "/issues/" + n, jsonOf("state", open ? "closed" : "open"), null), (r, err) -> {
                        if (err != null) { ghToast("فشل: " + err); return; }
                        s.dlg.dismiss();
                        ghIssueDetail(full, br, n);
                    }));
        });
    }

    // تعليقات مشتركة بين المشاكل وطلبات الدمج
    private void ghComments(final String full, final int n) {
        ghToast("جارٍ التحميل ...");
        this.<org.json.JSONArray>ghAsync(() -> new org.json.JSONArray(ghGet("/repos/" + full + "/issues/" + n + "/comments?per_page=100")), (a, err) -> {
            if (err != null) { ghToast(err); return; }
            StringBuilder sb = new StringBuilder();
            try {
                for (int i = 0; i < a.length(); i++) {
                    JSONObject c = a.getJSONObject(i);
                    sb.append(c.getJSONObject("user").optString("login")).append(" (").append(ghDate(c.optString("created_at"))).append("):\n")
                            .append(c.optString("body")).append("\n\n— — —\n\n");
                }
            } catch (Exception ignored) {}
            final LinearLayout lay = new LinearLayout(this);
            lay.setOrientation(LinearLayout.VERTICAL);
            TextView tv = new TextView(this);
            tv.setText(sb.length() == 0 ? "لا توجد تعليقات." : sb.toString());
            tv.setTextSize(13);
            tv.setTextIsSelectable(true);
            tv.setPadding(dp(14), dp(8), dp(14), dp(8));
            ScrollView sv = new ScrollView(this);
            sv.addView(tv);
            lay.addView(sv, new LinearLayout.LayoutParams(-1, -2));
            new NavAlertBuilder().setTitle("تعليقات #" + n).setView(lay)
                    .setPositiveButton("إضافة تعليق", (d, w) -> ghPrompt("تعليق جديد", "اكتب تعليقك", "", txt ->
                            this.<String>ghAsync(() -> ghHttp("POST", "/repos/" + full + "/issues/" + n + "/comments", jsonOf("body", txt), null), (r, e2) ->
                                    ghToast(e2 != null ? "فشل: " + e2 : "تمت الإضافة ✔"))))
                    .setNegativeButton("إغلاق", null)
                    .show();
        });
    }

    // ---------- الإشعارات ----------
    private void ghNotifs() {
        final GhScreen s = ghOpen("ghNotifs", "الإشعارات", () -> ghNotifs());
        this.<org.json.JSONArray>ghLoad(s, () -> ghNotifs(), () -> new org.json.JSONArray(ghGet("/notifications?per_page=50")), a -> {
            if (a.length() == 0) ghNote(s.box, "لا توجد إشعارات غير مقروءة 🎉");
            else addMenuCard(s.box, "\u2714", "تعليم الكل كمقروء", "#4CAF50", () ->
                    this.<String>ghAsync(() -> ghHttp("PUT", "/notifications", "{}", null), (r, err) -> {
                        if (err != null) { ghToast("فشل: " + err); return; }
                        s.dlg.dismiss();
                        ghNotifs();
                    }));
            for (int i = 0; i < a.length(); i++) {
                final JSONObject nt = a.getJSONObject(i);
                final JSONObject sub = nt.getJSONObject("subject");
                final String repo = nt.getJSONObject("repository").optString("full_name");
                final String type = sub.optString("type");
                final String url = sub.optString("url", "");
                final String id = nt.optString("id");
                addMenuCard(s.box, type.equals("PullRequest") ? "\uD83D\uDD00" : type.equals("Issue") ? "\uD83D\uDC1E" : "\uD83D\uDD14", sub.optString("title"),
                        repo + " • " + ghTypeAr(type) + " • " + ghReasonAr(nt.optString("reason")), "#FF9800", () -> {
                            this.<String>ghAsync(() -> ghHttp("PATCH", "/notifications/threads/" + id, null, null), (r, err) -> {});
                            java.util.regex.Matcher m = java.util.regex.Pattern.compile("/(pulls|issues)/(\\d+)$").matcher(url);
                            if (m.find()) {
                                int num = Integer.parseInt(m.group(2));
                                s.dlg.dismiss();
                                if (m.group(1).equals("pulls")) ghPullDetail(repo, num);
                                else ghIssueDetail(repo, null, num);
                            } else {
                                s.dlg.dismiss();
                                ghRepo(repo, null);
                            }
                        });
            }
        });
    }

    // ---------- تنزيل مستودع كمشروع ----------
    // يشغّل المهمة ويفتح فورًا نافذة الناتج بملء الشاشة ليرى المستخدم التقدّم وسبب أي فشل داخل التطبيق
    private void ghRunWithOutput(final Supplier<String> task) {
        if (busy) {
            Toast.makeText(this, "توجد عملية جارية", Toast.LENGTH_SHORT).show();
            return;
        }
        startTask(task);
        try { showOutputDialog("جارٍ العمل...\nيتصل بـ GitHub ..."); } catch (Throwable ignored) {}
    }

    private void ghDownloadProject(final String full, final String br) {
        String def = full.substring(full.indexOf('/') + 1).replaceAll("[\\\\/:*?\"<>|\\s]", "_");
        ghPrompt("اسم المشروع على الجهاز", "اسم المشروع", def, v -> {
            final String name = v.replaceAll("[\\\\/:*?\"<>|\\s]", "_");
            if (name.equals(".") || name.equals("..")) { ghToast("اسم غير صالح"); return; }
            if (new File(projectsDir(), name).exists()) {
                ghConfirm("المشروع «" + name + "» موجود", "سيُستبدل بنسخة GitHub بعد حفظ نسخة احتياطية منه. متابعة؟", () -> ghRunWithOutput(() -> ghDoDownload(full, br, name)));
            } else {
                ghRunWithOutput(() -> ghDoDownload(full, br, name));
            }
        });
    }

    // اتصال GitHub مع إعادة محاولة تلقائية عند فشل/انتهاء مهلة الاتصال (شبكات بطيئة أو متقطعة)
    private java.net.HttpURLConnection ghConnRetry(String method, String path, String accept) throws Exception {
        Exception last = null;
        for (int i = 1; i <= 2; i++) {
            ghViaNetwork = (i % 2 == 1);
            java.net.HttpURLConnection c = ghConn(method, path, accept);
            c.setConnectTimeout(12000);
            try {
                c.getResponseCode();
                return c;
            } catch (java.net.SocketException | java.net.SocketTimeoutException | java.net.UnknownHostException e) {
                last = e;
                c.disconnect();
                if (i < 2) {
                    progress("تعذّر الاتصال بـ api.github.com — إعادة المحاولة ...");
                }
            }
        }
        throw last;
    }

    // مسار بديل للتنزيل عندما يكون api.github.com محجوبًا/بطيئًا في الشبكة: github.com ثم codeload.github.com
    private java.net.HttpURLConnection ghFallbackZip(String full, String br, Exception apiEx) throws Exception {
        String enc = ghEncPath(br);
        String[] urls = {
            "https://github.com/" + full + "/archive/refs/heads/" + enc + ".zip",
            "https://codeload.github.com/" + full + "/zip/refs/heads/" + enc,
            "https://github.com/" + full + "/archive/" + enc + ".zip"
        };
        String tok = ghMgrToken();
        Exception last = apiEx;
        for (String u : urls) {
            for (int k = 0; k < 2; k++) {
                ghViaNetwork = (k == 0);
                java.net.HttpURLConnection c = null;
                try {
                    progress("api.github.com لا يستجيب — يجرّب مسارًا بديلًا: " + u.substring(8, u.indexOf('/', 8)) + " ...");
                    c = ghOpenUrl(u);
                    c.setConnectTimeout(15000);
                    c.setReadTimeout(60000);
                    c.setInstanceFollowRedirects(true);
                    c.setRequestProperty("User-Agent", "L2SBuilder");
                    if (!tok.isEmpty()) c.setRequestProperty("Authorization", "token " + tok);
                    int rc = c.getResponseCode();
                    if (rc == 200) return c;
                    last = new IOException("المسار البديل أرجع الرمز " + rc
                            + (rc == 404 ? " — المستودع خاص أو الفرع غير موجود" : ""));
                    c.disconnect();
                    break;
                } catch (java.io.IOException e) {
                    last = e;
                    if (c != null) c.disconnect();
                }
            }
        }
        throw new IOException("تعذّر الاتصال بـ GitHub بكل المسارات (api / github.com / codeload). "
                + "الشبكة تحجب GitHub على هذا التطبيق. آخر خطأ: " + last.getMessage());
    }

    private String ghDoDownload(String full, String br, String name) {
        File tmp = new File(getCacheDir(), "gh_dl.zip");
        File stage = new File(getFilesDir(), "staging_gh");
        deleteRec(stage);
        try {
            progress("ينزّل " + full + " (" + br + ") ...");
            java.net.HttpURLConnection c;
            try {
                c = ghConnRetry("GET", "/repos/" + full + "/zipball/" + ghEncPath(br), null);
            } catch (java.io.IOException apiEx) {
                c = ghFallbackZip(full, br, apiEx);
            }
            try {
                int rc = c.getResponseCode();
                if (rc >= 400) {
                    InputStream es = c.getErrorStream();
                    byte[] eb = es == null ? new byte[0] : readCapped(es, 1 << 20);
                    throw ghError(rc, eb == null ? "" : new String(eb, StandardCharsets.UTF_8));
                }
                long total = c.getContentLengthLong();
                try (InputStream in = c.getInputStream(); FileOutputStream fo = new FileOutputStream(tmp)) {
                    byte[] buf = new byte[1 << 16];
                    long got = 0, last = 0;
                    int k;
                    while ((k = in.read(buf)) > 0) {
                        fo.write(buf, 0, k);
                        got += k;
                        long now = System.currentTimeMillis();
                        if (now - last > 700) { last = now; progress("ينزّل ... " + fmtSize(got) + (total > 0 ? " / " + fmtSize(total) : "")); }
                    }
                }
            } finally {
                c.disconnect();
            }
            stage.mkdirs();
            String canon = stage.getCanonicalPath() + File.separator;
            int n = 0;
            try (ZipInputStream zin = new ZipInputStream(new BufferedInputStream(new FileInputStream(tmp), 1 << 16))) {
                ZipEntry e;
                byte[] buf = new byte[1 << 16];
                while ((e = zin.getNextEntry()) != null) {
                    String nm = e.getName().replace('\\', '/');
                    int slash = nm.indexOf('/');
                    if (slash < 0) continue;
                    String rel = nm.substring(slash + 1);
                    if (rel.isEmpty()) continue;
                    File f = new File(stage, rel);
                    if (!f.getCanonicalPath().startsWith(canon)) continue;
                    if (e.isDirectory()) { f.mkdirs(); continue; }
                    f.getParentFile().mkdirs();
                    try (FileOutputStream fo = new FileOutputStream(f)) {
                        int k;
                        while ((k = zin.read(buf)) > 0) fo.write(buf, 0, k);
                    }
                    if (++n % 200 == 0) progress("يفك ... " + n + " ملفًا");
                }
            }
            File dest = new File(projectsDir(), name);
            String ts = null;
            if (dest.exists()) {
                progress("نسخة احتياطية قبل الاستبدال ...");
                ts = backupProjectNow(name);
                deleteRec(dest);
            }
            if (!stage.renameTo(dest)) return "تعذّر نقل المشروع إلى قائمة المشاريع.";
            uiPrefs().edit().putString("proj", name).apply();
            return "تم تنزيل «" + name + "» من " + full + " (" + br + ") ✔ | ملفات: " + n
                    + (ts != null ? "\nنسخة احتياطية للقديم: " + ts : "") + "\nأصبح هو المشروع الحالي.";
        } catch (Throwable e) {
            return "فشل التنزيل: " + e.getMessage();
        } finally {
            tmp.delete();
            deleteRec(stage);
        }
    }

    // ---------- رفع مشروع إلى GitHub ----------
    // pre != null: مشروع محدد مسبقًا (من إعدادات المشروع) دون سؤال
    private void ghUploadProject(final String full, final String br, final String pre) {
        if (pre != null) { ghUploadModeStep(full, br, pre); return; }
        String[] ps = projectsDir().list();
        final java.util.ArrayList<String> names = new java.util.ArrayList<>();
        if (ps != null) for (String p : ps) if (new File(projectsDir(), p).isDirectory()) names.add(p);
        java.util.Collections.sort(names);
        if (names.isEmpty()) { ghToast("لا توجد مشاريع على الجهاز."); return; }
        String cur = currentProject();
        if (names.remove(cur)) names.add(0, cur);
        new NavAlertBuilder().setTitle("اختر المشروع للرفع").setItems(names.toArray(new CharSequence[0]), (d, w) ->
                ghUploadModeStep(full, br, names.get(w))).show();
    }

    private void ghUploadModeStep(final String full, final String br, final String proj) {
        new NavAlertBuilder().setTitle("طريقة الرفع إلى " + full).setItems(new CharSequence[]{
                "تحديث وإضافة فقط (آمن)", "مطابقة كاملة (يحذف من GitHub ما ليس في المشروع)"}, (d, w) -> {
            final boolean mirror = w == 1;
            Runnable go = () -> ghAskMessage("Update from L2SBuilder: " + proj, msg -> startTask(() -> ghDoPush(full, br, proj, mirror, msg)));
            if (mirror) ghConfirm("مطابقة كاملة؟", "ستُحذف من الفرع " + br + " كل الملفات غير الموجودة في المشروع المحلي.", go);
            else go.run();
        }).show();
    }

    private static String ghBlobSha(byte[] data) throws Exception {
        java.security.MessageDigest md = java.security.MessageDigest.getInstance("SHA-1");
        md.update(("blob " + data.length + "\0").getBytes(StandardCharsets.UTF_8));
        md.update(data);
        byte[] h = md.digest();
        StringBuilder sb = new StringBuilder();
        for (byte b : h) sb.append(String.format("%02x", b));
        return sb.toString();
    }

    private static JSONObject ghTreeEntry(String path, String mode) throws org.json.JSONException {
        JSONObject o = new JSONObject();
        o.put("path", path);
        o.put("mode", mode);
        o.put("type", "blob");
        return o;
    }

    // ---------- رفع مشروع على دفعات قابلة للاستئناف ----------
    // كل دفعة (حتى 60 ملفًا / 5 ميغابايت تقريبًا) تُحفظ كإيداع مستقل على GitHub؛ فإذا انقطع الرفع يبقى ما رُفع محفوظًا،
    // وعند «مواصلة الرفع» تُقارن الملفات بالمستودع (SHA) فيُرفع الباقي فقط.
    private static final class GhPushItem {
        String rel;
        File f;
        String mode;
        long size;
        boolean big;
    }

    // حدّ GitHub للملف الواحد 100 ميغابايت؛ نترك هامشًا. الملفات الأكبر من حد الذاكرة تُرفع «بثًّا» دون تحميلها كاملة.
    private static final int GH_MAX_FILE_MB_DEFAULT = 99;
    private int ghMaxFileMb() { return Math.max(1, Math.min(100, uiPrefs().getInt("gh_max_file_mb", GH_MAX_FILE_MB_DEFAULT))); }
    private long ghMaxFile() { return ghMaxFileMb() * (1L << 20); }
    private static final long GH_MEM_FILE = 8L << 20;

    private int ghBatchFiles() { return Math.max(10, Math.min(300, uiPrefs().getInt("gh_batch_files", 100))); }
    private int ghBatchMb() { return Math.max(1, Math.min(20, uiPrefs().getInt("gh_batch_mb", 8))); }
    private boolean ghSkipCi() { return uiPrefs().getBoolean("gh_skipci", true); }

    // ===== الملفات الأكبر من الحد: Releases (مجاني، بلا حد للمساحة الإجمالية) أو Git LFS (ضمن الحصة المجانية فقط) =====
    private static final long GH_ASSET_MAX = (2L << 30) - (1L << 20);   // أقل من 2 جيجا (حد ملف Release)
    private static final long GH_LFS_FREE_CAP = 900L << 20;             // الحصة المجانية 1 جيجا، نترك هامشًا
    private static final String GH_LARGE_TAG = "large-files";

    private String ghLargeMode() {
        String m = uiPrefs().getString("gh_large_mode", "release");
        return m.equals("lfs") || m.equals("skip") ? m : "release";
    }

    private String ghLargeModeShort() {
        String m = ghLargeMode();
        return m.equals("lfs") ? "Git LFS (ضمن المجاني)" : m.equals("skip") ? "التخطي" : "Releases";
    }

    private static class GhLarge {
        final java.util.LinkedHashMap<String, String> texts = new java.util.LinkedHashMap<>();
        final java.util.ArrayList<String> info = new java.util.ArrayList<>();
        String summary() {
            if (info.isEmpty()) return "";
            return "\n📦 الملفات الكبيرة:\n" + android.text.TextUtils.join("\n", info);
        }
    }

    private long ghLfsUsed() {
        try {
            JSONObject o = new JSONObject(uiPrefs().getString("gh_lfs_used", "{}"));
            long t = 0;
            java.util.Iterator<String> it = o.keys();
            while (it.hasNext()) t += o.optLong(it.next());
            return t;
        } catch (Throwable e) { return 0; }
    }

    private boolean ghLfsKnown(String oid) {
        try { return new JSONObject(uiPrefs().getString("gh_lfs_used", "{}")).has(oid); } catch (Throwable e) { return false; }
    }

    private void ghLfsRemember(String oid, long size) {
        try {
            JSONObject o = new JSONObject(uiPrefs().getString("gh_lfs_used", "{}"));
            o.put(oid, size);
            uiPrefs().edit().putString("gh_lfs_used", o.toString()).apply();
        } catch (Throwable ignored) {}
    }

    private static String ghSha256File(File f) throws Exception {
        java.security.MessageDigest md = java.security.MessageDigest.getInstance("SHA-256");
        try (InputStream in = new FileInputStream(f)) {
            byte[] buf = new byte[64 * 1024];
            int n;
            while ((n = in.read(buf)) > 0) md.update(buf, 0, n);
        }
        StringBuilder sb = new StringBuilder();
        for (byte b : md.digest()) sb.append(String.format("%02x", b));
        return sb.toString();
    }

    private static String ghAssetName(String path) {
        return path.replace("/", "__").replaceAll("[^A-Za-z0-9._@+-]", "_");
    }

    private static String ghAttrLine(String path) {
        return (path.contains(" ") ? "\"" + path + "\"" : path) + " filter=lfs diff=lfs merge=lfs -text";
    }

    private static String ghMergeAttrs(String a, String b) {
        java.util.LinkedHashSet<String> set = new java.util.LinkedHashSet<>();
        for (String l : a.split("\n")) if (!l.trim().isEmpty()) set.add(l.trim());
        for (String l : b.split("\n")) if (!l.trim().isEmpty()) set.add(l.trim());
        return android.text.TextUtils.join("\n", set) + "\n";
    }

    private static String ghConnBody(java.net.HttpURLConnection c, int rc) throws IOException {
        InputStream is = rc >= 400 ? c.getErrorStream() : c.getInputStream();
        if (is == null) return "";
        try (InputStream in = is) {
            byte[] a = readCapped(in, 4L << 20);
            return a == null ? "" : new String(a, StandardCharsets.UTF_8);
        }
    }

    private void ghCopyProg(InputStream in, OutputStream os, long total, String label) throws IOException {
        byte[] buf = new byte[64 * 1024];
        long done = 0, last = -1;
        int n;
        while ((n = in.read(buf)) > 0) {
            os.write(buf, 0, n);
            done += n;
            long step = total > 0 ? (done * 100 / total) / 5 : 0;
            if (step != last) { last = step; progress(label + " — " + (step * 5) + "%"); }
        }
        os.flush();
    }

    private String ghRemoteText(String full, String br, String path) throws Exception {
        try {
            byte[] b = ghHttpBytes("GET", "/repos/" + full + "/contents/" + ghEncPath(path) + "?ref=" + ghEnc(br), null, "application/vnd.github.raw+json", 4L << 20);
            return new String(b, StandardCharsets.UTF_8);
        } catch (Exception e) {
            if (String.valueOf(e.getMessage()).startsWith("404")) return null;
            throw e;
        }
    }

    private static boolean ghApplyHeaders(java.net.HttpURLConnection c, JSONObject hd) throws Exception {
        boolean hasCt = false;
        if (hd != null) {
            java.util.Iterator<String> ks = hd.keys();
            while (ks.hasNext()) {
                String k = ks.next();
                if (k.equalsIgnoreCase("Content-Type")) hasCt = true;
                c.setRequestProperty(k, hd.getString(k));
            }
        }
        return hasCt;
    }

    // رفع كائن إلى Git LFS (بروتوكول basic): batch ثم PUT ثم verify
    private void ghLfsUpload(String full, File f, String oid, long size) throws Exception {
        String txt;
        java.net.HttpURLConnection c = ghConn("POST", "https://github.com/" + full + ".git/info/lfs/objects/batch", "application/vnd.git-lfs+json");
        try {
            c.setRequestProperty("Authorization", "Basic " + android.util.Base64.encodeToString(("x-access-token:" + ghMgrToken()).getBytes(StandardCharsets.UTF_8), android.util.Base64.NO_WRAP));
            c.setRequestProperty("Content-Type", "application/vnd.git-lfs+json");
            c.setDoOutput(true);
            JSONObject body = new JSONObject();
            body.put("operation", "upload");
            body.put("transfers", new org.json.JSONArray().put("basic"));
            body.put("hash_algo", "sha256");
            body.put("objects", new org.json.JSONArray().put(new JSONObject().put("oid", oid).put("size", size)));
            byte[] b = body.toString().getBytes(StandardCharsets.UTF_8);
            c.setFixedLengthStreamingMode(b.length);
            try (OutputStream os = c.getOutputStream()) { os.write(b); }
            int rc = c.getResponseCode();
            txt = ghConnBody(c, rc);
            if (rc >= 400) throw ghError(rc, txt);
        } finally {
            c.disconnect();
        }
        JSONObject ob = new JSONObject(txt).getJSONArray("objects").getJSONObject(0);
        JSONObject er = ob.optJSONObject("error");
        if (er != null) throw new IOException("LFS: " + er.optString("message", "خطأ"));
        JSONObject acts = ob.optJSONObject("actions");
        if (acts == null) return; // موجود مسبقًا على الخادم
        JSONObject up = acts.optJSONObject("upload");
        if (up != null) {
            java.net.HttpURLConnection pc = (java.net.HttpURLConnection) new java.net.URL(up.getString("href")).openConnection();
            try {
                pc.setRequestMethod("PUT");
                pc.setConnectTimeout(20000);
                pc.setReadTimeout(600000);
                pc.setRequestProperty("User-Agent", "L2SBuilder");
                pc.setDoOutput(true);
                if (!ghApplyHeaders(pc, up.optJSONObject("header"))) pc.setRequestProperty("Content-Type", "application/octet-stream");
                pc.setFixedLengthStreamingMode(size);
                try (OutputStream os = new java.io.BufferedOutputStream(pc.getOutputStream(), 64 * 1024); InputStream in = new FileInputStream(f)) {
                    ghCopyProg(in, os, size, "يرفع إلى LFS: " + f.getName());
                }
                int rc = pc.getResponseCode();
                if (rc >= 400) throw new IOException(rc + ": فشل رفع الملف إلى LFS\n" + ghConnBody(pc, rc));
            } finally {
                pc.disconnect();
            }
        }
        JSONObject ver = acts.optJSONObject("verify");
        if (ver != null) {
            java.net.HttpURLConnection vc = (java.net.HttpURLConnection) new java.net.URL(ver.getString("href")).openConnection();
            try {
                vc.setRequestMethod("POST");
                vc.setConnectTimeout(20000);
                vc.setReadTimeout(60000);
                vc.setRequestProperty("User-Agent", "L2SBuilder");
                vc.setRequestProperty("Accept", "application/vnd.git-lfs+json");
                vc.setDoOutput(true);
                if (!ghApplyHeaders(vc, ver.optJSONObject("header"))) vc.setRequestProperty("Content-Type", "application/vnd.git-lfs+json");
                byte[] vb = new JSONObject().put("oid", oid).put("size", size).toString().getBytes(StandardCharsets.UTF_8);
                vc.setFixedLengthStreamingMode(vb.length);
                try (OutputStream os = vc.getOutputStream()) { os.write(vb); }
                int rc = vc.getResponseCode();
                if (rc >= 400) throw new IOException(rc + ": فشل التحقق من الملف في LFS");
            } finally {
                vc.disconnect();
            }
        }
    }

    private JSONObject ghEnsureRelease(String full, String br) throws Exception {
        try {
            return new JSONObject(ghGet("/repos/" + full + "/releases/tags/" + GH_LARGE_TAG));
        } catch (Exception e) {
            if (!String.valueOf(e.getMessage()).startsWith("404")) throw e;
        }
        JSONObject b = new JSONObject();
        b.put("tag_name", GH_LARGE_TAG);
        b.put("target_commitish", br);
        b.put("name", "Large files");
        b.put("body", "ملفات كبيرة رفعها L2SBuilder خارج المستودع. المسارات والروابط في large-files.json");
        b.put("make_latest", "false");
        return new JSONObject(ghHttp("POST", "/repos/" + full + "/releases", b.toString(), null));
    }

    private java.util.HashMap<String, JSONObject> ghListAssets(String full, long rid) throws Exception {
        java.util.HashMap<String, JSONObject> m = new java.util.HashMap<>();
        for (int pg = 1; pg <= 10; pg++) {
            org.json.JSONArray arr = new org.json.JSONArray(ghGet("/repos/" + full + "/releases/" + rid + "/assets?per_page=100&page=" + pg));
            for (int i = 0; i < arr.length(); i++) { JSONObject a = arr.getJSONObject(i); m.put(a.getString("name"), a); }
            if (arr.length() < 100) break;
        }
        return m;
    }

    private String ghReleaseUpload(String full, long rid, String name, File f) throws Exception {
        long size = f.length();
        for (int t = 0; ; t++) {
            java.net.HttpURLConnection c = ghConn("POST", "https://uploads.github.com/repos/" + full + "/releases/" + rid + "/assets?name=" + ghEnc(name), null);
            try {
                c.setDoOutput(true);
                c.setReadTimeout(600000);
                c.setRequestProperty("Content-Type", "application/octet-stream");
                c.setFixedLengthStreamingMode(size);
                try (OutputStream os = new java.io.BufferedOutputStream(c.getOutputStream(), 64 * 1024); InputStream in = new FileInputStream(f)) {
                    ghCopyProg(in, os, size, "يرفع إلى Releases: " + f.getName());
                }
                int rc = c.getResponseCode();
                String txt = ghConnBody(c, rc);
                if (rc >= 400) throw ghError(rc, txt);
                return new JSONObject(txt).optString("browser_download_url");
            } catch (Exception e) {
                String m = String.valueOf(e.getMessage());
                boolean retry = !m.matches("(?s)^[0-9]{3}.*") || m.startsWith("5");
                if (!retry || t >= 2) throw e;
                progress("انقطاع — إعادة رفع الملف (" + (t + 1) + "/2) ...");
                Thread.sleep(5000L * (t + 1));
                try {
                    JSONObject part = ghListAssets(full, rid).get(name);
                    if (part != null) ghHttp("DELETE", "/repos/" + full + "/releases/assets/" + part.getLong("id"), null, null);
                } catch (Exception ignored) {}
            } finally {
                c.disconnect();
            }
        }
    }

    private void ghReleasePart(String full, String br, java.util.LinkedHashMap<String, File> files, GhLarge r) throws Exception {
        if (files.isEmpty()) return;
        progress("يجهّز Release «" + GH_LARGE_TAG + "» ...");
        long rid = ghEnsureRelease(full, br).getLong("id");
        java.util.HashMap<String, JSONObject> assets = ghListAssets(full, rid);
        String oldTxt = ghRemoteText(full, br, "large-files.json");
        JSONObject man = new JSONObject();
        JSONObject mf = new JSONObject();
        if (oldTxt != null) {
            try {
                man = new JSONObject(oldTxt);
                mf = man.optJSONObject("files");
                if (mf == null) mf = new JSONObject();
            } catch (Throwable t) { man = new JSONObject(); mf = new JSONObject(); }
        }
        for (java.util.Map.Entry<String, File> en : files.entrySet()) {
            String path = en.getKey();
            File f = en.getValue();
            long size = f.length();
            String name = ghAssetName(path);
            JSONObject old = assets.get(name);
            String url;
            if (old != null && old.optLong("size") == size && "uploaded".equals(old.optString("state", "uploaded"))) {
                url = old.optString("browser_download_url");
                r.info.add("= " + path + " (" + (size >> 20) + " م.ب) — موجود في Release بلا تغيير، لم يُرفع من جديد");
            } else {
                if (old != null) ghHttp("DELETE", "/repos/" + full + "/releases/assets/" + old.getLong("id"), null, null);
                progress("يرفع " + path + " (" + (size >> 20) + " م.ب) إلى Releases ...");
                url = ghReleaseUpload(full, rid, name, f);
                r.info.add("⬆ " + path + " (" + (size >> 20) + " م.ب) → Release");
            }
            JSONObject e = new JSONObject();
            e.put("asset", name);
            e.put("size", size);
            e.put("url", url);
            mf.put(path, e);
        }
        man.put("release_tag", GH_LARGE_TAG);
        man.put("files", mf);
        String newTxt = man.toString(2) + "\n";
        if (!newTxt.equals(oldTxt)) r.texts.put("large-files.json", newTxt);
    }

    // يعالج الملفات الأكبر من الحد حسب الإعداد؛ يُرجع نصوصًا تُضاف إلى الإيداع (مؤشرات LFS و.gitattributes وlarge-files.json)
    private GhLarge ghLargeProcess(String full, String br, java.util.LinkedHashMap<String, File> big, java.util.Map<String, String> remote) throws Exception {
        GhLarge r = new GhLarge();
        if (big.isEmpty()) return r;
        java.util.LinkedHashMap<String, File> rel = new java.util.LinkedHashMap<>();
        if (ghLargeMode().equals("lfs")) {
            long used = ghLfsUsed();
            java.util.ArrayList<String> attrs = new java.util.ArrayList<>();
            for (java.util.Map.Entry<String, File> en : big.entrySet()) {
                String path = en.getKey();
                File f = en.getValue();
                long size = f.length();
                try {
                    progress("يحسب بصمة " + path + " ...");
                    String oid = ghSha256File(f);
                    String pointer = "version https://git-lfs.github.com/spec/v1\noid sha256:" + oid + "\nsize " + size + "\n";
                    String rsha = remote.get(path);
                    if (rsha != null && rsha.equals(ghBlobSha(pointer.getBytes(StandardCharsets.UTF_8)))) {
                        r.info.add("= " + path + " — في LFS بلا تغيير");
                        continue;
                    }
                    boolean known = ghLfsKnown(oid);
                    if (!known && used + size > GH_LFS_FREE_CAP) {
                        r.info.add("↪ " + path + " (" + (size >> 20) + " م.ب) — حصة LFS المجانية (1 جيجا) لا تكفي؛ رُفع إلى Releases بدل LFS كي لا تتجاوز المجاني");
                        rel.put(path, f);
                        continue;
                    }
                    if (!known) {
                        ghLfsUpload(full, f, oid, size);
                        ghLfsRemember(oid, size);
                        used += size;
                    }
                    r.texts.put(path, pointer);
                    attrs.add(ghAttrLine(path));
                    r.info.add("⬆ " + path + " (" + (size >> 20) + " م.ب) → Git LFS");
                } catch (Exception e) {
                    String m = String.valueOf(e.getMessage());
                    int nl = m.indexOf('\n');
                    r.info.add("↪ " + path + " — تعذّر LFS (" + (nl > 0 ? m.substring(0, nl) : m) + ")؛ رُفع إلى Releases");
                    rel.put(path, f);
                }
            }
            if (!attrs.isEmpty()) {
                String oldA = ghRemoteText(full, br, ".gitattributes");
                r.texts.put(".gitattributes", ghMergeAttrs(oldA == null ? "" : oldA, android.text.TextUtils.join("\n", attrs)));
            }
        } else {
            rel.putAll(big);
        }
        ghReleasePart(full, br, rel, r);
        return r;
    }

    // يضيف نصوص الملفات الكبيرة إلى مدخلات شجرة الإيداع (يدمج .gitattributes إن وُجد)
    private void ghMergeLarge(org.json.JSONArray entries, GhLarge r) throws Exception {
        for (java.util.Map.Entry<String, String> en : r.texts.entrySet()) {
            String p = en.getKey();
            String txt = en.getValue();
            boolean done = false;
            for (int i = 0; i < entries.length(); i++) {
                JSONObject e = entries.getJSONObject(i);
                if (!p.equals(e.optString("path"))) continue;
                String oldc = e.has("content") ? e.optString("content", null) : null;
                if (p.equals(".gitattributes") && oldc != null) txt = ghMergeAttrs(oldc, txt);
                e.remove("sha");
                e.put("content", txt);
                done = true;
                break;
            }
            if (!done) entries.put(ghTreeEntry(p, "100644").put("content", txt));
        }
    }

    private void ghLargeModeDialog() {
        final String[] keys = {"release", "lfs", "skip"};
        String[] labels = {
            "Releases — مجاني، بلا حد للمساحة (موصى به)",
            "Git LFS — مجاني حتى 1 جيجا فقط",
            "تخطي الملفات الكبيرة"
        };
        int cur = 0;
        for (int i = 0; i < keys.length; i++) if (keys[i].equals(ghLargeMode())) cur = i;
        new NavAlertBuilder()
                .setTitle("الملفات الأكبر من الحد")
                .setSingleChoiceItems(labels, cur, (d, w) -> {
                    uiPrefs().edit().putString("gh_large_mode", keys[w]).apply();
                    if (w == 1) Toast.makeText(this, "تنبيه: كل تنزيل من LFS (مثل بناء Actions) يستهلك من 1 جيجا/شهر المجانية. عند امتلاء الحصة يتحوّل التطبيق تلقائيًا إلى Releases.", Toast.LENGTH_LONG).show();
                    else Toast.makeText(this, "تم الحفظ", Toast.LENGTH_SHORT).show();
                    d.dismiss();
                })
                .setNegativeButton("إلغاء", null)
                .show();
    }

    // سطور الخطوات التي تُضاف بعد checkout؛ sp = مسافة بداية الخطوة
    private static String ghLargeStepLines(String sp, boolean release, boolean lfs) {
        StringBuilder y = new StringBuilder();
        if (lfs) {
            y.append(sp).append("- name: Pull LFS files\n")
                    .append(sp).append("  continue-on-error: true\n")
                    .append(sp).append("  run: git lfs pull\n");
        }
        if (release) {
            y.append(sp).append("- name: Download large files\n")
                    .append(sp).append("  continue-on-error: true\n")
                    .append(sp).append("  env:\n")
                    .append(sp).append("    GH_TOKEN: ${{ github.token }}\n")
                    .append(sp).append("  run: |\n")
                    .append(sp).append("    if [ -f large-files.json ]; then\n")
                    .append(sp).append("      jq -r '.files | to_entries[] | [.key, .value.asset] | @tsv' large-files.json |\n")
                    .append(sp).append("      while IFS=$'\\t' read -r p a; do\n")
                    .append(sp).append("        mkdir -p \"$(dirname \"$p\")\"\n")
                    .append(sp).append("        gh release download " + GH_LARGE_TAG + " --pattern \"$a\" --output \"$p\" --clobber\n")
                    .append(sp).append("      done\n")
                    .append(sp).append("    fi\n");
        }
        return y.toString();
    }

    private String ghLargeStepYaml() {
        String m = ghLargeMode();
        if (m.equals("skip")) return "";
        return ghLargeStepLines("      ", true, m.equals("lfs"));
    }

    private static int ghIndentOf(String l) {
        int k = 0;
        while (k < l.length() && l.charAt(k) == ' ') k++;
        return k;
    }

    // يضيف خطوات تحميل الملفات الكبيرة بعد كل خطوة actions/checkout. يُرجع null إن لا حاجة أو تعذّر بأمان.
    private static String addLargeSteps(String yml, boolean release, boolean lfs) {
        try {
            if (yml == null) return null;
            boolean needR = release && !yml.contains("large-files.json");
            boolean needL = lfs && !yml.contains("git lfs pull");
            if (!needR && !needL) return null;
            String nl = yml.contains("\r\n") ? "\r\n" : "\n";
            java.util.List<String> lines = new java.util.ArrayList<>(java.util.Arrays.asList(yml.split("\r?\n", -1)));
            java.util.regex.Pattern co = java.util.regex.Pattern.compile("^(\\s*)(-\\s+)?uses:\\s*['\"]?actions/checkout@.*$");
            boolean changed = false;
            for (int i = lines.size() - 1; i >= 0; i--) {
                java.util.regex.Matcher m = co.matcher(lines.get(i));
                if (!m.matches()) continue;
                int stepIndent = -1;
                if (m.group(2) != null) {
                    stepIndent = m.group(1).length();
                } else {
                    int own = m.group(1).length();
                    for (int k = i - 1; k >= 0; k--) {
                        String L = lines.get(k);
                        String t = L.trim();
                        if (t.isEmpty() || t.startsWith("#")) continue;
                        if (ghIndentOf(L) < own) {
                            if (t.startsWith("- ") || t.equals("-")) stepIndent = ghIndentOf(L);
                            break;
                        }
                    }
                }
                if (stepIndent < 0) continue;
                int last = i;
                for (int j = i + 1; j < lines.size(); j++) {
                    String L = lines.get(j);
                    if (L.trim().isEmpty()) continue;
                    if (ghIndentOf(L) <= stepIndent) break;
                    last = j;
                }
                StringBuilder sp = new StringBuilder();
                for (int q = 0; q < stepIndent; q++) sp.append(' ');
                String add = ghLargeStepLines(sp.toString(), needR, needL);
                java.util.List<String> nw = new java.util.ArrayList<>(java.util.Arrays.asList(add.split("\n", -1)));
                if (!nw.isEmpty() && nw.get(nw.size() - 1).isEmpty()) nw.remove(nw.size() - 1);
                lines.addAll(last + 1, nw);
                changed = true;
            }
            return changed ? android.text.TextUtils.join(nl, lines) : null;
        } catch (Throwable e) {
            return null;
        }
    }

    // "" = معطّل، "release" = خطوة Releases، "lfs" = خطوة LFS + Releases (للتحويل التلقائي)
    private String ghWfLarge = "";

    private void ghWfPlan(java.util.Map<String, String> remote, boolean bigPresent) {
        String m = ghLargeMode();
        boolean on = uiPrefs().getBoolean("gh_large_wf", true) && !m.equals("skip")
                && (bigPresent || remote.containsKey("large-files.json") || (m.equals("lfs") && remote.containsKey(".gitattributes")));
        ghWfLarge = on ? m : "";
    }

    private byte[] ghFixWf(String path, byte[] data) {
        byte[] d = ghFixWorkflowBytes(path, data);
        try {
            if (ghWfLarge.isEmpty() || path == null || d == null) return d;
            String low = path.toLowerCase(java.util.Locale.US);
            if (!low.startsWith(".github/workflows/") || !(low.endsWith(".yml") || low.endsWith(".yaml"))) return d;
            String f = addLargeSteps(new String(d, StandardCharsets.UTF_8), true, ghWfLarge.equals("lfs"));
            return f == null ? d : f.getBytes(StandardCharsets.UTF_8);
        } catch (Throwable e) {
            return d;
        }
    }

    // ملفات البناء الموجودة في المستودع ولم تُرفع الآن: تُعدَّل في نفس الإيداع إن كانت تفتقد الخطوة
    private void ghPatchRemoteWorkflows(String full, String br, org.json.JSONArray entries, java.util.Map<String, String> remote) throws Exception {
        if (ghWfLarge.isEmpty()) return;
        for (String p : remote.keySet()) {
            String low = p.toLowerCase(java.util.Locale.US);
            if (!low.startsWith(".github/workflows/") || !(low.endsWith(".yml") || low.endsWith(".yaml"))) continue;
            boolean inEntries = false;
            for (int i = 0; i < entries.length(); i++) {
                if (p.equals(entries.getJSONObject(i).optString("path"))) { inEntries = true; break; }
            }
            if (inEntries) continue;
            String t = ghRemoteText(full, br, p);
            if (t == null) continue;
            String f = addLargeSteps(t, true, ghWfLarge.equals("lfs"));
            if (f != null) entries.put(ghTreeEntry(p, "100644").put("content", f));
        }
    }

