    // SHA-1 لملف بصيغة git blob دون تحميله كاملًا في الذاكرة
    private static String ghBlobShaFile(File f) throws Exception {
        java.security.MessageDigest md = java.security.MessageDigest.getInstance("SHA-1");
        md.update(("blob " + f.length() + "\0").getBytes(StandardCharsets.UTF_8));
        try (InputStream in = new FileInputStream(f)) {
            byte[] buf = new byte[64 * 1024];
            int n;
            while ((n = in.read(buf)) > 0) md.update(buf, 0, n);
        }
        StringBuilder sb = new StringBuilder();
        for (byte b : md.digest()) sb.append(String.format("%02x", b));
        return sb.toString();
    }

    // يرفع ملفًا كبيرًا كـ blob بثًّا (base64 على دفعات صغيرة) بدل تحميله كاملًا في الذاكرة
    private String ghUploadBlobStream(String full, File f) throws Exception {
        java.net.HttpURLConnection c = ghConn("POST", "/repos/" + full + "/git/blobs", null);
        try {
            c.setDoOutput(true);
            c.setRequestProperty("Content-Type", "application/json; charset=utf-8");
            c.setChunkedStreamingMode(64 * 1024);
            c.setReadTimeout(300000);
            try (OutputStream os = new BufferedOutputStream(c.getOutputStream(), 64 * 1024); InputStream in = new FileInputStream(f)) {
                os.write("{\"encoding\":\"base64\",\"content\":\"".getBytes(StandardCharsets.UTF_8));
                byte[] buf = new byte[3 * 16384];
                while (true) {
                    int off = 0, n;
                    while (off < buf.length && (n = in.read(buf, off, buf.length - off)) > 0) off += n;
                    if (off == 0) break;
                    os.write(android.util.Base64.encode(buf, 0, off, android.util.Base64.NO_WRAP));
                    if (off < buf.length) break;
                }
                os.write("\"}".getBytes(StandardCharsets.UTF_8));
                os.flush();
            }
            int rc = c.getResponseCode();
            InputStream is = rc >= 400 ? c.getErrorStream() : c.getInputStream();
            byte[] body = new byte[0];
            if (is != null) {
                try (InputStream in2 = is) {
                    byte[] all = readCapped(in2, 4L << 20);
                    if (all != null) body = all;
                }
            }
            String txt = new String(body, StandardCharsets.UTF_8);
            if (rc >= 400) throw ghError(rc, txt);
            return new JSONObject(txt).getString("sha");
        } finally {
            c.disconnect();
        }
    }

    private String ghUploadBlobStreamRetry(String full, File f) throws Exception {
        for (int t = 0; ; t++) {
            try {
                return ghUploadBlobStream(full, f);
            } catch (Exception e) {
                String m = String.valueOf(e.getMessage());
                boolean limit = m.startsWith("429") || (m.startsWith("403") && (m.contains("حد الطلبات") || m.contains("طلبات كثيرة")));
                boolean retry = !m.matches("(?s)^[0-9]{3}.*") || m.startsWith("5") || limit;
                if (!retry || t >= 3) throw e;
                progress("انقطاع أو حد من GitHub — إعادة رفع الملف الكبير (" + (t + 1) + "/3) ...");
                Thread.sleep(limit ? 20000 : 5000L * (t + 1));
            }
        }
    }

    private void ghSetPending(String full, String br, String proj, boolean mirror, String msg) {
        uiPrefs().edit().putString("gh_pending_push", jsonOf("full", full, "br", br, "proj", proj, "mirror", mirror, "msg", msg)).apply();
    }

    private void ghClearPending() { uiPrefs().edit().remove("gh_pending_push").apply(); }

    private JSONObject ghPending() {
        try {
            String v = uiPrefs().getString("gh_pending_push", "");
            return v.isEmpty() ? null : new JSONObject(v);
        } catch (Exception e) {
            return null;
        }
    }

    // يعرض بطاقتي «مواصلة الرفع» و«تجاهل» إن وُجد رفع معلّق
    private void ghAddPendingCards(final GhScreen s) {
        final JSONObject pd = ghPending();
        if (pd == null) return;
        final String full = pd.optString("full"), br = pd.optString("br"), proj = pd.optString("proj"), msg = pd.optString("msg");
        final boolean mirror = pd.optBoolean("mirror");
        addMenuCard(s.box, "\u25B6", "مواصلة رفع «" + proj + "»", "إلى " + full + " — انقطع الرفع؛ يُكمل الباقي فقط ولا يعيد ما رُفع", "#FF9800", () -> {
            s.dlg.dismiss();
            startTask(() -> ghDoPush(full, br, proj, mirror, msg));
        });
        addMenuCard(s.box, "\u2716", "تجاهل الرفع المعلّق", "لا يحذف شيئًا من GitHub؛ يخفي بطاقة المواصلة فقط", "#9E9E9E", () -> {
            ghClearPending();
            s.dlg.dismiss();
            ghRepos();
        });
    }

    // طلب GitHub مع إعادة المحاولة عند انقطاع الشبكة أو حد المعدّل أو أخطاء الخادم
    private String ghHttpRetry(String method, String path, String json) throws Exception {
        for (int t = 0; ; t++) {
            try {
                return ghHttp(method, path, json, null);
            } catch (Exception e) {
                String m = String.valueOf(e.getMessage());
                boolean limit = m.startsWith("429") || (m.startsWith("403") && (m.contains("حد الطلبات") || m.contains("طلبات كثيرة")));
                boolean retry = !m.matches("(?s)^[0-9]{3}.*") || m.startsWith("5") || limit;
                if (!retry || t >= 3) throw e;
                progress("انقطاع أو حد من GitHub — إعادة المحاولة (" + (t + 1) + "/3) ...");
                Thread.sleep(limit ? 20000 : 4000L * (t + 1));
            }
        }
    }

    // ملخص الملفات التي لم تُرفع وسبب كل منها (حتى يعرف المستخدم أن المشروع ناقص ولماذا)
    private static String ghSkipSummary(java.util.List<String> info) {
        if (info == null || info.isEmpty()) return "";
        StringBuilder sb = new StringBuilder("\n⚠ لم يُرفع " + info.size() + " ملف:");
        for (int i = 0; i < info.size() && i < 12; i++) sb.append("\n• ").append(info.get(i));
        if (info.size() > 12) sb.append("\n… و").append(info.size() - 12).append(" أخرى");
        return sb.toString();
    }

    private String ghDoPush(String full, String br, String proj, boolean mirror, String msg) {
        File src = new File(projectsDir(), proj);
        if (!src.isDirectory()) return "المشروع غير موجود: " + proj;
        int total = 0, committed = 0;
        try {
            String preScopes = ghPreflightScopes(src);
            if (preScopes != null) return preScopes;
            ghSetPending(full, br, proj, mirror, msg); // يبقى محفوظًا حتى ينتهي الرفع بنجاح
            progress("يقرأ حالة الفرع على GitHub ...");
            String parent = new JSONObject(ghGet("/repos/" + full + "/git/ref/heads/" + ghEncPath(br))).getJSONObject("object").getString("sha");
            String baseTree = new JSONObject(ghGet("/repos/" + full + "/git/commits/" + parent)).getJSONObject("tree").getString("sha");
            JSONObject rt = new JSONObject(ghGet("/repos/" + full + "/git/trees/" + baseTree + "?recursive=1"));
            java.util.HashMap<String, String> remote = new java.util.HashMap<>();
            org.json.JSONArray rtree = rt.getJSONArray("tree");
            for (int i = 0; i < rtree.length(); i++) {
                JSONObject e = rtree.getJSONObject(i);
                if ("blob".equals(e.optString("type"))) remote.put(e.getString("path"), e.getString("sha"));
            }
            List<File> files = new ArrayList<>();
            List<String> rels = new ArrayList<>();
            mdCollect(src, "", 0, files, rels);
            boolean bigNow = false;
            for (File bf : files) if (bf.length() > ghMaxFile() && bf.length() <= GH_ASSET_MAX) { bigNow = true; break; }
            ghWfPlan(remote, bigNow);
            java.util.ArrayList<GhPushItem> todo = new java.util.ArrayList<>();
            java.util.HashSet<String> local = new java.util.HashSet<>();
            int nNew = 0, nMod = 0, nSame = 0, nSkip = 0;
            java.util.ArrayList<String> skipInfo = new java.util.ArrayList<>();
            java.util.LinkedHashMap<String, File> bigMap = new java.util.LinkedHashMap<>();
            for (int i = 0; i < files.size(); i++) {
                String rel = rels.get(i);
                File f = files.get(i);
                String low = rel.toLowerCase(java.util.Locale.US);
                String why = null;
                if (rel.equals("local.properties")) why = "خاص بجهازك (مسارات SDK)";
                else if (low.endsWith(".keystore") || low.endsWith(".jks")) why = "ملف مفاتيح توقيع (سري، يُترك عمدًا)";
                else if (f.length() > GH_ASSET_MAX) why = (f.length() >> 20) + " م.ب — أكبر من 2 جيجا، لا يقبله Releases ولا LFS المجاني";
                else if (f.length() > ghMaxFile()) why = (f.length() >> 20) + (ghMaxFileMb() >= 99
                        ? " م.ب — أكبر من حد GitHub (100 م.ب)، يحتاج Git LFS"
                        : " م.ب — أكبر من الحد الذي حددته في الإعدادات (" + ghMaxFileMb() + " م.ب)");
                if (why != null && f.length() > ghMaxFile() && f.length() <= GH_ASSET_MAX && !rel.equals("local.properties")
                        && !low.endsWith(".keystore") && !low.endsWith(".jks") && !ghLargeMode().equals("skip")) {
                    bigMap.put(rel, f);
                    local.add(rel);
                    continue;
                }
                if (why != null) { nSkip++; skipInfo.add(rel + " — " + why); continue; }
                boolean big = f.length() > GH_MEM_FILE;
                String lsha;
                long fsize;
                if (big) {
                    lsha = ghBlobShaFile(f);
                    fsize = f.length();
                } else {
                    byte[] data = ghFixWf(rel, Compat.readAllBytes(f));
                    lsha = ghBlobSha(data);
                    fsize = data.length;
                }
                local.add(rel);
                String rsha = remote.get(rel);
                if (lsha.equals(rsha)) { nSame++; continue; }
                if (rsha == null) nNew++; else nMod++;
                GhPushItem it = new GhPushItem();
                it.rel = rel;
                it.f = f;
                it.mode = rel.equals("gradlew") || rel.endsWith(".sh") ? "100755" : "100644";
                it.size = fsize;
                it.big = big;
                todo.add(it);
            }
            GhLarge lg = new GhLarge();
            if (!bigMap.isEmpty()) {
                lg = ghLargeProcess(full, br, bigMap, remote);
                local.add("large-files.json");
                local.add(".gitattributes");
            }
            java.util.ArrayList<String> dels = new java.util.ArrayList<>();
            if (mirror) for (String k : remote.keySet()) if (!local.contains(k)) dels.add(k);
            if (todo.isEmpty() && dels.isEmpty() && lg.texts.isEmpty()) {
                ghClearPending();
                return "لا توجد تغييرات للرفع: كل الملفات (" + nSame + ") مطابقة لـ GitHub." + lg.summary();
            }
            total = todo.size();
            // تقسيم إلى دفعات
            java.util.ArrayList<java.util.ArrayList<GhPushItem>> steps = new java.util.ArrayList<>();
            java.util.ArrayList<GhPushItem> cur = new java.util.ArrayList<>();
            long curBytes = 0;
            final int maxFiles = ghBatchFiles();
            final long maxBytes = ghBatchMb() * (1L << 20);
            for (GhPushItem it : todo) {
                if (!cur.isEmpty() && (cur.size() >= maxFiles || curBytes + it.size > maxBytes)) {
                    steps.add(cur);
                    cur = new java.util.ArrayList<>();
                    curBytes = 0;
                }
                cur.add(it);
                curBytes += it.size;
            }
            if (!cur.isEmpty() || steps.isEmpty()) steps.add(cur);
            int nSteps = steps.size();
            String lastCommit = null;
            for (int si = 0; si < nSteps; si++) {
                java.util.ArrayList<GhPushItem> st = steps.get(si);
                progress("الجزء " + (si + 1) + "/" + nSteps + " — رُفع " + committed + " من " + total + " ملف ...");
                org.json.JSONArray entries = new org.json.JSONArray();
                final java.util.concurrent.ExecutorService pool = java.util.concurrent.Executors.newFixedThreadPool(6);
                final java.util.ArrayList<java.util.concurrent.Future<JSONObject>> futs = new java.util.ArrayList<>();
                try {
                for (GhPushItem it : st) {
                    if (it.big) {
                        progress("يرفع ملفًا كبيرًا: " + it.rel + " (" + (it.size >> 20) + " م.ب) ...");
                        JSONObject teb = ghTreeEntry(it.rel, it.mode);
                        teb.put("sha", ghUploadBlobStreamRetry(full, it.f));
                        entries.put(teb);
                        continue;
                    }
                    byte[] data = ghFixWf(it.rel, Compat.readAllBytes(it.f));
                    JSONObject te = ghTreeEntry(it.rel, it.mode);
                    String asText = null;
                    if (looksText(data)) {
                        String t = new String(data, StandardCharsets.UTF_8);
                        if (java.util.Arrays.equals(t.getBytes(StandardCharsets.UTF_8), data)) asText = t;
                    }
                    if (asText != null) {
                        te.put("content", asText);
                    } else {
                        // الملفات الثنائية تُرفع بالتوازي (6 اتصالات) بدل واحد تلو الآخر
                        final JSONObject fte = te;
                        final byte[] fdata = data;
                        final String frel = it.rel;
                        futs.add(pool.submit(() -> {
                            String b64 = android.util.Base64.encodeToString(fdata, android.util.Base64.NO_WRAP);
                            fte.put("sha", new JSONObject(ghHttpRetry("POST", "/repos/" + full + "/git/blobs", jsonOf("content", b64, "encoding", "base64"))).getString("sha"));
                            return fte;
                        }));
                        continue;
                    }
                    entries.put(te);
                }
                int bdone = 0;
                for (java.util.concurrent.Future<JSONObject> fu : futs) {
                    try { entries.put(fu.get()); }
                    catch (java.util.concurrent.ExecutionException ee) { throw ee.getCause() instanceof Exception ? (Exception) ee.getCause() : ee; }
                    bdone++;
                    if (bdone % 5 == 0 || bdone == futs.size()) progress("الجزء " + (si + 1) + "/" + nSteps + " — رُفع " + bdone + "/" + futs.size() + " ملفًا ثنائيًا ...");
                }
                } finally { pool.shutdownNow(); }
                if (si == nSteps - 1) {
                    for (String d : dels) {
                        JSONObject te = ghTreeEntry(d, "100644");
                        te.put("sha", JSONObject.NULL);
                        entries.put(te);
                    }
                    ghMergeLarge(entries, lg);
                    ghPatchRemoteWorkflows(full, br, entries, remote);
                }
                JSONObject tb = new JSONObject();
                tb.put("base_tree", baseTree);
                tb.put("tree", entries);
                String newTree = new JSONObject(ghHttpRetry("POST", "/repos/" + full + "/git/trees", tb.toString())).getString("sha");
                JSONObject cb = new JSONObject();
                cb.put("message", nSteps > 1 ? msg + " (" + (si + 1) + "/" + nSteps + ")" + (ghSkipCi() && si < nSteps - 1 ? " [skip ci]" : "") : msg);
                cb.put("tree", newTree);
                cb.put("parents", new org.json.JSONArray().put(parent));
                String newCommit = new JSONObject(ghHttpRetry("POST", "/repos/" + full + "/git/commits", cb.toString())).getString("sha");
                ghHttpRetry("PATCH", "/repos/" + full + "/git/refs/heads/" + ghEncPath(br), jsonOf("sha", newCommit));
                parent = newCommit;
                baseTree = newTree;
                lastCommit = newCommit;
                committed += st.size();
            }
            ghClearPending();
            return "تم الرفع إلى " + full + " (" + br + ") ✔\nجديد: " + nNew + " | معدّل: " + nMod + (mirror ? " | محذوف: " + dels.size() : "")
                    + " | بلا تغيير: " + nSame + (nSkip > 0 ? " | متجاهل (مفاتيح/محلي/كبير): " + nSkip : "")
                    + (nSteps > 1 ? "\nعلى " + nSteps + " إيداعات" + (ghSkipCi() ? " (البناء التلقائي يعمل للأخير فقط)" : "") : "")
                    + "\nالإيداع: " + (lastCommit == null ? "" : lastCommit.substring(0, 7))
                    + ghSkipSummary(skipInfo) + lg.summary();
        } catch (Throwable e) {
            String m = String.valueOf(e.getMessage());
            if (m.startsWith("409") || m.contains("empty")) m += "\nإن كان المستودع فارغًا: أنشئ فيه أول ملف من «تصفح الملفات» ثم أعد الرفع.";
            if (m.contains("الرمز غير صالح")) m += "\n🔑 رمز GitHub منتهٍ أو ملغى: افتح قائمة GitHub ← «الحساب وتسجيل الدخول» وأدخل رمزًا جديدًا (بصلاحيتي repo و workflow)، ثم اضغط «مواصلة الرفع».";
            if (m.contains("workflow") && (m.contains("صلاحية workflow") || m.toLowerCase(java.util.Locale.US).contains("`workflow` scope")))
                m += "\n🔑 أنشئ رمزًا جديدًا: Classic مع تفعيل repo و workflow، أو Fine-grained مع Contents وWorkflows = Read and write. ضعه من «الحساب وتسجيل الدخول» ثم اضغط «مواصلة الرفع».";
            return "فشل الرفع: " + m
                    + (total > 0 ? "\nرُفع وحُفظ على GitHub: " + committed + " من " + total + " ملف." : "")
                    + "\n⏸ الرفع معلّق: افتح «مستودعاتي» (أو قائمة GitHub) ثم اضغط «مواصلة الرفع» لإكمال الباقي فقط دون إعادة ما رُفع.";
        }
    }

    // زر «رفع إلى GitHub» في إعدادات المشروع: يستخدم المستودع المحفوظ لهذا المشروع
    private void ghPushFromSetup(final String pn) {
        if (ghBlocked()) return;
        if (ghMgrToken().isEmpty()) { ghToast("سجّل الدخول إلى GitHub أولًا."); ghLogin(); return; }
        String mode = uiPrefs().getString("gh_repomode_" + pn, "existing");
        final String val = uiPrefs().getString("gh_repourl_" + pn, "").trim();
        if (val.isEmpty()) { ghToast("أدخل رابط المستودع أو اسمه أولًا."); return; }
        if (mode.equals("existing")) {
            java.util.regex.Matcher m = java.util.regex.Pattern
                    .compile("(?:github\\.com[:/]+)?([A-Za-z0-9_.-]+)/([A-Za-z0-9_.-]+?)(?:\\.git)?/?$").matcher(val);
            if (!m.find()) { ghToast("تعذّر فهم رابط المستودع."); return; }
            final String full = m.group(1) + "/" + m.group(2);
            this.<String>ghAsync(() -> new JSONObject(ghGet("/repos/" + full)).optString("default_branch", "main"), (br, err) -> {
                if (err != null) { ghToast("تعذّر الوصول للمستودع: " + err); return; }
                ghUploadModeStep(full, br, pn);
            });
        } else {
            final String name = val.replaceAll("[^A-Za-z0-9._-]", "-");
            ghConfirm("إنشاء مستودع «" + name + "»؟", "سيُنشأ مستودع خاص جديد ثم يُرفع إليه المشروع.", () ->
                    this.<JSONObject>ghAsync(() -> new JSONObject(ghHttp("POST", "/user/repos", jsonOf("name", name, "private", true, "auto_init", true), null)), (r, err) -> {
                        if (err != null) { ghToast("فشل الإنشاء: " + err); return; }
                        uiPrefs().edit().putString("gh_repomode_" + pn, "existing").putString("gh_repourl_" + pn, r.optString("html_url")).apply();
                        ghUploadModeStep(r.optString("full_name"), r.optString("default_branch", "main"), pn);
                    }));
        }
    }

    // ===== تسجيل الدخول إلى GitHub: رمز مباشر / عبر المتصفح (Device Flow) / اسم مستخدم + رمز =====
    private String ghForm(String url, String form) throws Exception {
        if (!ghEnabled()) throw new IOException(GH_OFF_MSG);
        java.net.HttpURLConnection c = (java.net.HttpURLConnection) new java.net.URL(url).openConnection();
        try {
            c.setConnectTimeout(20000);
            c.setReadTimeout(30000);
            c.setRequestMethod("POST");
            c.setRequestProperty("Accept", "application/json");
            c.setRequestProperty("User-Agent", "L2SBuilder");
            c.setRequestProperty("Content-Type", "application/x-www-form-urlencoded");
            c.setDoOutput(true);
            byte[] b = form.getBytes(StandardCharsets.UTF_8);
            c.setFixedLengthStreamingMode(b.length);
            try (OutputStream os = c.getOutputStream()) { os.write(b); }
            int rc = c.getResponseCode();
            InputStream is = rc >= 400 ? c.getErrorStream() : c.getInputStream();
            String body = "";
            if (is != null) {
                try (InputStream in = is) {
                    byte[] all = readCapped(in, 1L << 20);
                    if (all != null) body = new String(all, StandardCharsets.UTF_8);
                }
            }
            if (rc >= 400) throw new IOException(rc + ": " + body);
            return body;
        } finally {
            c.disconnect();
        }
    }

    // يتحقق من اسم المستخدم + السر بمصادقة Basic؛ GitHub يقبل رمز الوصول في خانة كلمة المرور فقط
    private JSONObject ghBasicUser(String user, String secret) throws Exception {
        if (!ghEnabled()) throw new IOException(GH_OFF_MSG);
        java.net.HttpURLConnection c = (java.net.HttpURLConnection) new java.net.URL(GH_API + "/user").openConnection();
        try {
            c.setConnectTimeout(20000);
            c.setReadTimeout(30000);
            String cred = android.util.Base64.encodeToString((user + ":" + secret).getBytes(StandardCharsets.UTF_8), android.util.Base64.NO_WRAP);
            c.setRequestProperty("Authorization", "Basic " + cred);
            c.setRequestProperty("Accept", "application/vnd.github+json");
            c.setRequestProperty("User-Agent", "L2SBuilder");
            int rc = c.getResponseCode();
            InputStream is = rc >= 400 ? c.getErrorStream() : c.getInputStream();
            String body = "";
            if (is != null) {
                try (InputStream in = is) {
                    byte[] all = readCapped(in, 1L << 20);
                    if (all != null) body = new String(all, StandardCharsets.UTF_8);
                }
            }
            if (rc == 200) return new JSONObject(body);
            if (rc == 401) throw new IOException("401: اسم المستخدم أو السر غير صحيح.\nGitHub لا يقبل كلمة مرور الحساب نفسها منذ 2021؛ ضع في خانة كلمة المرور «رمز وصول شخصي» (ghp_... أو github_pat_...) أو استخدم الدخول عبر المتصفح.");
            throw ghError(rc, body);
        } finally {
            c.disconnect();
        }
    }

    private void ghLoggedIn(GhScreen s) {
        if (s != null && s.alive) s.dlg.dismiss();
        navReset(); // الرجوع من الرئيسية يخرج، ولا يعيد إلى شاشة تسجيل الدخول
        ghHome();
    }

    private void ghLogin() {
        if (ghBlocked()) return;
        final GhScreen s = ghOpen("ghLogin", "تسجيل الدخول إلى GitHub", () -> ghLogin());
        String tok = ghMgrToken();
        String who = uiPrefs().getString("gh_login", "");
        ghNote(s.box, tok.isEmpty() ? "غير مسجّل الدخول. اختر إحدى الطرق:" : "مسجّل الدخول" + (who.isEmpty() ? "" : " باسم " + who) + ".");
        addMenuSectionHeader(s.box, "طرق الدخول");
        addMenuCard(s.box, "\uD83C\uDF10", "الدخول عبر المتصفح", "يفتح صفحة GitHub لتوافق، ثم يكمل التطبيق تلقائيًا", "#4CAF50", () -> ghDeviceLogin(s));
        addMenuCard(s.box, "\uD83D\uDC64", "اسم المستخدم + رمز الوصول", "يتحقق من الحساب ثم يحفظ الدخول", "#2196F3", () -> ghUserPassDialog(s));
        addMenuCard(s.box, "\uD83D\uDD11", "لصق رمز وصول مباشرة", "ghp_... أو github_pat_...", "#3F51B5", () -> ghEditToken(null, () -> ghLoggedIn(s)));
        addMenuSectionHeader(s.box, "إعدادات");
        String cid = uiPrefs().getString("gh_client_id", "");
        addMenuCard(s.box, "\u2699", "معرّف تطبيق OAuth (Client ID)", cid.isEmpty() ? "مطلوب للدخول عبر المتصفح" : cid, "#795548", () -> ghAskClientId(null));
        addMenuCard(s.box, "\uD83D\uDD17", "فتح رابط GitHub", "الصق رابط مستودع أو ملف أو طلب دمج", "#FF9800", () -> ghOpenLink());
        if (!tok.isEmpty()) {
            addMenuCard(s.box, "\uD83D\uDEAA", "تسجيل الخروج", "يمسح الرمز المحفوظ من الجهاز", "#F44336", () ->
                    ghConfirm("تسجيل الخروج؟", "سيُمسح رمز GitHub المحفوظ من هذا الجهاز.", () -> {
                        uiPrefs().edit().remove("gh_token_shared").remove("gh_login").apply();
                        s.dlg.dismiss();
                        ghLogin();
                    }));
        }
    }

    private void ghAskClientId(final Runnable then) {
        final android.widget.EditText et = new android.widget.EditText(this);
        et.setHint("Client ID");
        et.setText(uiPrefs().getString("gh_client_id", ""));
        et.setTextDirection(View.TEXT_DIRECTION_LTR);
        new NavAlertBuilder()
                .setTitle("معرّف تطبيق OAuth")
                .setMessage("للدخول عبر المتصفح تحتاج تطبيق OAuth خاصًا بك (مرة واحدة):\n"
                        + "GitHub ← Settings ← Developer settings ← OAuth Apps ← New OAuth App.\n"
                        + "اكتب أي اسم وأي رابط، وفعّل الخيار «Enable Device Flow»، ثم انسخ Client ID والصقه هنا.")
                .setView(et)
                .setPositiveButton("حفظ", (d, w) -> {
                    uiPrefs().edit().putString("gh_client_id", et.getText().toString().trim()).apply();
                    if (then != null) then.run();
                })
                .setNegativeButton("إلغاء", null)
                .show();
    }

    private void ghDeviceLogin(final GhScreen s) {
        final String cid = uiPrefs().getString("gh_client_id", "").trim();
        if (cid.isEmpty()) { ghAskClientId(() -> ghDeviceLogin(s)); return; }
        ghToast("جارٍ طلب رمز الدخول ...");
        this.<JSONObject>ghAsync(() -> new JSONObject(ghForm("https://github.com/login/device/code",
                "client_id=" + ghEnc(cid) + "&scope=" + ghEnc("repo read:user notifications"))), (r, err) -> {
            if (err != null) { ghToast("تعذّر البدء: " + err); return; }
            if (r.has("error")) {
                String e = r.optString("error");
                ghToast(r.optString("error_description", e) + (e.equals("device_flow_disabled") ? "\nفعّل Device Flow في إعدادات تطبيق OAuth." : ""));
                return;
            }
            ghDeviceShow(s, cid, r);
        });
    }

    private void ghDeviceShow(final GhScreen s, final String cid, JSONObject r) {
        final String code = r.optString("user_code");
        final String uri = r.optString("verification_uri", "https://github.com/login/device");
        final String dev = r.optString("device_code");
        final int expires = r.optInt("expires_in", 900);
        final int[] interval = {Math.max(5, r.optInt("interval", 5))};
        final java.util.concurrent.atomic.AtomicBoolean stop = new java.util.concurrent.atomic.AtomicBoolean(false);
        final android.app.AlertDialog d = new NavAlertBuilder()
                .setTitle("الدخول عبر المتصفح")
                .setMessage("1) افتح الرابط:\n" + uri + "\n\n2) أدخل هذا الرمز:\n\n      " + code + "\n\n3) وافق على الطلب. سيكتمل الدخول هنا تلقائيًا.")
                .setPositiveButton("فتح المتصفح", null)
                .setNeutralButton("نسخ الرمز", null)
                .setNegativeButton("إلغاء", null)
                .create();
        d.setOnDismissListener(x -> stop.set(true));
        d.show();
        d.getButton(android.app.AlertDialog.BUTTON_POSITIVE).setOnClickListener(v -> {
            try { startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(uri))); } catch (Throwable e) { ghToast("لا يوجد متصفح على الجهاز"); }
        });
        d.getButton(android.app.AlertDialog.BUTTON_NEUTRAL).setOnClickListener(v -> {
            ClipboardManager cm = (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
            if (cm != null) cm.setPrimaryClip(ClipData.newPlainText("code", code));
            Toast.makeText(this, "تم نسخ الرمز", Toast.LENGTH_SHORT).show();
        });
        new Thread(() -> {
            long end = System.currentTimeMillis() + expires * 1000L;
            while (!stop.get() && System.currentTimeMillis() < end) {
                try { Thread.sleep(interval[0] * 1000L); } catch (InterruptedException ie) { return; }
                if (stop.get()) return;
                if (!ghEnabled()) { runOnUiThread(() -> { stop.set(true); d.dismiss(); }); return; }
                try {
                    JSONObject t = new JSONObject(ghForm("https://github.com/login/oauth/access_token",
                            "client_id=" + ghEnc(cid) + "&device_code=" + ghEnc(dev) + "&grant_type=" + ghEnc("urn:ietf:params:oauth:grant-type:device_code")));
                    String tok = t.optString("access_token", "");
                    if (!tok.isEmpty()) {
                        uiPrefs().edit().putString("gh_token_shared", tok).apply();
                        runOnUiThread(() -> {
                            stop.set(true);
                            d.dismiss();
                            ghToast("تم تسجيل الدخول ✔");
                            ghLoggedIn(s);
                        });
                        return;
                    }
                    String e = t.optString("error");
                    if (e.equals("slow_down")) {
                        interval[0] = t.optInt("interval", interval[0] + 5);
                    } else if (!e.equals("authorization_pending") && !e.isEmpty()) {
                        final String m = t.optString("error_description", e);
                        runOnUiThread(() -> { stop.set(true); d.dismiss(); ghToast("فشل الدخول: " + m); });
                        return;
                    }
                } catch (Throwable ex) {
                    // انقطاع مؤقت في الشبكة: نكمل المحاولة
                }
            }
            runOnUiThread(() -> {
                if (!stop.get()) { stop.set(true); d.dismiss(); ghToast("انتهت مهلة الرمز، أعد المحاولة"); }
            });
        }).start();
    }

    private void ghUserPassDialog(final GhScreen s) {
        LinearLayout lay = new LinearLayout(this);
        lay.setOrientation(LinearLayout.VERTICAL);
        lay.setPadding(dp(16), dp(8), dp(16), dp(8));
        final android.widget.EditText u = new android.widget.EditText(this);
        u.setHint("اسم المستخدم");
        u.setSingleLine(true);
        u.setTextDirection(View.TEXT_DIRECTION_LTR);
        lay.addView(u);
        final android.widget.EditText p = new android.widget.EditText(this);
        p.setHint("رمز الوصول (في خانة كلمة المرور)");
        p.setSingleLine(true);
        p.setInputType(android.text.InputType.TYPE_CLASS_TEXT | android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);
        p.setTextDirection(View.TEXT_DIRECTION_LTR);
        lay.addView(p);
        TextView hint = new TextView(this);
        hint.setText("ملاحظة: GitHub يرفض كلمة مرور الحساب العادية، ويقبل رمز الوصول الشخصي مكانها.");
        hint.setTextSize(12);
        hint.setPadding(0, dp(8), 0, 0);
        lay.addView(hint);
        new NavAlertBuilder()
                .setTitle("اسم المستخدم + رمز")
                .setView(lay)
                .setPositiveButton("دخول", (d, w) -> {
                    final String user = u.getText().toString().trim();
                    final String secret = p.getText().toString().trim();
                    if (user.isEmpty() || secret.isEmpty()) { ghToast("أكمل الخانتين"); return; }
                    ghToast("جارٍ التحقق ...");
                    this.<JSONObject>ghAsync(() -> ghBasicUser(user, secret), (r, err) -> {
                        if (err != null) { ghToast("فشل الدخول: " + err); return; }
                        uiPrefs().edit().putString("gh_token_shared", secret).putString("gh_login", r.optString("login", user)).apply();
                        ghToast("تم الدخول باسم " + r.optString("login", user) + " ✔");
                        ghLoggedIn(s);
                    });
                })
                .setNegativeButton("إلغاء", null)
                .show();
    }

    // فتح رابط من المتصفح: مستودع / ملف / مجلد / طلب دمج / مشكلة / إيداع
    private void ghOpenLink() {
        if (ghBlocked()) return;
        String pre = "";
        try {
            ClipboardManager cm = (ClipboardManager) getSystemService(Context.CLIPBOARD_SERVICE);
            if (cm != null && cm.hasPrimaryClip() && cm.getPrimaryClip().getItemCount() > 0) {
                CharSequence cs = cm.getPrimaryClip().getItemAt(0).getText();
                if (cs != null && cs.toString().contains("github.com")) pre = cs.toString().trim();
            }
        } catch (Throwable ignored) {}
        ghPrompt("افتح رابط GitHub", "https://github.com/user/repo", pre, v -> ghGoLink(v));
    }

    private void ghGoLink(String url) {
        java.util.regex.Matcher m = java.util.regex.Pattern.compile(
                "github\\.com/([A-Za-z0-9_.-]+)/([A-Za-z0-9_.-]+?)(?:\\.git)?(?:/(pull|pulls|issues|blob|tree|commit|commits)/([^#?\\s]*))?(?:[#?].*)?/?$")
                .matcher(url.trim());
        if (!m.find()) { ghToast("رابط غير مفهوم. مثال: https://github.com/user/repo"); return; }
        final String full = m.group(1) + "/" + m.group(2);
        final String kind = m.group(3);
        String rest = m.group(4) == null ? "" : m.group(4);
        while (rest.endsWith("/")) rest = rest.substring(0, rest.length() - 1);
        if (kind == null) { ghRepo(full, null); return; }
        if (kind.startsWith("pull") || kind.equals("issues")) {
            java.util.regex.Matcher nm = java.util.regex.Pattern.compile("^(\\d+)").matcher(rest);
            if (!nm.find()) { ghRepo(full, null); return; }
            int n = Integer.parseInt(nm.group(1));
            if (kind.startsWith("pull")) ghPullDetail(full, n); else ghIssueDetail(full, null, n);
        } else if (kind.startsWith("commit")) {
            if (rest.isEmpty()) ghRepo(full, null); else ghCommitDetail(full, "", rest.split("/")[0], 1);
        } else {
            int sl = rest.indexOf('/');
            String br = sl < 0 ? rest : rest.substring(0, sl);
            String path = sl < 0 ? "" : rest.substring(sl + 1);
            if (br.isEmpty()) { ghRepo(full, null); return; }
            if (kind.equals("blob") && !path.isEmpty()) ghOpenFile(full, br, path);
            else ghBrowse(full, br, path);
        }
    }

