    // كل الخيارات العميقة الحالية تابعة إمّا لشاشة "إعدادات الطرفية"، أو GitHub، أو
    // أزرار الشريط العلوي/السفلي؛ نُصنِّفها هنا تحت نفس أقسام termMenuCategory حتى
    // تظهر منظّمة في شاشة "اختر خيارًا لإضافته كاختصار".
    private String deepMenuCategory(String id) {
        if (id.startsWith("d_gh_") || id.startsWith("d_term_gradledist_")) return "الاتصال والصيانة";
        if (id.startsWith(TOPBTN_EDIT_PREFIX) || id.equals("d_topbtn_reset")
                || id.startsWith(BOTBTN_EDIT_PREFIX) || id.equals("d_botbtn_display_toggle")) return "الواجهة";
        return "الإعداد والطرفية";
    }

    // اسم الشاشة الأم لكل مجموعة خيارات عميقة، تُستخدم في عنوان فرعي بشاشة الإضافة.
    private String deepMenuParentLabel(String id) {
        if (id.startsWith("d_gh_")) return "إعدادات GitHub";
        if (id.startsWith("d_term_gradledist_")) return "قسم التنظيفات";
        if (id.startsWith(TOPBTN_EDIT_PREFIX) || id.equals("d_topbtn_reset")) return "أزرار الشريط العلوي";
        if (id.startsWith(BOTBTN_EDIT_PREFIX) || id.equals("d_botbtn_display_toggle")) return "أزرار الشريط السفلي";
        return "إعدادات الطرفية";
    }

    // ينفّذ الخيار العميق مباشرة (بدون فتح الشاشة الأم كاملة) — يُستدعى من الوصول السريع (⚡) فقط.
    private void deepMenuRun(String id) {
        if (id.startsWith(TOPBTN_EDIT_PREFIX)) {
            String bid = id.substring(TOPBTN_EDIT_PREFIX.length());
            String label = deepMenuLabel(id).replaceFirst("^تعديل زر: ", "");
            editButtonDialog(bid, label, bid.equals("top_more"));
            return;
        }
        if (id.startsWith(BOTBTN_EDIT_PREFIX)) {
            String bid = id.substring(BOTBTN_EDIT_PREFIX.length());
            String[] meta = BOT_BTN_META.get(bid);
            if (meta != null) editButtonDialog(bid, meta[0], bid.equals("bot_exec"));
            return;
        }
        switch (id) {
            case "d_term_theme_auto": uiPrefs().edit().putString("theme", "auto").apply(); termHome(); break;
            case "d_term_theme_light": uiPrefs().edit().putString("theme", "light").apply(); termHome(); break;
            case "d_term_theme_dark": uiPrefs().edit().putString("theme", "dark").apply(); termHome(); break;
            case "d_term_theme_amoled": uiPrefs().edit().putString("theme", "amoled").apply(); termHome(); break;
            case "d_term_theme_pro": uiPrefs().edit().putString("theme", "pro").apply(); termHome(); break;
            case "d_term_theme_schedule":
                uiPrefs().edit().putString("theme", "schedule").apply();
                termHome();
                termScheduleHourDialog(true);
                break;
            case "d_term_fsize_10": uiPrefs().edit().putInt("fsize", 10).apply(); termHome(); break;
            case "d_term_fsize_12": uiPrefs().edit().putInt("fsize", 12).apply(); termHome(); break;
            case "d_term_fsize_14": uiPrefs().edit().putInt("fsize", 14).apply(); termHome(); break;
            case "d_term_fsize_16": uiPrefs().edit().putInt("fsize", 16).apply(); termHome(); break;
            case "d_term_keepon":
                uiPrefs().edit().putBoolean("keepon", !uiPrefs().getBoolean("keepon", true)).apply();
                termHome();
                break;
            case "d_term_cmdlimit": termCmdLimitDialog(); break;
            case "d_term_gradledist_keep": uiPrefs().edit().putString("gradle_local_dist_mode", "keep").apply(); termHome(); break;
            case "d_term_gradledist_compressed": uiPrefs().edit().putString("gradle_local_dist_mode", "compressed").apply(); termHome(); break;
            case "d_term_gradledist_delete": uiPrefs().edit().putString("gradle_local_dist_mode", "delete").apply(); termHome(); break;
            case "d_gh_tokmode_toggle": {
                boolean sharedTok = uiPrefs().getString("gh_tokmode", "shared").equals("shared");
                uiPrefs().edit().putString("gh_tokmode", sharedTok ? "perproj" : "shared").apply();
                Toast.makeText(this, "تم التبديل", Toast.LENGTH_SHORT).show();
                break;
            }
            case "d_gh_msgmode_toggle": {
                boolean autoMsg = uiPrefs().getString("gh_msgmode", "manual").equals("auto");
                uiPrefs().edit().putString("gh_msgmode", autoMsg ? "manual" : "auto").apply();
                Toast.makeText(this, "تم التبديل", Toast.LENGTH_SHORT).show();
                break;
            }
            case "d_gh_edittoken_shared": ghEditToken(null); break;
            case "d_topbtn_reset": {
                android.content.SharedPreferences.Editor ed = uiPrefs().edit();
                for (String bid : new String[]{"top_quick", "top_switch", "top_more"}) {
                    ed.remove("btnvis_" + bid).remove("btnsize_" + bid).remove("btnpadh_" + bid).remove("btnpadv_" + bid);
                }
                ed.apply();
                termHome();
                break;
            }
            case "d_botbtn_display_toggle": {
                boolean textMode = botTextMode();
                uiPrefs().edit().putString("bot_display_mode", textMode ? "icon" : "text").apply();
                termHome();
                break;
            }
        }
    }

    // لمسة طويلة على أي خيار "عميق" في مكانه الطبيعي (بدل تنفيذه) تعرض هذا
    // التأكيد لإضافته كاختصار في الوصول السريع (⚡) — دون أي "وضع" خاص يُفعَّل
    // أو يُنسى مفعّلًا: الضغطة العادية تبقى تنفّذ الخيار كالمعتاد دائمًا.
    private void offerAddShortcut(final String id) {
        String label = deepMenuLabel(id);
        new NavAlertBuilder()
                .setTitle("إضافة اختصار")
                .setMessage("إضافة \"" + label + "\" إلى الوصول السريع (⚡)؟")
                .setPositiveButton("إضافة", (d, w) -> {
                    java.util.List<String> order = new java.util.ArrayList<>(quickAccessOrder());
                    if (order.contains(id)) {
                        Toast.makeText(this, "موجود بالفعل في الوصول السريع", Toast.LENGTH_SHORT).show();
                    } else {
                        order.add(id);
                        quickAccessSaveOrder(order);
                        Toast.makeText(this, "أُضيف إلى الوصول السريع ⚡", Toast.LENGTH_SHORT).show();
                    }
                })
                .setNegativeButton("إلغاء", null)
                .show();
    }

