    // كشف لمسة طويلة يدوي (بدل الاعتماد فقط على setOnLongClickListener الجاهز من
    // أندرويد، الذي لوحظ أنه لا يعمل بثبات على بعض الشاشات) — يعتمد على مؤقّت
    // (Handler) يُطلَق بعد مهلة اللمس الطويل القياسية، ويُلغى إن تحرك الإصبع أكثر
    // من الحد المسموح (touch slop) أو رُفعت الإصبع قبل انتهاء المهلة. هذا يوحّد
    // سلوك الضغط العادي/الطويل عبر كل البطاقات مهما كانت الشاشة الحاوية لها.
    private void attachClickAndLongPress(final View v, final Runnable action, final Runnable longPress) {
        v.setClickable(true);
        v.setFocusable(true);
        if (longPress == null) {
            v.setOnClickListener(vv -> action.run());
            return;
        }
        v.setLongClickable(true);
        final android.os.Handler handler = new android.os.Handler(android.os.Looper.getMainLooper());
        final boolean[] longFired = {false};
        final boolean[] moved = {false};
        final float[] start = {0f, 0f};
        final Runnable[] pending = {null};
        final int touchSlop = android.view.ViewConfiguration.get(v.getContext()).getScaledTouchSlop();
        v.setOnTouchListener((view, event) -> {
            switch (event.getActionMasked()) {
                case android.view.MotionEvent.ACTION_DOWN:
                    longFired[0] = false;
                    moved[0] = false;
                    start[0] = event.getRawX();
                    start[1] = event.getRawY();
                    pending[0] = () -> {
                        longFired[0] = true;
                        view.performHapticFeedback(android.view.HapticFeedbackConstants.LONG_PRESS);
                        longPress.run();
                    };
                    handler.postDelayed(pending[0], android.view.ViewConfiguration.getLongPressTimeout());
                    return true;
                case android.view.MotionEvent.ACTION_MOVE:
                    if (!moved[0] && (Math.abs(event.getRawX() - start[0]) > touchSlop
                            || Math.abs(event.getRawY() - start[1]) > touchSlop)) {
                        moved[0] = true;
                        if (pending[0] != null) handler.removeCallbacks(pending[0]);
                    }
                    return true;
                case android.view.MotionEvent.ACTION_UP:
                    if (pending[0] != null) handler.removeCallbacks(pending[0]);
                    if (!longFired[0] && !moved[0]) {
                        view.performClick();
                        action.run();
                    }
                    return true;
                case android.view.MotionEvent.ACTION_CANCEL:
                    if (pending[0] != null) handler.removeCallbacks(pending[0]);
                    return true;
                default:
                    return false;
            }
        });
    }

    // ui54: unified card screens
    private void addMenuCard(LinearLayout container, String icon, String title, String subtitle, String colorHex, Runnable action) {
        float d = getResources().getDisplayMetrics().density;
        LinearLayout card = new LinearLayout(this);
        card.setOrientation(LinearLayout.HORIZONTAL);
        card.setGravity(android.view.Gravity.CENTER_VERTICAL);
        card.setPadding((int) (14 * d), (int) (12 * d), (int) (14 * d), (int) (12 * d));
        card.setClickable(true);
        card.setFocusable(true);

        android.graphics.drawable.GradientDrawable bg = new android.graphics.drawable.GradientDrawable();
        bg.setColor(themeCardBg());
        bg.setCornerRadius(12 * d);
        bg.setStroke(themeStrokeW(d), themeCardStroke());
        card.setBackground(bg);

        View iconView = makeIconBadge(icon, colorHex, 38, 18);
        LinearLayout.LayoutParams iconLp = new LinearLayout.LayoutParams((int) (38 * d), (int) (38 * d));
        iconLp.rightMargin = (int) (12 * d);
        card.addView(iconView, iconLp);

        LinearLayout textCol = new LinearLayout(this);
        textCol.setOrientation(LinearLayout.VERTICAL);
        TextView titleView = new TextView(this);
        titleView.setText(title);
        titleView.setTextSize(15);
        titleView.setTypeface(null, Typeface.BOLD);
        titleView.setTextColor(themeTextPrimary());
        textCol.addView(titleView);
        if (subtitle != null && !subtitle.isEmpty()) {
            TextView subView = new TextView(this);
            subView.setText(subtitle);
            subView.setTextSize(12);
            subView.setTextColor(themeTextSecondary());
            textCol.addView(subView);
        }
        card.addView(textCol, new LinearLayout.LayoutParams(0, -2, 1f));

        TextView arrow = new TextView(this);
        arrow.setText("\u2039");
        arrow.setTextSize(18);
        arrow.setGravity(android.view.Gravity.CENTER);
        arrow.setTextColor(iconContrastColor(android.graphics.Color.parseColor(colorHex), themeCardBg()));
        android.graphics.drawable.GradientDrawable arrowBg = new android.graphics.drawable.GradientDrawable();
        arrowBg.setShape(android.graphics.drawable.GradientDrawable.OVAL);
        arrowBg.setColor(android.graphics.Color.parseColor("#33888888"));
        arrow.setBackground(arrowBg);
        LinearLayout.LayoutParams arrowLp = new LinearLayout.LayoutParams((int) (40 * d), (int) (40 * d));
        arrowLp.leftMargin = (int) (10 * d);
        card.addView(arrow, arrowLp);

        card.setOnClickListener(v -> action.run());

        LinearLayout.LayoutParams cardLp = new LinearLayout.LayoutParams(-1, -2);
        cardLp.bottomMargin = (int) (8 * d);
        container.addView(card, cardLp);
    }

    // بطاقة اختيار واضحة (صندوق تحديد حقيقي): مربع مملوء بلون + علامة ✓ بيضاء عند التحديد،
    // ومربع بإطار فارغ عند عدم التحديد، وإطار/خلفية ملوّنة للبطاقة المحددة. بدون سهم تنقّل.
    private void addSelectCard(LinearLayout container, boolean checked, String title, String subtitle, String colorHex, Runnable action) {
        float d = getResources().getDisplayMetrics().density;
        int accent = android.graphics.Color.parseColor(colorHex);
        LinearLayout card = new LinearLayout(this);
        card.setOrientation(LinearLayout.HORIZONTAL);
        card.setGravity(android.view.Gravity.CENTER_VERTICAL);
        card.setPadding((int) (14 * d), (int) (12 * d), (int) (14 * d), (int) (12 * d));
        card.setClickable(true);
        card.setFocusable(true);

        android.graphics.drawable.GradientDrawable bg = new android.graphics.drawable.GradientDrawable();
        bg.setColor(checked ? ((accent & 0x00FFFFFF) | 0x22000000) : themeCardBg());
        bg.setCornerRadius(12 * d);
        bg.setStroke(checked ? (int) (2 * d) : themeStrokeW(d), checked ? accent : themeCardStroke());
        card.setBackground(bg);

        TextView box = new TextView(this);
        box.setText(checked ? "\u2714" : "");
        box.setTextSize(20);
        box.setTypeface(null, Typeface.BOLD);
        box.setTextColor(android.graphics.Color.WHITE);
        box.setGravity(android.view.Gravity.CENTER);
        android.graphics.drawable.GradientDrawable boxBg = new android.graphics.drawable.GradientDrawable();
        boxBg.setCornerRadius(8 * d);
        if (checked) {
            boxBg.setColor(accent);
        } else {
            boxBg.setColor(android.graphics.Color.TRANSPARENT);
            boxBg.setStroke((int) (2 * d), android.graphics.Color.parseColor("#9E9E9E"));
        }
        box.setBackground(boxBg);
        LinearLayout.LayoutParams boxLp = new LinearLayout.LayoutParams((int) (30 * d), (int) (30 * d));
        boxLp.rightMargin = (int) (12 * d);
        card.addView(box, boxLp);

        LinearLayout textCol = new LinearLayout(this);
        textCol.setOrientation(LinearLayout.VERTICAL);
        TextView titleView = new TextView(this);
        titleView.setText(title);
        titleView.setTextSize(15);
        titleView.setTypeface(null, Typeface.BOLD);
        titleView.setTextColor(themeTextPrimary());
        textCol.addView(titleView);
        if (subtitle != null && !subtitle.isEmpty()) {
            TextView subView = new TextView(this);
            subView.setText(subtitle);
            subView.setTextSize(12);
            subView.setTextColor(themeTextSecondary());
            textCol.addView(subView);
        }
        card.addView(textCol, new LinearLayout.LayoutParams(0, -2, 1f));

        card.setOnClickListener(v -> action.run());
        LinearLayout.LayoutParams cardLp = new LinearLayout.LayoutParams(-1, -2);
        cardLp.bottomMargin = (int) (8 * d);
        container.addView(card, cardLp);
    }

