    // نسخة عامة من شبكة الألوان: تُستخدم لتلوين زر واحد أو لتطبيق نفس اللون على مجموعة أزرار دفعة واحدة
    private void colorPaletteDialogPick(String title, java.util.function.Consumer<String> onPick) {
        final android.app.Dialog dlg = newScreen("colorPaletteDialogPick" + ":" + String.valueOf(title), () -> colorPaletteDialogPick(title, onPick));
        LinearLayout root = beginFullscreenCardDialog(dlg, title);
        LinearLayout box = (LinearLayout) root.getTag();
        float d = getResources().getDisplayMetrics().density;
        LinearLayout row = null;
        int perRow = 6;
        for (int i = 0; i < COLOR_PALETTE.length; i++) {
            if (i % perRow == 0) {
                row = new LinearLayout(this);
                row.setOrientation(LinearLayout.HORIZONTAL);
                LinearLayout.LayoutParams rowLp = new LinearLayout.LayoutParams(-1, -2);
                rowLp.bottomMargin = dp(8);
                box.addView(row, rowLp);
            }
            final String hex = COLOR_PALETTE[i];
            View sw = new View(this);
            android.graphics.drawable.GradientDrawable swBg = new android.graphics.drawable.GradientDrawable();
            swBg.setColor(android.graphics.Color.parseColor(hex));
            swBg.setCornerRadius(8 * d);
            swBg.setStroke((int) (1 * d), android.graphics.Color.parseColor("#E0E0E0"));
            sw.setBackground(swBg);
            LinearLayout.LayoutParams swLp = new LinearLayout.LayoutParams(0, dp(38), 1f);
            swLp.setMarginEnd(dp(6));
            sw.setOnClickListener(v -> {
                onPick.accept(hex);
                dlg.dismiss();
                termHome();
                if (!menuStack.isEmpty()) navBack();
            });
            row.addView(sw, swLp);
        }
        dlg.setContentView(root);
        dlg.show();
    }

