    // يرجّع ترتيب أزرار الشريط السفلي المخزّن، ويضيف تلقائيًا أي معرّف جديد غير موجود بعد
    private java.util.List<String> botButtonOrder() {
        String saved = uiPrefs().getString("botOrder", "");
        java.util.LinkedHashSet<String> order = new java.util.LinkedHashSet<>();
        if (!saved.isEmpty()) {
            for (String id : saved.split(",")) if (BOT_BTN_META.containsKey(id)) order.add(id);
        }
        for (String id : BOT_BTN_DEFAULT_ORDER) order.add(id);
        return new java.util.ArrayList<>(order);
    }

    private void saveBotButtonOrder(java.util.List<String> order) {
        uiPrefs().edit().putString("botOrder", Compat.join(",", order)).apply();
    }

    private void moveBotButton(String id, int dir) {
        java.util.List<String> order = botButtonOrder();
        int i = order.indexOf(id);
        int j = i + dir;
        if (i < 0 || j < 0 || j >= order.size()) return;
        java.util.Collections.swap(order, i, j);
        saveBotButtonOrder(order);
    }

    private void pickPreset(String title, int[] vals, java.util.function.IntConsumer onPick) {
        final android.app.Dialog dlg = newScreen("pickPreset" + ":" + String.valueOf(title), () -> pickPreset(title, vals, onPick));
        LinearLayout root = beginFullscreenCardDialog(dlg, title);
        LinearLayout box = (LinearLayout) root.getTag();
        for (int v : vals) {
            final int val = v;
            addMenuCard(box, "\uD83D\uDD22", String.valueOf(val), "#607D8B", () -> {
                onPick.accept(val);
                dlg.dismiss();
                termHome();
                if (!menuStack.isEmpty()) navBack();
            });
        }
        dlg.setContentView(root);
        dlg.show();
    }

    private void editButtonDialog(final String id, final String label, final boolean protectedBtn) {
        final String curLabel = BOT_BTN_META.containsKey(id) ? btnLabel(id, label) : label;
        final android.app.Dialog dlg = newScreen("editButtonDialog" + ":" + String.valueOf(id), () -> editButtonDialog(id, label, protectedBtn));
        LinearLayout root = beginFullscreenCardDialog(dlg, curLabel);
        LinearLayout box = (LinearLayout) root.getTag();

        String[] previewMeta = BOT_BTN_META.get(id);
        if (previewMeta != null) box.addView(buildBtnPreview(id, previewMeta));

        addToggleCard(box, protectedBtn ? "\uD83D\uDD12" : "\uD83D\uDC41", "إظهار الزر",
                protectedBtn ? "محمي (دائمًا ظاهر)" : "إيقاف = مخفي", "#795548", protectedBtn || btnVis(id),
                on -> {
                    if (protectedBtn) { Toast.makeText(this, "هذا الزر محمي ولا يمكن إخفاؤه", Toast.LENGTH_SHORT).show(); return false; }
                    uiPrefs().edit().putBoolean("btnvis_" + id, on).apply();
                    dlg.dismiss();
                    termHome();
                    editButtonDialog(id, label, protectedBtn);
                    return true;
                }, null);
        if (BOT_BTN_META.containsKey(id)) {
            addMenuCard(box, "\u270F", "تغيير اسم الزر", curLabel, "#8E24AA", () -> {
                dlg.dismiss();
                renameBotButton(id, label);
            });
            java.util.List<String> hist = btnLabelHistory(id);
            addMenuCard(box, "\uD83D\uDD70", "العودة إلى اسم سابق",
                    hist.isEmpty() ? "لا يوجد اسم سابق بعد" : Compat.join("، ", hist), "#5D4037", () -> {
                if (hist.isEmpty()) { Toast.makeText(this, "لا يوجد اسم سابق محفوظ لهذا الزر", Toast.LENGTH_SHORT).show(); return; }
                dlg.dismiss();
                btnLabelHistoryDialog(id, label);
            });
        }
        addMenuCard(box, "\uD83D\uDD24", "حجم الخط", String.valueOf(btnSize(id, 14)), "#3F51B5", () -> {
            dlg.dismiss();
            pickPreset("حجم الخط", new int[]{10, 11, 12, 13, 14, 15, 16, 18, 20}, v -> uiPrefs().edit().putInt("btnsize_" + id, v).apply());
        });
        addMenuCard(box, "\u2194", "العرض (حشو أفقي)", btnPadH(id, 8) + "dp", "#009688", () -> {
            dlg.dismiss();
            pickPreset("العرض (حشو أفقي dp)", new int[]{2, 4, 6, 8, 10, 12, 14, 16, 20, 24}, v -> uiPrefs().edit().putInt("btnpadh_" + id, v).apply());
        });
        addMenuCard(box, "\u2195", "الطول (حشو عمودي)", btnPadV(id, 6) + "dp", "#FF9800", () -> {
            dlg.dismiss();
            pickPreset("الطول (حشو عمودي dp)", new int[]{2, 4, 6, 8, 10, 12, 14, 16}, v -> uiPrefs().edit().putInt("btnpadv_" + id, v).apply());
        });
        if (BOT_BTN_META.containsKey(id)) {
            addMenuCard(box, "\uD83C\uDFA8", "لون الخلفية", "اختر من مجموعة كبيرة من الألوان", "#E91E63", () -> {
                dlg.dismiss();
                colorPaletteDialog(id);
            });
            addToggleCard(box, "\uD83D\uDEAB", "إزالة الخلفية الملونة", "تشغيل = شفاف بلا لون", "#9E9E9E", btnNoBg(id),
                    on -> {
                        uiPrefs().edit().putBoolean("btnnobg_" + id, on).apply();
                        dlg.dismiss();
                        termHome();
                        editButtonDialog(id, label, protectedBtn);
                        return true;
                    }, null);
        }
        addMenuCard(box, "\uD83D\uDD04", "إعادة تعيين للوضع الافتراضي", "يمسح كل تخصيصات هذا الزر (الاسم والحجم واللون والحشو والإظهار)", "#4CAF50", () -> {
            uiPrefs().edit()
                    .remove("btnvis_" + id)
                    .remove("btnsize_" + id)
                    .remove("btnpadh_" + id)
                    .remove("btnpadv_" + id)
                    .remove("btncolor_" + id)
                    .remove("btnnobg_" + id)
                    .remove("btnlabel_" + id)
                    .remove("btnlabelhist_" + id)
                    .apply();
            dlg.dismiss();
            termHome();
            editButtonDialog(id, label, protectedBtn);
        });

        dlg.setContentView(root);
        dlg.show();
    }

    private void topButtonsSettings() {
        // ملاحظة: زرا "بناء" و"وضع العرض" انتقلا لنافذة "الوصول السريع" (⚡)، وزر ⚡ نفسه
        // يظهر الآن كزر مستقل بالشريط العلوي جنب التبديل والإعدادات.
        final String[] ids = {"top_quick", "top_switch", "top_more"};
        final String[] labels = {"الوصول السريع", "تبديل المحرر الأساسي", "القائمة (محمي)"};
        final String[] icons = {"\u26A1", "\u21C4", "\u2699\uFE0E"};
        final String[] colors = {"#FFB300", "#00897B", "#607D8B"};
        final boolean[] prot = {false, false, true};

        final android.app.Dialog dlg = newScreen("topButtonsSettings", () -> topButtonsSettings());
        LinearLayout root = beginFullscreenCardDialog(dlg, "أزرار الشريط العلوي");
        LinearLayout box = (LinearLayout) root.getTag();
        for (int i = 0; i < ids.length; i++) {
            final int idx = i;
            addMenuCardLP(box, icons[idx], labels[idx], null, colors[idx], () -> {
                dlg.dismiss();
                editButtonDialog(ids[idx], labels[idx], prot[idx]);
            }, () -> offerAddShortcut("d_topbtn_edit_" + ids[idx]));
        }
        addMenuCardLP(box, "\uD83D\uDD04", "إعادة تعيين أزرار الشريط العلوي", "يمسح كل تخصيصات هذه الأزرار الثلاثة", "#4CAF50", () -> {
            android.content.SharedPreferences.Editor ed = uiPrefs().edit();
            for (String bid : ids) {
                ed.remove("btnvis_" + bid).remove("btnsize_" + bid).remove("btnpadh_" + bid).remove("btnpadv_" + bid);
            }
            ed.apply();
            dlg.dismiss();
            termHome();
            topButtonsSettings();
        }, () -> offerAddShortcut("d_topbtn_reset"));
        dlg.setContentView(root);
        dlg.show();
    }

    private void bottomButtonsSettings() {
        final java.util.List<String> order = botButtonOrder();
        final android.app.Dialog dlg = newScreen("bottomButtonsSettings", () -> bottomButtonsSettings());
        LinearLayout root = beginFullscreenCardDialog(dlg, "أزرار الشريط السفلي");
        LinearLayout box = (LinearLayout) root.getTag();

        TextView hint = new TextView(this);
        hint.setText("استخدم ▲▼ لتحريك الزر وترتيبه كما تريد، واضغط على الزر نفسه لتعديل إظهاره وحجمه — ولمسة طويلة لإضافته كاختصار ⚡");
        hint.setTextSize(12);
        hint.setTextColor(android.graphics.Color.parseColor("#757575"));
        LinearLayout.LayoutParams hintLp = new LinearLayout.LayoutParams(-1, -2);
        hintLp.bottomMargin = dp(10);
        box.addView(hint, hintLp);

        addToggleCard(box, "\uD83D\uDD24", "عرض الأزرار كنصوص", "إيقاف = عرض الأزرار كأيقونات", "#5D4037", botTextMode(),
                on -> {
                    uiPrefs().edit().putString("bot_display_mode", on ? "text" : "icon").apply();
                    dlg.dismiss();
                    termHome();
                    bottomButtonsSettings();
                    return true;
                }, () -> offerAddShortcut("d_botbtn_display_toggle"));

        for (int i = 0; i < order.size(); i++) {
            final String id = order.get(i);
            final boolean isProtected = id.equals("bot_exec");
            String[] meta = BOT_BTN_META.get(id);
            if (meta == null) continue;
            String label = btnLabel(id, meta[0]) + (isProtected ? " (محمي)" : "");
            String icon = botBtnIcon(id);
            final boolean canUp = i > 0;
            final boolean canDown = i < order.size() - 1;
            addReorderableMenuCard(box, icon, label, meta[1],
                    () -> { dlg.dismiss(); editButtonDialog(id, meta[0], isProtected); },
                    canUp ? () -> { moveBotButton(id, -1); dlg.dismiss(); bottomButtonsSettings(); } : null,
                    canDown ? () -> { moveBotButton(id, 1); dlg.dismiss(); bottomButtonsSettings(); } : null,
                    () -> offerAddShortcut("d_botbtn_edit_" + id));
        }
        addMenuSectionHeader(box, "تطبيق دفعة واحدة على كل الأزرار");
        addMenuCard(box, "\uD83C\uDFA8", "لون موحّد لكل الأزرار", "اختر لونًا يُطبّق فورًا على كل الأزرار", "#E91E63", () -> {
            dlg.dismiss();
            colorPaletteDialogPick("لون موحّد لكل الأزرار", hex -> {
                android.content.SharedPreferences.Editor ed = uiPrefs().edit();
                for (String bid : BOT_BTN_META.keySet()) ed.putString("btncolor_" + bid, hex).putBoolean("btnnobg_" + bid, false);
                ed.apply();
            });
        });
        addMenuCard(box, "\uD83D\uDEAB", "إزالة الخلفية من كل الأزرار", "يجعل كل الأزرار بدون لون خلفية (نص فقط)", "#9E9E9E", () -> {
            android.content.SharedPreferences.Editor ed = uiPrefs().edit();
            for (String bid : BOT_BTN_META.keySet()) ed.putBoolean("btnnobg_" + bid, true);
            ed.apply();
            dlg.dismiss();
            termHome();
            bottomButtonsSettings();
        });
        addMenuCard(box, "\uD83D\uDD24", "حجم خط موحّد لكل الأزرار", "اختر حجمًا يُطبّق على كل الأزرار دفعة واحدة", "#3F51B5", () -> {
            dlg.dismiss();
            pickPreset("حجم الخط لكل الأزرار", new int[]{10, 11, 12, 13, 14, 15, 16, 18, 20}, v -> {
                android.content.SharedPreferences.Editor ed = uiPrefs().edit();
                for (String bid : BOT_BTN_META.keySet()) ed.putInt("btnsize_" + bid, v);
                ed.apply();
            });
        });
        addMenuCard(box, "\u2194", "عرض موحّد (حشو أفقي) لكل الأزرار", "اختر قيمة تُطبّق على كل الأزرار دفعة واحدة", "#009688", () -> {
            dlg.dismiss();
            pickPreset("العرض (حشو أفقي dp) لكل الأزرار", new int[]{2, 4, 6, 8, 10, 12, 14, 16, 20, 24}, v -> {
                android.content.SharedPreferences.Editor ed = uiPrefs().edit();
                for (String bid : BOT_BTN_META.keySet()) ed.putInt("btnpadh_" + bid, v);
                ed.apply();
            });
        });
        addMenuCard(box, "\u2195", "طول موحّد (حشو عمودي) لكل الأزرار", "اختر قيمة تُطبّق على كل الأزرار دفعة واحدة", "#FF9800", () -> {
            dlg.dismiss();
            pickPreset("الطول (حشو عمودي dp) لكل الأزرار", new int[]{2, 4, 6, 8, 10, 12, 14, 16}, v -> {
                android.content.SharedPreferences.Editor ed = uiPrefs().edit();
                for (String bid : BOT_BTN_META.keySet()) ed.putInt("btnpadv_" + bid, v);
                ed.apply();
            });
        });
        addMenuSectionHeader(box, "أخرى");
        addMenuCard(box, "\uD83D\uDD04", "إعادة تعيين الشريط السفلي بالكامل", "الترتيب والأسماء والألوان والأحجام كلها للوضع الافتراضي", "#F44336", () -> {
            android.content.SharedPreferences.Editor ed = uiPrefs().edit();
            ed.remove("botOrder");
            for (String bid : BOT_BTN_META.keySet()) {
                ed.remove("btnvis_" + bid).remove("btnsize_" + bid).remove("btnpadh_" + bid)
                        .remove("btnpadv_" + bid).remove("btncolor_" + bid).remove("btnnobg_" + bid)
                        .remove("btnlabel_" + bid).remove("btnlabelhist_" + bid);
            }
            ed.apply();
            dlg.dismiss();
            termHome();
            bottomButtonsSettings();
        });
        dlg.setContentView(root);
        dlg.show();
    }

    // بطاقة إعدادات مع سهمي تحريك (▲/▼) لإعادة ترتيب العنصر ضمن قائمة، بالإضافة للضغط العادي لفتح تعديلاته
    private void addReorderableMenuCard(LinearLayout container, String icon, String title, String colorHex,
                                         Runnable action, Runnable moveUp, Runnable moveDown, Runnable longPress) {
        float d = getResources().getDisplayMetrics().density;
        LinearLayout card = new LinearLayout(this);
        card.setOrientation(LinearLayout.HORIZONTAL);
        card.setGravity(android.view.Gravity.CENTER_VERTICAL);
        card.setPadding((int) (14 * d), (int) (10 * d), (int) (10 * d), (int) (10 * d));
        card.setClickable(true);
        card.setFocusable(true);

        android.graphics.drawable.GradientDrawable bg = new android.graphics.drawable.GradientDrawable();
        bg.setColor(themeCardBg());
        bg.setCornerRadius(12 * d);
        bg.setStroke(themeStrokeW(d), themeCardStroke());
        card.setBackground(bg);

        View iconView = makeIconBadge(icon, colorHex, 34, 16);
        LinearLayout.LayoutParams iconLp = new LinearLayout.LayoutParams((int) (34 * d), (int) (34 * d));
        iconLp.rightMargin = (int) (10 * d);
        card.addView(iconView, iconLp);

        TextView titleView = new TextView(this);
        titleView.setText(title);
        titleView.setTextSize(14);
        titleView.setTypeface(null, Typeface.BOLD);
        titleView.setTextColor(themeTextPrimary());
        card.addView(titleView, new LinearLayout.LayoutParams(0, -2, 1f));

        LinearLayout moveCol = new LinearLayout(this);
        moveCol.setOrientation(LinearLayout.HORIZONTAL);
        int moveEnabled = themeIconBtn();
        int moveDisabled = themeDivider();
        Button upBtn = makeOutIconBtn("\u25B2", () -> { if (moveUp != null) moveUp.run(); });
        upBtn.setTextColor(moveUp != null ? moveEnabled : moveDisabled);
        upBtn.setEnabled(moveUp != null);
        moveCol.addView(upBtn);
        Button downBtn = makeOutIconBtn("\u25BC", () -> { if (moveDown != null) moveDown.run(); });
        downBtn.setTextColor(moveDown != null ? moveEnabled : moveDisabled);
        downBtn.setEnabled(moveDown != null);
        moveCol.addView(downBtn);
        card.addView(moveCol);

        attachClickAndLongPress(card, action, longPress);

        LinearLayout.LayoutParams cardLp = new LinearLayout.LayoutParams(-1, -2);
        cardLp.bottomMargin = (int) (8 * d);
        container.addView(card, cardLp);
    }

    // شريط واحد يتحكم بحجم خط الناتج من 8 إلى 50 (مع أزرار − و + للضبط الدقيق)
    private void addFontSizeSlider(LinearLayout container) {
        final int MIN = 8, MAX = 50;
        float d = getResources().getDisplayMetrics().density;
        final int cur0 = Math.max(MIN, Math.min(MAX, uiPrefs().getInt("fsize", 12)));

        LinearLayout card = new LinearLayout(this);
        card.setOrientation(LinearLayout.VERTICAL);
        card.setPadding((int) (14 * d), (int) (12 * d), (int) (14 * d), (int) (12 * d));
        android.graphics.drawable.GradientDrawable bg = new android.graphics.drawable.GradientDrawable();
        bg.setColor(themeCardBg());
        bg.setCornerRadius(12 * d);
        bg.setStroke(themeStrokeW(d), themeCardStroke());
        card.setBackground(bg);

        final TextView label = new TextView(this);
        label.setText("حجم الخط: " + cur0);
        label.setTextSize(15);
        label.setTypeface(null, Typeface.BOLD);
        label.setTextColor(themeTextPrimary());
        card.addView(label);

        final TextView preview = new TextView(this);
        preview.setText("معاينة النص  Abc 123");
        preview.setTextSize(cur0);
        preview.setTextColor(themeTextSecondary());
        preview.setPadding(0, dp(4), 0, dp(4));
        card.addView(preview);

        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setGravity(android.view.Gravity.CENTER_VERTICAL);
        row.setLayoutDirection(View.LAYOUT_DIRECTION_LTR);

        final android.widget.SeekBar sb = new android.widget.SeekBar(this);
        sb.setMax(MAX - MIN);
        sb.setProgress(cur0 - MIN);

        final Runnable[] commit = new Runnable[1];
        commit[0] = () -> {
            int v = sb.getProgress() + MIN;
            uiPrefs().edit().putInt("fsize", v).apply();
            termHome();
        };
        final java.util.function.IntConsumer show = v -> {
            label.setText("حجم الخط: " + v);
            preview.setTextSize(v);
        };

        Button minus = makeOutIconBtn("\u2212", () -> {
            if (sb.getProgress() > 0) { sb.setProgress(sb.getProgress() - 1); commit[0].run(); }
        });
        Button plus = makeOutIconBtn("+", () -> {
            if (sb.getProgress() < MAX - MIN) { sb.setProgress(sb.getProgress() + 1); commit[0].run(); }
        });
        minus.setTextColor(themeIconBtn());
        plus.setTextColor(themeIconBtn());

        sb.setOnSeekBarChangeListener(new android.widget.SeekBar.OnSeekBarChangeListener() {
            @Override public void onProgressChanged(android.widget.SeekBar b, int p, boolean fromUser) { show.accept(p + MIN); }
            @Override public void onStartTrackingTouch(android.widget.SeekBar b) {}
            @Override public void onStopTrackingTouch(android.widget.SeekBar b) { commit[0].run(); }
        });

        row.addView(minus, new LinearLayout.LayoutParams(-2, -2));
        row.addView(sb, new LinearLayout.LayoutParams(0, -2, 1f));
        row.addView(plus, new LinearLayout.LayoutParams(-2, -2));
        card.addView(row, new LinearLayout.LayoutParams(-1, -2));

        LinearLayout hints = new LinearLayout(this);
        hints.setOrientation(LinearLayout.HORIZONTAL);
        hints.setLayoutDirection(View.LAYOUT_DIRECTION_LTR);
        TextView lo = new TextView(this); lo.setText(String.valueOf(MIN)); lo.setTextSize(11); lo.setTextColor(themeTextSecondary());
        TextView hi = new TextView(this); hi.setText(String.valueOf(MAX)); hi.setTextSize(11); hi.setTextColor(themeTextSecondary());
        hints.addView(lo, new LinearLayout.LayoutParams(0, -2, 1f));
        hints.addView(hi, new LinearLayout.LayoutParams(-2, -2));
        card.addView(hints, new LinearLayout.LayoutParams(-1, -2));

        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(-1, -2);
        lp.bottomMargin = (int) (8 * d);
        container.addView(card, lp);
    }

