    private void ndkManageDialog() {
        Toast.makeText(this, "يحسب الحجم...", Toast.LENGTH_SHORT).show();
        new Thread(() -> {
            final boolean nd = ndkInstalled(), cm = cmakeInstalled();
            final long sz = nd ? dirSize(ndkDir()) : 0L;
            runOnUiThread(() -> {
                final java.util.List<String> labels = new ArrayList<>();
                final java.util.List<Runnable> acts = new ArrayList<>();
                if (nd) { labels.add("حذف NDK فقط"); acts.add(() -> confirmRemoveNdk(false)); }
                if (nd || cm) { labels.add("حذف NDK + cmake وninja"); acts.add(() -> confirmRemoveNdk(true)); }
                if (nd) { labels.add("تصدير NDK إلى تخزين الهاتف"); acts.add(this::confirmExportNdk); }
                labels.add("استيراد NDK من تخزين الهاتف");
                acts.add(() -> pickFile(PICK_NDK_IMPORT));
                labels.add(nd ? "إعادة التثبيت من الإنترنت" : "تنزيل وتثبيت من الإنترنت");
                acts.add(this::installNdkReal);
                labels.add("إلغاء");
                acts.add(() -> {});
                new NavAlertBuilder()
                        .setTitle("NDK: " + (nd ? "مثبّت (" + fmtSize(sz) + ")" : "غير مثبّت")
                                + " | cmake وninja: " + (cm ? "مثبّتان" : "غير مثبّتين"))
                        .setItems(labels.toArray(new String[0]), (d, which) -> acts.get(which).run())
                        .show();
            });
        }).start();
    }

    private void confirmExportNdk() {
        new NavAlertBuilder()
                .setTitle("تصدير NDK إلى تخزين الهاتف")
                .setMessage("سيُضغط مجلد sdk/ndk كملف l2s-ndk-الإصدار.tar.gz (يحفظ الصلاحيات والروابط) ويُنسخ إلى مجلد التنزيلات (وإلى مجلد النسخ الاحتياطي إن كان مفعّلًا). قد يستغرق دقائق ويحتاج مساحة حرة تقارب نصف حجم NDK مؤقتًا.\n\nيمكنك لاحقًا استيراده بدل التنزيل من الإنترنت.")
                .setPositiveButton("ابدأ", (d, w) -> startTask(this::exportNdk))
                .setNegativeButton("إلغاء", null)
                .show();
    }

    // تشغيل سكربت داخل Debian مع ربط الـSDK على /opt/sdk
    private Res guestSdk(String script, int timeoutSec) {
        File base = toolsBase();
        File rootfs = findRoot(new File(getFilesDir(), "rootfs"), 2);
        File sdk = new File(getFilesDir(), "sdk");
        List<String> c = new ArrayList<>();
        c.add(new File(base, "bin/proot").getAbsolutePath());
        c.add("--link2symlink");
        c.add("--kill-on-exit");
        c.add("-0");
        c.add("-r");
        c.add(rootfs.getAbsolutePath());
        for (String bnd : new String[]{"/dev", "/proc", "/sys", "/system"}) { c.add("-b"); c.add(bnd); }
        if (new File("/apex").exists()) { c.add("-b"); c.add("/apex"); }
        c.add("-b"); c.add(base.getAbsolutePath() + ":/opt/l2s");
        c.add("-b"); c.add(sdk.getAbsolutePath() + ":/opt/sdk");
        c.add("-w"); c.add("/root");
        c.add("/usr/bin/env");
        c.add("-i");
        c.add("HOME=/root");
        c.add("PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin");
        c.add("LANG=C.UTF-8");
        c.add("TMPDIR=/tmp");
        c.add("/bin/sh");
        c.add("-c");
        c.add(script);
        return exec(base, timeoutSec, 30, null, c);
    }

    private String exportNdk() {
        if (!ndkInstalled()) return "لا يوجد NDK مثبّت لتصديره.";
        File base = toolsBase();
        File rootfs = findRoot(new File(getFilesDir(), "rootfs"), 2);
        if (rootfs == null || !new File(base, "bin/proot").exists()) return "بيئة Debian غير جاهزة (يلزم tar وgzip).";
        String[] revs = ndkDir().list((d, n) -> new File(d, n).isDirectory());
        if (revs == null || revs.length == 0) return "لا يوجد NDK مثبّت لتصديره.";
        java.util.Arrays.sort(revs);
        String rev = revs[revs.length - 1].replaceAll("[^A-Za-z0-9._-]", "_");
        progress("يحسب حجم NDK ...");
        long need = dirSize(ndkDir());
        if (getFilesDir().getUsableSpace() < need / 2) {
            return "المساحة الحرة لا تكفي لضغط NDK (يلزم نحو " + fmtSize(need / 2) + ").";
        }
        String fname = "l2s-ndk-" + rev + ".tar.gz";
        File out = new File(getFilesDir(), "sdk/" + fname);
        out.delete();
        progress("يضغط NDK (" + fmtSize(need) + ") — قد يستغرق دقائق ...");
        Res r = guestSdk("tar -cf - -C /opt/sdk ndk | gzip -1 > /opt/sdk/" + fname, 3600);
        if (r.code != 0 || !out.exists() || out.length() == 0) {
            out.delete();
            return "فشل ضغط NDK (رمز " + r.code + "):\n" + r.text;
        }
        long outSz = out.length();
        progress("ينسخ الملف إلى تخزين الهاتف ...");
        String msg = protectFile(out, "application/gzip");
        out.delete();
        return "تم تصدير NDK ✔ | " + fname + " | " + fmtSize(outSz) + "\n" + msg;
    }

    private void findNdkRoots(File d, int depth, List<File> out) {
        if (new File(d, "source.properties").isFile() && new File(d, "toolchains").isDirectory()) {
            out.add(d);
            return;
        }
        if (depth >= 4) return;
        File[] ks = d.listFiles(File::isDirectory);
        if (ks == null) return;
        for (File k : ks) {
            if (Compat.isSymbolicLink(k)) continue;
            findNdkRoots(k, depth + 1, out);
        }
    }

    private String readNdkRevision(File root) {
        try {
            for (String ln : Compat.readAllLines(new File(root, "source.properties"), StandardCharsets.UTF_8)) {
                String t = ln.trim();
                if (t.startsWith("Pkg.Revision")) {
                    int i = t.indexOf('=');
                    if (i > 0) return t.substring(i + 1).trim().replaceAll("[^A-Za-z0-9._-]", "_");
                }
            }
        } catch (Throwable ignored) {}
        return null;
    }

    // أرشيفات zip لا تحفظ صلاحية التنفيذ: أعدها لملفات bin والسكربتات
    private void fixNdkPerms(File d) {
        File[] ks = d.listFiles();
        if (ks == null) return;
        for (File k : ks) {
            if (Compat.isSymbolicLink(k)) continue;
            if (k.isDirectory()) { fixNdkPerms(k); continue; }
            String n = k.getName();
            String path = k.getAbsolutePath().replace('\\', '/');
            if (path.contains("/bin/") || n.endsWith(".sh") || n.equals("ndk-build") || n.equals("ndk-gdb") || n.equals("ndk-which")) {
                k.setExecutable(true, false);
            }
        }
    }

    private String importNdk(Uri u) {
        File nd = ndkDir();
        nd.mkdirs();
        File stage = new File(nd, "_import");
        deleteRec(stage);
        stage.mkdirs();
        try {
            boolean gz, zip;
            try (InputStream in = getContentResolver().openInputStream(u)) {
                int b1 = in.read(), b2 = in.read();
                gz = b1 == 0x1f && b2 == 0x8b;
                zip = b1 == 'P' && b2 == 'K';
            }
            if (!gz && !zip) { deleteRec(stage); return "الملف ليس zip ولا tar.gz."; }
            progress("يفك الملف إلى مجلد مؤقت ...");
            if (gz) {
                try (InputStream raw = getContentResolver().openInputStream(u);
                     BufferedInputStream bin = new BufferedInputStream(raw, 1 << 16);
                     GZIPInputStream gin = new GZIPInputStream(bin, 1 << 16)) {
                    readTarGzCore(gin, stage);
                }
            } else {
                unzipTo(u, stage);
            }
            List<File> roots = new ArrayList<>();
            findNdkRoots(stage, 0, roots);
            if (roots.isEmpty()) {
                deleteRec(stage);
                return "لم أجد NDK داخل الملف (لا يوجد source.properties بجانب مجلد toolchains).";
            }
            StringBuilder r = new StringBuilder();
            int ok = 0;
            for (File root : roots) {
                String rev = readNdkRevision(root);
                if (rev == null || rev.isEmpty()) rev = root.getName();
                File dst = new File(nd, rev);
                deleteRec(dst);
                if (!root.renameTo(dst)) {
                    r.append("تعذّر نقل ").append(rev).append(" ✘\n");
                    continue;
                }
                progress("يضبط صلاحيات التنفيذ ...");
                fixNdkPerms(dst);
                r.append("استُورد NDK ").append(rev).append(" ✔ (").append(fmtSize(dirSize(dst))).append(")\n");
                ok++;
            }
            deleteRec(stage);
            if (ok > 0) r.append("ضع ndkVersion في build.gradle مطابقًا للإصدار أعلاه. إن لم يكن cmake مثبّتًا فثبّته من خيار التنزيل/التثبيت أو apt.");
            return r.toString();
        } catch (Throwable e) {
            deleteRec(stage);
            return "فشل استيراد NDK: " + e;
        }
    }

    private void confirmRemoveNdk(final boolean withPackages) {
        new NavAlertBuilder()
                .setTitle(withPackages ? "حذف NDK وcmake وninja؟" : "حذف NDK؟")
                .setMessage(withPackages
                        ? "سيُحذف مجلد sdk/ndk، وتُزال حزم cmake وninja-build من Debian (بدون autoremove، فلا تُمسّ حزم أخرى). بعدها يتوقف التطبيق عن كتابة cmake.dir في local.properties."
                        : "سيُحذف مجلد sdk/ndk فقط. يبقى cmake وninja داخل Debian.")
                .setPositiveButton("حذف", (d, w) -> startTask(() -> removeNdk(withPackages)))
                .setNegativeButton("إلغاء", null)
                .show();
    }

    private String removeNdk(boolean withPackages) {
        StringBuilder r = new StringBuilder();
        File nd = ndkDir();
        if (nd.exists()) {
            progress("يحذف مجلد NDK ...");
            long freed = dirSize(nd);
            deleteRec(nd);
            r.append(nd.exists() ? "تعذّر حذف NDK بالكامل ✘\n" : "حُذف NDK (" + fmtSize(freed) + ") ✔\n");
        } else {
            r.append("لا يوجد NDK مثبّت.\n");
        }
        if (withPackages) {
            File base = toolsBase();
            File rootfs = findRoot(new File(getFilesDir(), "rootfs"), 2);
            if (rootfs == null || !new File(base, "bin/proot").exists()) {
                r.append("تعذّر حذف cmake: بيئة Debian غير جاهزة.\n");
            } else {
                progress("يزيل cmake وninja من Debian ...");
                String out = guest(base, rootfs, null, "/bin/sh", "-c",
                        "apt-get remove -y --purge cmake cmake-data ninja-build 2>&1 | tail -n 5");
                r.append(cmakeInstalled() ? "لم تُزَل حزم cmake ✘\n" : "أُزيل cmake وninja ✔\n").append(out);
            }
        }
        return r.toString();
    }

    private void installNdkReal() {
        final android.widget.EditText et = new android.widget.EditText(this);
        et.setText(ndkUrl());
        et.setSingleLine(false);
        et.setTextSize(13);
        et.setTextDirection(View.TEXT_DIRECTION_LTR);
        new NavAlertBuilder()
                .setTitle("تثبيت NDK وcmake (تجريبي)")
                .setMessage("رابط تنزيل NDK (يمكنك تعديله إن تغيّر؛ يدعم tar.xz وzip و7z). "
                        + "سيُنفَّذ في الطرفية: تثبيت cmake وninja ثم تنزيل NDK وفكه وطباعة إصداره. "
                        + "حجم كبير (قد يتجاوز 1GB بعد الفك). إن انقطع التنزيل أعد التشغيل فيُستكمل.")
                .setView(et)
                .setPositiveButton("ابدأ", (d, w) -> {
                    String u = et.getText().toString().trim();
                    if (!ndkUrlValid(u)) {
                        android.widget.Toast.makeText(this, "الرابط غير صالح (يجب أن يبدأ بـ http أو https بلا مسافات)", android.widget.Toast.LENGTH_LONG).show();
                        return;
                    }
                    uiPrefs().edit().putString("ndk_url", u).apply();
                    termExecLive(ndkInstallScript());
                })
                .setNeutralButton("الافتراضي", (d, w) -> {
                    uiPrefs().edit().remove("ndk_url").apply();
                    android.widget.Toast.makeText(this, "أُعيد الرابط الافتراضي", android.widget.Toast.LENGTH_SHORT).show();
                    installNdkReal();
                })
                .setNegativeButton("إلغاء", null)
                .show();
    }

