    // ------------------------------------------------------------------
    // حزم Debian المثبّتة: عرض (مرتبة بالحجم) + حذف عبر apt-get
    // ------------------------------------------------------------------
    private static class DebPkg {
        String name = "", version = "", priority = "";
        long sizeKb;
        boolean manual, essential;
        boolean protectedPkg() { return essential || priority.equals("required"); }
    }

    private void showDebianPackages(final boolean manualOnly) {
        final android.app.Dialog dlg = newScreen("showDebianPackages" + ":" + String.valueOf(manualOnly), () -> showDebianPackages(manualOnly));
        LinearLayout root = beginFullscreenCardDialog(dlg, "حزم Debian المثبّتة");
        LinearLayout box = (LinearLayout) root.getTag();
        final TextView loading = new TextView(this);
        loading.setText("يقرأ قائمة الحزم...");
        loading.setTextSize(14);
        loading.setTextColor(themeTextSecondary());
        loading.setPadding(dp(8), dp(16), dp(8), dp(16));
        box.addView(loading);
        dlg.setContentView(root);
        dlg.show();

        final File base = toolsBase();
        final File rootfs = findRoot(new File(getFilesDir(), "rootfs"), 2);
        if (rootfs == null || !new File(base, "bin/proot").exists()) {
            loading.setText("أولًا أكمل الإعداد الأولي (الأدوات وDebian).");
            return;
        }
        final java.util.concurrent.atomic.AtomicBoolean closed = new java.util.concurrent.atomic.AtomicBoolean(false);
        dlg.setOnDismissListener(di -> closed.set(true));
        Thread t = new Thread(() -> {
            String script = "apt-mark showmanual | sed 's/^/M:/'; "
                    + "dpkg-query -W -f='P:${Package}\\t${Installed-Size}\\t${Version}\\t${Essential}\\t${Priority}\\t${db:Status-Abbrev}\\n'";
            Res r = guestRunT(base, rootfs, false, null, 120, 20000, "/bin/sh", "-c", script);
            if (r.code != 0 && r.text.indexOf("P:") < 0) r = guestRunT(base, rootfs, true, null, 120, 20000, "/bin/sh", "-c", script);
            final Res fr = r;
            final java.util.Set<String> manual = new java.util.HashSet<>();
            final List<DebPkg> all = new ArrayList<>();
            for (String line : fr.text.split("\n")) {
                if (line.startsWith("M:")) { manual.add(line.substring(2).trim()); continue; }
                if (!line.startsWith("P:")) continue;
                String[] f = line.substring(2).split("\t", -1);
                if (f.length < 6 || !f[5].trim().startsWith("ii")) continue;
                DebPkg d = new DebPkg();
                d.name = f[0].trim();
                try { d.sizeKb = Long.parseLong(f[1].trim()); } catch (Exception ignored) { }
                d.version = f[2].trim();
                d.essential = f[3].trim().equalsIgnoreCase("yes");
                d.priority = f[4].trim();
                all.add(d);
            }
            final List<DebPkg> shown = new ArrayList<>();
            for (DebPkg d : all) {
                d.manual = manual.contains(d.name);
                if (!manualOnly || d.manual) shown.add(d);
            }
            java.util.Collections.sort(shown, (a, b) -> Long.compare(b.sizeKb, a.sizeKb));
            final int totalAll = all.size();
            runOnUiThread(() -> {
                if (closed.get()) return;
                box.removeView(loading);
                if (all.isEmpty()) {
                    TextView e = new TextView(this);
                    e.setText("تعذّر قراءة الحزم:\n" + fr.text);
                    e.setTextColor(themeTextSecondary());
                    e.setTextSize(13);
                    box.addView(e);
                    return;
                }
                final java.util.Set<String> selected = new java.util.LinkedHashSet<>();
                final boolean[] selectMode = {false};
                final List<DebPkg> removable = new ArrayList<>();
                long sum = 0;
                for (DebPkg d : shown) { sum += d.sizeKb * 1024L; if (!d.protectedPkg()) removable.add(d); }
                final long fSum = sum;
                final Runnable onDone = () -> { dlg.dismiss(); showDebianPackages(manualOnly); };
                final Runnable[] render = new Runnable[1];
                render[0] = () -> {
                    box.removeAllViews();
                    addMenuCardLP(box, manualOnly ? "\uD83D\uDD0D" : "\uD83D\uDCCB",
                            manualOnly ? "المعروضة: المثبّتة يدويًا فقط (" + shown.size() + ")" : "المعروضة: كل الحزم (" + shown.size() + ")",
                            (manualOnly ? "اضغط لعرض كل الحزم (" + totalAll + ")" : "اضغط لعرض المثبّتة يدويًا فقط") + " — الحجم التقريبي: " + fmtSize(fSum),
                            "#607D8B", () -> { dlg.dismiss(); showDebianPackages(!manualOnly); }, null);

                    addToggleCard(box, "\u2611", "تحديد متعدد", "حدّد عدة حزم واحذفها دفعة واحدة", "#3F51B5", selectMode[0],
                            on -> { selectMode[0] = on; if (!on) selected.clear(); box.post(render[0]); return true; }, null);

                    if (selectMode[0]) {
                        boolean allSel = !removable.isEmpty() && selected.size() == removable.size();
                        addMenuCard(box, allSel ? "\u2716" : "\u2705", allSel ? "إلغاء تحديد الكل" : "تحديد الكل (" + removable.size() + ")",
                                "الحزم الأساسية لا تُحدَّد", "#3F51B5", () -> {
                            if (allSel) selected.clear();
                            else { selected.clear(); for (DebPkg x : removable) selected.add(x.name); }
                            render[0].run();
                        });
                        if (!selected.isEmpty()) {
                            final List<DebPkg> chosen = new ArrayList<>();
                            long selBytes = 0;
                            for (DebPkg x : removable) if (selected.contains(x.name)) { chosen.add(x); selBytes += x.sizeKb * 1024L; }
                            addMenuCard(box, "\uD83D\uDDD1", "حذف المحدد (" + chosen.size() + ")", "الحجم التقريبي: " + fmtSize(selBytes), "#F44336",
                                    () -> confirmRemoveDebPackages(chosen, false, onDone));
                        }
                    }
                    if (!removable.isEmpty()) {
                        addMenuCard(box, "\u26A0", "حذف الكل (" + removable.size() + " حزمة)",
                                "كل المعروضة عدا الأساسية — قد يزيل أدوات تحتاجها للبناء", "#D32F2F",
                                () -> confirmRemoveDebPackages(new ArrayList<>(removable), true, onDone));
                    }

                    int limit = Math.min(shown.size(), 300);
                    for (int i = 0; i < limit; i++) {
                        final DebPkg d = shown.get(i);
                        String sub = fmtSize(d.sizeKb * 1024L) + " — " + d.version + (d.protectedPkg() ? " — أساسية (لا تُحذف)" : "");
                        if (selectMode[0] && !d.protectedPkg()) {
                            addSelectCard(box, selected.contains(d.name), d.name, sub, "#F44336", () -> {
                                if (!selected.remove(d.name)) selected.add(d.name);
                                render[0].run();
                            });
                            continue;
                        }
                        addMenuCardLP(box, d.protectedPkg() ? "\uD83D\uDD12" : "\uD83D\uDCE6", d.name, sub,
                                d.protectedPkg() ? "#9E9E9E" : "#795548", () -> {
                            if (d.protectedPkg()) {
                                Toast.makeText(this, "حزمة أساسية للنظام، حذفها يكسر Debian", Toast.LENGTH_LONG).show();
                                return;
                            }
                            confirmRemoveDebPackage(d, onDone);
                        }, null);
                    }
                    if (shown.size() > limit) {
                        TextView more = new TextView(this);
                        more.setText("عُرضت أكبر " + limit + " حزمة من " + shown.size() + ".");
                        more.setTextSize(12);
                        more.setTextColor(themeTextSecondary());
                        more.setPadding(dp(8), dp(10), dp(8), dp(10));
                        box.addView(more);
                    }
                };
                render[0].run();
            });
        });
        t.setPriority(Thread.MIN_PRIORITY);
        t.setDaemon(true);
        t.start();
    }

    private void confirmRemoveDebPackage(final DebPkg d, final Runnable onDone) {
        final String[] opts = {"حذف الحزمة", "إلغاء"};
        new NavAlertBuilder()
                .setTitle(d.name + " (" + fmtSize(d.sizeKb * 1024L) + ")")
                .setItems(opts, (di, which) -> { if (which == 0) removeDebPackage(d, onDone); })
                .show();
    }

    private void confirmRemoveDebPackages(final List<DebPkg> list, final boolean all, final Runnable onDone) {
        if (list.isEmpty()) return;
        long bytes = 0;
        for (DebPkg x : list) bytes += x.sizeKb * 1024L;
        StringBuilder names = new StringBuilder();
        for (int i = 0; i < list.size() && i < 12; i++) names.append("• ").append(list.get(i).name).append("\n");
        if (list.size() > 12) names.append("... و").append(list.size() - 12).append(" أخرى\n");
        String msg = "سيُحذف " + list.size() + " حزمة (الحجم التقريبي " + fmtSize(bytes) + "):\n\n" + names
                + (all ? "\n⚠ هذا يحذف كل الحزم غير الأساسية المعروضة، وقد يزيل أدوات يعتمد عليها البناء (مثل git وgcc وjava)، وقد تحتاج إعادة تثبيتها لاحقًا."
                       : "\nسيُشغَّل autoremove بعد الحذف لإزالة التبعيات غير المستخدمة.");
        new NavAlertBuilder()
                .setTitle(all ? "حذف كل الحزم؟" : "حذف " + list.size() + " حزمة؟")
                .setMessage(msg)
                .setPositiveButton(all ? "نعم، احذف الكل" : "حذف", (d, w) -> removeDebPackages(list, onDone))
                .setNegativeButton("إلغاء", null)
                .show();
    }

    private void removeDebPackage(final DebPkg d, final Runnable onDone) {
        removeDebPackages(java.util.Collections.singletonList(d), onDone);
    }

    private void removeDebPackages(final List<DebPkg> list, final Runnable onDone) {
        final File base = toolsBase();
        final File rootfs = findRoot(new File(getFilesDir(), "rootfs"), 2);
        if (rootfs == null || list.isEmpty()) return;
        final StringBuilder pk = new StringBuilder();
        for (DebPkg x : list) {
            if (x.name.matches("[A-Za-z0-9+._:-]+")) pk.append(x.name).append(' ');
        }
        if (pk.length() == 0) return;
        final String title = list.size() == 1 ? "جارٍ حذف " + list.get(0).name : "جارٍ حذف " + list.size() + " حزمة";
        final int timeout = Math.min(3600, 600 + 20 * list.size());
        final android.app.AlertDialog wait = new NavAlertBuilder()
                .setTitle(title)
                .setMessage("أبقِ التطبيق مفتوحًا...")
                .setCancelable(false)
                .show();
        BuildService.start(this);
        new Thread(() -> {
            String script = "export DEBIAN_FRONTEND=noninteractive; apt-get purge -y " + pk + "&& apt-get autoremove -y --purge";
            Res r = guestRunT(base, rootfs, false, null, timeout, 40, "/bin/sh", "-c", script);
            if (r.code != 0) r = guestRunT(base, rootfs, true, null, timeout, 40, "/bin/sh", "-c", script);
            final Res fr = r;
            runOnUiThread(() -> {
                try { wait.dismiss(); } catch (Exception ignored) { }
                BuildService.stop(this);
                if (fr.code == 0) {
                    Toast.makeText(this, list.size() == 1 ? "تم حذف " + list.get(0).name : "تم حذف " + list.size() + " حزمة", Toast.LENGTH_SHORT).show();
                } else {
                    new NavAlertBuilder().setTitle("فشل الحذف").setMessage(fr.text).setPositiveButton("حسنًا", null).show();
                }
                onDone.run();
            });
        }).start();
    }

    // اختيار ساعتي بداية/نهاية الوضع الداكن التلقائي (جدولة بالوقت). عند اختيار البداية يُكمل تلقائيًا لاختيار النهاية.
    private void termScheduleHourDialog(final boolean pickingStart) {
        final android.app.Dialog dlg = newScreen("termScheduleHourDialog" + ":" + String.valueOf(pickingStart), () -> termScheduleHourDialog(pickingStart));
        LinearLayout root = beginFullscreenCardDialog(dlg, pickingStart ? "بداية الوضع الداكن" : "نهاية الوضع الداكن (العودة للفاتح)");
        LinearLayout box = (LinearLayout) root.getTag();
        int current = uiPrefs().getInt(pickingStart ? "sched_start" : "sched_end", pickingStart ? 19 : 7);
        for (int h = 0; h < 24; h++) {
            final int hh = h;
            String label = String.format(java.util.Locale.US, "%02d:00", hh);
            addMenuCard(box, hh == current ? "\u2705" : "\uD83D\uDD50", label, "#8E24AA", () -> {
                uiPrefs().edit().putInt(pickingStart ? "sched_start" : "sched_end", hh).apply();
                dlg.dismiss();
                if (pickingStart) {
                    termScheduleHourDialog(false);
                } else {
                    navReset();
                    termHome();
                }
            });
        }
        dlg.setContentView(root);
        dlg.show();
    }

    private void termCmdLimitDialog() {
        final String[] opts = {"بلا حد", "5", "10", "20", "50"};
        final int[] vals = {0, 5, 10, 20, 50};

        final android.app.Dialog dlg = newScreen("termCmdLimitDialog", () -> termCmdLimitDialog());
        LinearLayout root = beginFullscreenCardDialog(dlg, "عدد الأوامر المحفوظة");
        LinearLayout box = (LinearLayout) root.getTag();
        for (int i = 0; i < opts.length; i++) {
            final int idx = i;
            addMenuCard(box, "\uD83D\uDCCA", opts[idx], "#E91E63", () -> {
                uiPrefs().edit().putInt("cmdlimit", vals[idx]).apply();
                dlg.dismiss();
                termHome();
            });
        }
        dlg.setContentView(root);
        dlg.show();
    }

    private void smartAutoScroll() {
        if (termScroll == null || out == null) return;
        termScroll.post(() -> termScroll.fullScroll(View.FOCUS_DOWN));
    }

    private static final StringBuilder termPending = new StringBuilder();
    private static long termLastFlush = 0;
    private static final Object termPendingLock = new Object();

    private void termAppendThrottled(final String s) {
        boolean flushNow;
        synchronized (termPendingLock) {
            termPending.append(s);
            long now = System.currentTimeMillis();
            flushNow = (now - termLastFlush) >= 120;
            if (flushNow) termLastFlush = now;
        }
        if (flushNow) termFlushPending();
        else {
            final MainActivity a = live;
            if (a != null && a.out != null) a.out.postDelayed(a::termFlushPending, 130);
        }
    }

    private void termFlushPending() {
        final String chunk;
        synchronized (termPendingLock) {
            if (termPending.length() == 0) return;
            chunk = termPending.toString();
            termPending.setLength(0);
            termLastFlush = System.currentTimeMillis();
        }
        termAppend(chunk);
    }

    private void termAppend(final String s) {
        synchronized (termBlocks) {
            if (!termBlocks.isEmpty()) termBlocks.get(termBlocks.size() - 1).append(s);
        }
        final MainActivity a = live;
        if (a == null) return;   // لا واجهة حاليًا؛ المخرجات محفوظة في termBlocks وستُعرض عند العودة.
        a.runOnUiThread(() -> {
            if (a.out == null) return;
            a.out.append(s);
            if (a.taskDialog != null && a.taskDialog.isShowing() && a.taskDialogText != null) {
                a.taskDialogText.setText(a.out.getText());
                if (a.taskDialogScroll != null) a.taskDialogScroll.post(() -> a.taskDialogScroll.fullScroll(View.FOCUS_DOWN));
            }
            a.smartAutoScroll();
        });
    }

    private CharSequence colorizeTerm(String text) {
        android.text.SpannableStringBuilder sb = new android.text.SpannableStringBuilder(text);
        String[] lines = text.split("\n", -1);
        int idx = 0;
        for (String line : lines) {
            int start = idx;
            int end = idx + line.length();
            String trimmed = line.trim();
            String low = line.toLowerCase(java.util.Locale.ROOT);
            int color = 0;
            if (low.contains("error") || line.contains("خطأ") || line.contains("فشل") || line.contains("\u2718")) {
                color = 0xFFE53935;
            } else if (line.contains("\u2714") || line.contains("نجح") || trimmed.startsWith("تم") || low.contains("build successful")) {
                color = 0xFF43A047;
            } else if (trimmed.startsWith("==")) {
                color = 0xFFFFB300;
            } else if (trimmed.startsWith("$")) {
                color = 0xFF29B6F6;
            }
            if (color != 0 && end > start) {
                sb.setSpan(new android.text.style.ForegroundColorSpan(color), start, end, android.text.Spannable.SPAN_EXCLUSIVE_EXCLUSIVE);
            }
            idx = end + 1;
        }
        return sb;
    }

    private void termRenderBlocks() {
        // v2 لا يحذف التاريخ: وضع "مفرد" يعرض آخر أمر فقط، لكن التاريخ الكامل يبقى محفوظًا في termBlocks
        boolean single = uiPrefs().getString("outmode", "cum").equals("single");
        StringBuilder all = new StringBuilder();
        synchronized (termBlocks) {
            if (single) {
                if (!termBlocks.isEmpty()) all.append(termBlocks.get(termBlocks.size() - 1));
            } else {
                for (StringBuilder b : termBlocks) all.append(b);
            }
        }
        out.setText(all.length() == 0 ? "طرفية L2SBuilder\nاكتب أمرًا بالأسفل ثم «تنفيذ»." : colorizeTerm(all.toString()));
        smartAutoScroll();
    }

    // يزيل رموز ANSI (ألوان/تحكم بالمؤشر) من خرج PTY ويعالج \r، مع الاحتفاظ بتسلسل مقطوع بين دفعتين.
    private static final class AnsiStrip {
        private String pending = "";
        private static final java.util.regex.Pattern COMPLETE = java.util.regex.Pattern.compile(
                "^\u001b(\\[[0-9;?]*[ -/]*[@-~]|\\][^\u0007]*(\u0007|\u001b\\\\)|[()][A-Za-z0-9]|[=>78M]).*", java.util.regex.Pattern.DOTALL);
        private static final java.util.regex.Pattern SEQ = java.util.regex.Pattern.compile(
                "\u001b\\[[0-9;?]*[ -/]*[@-~]|\u001b\\][^\u0007]*(\u0007|\u001b\\\\)|\u001b[()][A-Za-z0-9]|\u001b[=>78M]");

        String feed(String chunk) {
            String t = pending + chunk;
            pending = "";
            int idx = t.lastIndexOf('\u001b');
            if (idx >= 0 && t.length() - idx < 64 && !COMPLETE.matcher(t.substring(idx)).matches()) {
                pending = t.substring(idx);
                t = t.substring(0, idx);
            }
            t = SEQ.matcher(t).replaceAll("");
            t = t.replace("\r\n", "\n").replace('\r', '\n');
            return t;
        }
    }

    private void termExecLive(final String script) {
        if (busy) {
            Toast.makeText(this, "توجد عملية جارية", Toast.LENGTH_SHORT).show();
            return;
        }
        busy = true;
        final String afterBuild = (script.contains("ndk.pkg") ? pendingBuildAfterNdk : null);
        pendingBuildAfterNdk = null;
        final boolean ptyMode = uiPrefs().getBoolean("term_pty", false);
        final String pn = currentProject();
        final String header = "\n$ " + (script.length() > 200 ? script.substring(0, 200) + " ..." : script) + "\n";
        boolean single = uiPrefs().getString("outmode", "cum").equals("single");
        int limit = uiPrefs().getInt("cmdlimit", 0);
        synchronized (termBlocks) {
            termBlocks.add(new StringBuilder(header));
            if (limit > 0) {
                while (termBlocks.size() > limit) termBlocks.remove(0);
            }
        }
        termRenderBlocks();
        // كان هذا المسار (الطرفية الرئيسية) يعمل على Thread خام دون أي حماية، فيتجمّد
        // عند إطفاء الشاشة. الآن نبدأ الخدمة الأمامية + WakeLock طوال مدة الأمر.
        BuildService.start(this);
        opBatteryStart();
        final boolean[] timedOutFlag = new boolean[]{false};
        new Thread(() -> {
            try {
                File base = toolsBase();
                File rootfs = findRoot(new File(getFilesDir(), "rootfs"), 2);
                File sdk = new File(getFilesDir(), "sdk");
                if (!new File(base, "bin/proot").exists()) { termAppend("أولًا الإعداد: الخطوة 1 (الأدوات).\n"); return; }
                if (rootfs == null) { termAppend("أولًا الإعداد: الخطوة 2 (Debian).\n"); return; }
                File root = null;
                if (!pn.isEmpty()) {
                    File proj = new File(projectsDir(), pn);
                    root = proj;
                    if (!new File(root, "gradle/wrapper/gradle-wrapper.jar").exists()) {
                        File[] ks = proj.listFiles();
                        if (ks != null && ks.length == 1 && ks[0].isDirectory()) root = ks[0];
                    }
                }
                File rc = new File(rootfs, "etc/resolv.conf");
                Compat.deleteIfExists(rc);
                Compat.write(rc, "nameserver 8.8.8.8\nnameserver 1.1.1.1\n".getBytes(StandardCharsets.UTF_8));
                new File(rootfs, "tmp").mkdirs();
                Compat.write(new File(rootfs, "tmp/term.sh"), script.getBytes(StandardCharsets.UTF_8));
                List<String> c = new ArrayList<>();
                c.add(new File(base, "bin/proot").getAbsolutePath());
                c.add("--link2symlink");
                c.add("--kill-on-exit");
                c.add("-0");
                c.add("-r");
                c.add(rootfs.getAbsolutePath());
                for (String bnd : new String[]{"/dev", "/proc", "/sys", "/system"}) { c.add("-b"); c.add(bnd); }
                if (new File("/apex").exists()) { c.add("-b"); c.add("/apex"); }
                c.add("-b"); c.add(base.getAbsolutePath() + ":/opt/l2s");
                c.add("-b"); c.add(sdk.getAbsolutePath() + ":/opt/sdk");
                File gh = new File(getFilesDir(), "gradle-home");
                gh.mkdirs();
                c.add("-b"); c.add(gh.getAbsolutePath() + ":/root/.gradle");
                File ah = new File(getFilesDir(), "android-home");
                ah.mkdirs();
                new File(rootfs, "root/.android").mkdirs();
                c.add("-b"); c.add(ah.getAbsolutePath() + ":/root/.android");
                if (root != null) { c.add("-b"); c.add(root.getAbsolutePath() + ":/proj"); c.add("-w"); c.add("/proj"); }
                else { c.add("-w"); c.add("/root"); }

                // اكتشاف مسار توزيعة Gradle المستخرجة (اسم مجلد hash عشوائي)
                // وإضافته إلى PATH ليعمل أمر gradle مباشرة، مثل Termux تمامًا.
                String gradleBinDir = null;
                GradleAdvisor.fixExecBits(gh);
                File gdBest = findGradleHomeDir(gh, root);
                if (gdBest != null) {
                    String rel = gdBest.getAbsolutePath().substring(gh.getAbsolutePath().length());
                    gradleBinDir = "/root/.gradle" + rel + "/bin";
                }
                String pathValue = "/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin";
                if (gradleBinDir != null) pathValue = gradleBinDir + ":" + pathValue;

                c.add("/usr/bin/env");
                c.add("-i");
                c.add("HOME=/root");
                c.add("P=/proj");
                c.add("PATH=" + pathValue);
                c.add("LANG=C.UTF-8");
                c.add("TMPDIR=/tmp");
                c.add("ANDROID_HOME=/opt/sdk");
                c.add("JAVA_HOME=/usr/lib/jvm/java-21-openjdk-arm64");
                if (ptyMode) {
                    // طرفية وهمية (PTY): script (من util-linux) ثم python3 (pty) ثم الوضع العادي كاحتياطي.
                    c.add("TERM=xterm-256color");
                    c.add("/bin/sh");
                    c.add("-c");
                    c.add("W='stty cols 100 rows 30 2>/dev/null; exec /bin/sh /tmp/term.sh'; "
                            + "if command -v script >/dev/null 2>&1; then exec script -qefc \"$W\" /dev/null; "
                            + "elif command -v python3 >/dev/null 2>&1; then exec python3 -c 'import os,pty,sys; "
                            + "sys.exit(os.waitstatus_to_exitcode(pty.spawn([\"/bin/sh\",\"-c\",sys.argv[1]])))' \"$W\"; "
                            + "else exec /bin/sh /tmp/term.sh; fi");
                } else {
                    c.add("/bin/sh");
                    c.add("/tmp/term.sh");
                }
                ProcessBuilder pb = new ProcessBuilder(c);
                pb.redirectErrorStream(true);
                Map<String, String> env = pb.environment();
                env.put("LD_LIBRARY_PATH", new File(base, "lib").getAbsolutePath());
                env.put("PROOT_LOADER", new File(base, "libexec/proot/loader").getAbsolutePath());
                env.put("PROOT_TMP_DIR", getCacheDir().getAbsolutePath());
                final Process p = pb.start();
                termProc = p;
                termStdin = p.getOutputStream();
                termPtyActive = ptyMode;
                final AnsiStrip ansi = ptyMode ? new AnsiStrip() : null;
                final long t0 = System.currentTimeMillis();
                final int cmdTimeoutMin = getCmdTimeoutMin();
                final long cmdTimeoutMs = cmdTimeoutMin * 60000L;
                try (BufferedReader br = new BufferedReader(new InputStreamReader(p.getInputStream(), StandardCharsets.UTF_8))) {
                    char[] buf = new char[2048];
                    int n;
                    while ((n = br.read(buf)) > 0) {
                        String chunk = new String(buf, 0, n);
                        if (ansi != null) chunk = ansi.feed(chunk);
                        if (!chunk.isEmpty()) termAppendThrottled(chunk);
                        if (System.currentTimeMillis() - t0 > cmdTimeoutMs) {
                            killProcessTree(p);
                            termAppendThrottled("\n[انتهت المهلة " + cmdTimeoutMin + " دقيقة]\n");
                            logAutoStop("cmd", pn, cmdTimeoutMin);
                            timedOutFlag[0] = true;
                            notifyAutoStop("توقف الأمر تلقائيًا", (pn.isEmpty() ? "" : "المشروع \"" + pn + "\" — ") + "تجاوز مهلة " + cmdTimeoutMin + " دقيقة وأُلغي تلقائيًا.");
                            break;
                        }
                    }
                }
                int code = p.waitFor();
                final int finalCode = code;
                if (!timedOutFlag[0]) {
                    notifyTaskDone(finalCode == 0 ? "انتهى الأمر ✔" : "انتهى الأمر (رمز الخروج " + finalCode + ")",
                            (pn.isEmpty() ? "" : "المشروع «" + pn + "» — ") + shortLine(script, 100));
                }
                runOnUiThread(() -> {
                    // تفريغ أي خرج معلّق أولًا، ثم إضافة رمز الخروج بعده مباشرة
                    // داخل نفس الاستدعاء المتزامن، لضمان الترتيب الصحيح دائمًا.
                    termFlushPending();
                    termAppend("\n[رمز الخروج: " + finalCode + "]\n");
                    if (finalCode == 0 && afterBuild != null) {
                        termAppend("\nاكتمل تثبيت NDK — يُعاد بناء «" + afterBuild + "» بعد لحظات...\n");
                        new android.os.Handler(android.os.Looper.getMainLooper()).postDelayed(
                                () -> startTask(() -> buildExisting(afterBuild)), 2000);
                    }
                });
            } catch (Throwable e) {
                termAppend("\nخطأ: " + e + "\n");
            } finally {
                termProc = null;
                termStdin = null;
                termPtyActive = false;
                busy = false;
                BuildService.stop(this);
                runOnUiThread(this::opBatteryEnd);
            }
        }).start();
    }

    // ===== حفظ نسخة من المشروع داخل التطبيق المبني (اختياري، معطّل افتراضيًا) =====
    // قبل تشغيل Gradle: نضغط ملفات المشروع في ملف zip واحد app/src/main/assets/project_copy/<اسم المشروع>.zip
    // (بدون أي واجهة أو تعديل على المانيفست)، فيظهر المجلد داخل APK ويُستخرج بأي أداة فك.
    // بعد البناء نحذف المجلد المضاف فيبقى المشروع نظيفًا.
    private static class EmbedState {
        File manifest;
        String manifestOriginal;
        final List<File> created = new ArrayList<>();
        final List<File> dirsMaybeEmpty = new ArrayList<>();
    }

    private static boolean embedSkip(String rel) {
        return rel.equals("build") || rel.equals("app/build") || rel.equals(".gradle") || rel.equals(".idea")
                || rel.equals(".git") || rel.equals(".cxx") || rel.equals("local.properties")
                || rel.equals("app/.cxx") || rel.equals("app/src/main/assets/project_copy");
    }

    private void embedCopyDir(File src, File dst, String rel) throws IOException {
        File[] kids = src.listFiles();
        if (kids == null) return;
        dst.mkdirs();
        for (File k : kids) {
            if (Compat.isSymbolicLink(k)) continue;
            String r = rel.isEmpty() ? k.getName() : rel + "/" + k.getName();
            if (embedSkip(r) || r.equals(embedSkipRel)) continue;
            File d = new File(dst, k.getName());
            if (k.isDirectory()) {
                embedCopyDir(k, d, r);
            } else {
                Compat.copy(k, d);
            }
        }
    }

    // كلمة سر ملف zip المضمّن داخل APK (تشفير ZipCrypto عبر ZipCryptoWriter)
    private static final String EMBED_ZIP_PASSWORD = "1200@9999";

    // يضغط المشروع إلى ملف zip واحد محمي بكلمة سر (بنفس الاستثناءات) بدل نسخه كمجلد؛
    // داخل الـ zip مجلد باسم المشروع.
    private void embedZipDir(ZipCryptoWriter zw, File src, String zipPrefix, String rel) throws IOException {
        File[] kids = src.listFiles();
        if (kids == null) return;
        for (File k : kids) {
            if (Compat.isSymbolicLink(k)) continue;
            String r = rel.isEmpty() ? k.getName() : rel + "/" + k.getName();
            if (embedSkip(r) || r.equals(embedSkipRel)) continue;
            String entry = zipPrefix + "/" + k.getName();
            if (k.isDirectory()) embedZipDir(zw, k, entry, r);
            else zw.addFile(entry, k);
        }
    }

    private volatile String embedSkipRel = "";

    // يبحث عن مجلد app/src/main الحقيقي للتطبيق؛ إن لم يجده يُنشئ المسار الافتراضي
    // app/src/main/assets داخل مجلد المشروع بدل إلغاء الحفظ.
    private File findEmbedMainDir(File root, EmbedState st) {
        File std = new File(root, "app/src/main");
        if (std.isDirectory()) return std;
        // أي مجلد src/main فيه AndroidManifest.xml (وحدة تطبيق باسم مختلف)
        File found = findManifestMain(root, 0);
        if (found != null) return found;
        // لم نجد شيئًا: ننشئ app/src/main داخل مجلد المشروع، ونتتبّع ما أنشأناه لنحذفه بعد البناء
        File app = new File(root, "app");
        File src = new File(app, "src");
        boolean appExisted = app.isDirectory(), srcExisted = src.isDirectory();
        std.mkdirs();
        if (!srcExisted) st.dirsMaybeEmpty.add(src);
        if (!appExisted) st.dirsMaybeEmpty.add(app);
        st.dirsMaybeEmpty.add(0, std);
        return std;
    }

    private File findManifestMain(File dir, int depth) {
        if (depth > 4) return null;
        File[] kids = dir.listFiles();
        if (kids == null) return null;
        for (File k : kids) {
            if (!k.isDirectory() || Compat.isSymbolicLink(k)) continue;
            String nm = k.getName();
            if (nm.equals("build") || nm.equals(".gradle") || nm.equals(".git") || nm.equals("assets")) continue;
            if (nm.equals("main") && k.getParentFile() != null && k.getParentFile().getName().equals("src")
                    && new File(k, "AndroidManifest.xml").isFile()) return k;
            File r = findManifestMain(k, depth + 1);
            if (r != null) return r;
        }
        return null;
    }

    private EmbedState embedProjectCopy(File root, String projName, StringBuilder pre) {
        EmbedState st = new EmbedState();
        File mainDir;
        try {
            mainDir = findEmbedMainDir(root, st);
        } catch (Exception e) {
            pre.append("تعذّر تضمين نسخة المشروع: ").append(e).append("\n");
            return null;
        }
        File assets = new File(mainDir, "assets");
        File copyDir = new File(assets, "project_copy");
        boolean assetsExisted = assets.isDirectory();
        try {
            String relCopy = root.toURI().relativize(copyDir.toURI()).getPath();
            if (relCopy.endsWith("/")) relCopy = relCopy.substring(0, relCopy.length() - 1);
            embedSkipRel = relCopy;
            deleteRec(copyDir);
            copyDir.mkdirs();
            File zipFile = new File(copyDir, projName + ".zip");
            st.created.add(copyDir);
            if (!assetsExisted) st.dirsMaybeEmpty.add(0, assets);
            try (ZipCryptoWriter zw = new ZipCryptoWriter(new FileOutputStream(zipFile), EMBED_ZIP_PASSWORD, Deflater.BEST_COMPRESSION)) {
                embedZipDir(zw, root, projName, "");
            }
            long sz = zipFile.length();
            String where = root.toURI().relativize(zipFile.toURI()).getPath();
            pre.append("ضُمّنت نسخة من المشروع كملف zip محمي بكلمة سر داخل APK (").append(fmtMb(sz)).append(") في ").append(where).append(" ✔\n");
            return st;
        } catch (Exception e) {
            pre.append("تعذّر تضمين نسخة المشروع: ").append(e).append("\n");
            st.created.add(copyDir);
            if (!assetsExisted) st.dirsMaybeEmpty.add(0, assets);
            restoreEmbed(st);
            return null;
        }
    }

    private void restoreEmbed(EmbedState st) {
        if (st == null) return;
        try {
            if (st.manifest != null && st.manifestOriginal != null) {
                Compat.write(st.manifest, st.manifestOriginal.getBytes(StandardCharsets.UTF_8));
            }
        } catch (Exception ignored) {}
        for (File f : st.created) { try { deleteRec(f); } catch (Exception ignored) {} }
        for (File d : st.dirsMaybeEmpty) {
            try {
                String[] k = d.list();
                if (k != null && k.length == 0) d.delete();
            } catch (Exception ignored) {}
        }
    }

